const EXIT_PORT: u16 = 0xF4;
const EXIT_SUCCESS: u32 = 0x10;
const EXIT_FAILURE: u32 = 0x11;

#[cfg(feature = "neo-test-inference-preemptible-liveness")]
static INFERENCE_PREEMPTIBLE_READY_PEER_STOP: AtomicBool = AtomicBool::new(false);

#[cfg(feature = "neo-test-inference-preemptible-liveness")]
extern "C" fn inference_preemptible_ready_peer() -> ! {
    while !INFERENCE_PREEMPTIBLE_READY_PEER_STOP.load(Ordering::Acquire) {
        crate::sched::yield_now();
        core::hint::spin_loop();
    }
    crate::sched::exit();
}

