pub fn scenario_name() -> &'static str {
    SCENARIO
}

pub fn prepare_bare_metal_mode() {
    // OT-66 L1: count the block ops under every guard, before anything
    // mounts (this runs after the PCI probes, before `fs::init`).
    #[cfg(feature = "neo-test-login-cut")]
    crate::drivers::block::login_cut::install();
    #[cfg(feature = "neo-test-bare-metal-mode")]
    {
        crate::scenario::phase(crate::scenario::ScenarioPhase::Boot);
        #[cfg(not(any(
            feature = "neo-test-mt7601u-scan-baremetal",
            feature = "neo-test-mt7601u-assoc-baremetal"
        )))]
        install_bare_metal_log_sink();
    }
}

/// Sink-only bootstrap for the MT7601U bare-metal lanes. The explicit
/// bare-metal boundary prevents the QEMU scenario builds from touching a block
/// evidence region. Any failure halts here, before network or USB initialization.
#[cfg(all(
    feature = "neo-test-bare-metal-mode",
    any(
        feature = "neo-test-mt7601u-scan-baremetal",
        feature = "neo-test-mt7601u-assoc-baremetal"
    )
))]
pub fn prepare_mt7601u_log_sink_before_io() {
    install_bare_metal_log_sink();
}

#[cfg(feature = "neo-test-bare-metal-mode")]
fn install_bare_metal_log_sink() {
    let target_driver = bare_metal_log_sink_target_driver();
    let Some((_index, device)) = crate::drivers::block::find_device_by_driver(target_driver) else {
        strict_bare_metal_halt(
            "no log sink device available",
            "no_log_sink_device_available",
        );
    };

    let sink = match crate::log::block_sink::BlockDeviceLogSink::new(
        device.clone(),
        crate::log::block_sink::DEFAULT_REGION_OFFSET,
        crate::log::block_sink::DEFAULT_REGION_SIZE,
    ) {
        Ok(sink) => sink,
        Err(_) => strict_bare_metal_halt("log sink invalid", "log_sink_invalid"),
    };

    match sink.install() {
        Ok(()) => {}
        // Zenbook lane: the target disk has no pre-provisioned NEO_LOG_v1
        // header, so it is not ours (a laptop's own NVMe). Refusing to write
        // it is the point; the run continues without a sink and the evidence
        // is the screen.
        Err(crate::drivers::block::BlockError::WriteRefused) => {
            serial_println!(
                "NEO_TEST/1 event=INFO name={} bare_metal_log_sink=refused target_driver={} reason=no_preprovisioned_header evidence=screen",
                SCENARIO,
                target_driver
            );
            return;
        }
        Err(_) => strict_bare_metal_halt("log sink install failed", "log_sink_install_failed"),
    }

    serial_println!(
        "NEO_TEST/1 event=INFO name={} bare_metal_log_sink=installed target_driver={} offset=0x{:x} size={}",
        SCENARIO,
        target_driver,
        crate::log::block_sink::DEFAULT_REGION_OFFSET,
        crate::log::block_sink::DEFAULT_REGION_SIZE
    );
    bare_metal_log_sink_selftest(&device);
}

#[cfg(feature = "neo-test-bare-metal-mode")]
fn bare_metal_log_sink_selftest(device: &crate::log::block_sink::BlockDeviceHandle) {
    serial_println!(
        "NEO_TEST/1 event=INFO name={} bare_metal_log_sink_selftest=begin",
        SCENARIO
    );
    crate::log::flush();

    match bare_metal_log_sink_selftest_check(device) {
        Ok(cursor) => {
            serial_println!(
                "NEO_TEST/1 event=INFO name={} bare_metal_log_sink_selftest=ok cursor={}",
                SCENARIO,
                cursor
            );
        }
        Err(_) => strict_bare_metal_halt("log sink selftest failed", "log_sink_selftest_failed"),
    }
}

#[cfg(feature = "neo-test-bare-metal-mode")]
fn bare_metal_log_sink_selftest_check(
    device: &crate::log::block_sink::BlockDeviceHandle,
) -> crate::drivers::block::BlockResult<u64> {
    let block_size = device.geometry().logical_block_size as usize;
    if block_size == 0
        || crate::log::block_sink::HEADER_SIZE % block_size != 0
        || crate::log::block_sink::DEFAULT_REGION_OFFSET % block_size as u64 != 0
    {
        return Err(crate::drivers::block::BlockError::InvalidRequest);
    }

    let header =
        crate::drivers::block::DmaBuffer::alloc_zeroed(crate::log::block_sink::HEADER_SIZE)
            .map_err(|_| crate::drivers::block::BlockError::Io)?;
    let header_lba = crate::log::block_sink::DEFAULT_REGION_OFFSET / block_size as u64;
    device.read_block(header_lba, core::slice::from_ref(&header))?;

    let header_bytes = unsafe { header.as_slice() };
    if &header_bytes[..crate::log::block_sink::LOG_MAGIC.len()]
        != &crate::log::block_sink::LOG_MAGIC[..]
    {
        return Err(crate::drivers::block::BlockError::InvalidRequest);
    }

    let degradation_reason = read_le_u32(header_bytes, 0x08c);
    if degradation_reason != 0 {
        return Err(crate::drivers::block::BlockError::Io);
    }

    let cursor = read_le_u64(header_bytes, 0x018);
    if cursor == 0 {
        return Err(crate::drivers::block::BlockError::Io);
    }

    let payload =
        crate::drivers::block::DmaBuffer::alloc_zeroed(crate::log::block_sink::HEADER_SIZE)
            .map_err(|_| crate::drivers::block::BlockError::Io)?;
    let payload_lba = (crate::log::block_sink::DEFAULT_REGION_OFFSET
        + crate::log::block_sink::HEADER_SIZE as u64)
        / block_size as u64;
    device.read_block(payload_lba, core::slice::from_ref(&payload))?;

    let payload_bytes = unsafe { payload.as_slice() };
    if !contains_selftest_sentinel(payload_bytes, SCENARIO.as_bytes()) {
        return Err(crate::drivers::block::BlockError::Io);
    }

    Ok(cursor)
}

#[cfg(feature = "neo-test-bare-metal-mode")]
fn read_le_u32(bytes: &[u8], offset: usize) -> u32 {
    let mut out = [0u8; 4];
    out.copy_from_slice(&bytes[offset..offset + 4]);
    u32::from_le_bytes(out)
}

#[cfg(feature = "neo-test-bare-metal-mode")]
fn read_le_u64(bytes: &[u8], offset: usize) -> u64 {
    let mut out = [0u8; 8];
    out.copy_from_slice(&bytes[offset..offset + 8]);
    u64::from_le_bytes(out)
}

#[cfg(feature = "neo-test-bare-metal-mode")]
fn contains_selftest_sentinel(payload: &[u8], scenario: &[u8]) -> bool {
    const PREFIX: &[u8] = b"NEO_TEST/1 event=INFO name=";
    const SUFFIX: &[u8] = b" bare_metal_log_sink_selftest=begin";
    let total_len = PREFIX.len() + scenario.len() + SUFFIX.len();
    if total_len > payload.len() {
        return false;
    }

    payload.windows(total_len).any(|window| {
        &window[..PREFIX.len()] == PREFIX
            && &window[PREFIX.len()..PREFIX.len() + scenario.len()] == scenario
            && &window[PREFIX.len() + scenario.len()..] == SUFFIX
    })
}

