    {
        if crate::fs::mount_neofs_from_device0_readonly().is_err() {
            fail("reason=inference_preemptible_neofs_mount_ro_failed");
        }
        if !crate::arch::x86_64::fpu::xsave_active() {
            fail("reason=inference_preemptible_xsave_inactive");
        }
        let xstate_mask = crate::arch::x86_64::fpu::xstate_mask();
        let required_xstate_mask = crate::arch::x86_64::fpu::required_xstate_mask();
        if xstate_mask & required_xstate_mask != required_xstate_mask {
            fail("reason=inference_preemptible_xstate_mask_missing_ymm");
        }
        INFERENCE_PREEMPTIBLE_READY_PEER_STOP.store(false, Ordering::Release);
        crate::sched::spawn("inference-preempt-peer", inference_preemptible_ready_peer);
        let exit_code = _ipc_smoke();
        INFERENCE_PREEMPTIBLE_READY_PEER_STOP.store(true, Ordering::Release);
        crate::sched::yield_now();
        crate::sched::reap();
        finish_infer_transformer_forward_from_user_exit(exit_code);
    }

