#[cfg(feature = "neo-test-neo-shell-builtins")]
fn run_neo_shell_builtins_sysstat_validation() {
    use crate::arch::x86_64::syscall::{SysStatV1, debug_sys_sysstat_for_test};
    use crate::errno::{EFAULT, EINVAL};

    let len = core::mem::size_of::<SysStatV1>();

    let rc_null = debug_sys_sysstat_for_test(core::ptr::null_mut(), len);
    if rc_null != EINVAL {
        serial_println!(
            "NEO_TEST/1 event=FAIL name={} reason=sysstat_null_expected_EINVAL got={}",
            SCENARIO,
            rc_null
        );
        debug_exit(EXIT_FAILURE);
    }

    let rc_short = debug_sys_sysstat_for_test(0x1000 as *mut SysStatV1, len - 1);
    if rc_short != EINVAL {
        serial_println!(
            "NEO_TEST/1 event=FAIL name={} reason=sysstat_short_expected_EINVAL got={}",
            SCENARIO,
            rc_short
        );
        debug_exit(EXIT_FAILURE);
    }

    let kernel_half_ptr = 0xFFFF_8000_0000_0000usize as *mut SysStatV1;
    let rc_kernel = debug_sys_sysstat_for_test(kernel_half_ptr, len);
    if rc_kernel != EFAULT {
        serial_println!(
            "NEO_TEST/1 event=FAIL name={} reason=sysstat_kernel_half_expected_EFAULT got={}",
            SCENARIO,
            rc_kernel
        );
        debug_exit(EXIT_FAILURE);
    }

    let near_limit_ptr = (0x0000_8000_0000_0000u64 - 1) as *mut SysStatV1;
    let rc_overflow = debug_sys_sysstat_for_test(near_limit_ptr, len);
    if rc_overflow != EFAULT {
        serial_println!(
            "NEO_TEST/1 event=FAIL name={} reason=sysstat_overflow_expected_EFAULT got={}",
            SCENARIO,
            rc_overflow
        );
        debug_exit(EXIT_FAILURE);
    }

    serial_println!("[ kernel ] sysstat: buffer-validation truth table PASS");
}

