#[cfg(feature = "neo-test-accel-gpu-compute")]
fn run_accel_gpu_compute() -> ! {
    use crate::atrium::blur::{self, BlurDims};
    use crate::drivers::accel::{self, gpu_compute};

    let (oracle_src, oracle_dst) = gpu_blur_gate_fixture();
    let dims = BlurDims {
        width: 8,
        height: 8,
        stride: 32,
        radius: 1,
    };
    let (_, driver) = accel::find_device_by_driver("accel_sim")
        .unwrap_or_else(|| fail("reason=accel_sim_not_registered"));

    let mut mid = [0u8; 256];

    // --- Phase 1: kill-switch OFF ⇒ pure CPU floor, NO submit. ---
    gpu_compute::set_gpu_compute_enable(false);
    gpu_compute::reset_compute_admits();
    let mut dst_off = [0u8; 256];
    let tok_off = gpu_compute::blur_backdrop(
        &driver,
        &oracle_src,
        &mut mid,
        &mut dst_off,
        dims,
        &blur::WEIGHTS_R1_Q16,
    )
    .unwrap_or_else(|_| fail("reason=compute_off_call_failed"));
    if dst_off != oracle_dst {
        fail("reason=compute_off_not_oracle_floor");
    }
    if gpu_compute::compute_admits() != 0 {
        fail("reason=compute_off_submitted");
    }
    if tok_off.sequence != 0 {
        fail("reason=compute_off_token_not_floor_sentinel");
    }

    // --- Phase 2: kill-switch ON ⇒ identical bytes + a submit that completed. ---
    gpu_compute::set_gpu_compute_enable(true);
    let mut dst_on = [0u8; 256];
    let tok_on = gpu_compute::blur_backdrop(
        &driver,
        &oracle_src,
        &mut mid,
        &mut dst_on,
        dims,
        &blur::WEIGHTS_R1_Q16,
    )
    .unwrap_or_else(|_| fail("reason=compute_on_call_failed"));
    if dst_on != oracle_dst {
        fail("reason=compute_on_not_oracle");
    }
    if gpu_compute::compute_admits() != 1 {
        fail("reason=compute_on_submit_not_counted");
    }
    if gpu_compute::compute_dispatches() != 1 || gpu_compute::compute_degrades() != 0 {
        fail("reason=compute_on_was_floor_masked");
    }
    if tok_on.sequence == 0 {
        fail("reason=compute_on_token_is_floor_sentinel");
    }
    // The Rule-1 equality: the two toggle states are byte-for-byte identical.
    if dst_off != dst_on {
        fail("reason=killswitch_bytes_diverged");
    }

    // --- Phase 3: QEMU wiring only. The sim writes the actual bound mid/dst
    // buffers so the service cannot pass by overwriting them with the CPU floor.
    // This is deliberately not Gen9 EU evidence.
    let h_only = accel::ComputePipeline::SeparableBlur {
        width: 8,
        height: 8,
        stride: 8 * 4,
        radius: 1,
        mode: accel::BlurDispatchMode::HorizontalOnly,
    };
    let mut oracle_mid = [0u8; 256];
    blur::blur_pass_h(&oracle_src, &mut oracle_mid, dims, &blur::WEIGHTS_R1_Q16)
        .unwrap_or_else(|_| fail("reason=cpu_h_oracle_failed"));
    let mut h_mid = [0u8; 256];
    let mut h_dst = [0x5au8; 256];
    let mut h_bindings = accel::ComputeBindings {
        src: &oracle_src,
        mid: &mut h_mid,
        dst: &mut h_dst,
        weights: &blur::WEIGHTS_R1_Q16,
    };
    let h_tok = driver
        .submit_compute_pipeline(&h_only, &mut h_bindings)
        .unwrap_or_else(|_| fail("reason=separable_blur_h_only_rejected"));
    driver
        .wait(h_tok, Some(core::time::Duration::from_secs(2)))
        .unwrap_or_else(|_| fail("reason=separable_blur_h_only_fence_failed"));
    drop(h_bindings);
    if h_mid != oracle_mid || h_dst != [0x5au8; 256] {
        fail("reason=separable_blur_h_only_binding_wrong");
    }

    let good = accel::ComputePipeline::SeparableBlur {
        width: 8,
        height: 8,
        stride: 8 * 4,
        radius: 1,
        mode: accel::BlurDispatchMode::TwoPass,
    };
    let mut direct_mid = [0u8; 256];
    let mut direct_dst = [0u8; 256];
    let mut good_bindings = accel::ComputeBindings {
        src: &oracle_src,
        mid: &mut direct_mid,
        dst: &mut direct_dst,
        weights: &blur::WEIGHTS_R1_Q16,
    };
    let good_tok = driver
        .submit_compute_pipeline(&good, &mut good_bindings)
        .unwrap_or_else(|_| fail("reason=separable_blur_wellformed_rejected"));
    driver
        .wait(good_tok, Some(core::time::Duration::from_secs(2)))
        .unwrap_or_else(|_| fail("reason=separable_blur_fence_failed"));
    drop(good_bindings);
    if direct_mid != oracle_mid || direct_dst != oracle_dst {
        fail("reason=separable_blur_bound_outputs_wrong");
    }
    let mut bad_mid = [0u8; 256];
    let mut bad_dst = [0u8; 256];
    let mut bad_bindings = accel::ComputeBindings {
        src: &oracle_src,
        mid: &mut bad_mid,
        dst: &mut bad_dst,
        weights: &blur::WEIGHTS_R1_Q16,
    };
    // Malformed: stride < width*4 (a shape the r=8 kernel's ABI cannot dispatch).
    let bad = accel::ComputePipeline::SeparableBlur {
        width: 640,
        height: 480,
        stride: 16, // < 640*4
        radius: 8,
        mode: accel::BlurDispatchMode::TwoPass,
    };
    if driver
        .submit_compute_pipeline(&bad, &mut bad_bindings)
        .is_ok()
    {
        fail("reason=separable_blur_malformed_accepted");
    }
    // Radius past the pinned r=8 is likewise rejected.
    let bad_r = accel::ComputePipeline::SeparableBlur {
        width: 8,
        height: 8,
        stride: 32,
        radius: 9,
        mode: accel::BlurDispatchMode::TwoPass,
    };
    if driver
        .submit_compute_pipeline(&bad_r, &mut bad_bindings)
        .is_ok()
    {
        fail("reason=separable_blur_bad_radius_accepted");
    }

    // --- Phase 4: enabled backend failure must be masked only by the floor,
    // with a counter that prevents those correct bytes being claimed as EU work.
    gpu_compute::reset_compute_admits();
    crate::drivers::accel::accel_sim::set_force_compute_reject(true);
    let mut degraded_mid = [0u8; 256];
    let mut degraded_dst = [0u8; 256];
    let degraded = gpu_compute::blur_backdrop(
        &driver,
        &oracle_src,
        &mut degraded_mid,
        &mut degraded_dst,
        dims,
        &blur::WEIGHTS_R1_Q16,
    )
    .unwrap_or_else(|_| fail("reason=compute_degrade_call_failed"));
    crate::drivers::accel::accel_sim::set_force_compute_reject(false);
    if degraded.sequence != 0 || degraded_dst != oracle_dst {
        fail("reason=compute_degrade_not_floor");
    }
    if gpu_compute::compute_admits() != 0
        || gpu_compute::compute_dispatches() != 0
        || gpu_compute::compute_degrades() != 1
    {
        fail("reason=compute_degrade_evidence_wrong");
    }

    gpu_compute::set_gpu_compute_enable(false);
    pass(
        "accel_gpu_compute=ok qemu_wiring_only=yes killswitch_off_floor=yes killswitch_on_bound_output=yes h_only_mid_capture=yes two_pass_bytes_equal=yes malformed=rejected enabled_failure_degrades=yes completion_is_fence_not_present=yes silicon_proof=required_baremetal i14a=no_gov_lock i14b=bounded_wait cp18=io_gate",
    );
}

/// Slice-6 needs the graphics-domain gate before `spawn_neo_init` can mint the
/// three trusted root caps.  This is intentionally before the user scenario:
/// a root constructor without the Slice-5 arena/narrowing proof fails closed.
#[cfg(feature = "neo-test-gpu-glass-slice6")]
fn prepare_gpu_glass_slice6_root() {
    use crate::drivers::graphics_arena;

    if graphics_arena::init(64).is_err() || !graphics_arena::set_narrowing(true) {
        fail("reason=slice6_graphics_arena_gate_not_established");
    }
}

/// OT-63 GPU P1 Slice 6 QEMU gate.  It first drives the real userland
/// `GpuCompute` ABI, then proves the compositor's capture -> blur/floor ->
/// tint -> composite path against a literal composited byte oracle.  The only
/// simulated part is the accelerator; raw scanout still goes through the
/// existing GpuSubmit gate.
///
/// `ORACLE_COMPOSITE` below is a golden-master regression snapshot, not this
/// scenario's independent proof.  Before exercising production code, the
/// scenario derives the same 8x8 r=1 result with the test-local reference
/// routine below: separate fixed constants, explicit edge samples, and no call
/// to `atrium::blur` or `accel_sim`.  The literal catches fixture drift; the
/// independent reference catches a shared production-arithmetic error.
#[cfg(feature = "neo-test-gpu-glass-slice6")]
fn slice6_independent_tint(src: &[u8; 256]) -> [u8; 256] {
    const TINT_BGR: [u32; 3] = [0x80, 0xC0, 0xFF];
    const ALPHA: u32 = 64;
    const INVERSE: u32 = 191;

    let mut out = [0u8; 256];
    for y in 0usize..8 {
        for x in 0usize..8 {
            let base = y * 32 + x * 4;
            for channel in 0..3 {
                out[base + channel] = ((src[base + channel] as u32 * INVERSE
                    + TINT_BGR[channel] * ALPHA
                    + 127)
                    / 255) as u8;
            }
            out[base + 3] = 0xFF;
        }
    }
    out
}

/// Independently derive the pinned 8x8/r=1 blur-plus-tint fixture.  Do not
/// replace this with `blur_pass_*` or `apply_vibrancy_tint`: its job is to make
/// the literal oracle meaningful even if all production paths share a bug.
#[cfg(feature = "neo-test-gpu-glass-slice6")]
fn slice6_independent_r1_composite(src: &[u8; 256]) -> [u8; 256] {
    const EDGE_WEIGHT: i32 = 16_384;
    const CENTER_WEIGHT: i32 = 32_768;
    const ROUND_HALF_UP_Q16: i32 = 32_768;

    let mut horizontal = [0u8; 256];
    for y in 0usize..8 {
        for x in 0usize..8 {
            let left = x.saturating_sub(1);
            let right = (x + 1).min(7);
            let base = y * 32 + x * 4;
            for channel in 0..3 {
                let sum = EDGE_WEIGHT * src[y * 32 + left * 4 + channel] as i32
                    + CENTER_WEIGHT * src[base + channel] as i32
                    + EDGE_WEIGHT * src[y * 32 + right * 4 + channel] as i32;
                horizontal[base + channel] = ((sum + ROUND_HALF_UP_Q16) >> 16) as u8;
            }
            horizontal[base + 3] = 0xFF;
        }
    }

    let mut vertical = [0u8; 256];
    for y in 0usize..8 {
        let top = y.saturating_sub(1);
        let bottom = (y + 1).min(7);
        for x in 0usize..8 {
            let base = y * 32 + x * 4;
            for channel in 0..3 {
                let sum = EDGE_WEIGHT * horizontal[top * 32 + x * 4 + channel] as i32
                    + CENTER_WEIGHT * horizontal[base + channel] as i32
                    + EDGE_WEIGHT * horizontal[bottom * 32 + x * 4 + channel] as i32;
                vertical[base + channel] = ((sum + ROUND_HALF_UP_Q16) >> 16) as u8;
            }
            vertical[base + 3] = 0xFF;
        }
    }

    slice6_independent_tint(&vertical)
}

#[cfg(feature = "neo-test-gpu-glass-slice6")]
fn run_gpu_glass_slice6(_ipc_smoke: fn() -> i32) -> ! {
    use crate::atrium::blur::{self, G1_VIBRANCY_TINT};
    use crate::atrium::buffer::SharedPixelBuffer;
    use crate::atrium::glass::GlassSurface;
    use crate::atrium::logic::{self, BufferDescV1, DamageRectV1};
    use crate::atrium::{self, present_backend};
    use crate::drivers::accel::{accel_sim, gpu_compute};
    use crate::errno::{EAGAIN, EPERM};

    // Golden-master regression snapshot. Provenance is deliberately explicit:
    // `slice6_independent_r1_composite` below is the independent fixture that
    // validates this literal before any production blur/tint path runs.
    #[rustfmt::skip]
    const ORACLE_COMPOSITE: [u8; 256] = [
        0x3B,0x3A,0x4E,0xFF,0x3C,0x3A,0x62,0xFF,0x3D,0x3A,0x7F,0xFF,0x40,0x3A,0xA1,0xFF,0x43,0x3A,0xC7,0xFF,0x46,0x3A,0xE7,0xFF,0x4B,0x3A,0xF9,0xFF,0x4F,0x3A,0xFE,0xFF,
        0x48,0x4A,0x4E,0xFF,0x49,0x4A,0x62,0xFF,0x4A,0x4A,0x7F,0xFF,0x4C,0x4A,0xA1,0xFF,0x4F,0x4A,0xC7,0xFF,0x53,0x4A,0xE7,0xFF,0x58,0x4A,0xF9,0xFF,0x5B,0x4A,0xFE,0xFF,
        0x4F,0x66,0x4E,0xFF,0x50,0x66,0x62,0xFF,0x52,0x66,0x7F,0xFF,0x54,0x66,0xA1,0xFF,0x57,0x66,0xC7,0xFF,0x5B,0x66,0xE7,0xFF,0x5E,0x66,0xF9,0xFF,0x62,0x66,0xFE,0xFF,
        0x55,0x8A,0x4E,0xFF,0x58,0x8A,0x62,0xFF,0x5A,0x8A,0x7F,0xFF,0x5C,0x8A,0xA1,0xFF,0x5F,0x8A,0xC7,0xFF,0x62,0x8A,0xE7,0xFF,0x65,0x8A,0xF9,0xFF,0x69,0x8A,0xFE,0xFF,
        0x71,0xAF,0x4E,0xFF,0x73,0xAF,0x62,0xFF,0x74,0xAF,0x7F,0xFF,0x76,0xAF,0xA1,0xFF,0x79,0xAF,0xC7,0xFF,0x7D,0xAF,0xE7,0xFF,0x81,0xAF,0xF9,0xFF,0x84,0xAF,0xFE,0xFF,
        0x8D,0xCA,0x4E,0xFF,0x8D,0xCA,0x62,0xFF,0x8F,0xCA,0x7F,0xFF,0x91,0xCA,0xA1,0xFF,0x94,0xCA,0xC7,0xFF,0x98,0xCA,0xE7,0xFF,0x9C,0xCA,0xF9,0xFF,0xA0,0xCA,0xFE,0xFF,
        0x9E,0xE0,0x4E,0xFF,0x9F,0xE0,0x62,0xFF,0xA0,0xE0,0x7F,0xFF,0xA2,0xE0,0xA1,0xFF,0xA5,0xE0,0xC7,0xFF,0xA9,0xE0,0xE7,0xFF,0xAE,0xE0,0xF9,0xFF,0xB1,0xE0,0xFE,0xFF,
        0xAB,0xEC,0x4E,0xFF,0xAB,0xEC,0x62,0xFF,0xAD,0xEC,0x7F,0xFF,0xAF,0xEC,0xA1,0xFF,0xB2,0xEC,0xC7,0xFF,0xB6,0xEC,0xE7,0xFF,0xBA,0xEC,0xF9,0xFF,0xBE,0xEC,0xFE,0xFF,
    ];

    prepare_gpu_glass_slice6_root();
    gpu_compute::set_gpu_compute_enable(false);
    let user_exit = _ipc_smoke();
    if user_exit != 0 {
        fail_with_hex(
            "reason=slice6_user_gpu_compute_abi_failed code",
            user_exit as u64,
        );
    }

    let (src_bytes, _) = gpu_blur_gate_fixture();
    if slice6_independent_r1_composite(&src_bytes) != ORACLE_COMPOSITE {
        fail("reason=slice6_independent_r1_fixture_disagrees_with_literal_oracle");
    }
    let desc = BufferDescV1 {
        width: 8,
        height: 8,
        stride: 32,
        format: logic::FORMAT_XRGB8888_LE,
        bytes: 256,
    };
    let backdrop = SharedPixelBuffer::create_gpu(desc)
        .unwrap_or_else(|_| fail("reason=slice6_backdrop_create_failed"));
    let mut backdrop_pixels = backdrop
        .contiguous_pixels_mut()
        .unwrap_or_else(|_| fail("reason=slice6_backdrop_view_failed"));
    backdrop_pixels.as_mut_slice().copy_from_slice(&src_bytes);
    drop(backdrop_pixels);
    let glass =
        GlassSurface::create(desc).unwrap_or_else(|_| fail("reason=slice6_glass_create_failed"));
    let driver =
        GlassSurface::qemu_driver().unwrap_or_else(|| fail("reason=slice6_accel_sim_missing"));
    let changed = DamageRectV1 {
        x: 2,
        y: 2,
        width: 2,
        height: 2,
    };
    let expected_damage = DamageRectV1 {
        x: 1,
        y: 1,
        width: 4,
        height: 4,
    };

    // Model crossed submits `(src=X, dst=Y)` + `(src=Y, dst=X)`: while the
    // first has its live writer for Y, the second must not manufacture a shared
    // source slice for Y.  The reader fails closed before it can coexist with
    // the writer; a second writer does too.  This is the latent C1.1 seam, made
    // QEMU-visible without needing preemptive user threads in this build.
    let crossed_src = SharedPixelBuffer::create_gpu(desc)
        .unwrap_or_else(|_| fail("reason=slice6_crossed_src_create_failed"));
    let crossed_dst = SharedPixelBuffer::create_gpu(desc)
        .unwrap_or_else(|_| fail("reason=slice6_crossed_dst_create_failed"));
    let first_src = crossed_src
        .contiguous_pixels()
        .unwrap_or_else(|_| fail("reason=slice6_crossed_first_src_acquire_failed"));
    let first_writer = crossed_dst
        .contiguous_pixels_mut()
        .unwrap_or_else(|_| fail("reason=slice6_crossed_first_dst_acquire_failed"));
    match crossed_dst.contiguous_pixels() {
        Err(errno) if errno == EAGAIN => {}
        _ => {
            drop(first_writer);
            drop(first_src);
            fail("reason=slice6_crossed_submit_src_read_not_eagain");
        }
    }
    match crossed_dst.contiguous_pixels_mut() {
        Err(errno) if errno == EAGAIN => {}
        _ => {
            drop(first_writer);
            drop(first_src);
            fail("reason=slice6_overlapping_dst_mut_borrow_not_eagain");
        }
    }
    drop(first_writer);
    drop(first_src);
    let reader = crossed_dst
        .contiguous_pixels()
        .unwrap_or_else(|_| fail("reason=slice6_reader_acquire_after_writer_release_failed"));
    match crossed_dst.contiguous_pixels_mut() {
        Err(errno) if errno == EAGAIN => {}
        _ => {
            drop(reader);
            fail("reason=slice6_reader_did_not_block_writer");
        }
    }
    drop(reader);
    if crossed_dst.contiguous_pixels_mut().is_err() {
        fail("reason=slice6_writer_not_released");
    }

    // The compositor construction rule is a second line of defense for the
    // merged `dst != self` guard: a composite surface may never be recycled as
    // a capture/compute source in the same glass material.
    if glass
        .draw_with_material(
            glass.composite(),
            changed,
            Some(&driver),
            1,
            &blur::WEIGHTS_R1_Q16,
            G1_VIBRANCY_TINT,
        )
        .is_ok()
    {
        fail("reason=slice6_glass_dst_self_alias_accepted");
    }

    // GPU off is the live CPU glass floor, including the tint/composite stage;
    // no GPU admission is allowed and the completed fence is the floor token.
    atrium::set_glass_blur_enabled(true);
    gpu_compute::set_gpu_compute_enable(false);
    gpu_compute::reset_compute_admits();
    let off = glass
        .draw_with_material(
            &backdrop,
            changed,
            Some(&driver),
            1,
            &blur::WEIGHTS_R1_Q16,
            G1_VIBRANCY_TINT,
        )
        .unwrap_or_else(|_| fail("reason=slice6_glass_cpu_floor_failed"));
    let off_bytes = glass
        .composite()
        .contiguous_pixels()
        .unwrap_or_else(|_| fail("reason=slice6_glass_cpu_view_failed"));
    if off_bytes.as_slice() != ORACLE_COMPOSITE
        || off.fence.sequence != 0
        || off.output_damage != expected_damage
        || gpu_compute::compute_admits() != 0
    {
        fail("reason=slice6_glass_cpu_floor_oracle_or_damage_failed");
    }
    drop(off_bytes);

    // GPU enabled must keep byte equality while recording an actual completed
    // simulated dispatch. The token remains compute evidence only.
    gpu_compute::set_gpu_compute_enable(true);
    gpu_compute::reset_compute_admits();
    let on = glass
        .draw_with_material(
            &backdrop,
            changed,
            Some(&driver),
            1,
            &blur::WEIGHTS_R1_Q16,
            G1_VIBRANCY_TINT,
        )
        .unwrap_or_else(|_| fail("reason=slice6_glass_gpu_call_failed"));
    let on_bytes = glass
        .composite()
        .contiguous_pixels()
        .unwrap_or_else(|_| fail("reason=slice6_glass_gpu_view_failed"));
    if on_bytes.as_slice() != ORACLE_COMPOSITE
        || on.fence.sequence == 0
        || gpu_compute::compute_admits() != 1
        || gpu_compute::compute_degrades() != 0
    {
        fail("reason=slice6_glass_gpu_oracle_or_fence_failed");
    }
    drop(on_bytes);

    // Enabled-path fault must degrade to precisely the same CPU composite.
    accel_sim::set_force_compute_reject(true);
    gpu_compute::reset_compute_admits();
    let degraded = glass
        .draw_with_material(
            &backdrop,
            changed,
            Some(&driver),
            1,
            &blur::WEIGHTS_R1_Q16,
            G1_VIBRANCY_TINT,
        )
        .unwrap_or_else(|_| fail("reason=slice6_glass_degrade_call_failed"));
    accel_sim::set_force_compute_reject(false);
    if glass
        .composite()
        .contiguous_pixels()
        .unwrap_or_else(|_| fail("reason=slice6_glass_degrade_view_failed"))
        .as_slice()
        != ORACLE_COMPOSITE
        || degraded.fence.sequence != 0
        || gpu_compute::compute_degrades() != 1
    {
        fail("reason=slice6_glass_degrade_not_cpu_floor");
    }

    // Exercise the production fixed r=8 material too. The r=1 call above is
    // only the reduced-size byte oracle; this call proves the public G1 entry
    // owns the pinned radius/weights/tint rather than exposing them as an ABI.
    let production_glass = GlassSurface::create(desc)
        .unwrap_or_else(|_| fail("reason=slice6_production_glass_create_failed"));
    gpu_compute::set_gpu_compute_enable(false);
    if production_glass
        .draw(&backdrop, changed, Some(&driver))
        .unwrap_or_else(|_| fail("reason=slice6_production_glass_draw_failed"))
        .fence
        .sequence
        != 0
    {
        fail("reason=slice6_production_glass_not_cpu_floor_when_gpu_off");
    }

    // A compute fence cannot bypass the independent raw-scanout gate. The
    // refused call leaves the committed damage untouched; an explicit present
    // with GpuSubmit authority then copies only the radius-expanded damage.
    present_backend::set_gpu_submit_enforce(true);
    if glass.composite().present(0, 0, false) != Err(EPERM) {
        fail("reason=slice6_compute_fence_bypassed_scanout_gate");
    }
    glass
        .composite()
        .present(0, 0, true)
        .unwrap_or_else(|_| fail("reason=slice6_authorized_present_failed"));
    if crate::drivers::fb::read_pixel(1, 1) != Some(0xFF62_4A49) {
        fail("reason=slice6_composited_damage_byte_not_presented");
    }

    // Reduce Transparency is a live, unblurred solid floor.  Exercise its
    // `copy_backdrop` arm and compare the composited bytes to the independent
    // tint of the original backdrop (not a production blur/tint helper).
    atrium::set_glass_blur_enabled(false);
    gpu_compute::set_gpu_compute_enable(true);
    gpu_compute::reset_compute_admits();
    let rt = glass
        .draw_with_material(
            &backdrop,
            changed,
            Some(&driver),
            1,
            &blur::WEIGHTS_R1_Q16,
            G1_VIBRANCY_TINT,
        )
        .unwrap_or_else(|_| fail("reason=slice6_reduce_transparency_draw_failed"));
    if glass
        .composite()
        .contiguous_pixels()
        .unwrap_or_else(|_| fail("reason=slice6_reduce_transparency_view_failed"))
        .as_slice()
        != slice6_independent_tint(&src_bytes)
        || rt.fence.sequence != 0
        || rt.output_damage != changed
        || gpu_compute::compute_admits() != 0
    {
        fail("reason=slice6_reduce_transparency_not_copy_backdrop_floor");
    }
    present_backend::set_gpu_submit_enforce(false);
    atrium::set_glass_blur_enabled(false);
    gpu_compute::set_gpu_compute_enable(false);
    pass(
        "gpu_glass_slice6=ok user_three_cap_abi=yes no_self_mint=yes derive_attenuation=yes revoke_fail_closed=yes shared_xor_mutable_crossed_submit_eagain=yes independent_r1_oracle=yes capture_blur_tint_composite=byte_oracle_match damage_scoped=yes gpu_off_eq_cpu_floor=yes gpu_degrade_eq_cpu_floor=yes reduce_transparency_copy_backdrop_oracle=yes compute_fence_not_present=yes scanout_authorized_gate=held qemu_accel_sim_only=yes",
    );
}

#[cfg(any(
    feature = "neo-test-accel-intel-blur-silicon",
    feature = "neo-test-accel-intel-blur-silicon-narrowed"
))]
fn run_accel_intel_blur_silicon_gate(narrowed: bool) -> ! {
    use core::time::Duration;

    use crate::atrium::blur::{self, BlurDims};
    use crate::drivers::accel::{self, BlurDispatchMode, ComputeBindings, gpu_compute};
    use crate::drivers::{graphics_arena, iommu};

    // ── DECISION 2026-08-01 §1: the I-14(c) REFUSAL discriminator ────────────
    //
    // OLD acceptance (void): "a real iGPU runs the blur with narrowing OFF,
    // proving narrowing-OFF ≡ pre-Slice-5 bit-for-bit." That configuration is
    // an uncontained bus-mastering DMA master — the exact hole the AAG bounce
    // closed — so it is no longer reachable and cannot be an acceptance.
    //
    // NEW acceptance: "on real silicon, with the graphics IOMMU domain NOT
    // armed, the accel probe REFUSES bus mastering, leaves the iGPU
    // decode-only and unregistered, and the system still boots with the CPU
    // compute floor intact." This makes the fail-closed guard self-testing —
    // its refusal path is exercised on hardware instead of believed in.
    if !narrowed {
        let probe = accel::accel_intel::last_probe_snapshot();
        // The device must have been SEEN and matched — otherwise a refusal is
        // vacuous (an absent GPU also "doesn't master the bus").
        if !probe.probed {
            fail("reason=blur_silicon_refusal_probe_never_ran");
        }
        if probe.device_id == 0 {
            fail("reason=blur_silicon_refusal_no_device_matched");
        }
        // The probe must have refused.
        if probe.probe_ok {
            fail("reason=blur_silicon_refusal_probe_unexpectedly_succeeded");
        }
        // Containment genuinely absent (the precondition under test).
        if graphics_arena::containment_armed() {
            fail("reason=blur_silicon_refusal_containment_unexpectedly_armed");
        }
        // No hardware accelerator may be marked bound — this is what keeps
        // `alloc_gpu` from ever handing out unfenced buddy memory.
        if graphics_arena::hardware_accelerator_bound() {
            fail("reason=blur_silicon_refusal_hw_accel_marked_bound");
        }
        // The refused device must NOT be registered, so nothing can submit.
        if accel::find_device_by_driver("accel_intel").is_some() {
            fail("reason=blur_silicon_refusal_device_still_registered");
        }
        // HARDWARE evidence, not control flow: BUS MASTER must be clear in
        // the device's own PCI COMMAND register.
        let command = accel::accel_intel::debug_command_register();
        if command & crate::drivers::pci::COMMAND_BUS_MASTER != 0 {
            fail_with_hex(
                "reason=blur_silicon_refusal_bus_master_still_set command",
                command as u64,
            );
        }
        // Degrade, not fail (DECISION condition 1): the CPU compute floor must
        // still be registered and usable, so the system boots and Arthur answers.
        if accel::find_device_by_driver("accel_cpu").is_none() {
            fail("reason=blur_silicon_refusal_cpu_floor_missing");
        }
        serial_println!(
            "SLICE4 i14c_refusal device_id=0x{:04x} probe_ok=false registered=false \
             pci_command=0x{:04x} bus_master=clear hw_accel_bound=false cpu_floor=present",
            probe.device_id,
            command
        );
        crate::log::flush();
        pass(
            "accel_intel_blur_silicon=ok acceptance=i14c_containment_refusal probe=refused \
             bus_master=clear_on_hardware device_registered=false hw_accel_bound=false \
             gpu_reachable_alloc=unreachable cpu_floor=present boot=continued \
             kill_switch=degrade_not_fail",
        );
    }

    let (_, driver) = accel::find_device_by_driver("accel_intel")
        .unwrap_or_else(|| fail("reason=blur_silicon_accel_intel_missing"));
    let probe = accel::accel_intel::last_probe_snapshot();
    if !probe.probed || !probe.probe_ok || !probe.gtt_mapped {
        fail("reason=blur_silicon_probe_incomplete");
    }

    // Run 2 is a separate boot: establish the complete graphics working-set
    // arena and move the real iGPU requester into its translated domain before
    // the first GPU-reachable allocation is made.
    // I-14(c) (Slice-4 AAG bounce, 2026-08-01): containment is now armed in the
    // BOOT path, before `accel::init()` probes — a bus-mastering accelerator
    // may not be granted DMA rights ahead of its VT-d domain. So the arena and
    // the narrowed domain already exist here; this scenario asserts that fact
    // instead of establishing it. A probe that got this far necessarily had
    // containment armed (it is refused otherwise), so this is a positive
    // cross-check of the boot-path guard, not a second arming.
    if !graphics_arena::containment_armed() {
        fail("reason=blur_silicon_containment_not_armed_at_scenario_entry");
    }
    if narrowed {
        if !iommu::available() || !iommu::enabled() {
            fail("reason=blur_silicon_narrowed_vtd_unavailable");
        }
        if !graphics_arena::arena_reserved() {
            fail("reason=blur_silicon_graphics_arena_missing");
        }
        if !graphics_arena::domain_armed() {
            fail("reason=blur_silicon_igpu_not_narrowed");
        }
        // Drain records that predate this scenario, then establish a clean
        // hardware-fault baseline before the first translated GPU access. A
        // later negative-control fault is attributable to the deliberately
        // out-of-domain weights page only if the complete positive working set
        // first runs without any VT-d fault record.
        iommu::poll_faults();
        iommu::reset_fault_counters();
    }
    // NOTE (Slice-4 AAG bounce): the former `else` arm asserted that the
    // identity run started with narrowing OFF — i.e. a real iGPU running with
    // unrestricted buddy DMA. That configuration is exactly the I-14(c)
    // violation this bounce closed, so it is no longer reachable: the probe
    // refuses bus mastering unless containment is armed. The Rule-1 kill-switch
    // equality still holds where it is meaningful — for the SIMULATED
    // accelerator, which never sets `hardware_accelerator_bound()` and so still
    // takes the pre-Slice-5 buddy path bit-for-bit.

    // Gen9 A64 PPGTT is an LRC property. The driver refuses the disproven
    // legacy-ring root path, so this toggle means "construct an ELSP context",
    // not "prepend the old PDP-load experiment."
    accel::accel_intel::set_ppgtt_enabled(true);
    accel::accel_intel::reset_blur_evidence();
    gpu_compute::set_gpu_compute_enable(true);
    gpu_compute::reset_compute_admits();

    let (src, oracle_dst) = gpu_blur_gate_fixture();
    let dims = BlurDims {
        width: 8,
        height: 8,
        stride: 32,
        radius: 1,
    };
    let mut oracle_mid = [0u8; 256];
    blur::blur_pass_h(&src, &mut oracle_mid, dims, &blur::WEIGHTS_R1_Q16)
        .unwrap_or_else(|_| fail("reason=blur_silicon_cpu_h_oracle_failed"));

    // Non-perturbing H-only run: its batch has no V walker or inter-pass
    // PIPE_CONTROL. Capture mid only and compare it with the CPU reference.
    let h_manifest = accel::ComputePipeline::SeparableBlur {
        width: 8,
        height: 8,
        stride: 32,
        radius: 1,
        mode: BlurDispatchMode::HorizontalOnly,
    };
    let mut h_mid = [0u8; 256];
    let mut h_dst = [0x5au8; 256];
    let mut h_bindings = ComputeBindings {
        src: &src,
        mid: &mut h_mid,
        dst: &mut h_dst,
        weights: &blur::WEIGHTS_R1_Q16,
    };
    let h_token = driver
        .submit_compute_pipeline(&h_manifest, &mut h_bindings)
        .unwrap_or_else(|_| fail("reason=blur_silicon_h_submit_failed"));
    driver
        .wait(h_token, Some(Duration::from_secs(3)))
        .unwrap_or_else(|_| fail("reason=blur_silicon_h_timeout"));
    drop(h_bindings);
    if h_mid != oracle_mid || h_dst != [0x5au8; 256] {
        fail("reason=blur_silicon_h_bytes_mismatch");
    }
    if !accel::accel_intel::debug_blur_mid_captured()
        || accel::accel_intel::debug_blur_dst_captured()
        || accel::accel_intel::debug_blur_walker_kicks() != 1
        || accel::accel_intel::debug_blur_completions() != 1
    {
        fail("reason=blur_silicon_h_evidence_wrong");
    }

    // Acceptance path, twice: the service must return the backend's dst bytes,
    // never overwrite them with the floor, and the repeated run must be stable.
    let mut first_mid = [0u8; 256];
    let mut first_dst = [0u8; 256];
    let first = gpu_compute::blur_backdrop(
        &driver,
        &src,
        &mut first_mid,
        &mut first_dst,
        dims,
        &blur::WEIGHTS_R1_Q16,
    )
    .unwrap_or_else(|_| fail("reason=blur_silicon_first_service_failed"));
    if first.sequence == 0 || first_mid != oracle_mid || first_dst != oracle_dst {
        fail("reason=blur_silicon_first_bytes_mismatch");
    }
    let mut second_mid = [0u8; 256];
    let mut second_dst = [0u8; 256];
    let second = gpu_compute::blur_backdrop(
        &driver,
        &src,
        &mut second_mid,
        &mut second_dst,
        dims,
        &blur::WEIGHTS_R1_Q16,
    )
    .unwrap_or_else(|_| fail("reason=blur_silicon_second_service_failed"));
    if second.sequence == 0
        || second_dst != oracle_dst
        || second_dst != first_dst
        || second_mid != oracle_mid
    {
        fail("reason=blur_silicon_repeat_nondeterministic");
    }

    // A 33x31 surface is the largest tightly packed RGBA fixture below the
    // driver's one-page operand limit. It forces a 2x4 walker grid: eight
    // workgroups / 256 SIMD32 hardware threads, with partial groups in both X
    // and Y. The 8x8 literal above pins the byte oracle; this generated oracle
    // separately makes group-ID packing and both edge guards observable.
    const MULTI_WIDTH: usize = 33;
    const MULTI_HEIGHT: usize = 31;
    const MULTI_STRIDE: usize = MULTI_WIDTH * 4;
    const MULTI_LEN: usize = MULTI_HEIGHT * MULTI_STRIDE;
    let multi_dims = BlurDims {
        width: MULTI_WIDTH,
        height: MULTI_HEIGHT,
        stride: MULTI_STRIDE,
        radius: 1,
    };
    let mut multi_src = alloc::vec![0u8; MULTI_LEN];
    for y in 0..MULTI_HEIGHT {
        for x in 0..MULTI_WIDTH {
            let base = y * MULTI_STRIDE + x * 4;
            multi_src[base] = (x * 17 + y * 11 + 3) as u8;
            multi_src[base + 1] = (x * 7 + y * 29 + 5) as u8;
            multi_src[base + 2] = (x * 31 + y * 13 + 9) as u8;
            multi_src[base + 3] = (x * 19 + y * 23 + 0x40) as u8;
        }
    }
    let mut multi_oracle_mid = alloc::vec![0u8; MULTI_LEN];
    let mut multi_oracle_dst = alloc::vec![0u8; MULTI_LEN];
    blur::blur_pass_h(
        &multi_src,
        &mut multi_oracle_mid,
        multi_dims,
        &blur::WEIGHTS_R1_Q16,
    )
    .unwrap_or_else(|_| fail("reason=blur_silicon_multigroup_cpu_h_failed"));
    blur::blur_pass_v(
        &multi_oracle_mid,
        &mut multi_oracle_dst,
        multi_dims,
        &blur::WEIGHTS_R1_Q16,
    )
    .unwrap_or_else(|_| fail("reason=blur_silicon_multigroup_cpu_v_failed"));
    let mut multi_mid = alloc::vec![0u8; MULTI_LEN];
    let mut multi_dst = alloc::vec![0u8; MULTI_LEN];
    let multi = gpu_compute::blur_backdrop(
        &driver,
        &multi_src,
        &mut multi_mid,
        &mut multi_dst,
        multi_dims,
        &blur::WEIGHTS_R1_Q16,
    )
    .unwrap_or_else(|_| fail("reason=blur_silicon_multigroup_service_failed"));
    if multi.sequence == 0 || multi_mid != multi_oracle_mid || multi_dst != multi_oracle_dst {
        fail("reason=blur_silicon_multigroup_bytes_mismatch");
    }
    if gpu_compute::compute_admits() != 3
        || gpu_compute::compute_dispatches() != 3
        || gpu_compute::compute_degrades() != 0
        || accel::accel_intel::debug_blur_walker_kicks() != 4
        || accel::accel_intel::debug_blur_completions() != 4
        || !accel::accel_intel::debug_blur_dst_captured()
        || accel::accel_intel::debug_ppgtt_last_root() == 0
        || !accel::accel_intel::debug_last_command_oracle_match()
        || !accel::accel_intel::debug_last_execlist_oracle_match()
    {
        fail("reason=blur_silicon_acceptance_evidence_wrong");
    }
    if narrowed {
        // Capture-before-the-negative: consume any hardware records produced
        // by H-only plus the three translated two-pass submissions. Byte-exact
        // output alone is not enough to prove the complete working set was
        // mapped; even one positive-phase VT-d fault invalidates I-14(c2).
        iommu::poll_faults();
        if iommu::faults_recorded() != 0 {
            fail("reason=blur_silicon_narrowed_positive_vtd_fault");
        }
        serial_println!(
            "[ kernel ] gpu-slice4: narrowed-positive-vtd faults=0 complete_working_set_mapped=yes"
        );
        crate::log::flush();
    }

    // Rule-1 negative: disabled means floor bytes and no fifth GPU kick.
    gpu_compute::set_gpu_compute_enable(false);
    gpu_compute::reset_compute_admits();
    let mut off_mid = [0u8; 256];
    let mut off_dst = [0u8; 256];
    let off = gpu_compute::blur_backdrop(
        &driver,
        &src,
        &mut off_mid,
        &mut off_dst,
        dims,
        &blur::WEIGHTS_R1_Q16,
    )
    .unwrap_or_else(|_| fail("reason=blur_silicon_killswitch_failed"));
    if off.sequence != 0
        || off_dst != oracle_dst
        || gpu_compute::compute_dispatches() != 0
        || accel::accel_intel::debug_blur_walker_kicks() != 4
    {
        fail("reason=blur_silicon_killswitch_not_inert");
    }

    // Last phase intentionally quarantines the device. Identity run forces an
    // observer timeout after a real seqno retirement; narrowed run makes the
    // real GPU read one out-of-domain weights page and requires a real VT-d
    // fault. In both cases the service must return the exact CPU floor.
    gpu_compute::set_gpu_compute_enable(true);
    gpu_compute::reset_compute_admits();
    if narrowed {
        iommu::reset_fault_counters();
        accel::accel_intel::set_blur_force_out_of_domain_weights(true);
    } else {
        accel::accel_intel::set_blur_force_observer_timeout(true);
    }
    let mut degraded_mid = [0u8; 256];
    let mut degraded_dst = [0u8; 256];
    let degraded = gpu_compute::blur_backdrop(
        &driver,
        &src,
        &mut degraded_mid,
        &mut degraded_dst,
        dims,
        &blur::WEIGHTS_R1_Q16,
    )
    .unwrap_or_else(|_| fail("reason=blur_silicon_degrade_call_failed"));
    if degraded.sequence != 0
        || degraded_dst != oracle_dst
        || gpu_compute::compute_admits() != 0
        || gpu_compute::compute_dispatches() != 1
        || gpu_compute::compute_degrades() != 1
        || accel::accel_intel::debug_blur_walker_kicks() != 5
        || accel::accel_intel::debug_blur_completions() != 4
    {
        fail("reason=blur_silicon_timeout_floor_evidence_wrong");
    }

    if narrowed {
        let mut fault_seen = false;
        for _ in 0..2_000_000u64 {
            iommu::poll_faults();
            if iommu::faults_recorded() > 0 {
                fault_seen = true;
                break;
            }
            crate::sched::yield_now();
        }
        if !fault_seen {
            fail("reason=blur_silicon_no_vtd_fault");
        }
        let bus = (probe.bdf >> 16) as u8;
        let device = (probe.bdf >> 8) as u8;
        let function = probe.bdf as u8;
        let sid = iommu::vtd_logic::source_id(bus, device, function);
        let (arena_base, arena_len) = graphics_arena::bounds()
            .unwrap_or_else(|| fail("reason=blur_silicon_graphics_bounds_missing"));
        let fault_addr = iommu::last_fault_addr();
        if iommu::last_fault_source_id() != sid
            || (fault_addr >= arena_base && fault_addr < arena_base + arena_len)
        {
            fail("reason=blur_silicon_vtd_fault_discriminator_wrong");
        }
        pass(
            "accel_intel_blur_silicon_narrowed=ok eu_dispatch=ELSP_LRC ppgtt=48bit_context h_only_mid=byte_exact two_pass_dst=byte_exact repeat=stable multigroup_edge=byte_exact groups=2x4 hw_threads=256 floor_masked=no graphics_vtd=translated positive_vtd_faults=0 real_igpu_dma=positive out_of_domain_weights=faulted fault_sid=igpu timeout_degrade=floor device_quarantined=yes",
        );
    }

    pass(
        "accel_intel_blur_silicon=ok eu_dispatch=ELSP_LRC ppgtt=48bit_context h_only_mid=byte_exact two_pass_dst=byte_exact repeat=stable multigroup_edge=byte_exact groups=2x4 hw_threads=256 floor_masked=no kill_switch=inert forced_observer_timeout=degraded_to_floor device_quarantined=yes narrowed_run=required_separate_boot",
    );
}

