#[cfg(feature = "neo-test-q8c-blocked-kill-foreign-parked")]
extern "C" fn q8c_foreign_target_blocker() -> ! {
    use crate::sched::process;

    Q8C_FOREIGN_TARGET_STARTED.store(1, Ordering::Release);
    // This thread is force-killed while parked, so its frame must own
    // nothing across the park (CP-30, Jarvis CP-67 N1): take only the
    // channel out of the fixture clone, drop the rest, and park through the
    // syscall arms' anchor so the reap drops the channel.
    let (target_pid, channel) = {
        let fixture = q8c_foreign_fixture();
        (fixture.target_pid, fixture.target_block_channel.clone())
    };
    let pmap = {
        let proc =
            process::get(target_pid).unwrap_or_else(|| fail("reason=q8c_foreign_target_missing"));
        proc.pmap
            .as_ref()
            .cloned()
            .unwrap_or_else(|| fail("reason=q8c_foreign_target_pmap_missing"))
    };
    let ret = crate::sched::with_channel_anchor(channel, |channel| {
        crate::arch::x86_64::without_interrupts(|| {
            channel.recv(crate::ipc::EndpointSide::A, Q8C_FOREIGN_BUF_VA, 1, pmap)
        })
    });
    fail_with_hex("reason=q8c_foreign_target_woke ret", ret as u64);
}

#[cfg(feature = "neo-test-q8c-blocked-kill-foreign-parked")]
extern "C" fn q8c_foreign_grantee_waiter() -> ! {
    // `exit` never returns, so every `Arc` must be dropped before it: the
    // body runs in its own frame, which has returned by the time we exit.
    q8c_foreign_grantee_wait();
    while Q8C_FOREIGN_ALLOW_EXIT.load(Ordering::Acquire) == 0 {
        crate::sched::yield_now();
    }
    Q8C_FOREIGN_DONE.store(1, Ordering::Release);
    crate::sched::exit();
}

#[cfg(feature = "neo-test-q8c-blocked-kill-foreign-parked")]
fn q8c_foreign_grantee_wait() {
    use crate::sched::process::{self, Handle};

    Q8C_FOREIGN_WAITER_STARTED.store(1, Ordering::Release);
    let fixture = q8c_foreign_fixture();
    let (channel, side, pmap) = crate::arch::x86_64::without_interrupts(|| {
        let proc = process::get(fixture.foreign_pid)
            .unwrap_or_else(|| fail("reason=q8c_foreign_proc_missing"));
        let pmap = proc
            .pmap
            .as_ref()
            .cloned()
            .unwrap_or_else(|| fail("reason=q8c_foreign_pmap_missing"));
        let handle = proc
            .handles
            .lock()
            .get(fixture.foreign_handle_idx)
            .unwrap_or_else(|| fail("reason=q8c_foreign_granted_handle_missing"));
        match handle {
            Handle::Channel {
                channel,
                side,
                rights,
                ..
            } => {
                if side != crate::ipc::EndpointSide::A {
                    fail("reason=q8c_foreign_granted_wrong_side");
                }
                if !rights.has_meta(process::meta_rights::USE)
                    || !rights.has_semantic(process::channel_rights::RECV)
                {
                    fail("reason=q8c_foreign_granted_rights_bad");
                }
                (channel, side, pmap)
            }
            Handle::Process { .. }
            | Handle::File { .. }
            | Handle::Socket { .. }
            | Handle::TcpSocket { .. }
            | Handle::TcpListener { .. }
            | Handle::NetDial { .. }
            | Handle::Tensor { .. }
            | Handle::Model { .. } => fail("reason=q8c_foreign_granted_not_channel"),
        }
    });
    let ret =
        crate::arch::x86_64::without_interrupts(|| channel.recv(side, Q8C_FOREIGN_BUF_VA, 1, pmap));
    Q8C_FOREIGN_WAKE_RET.store(ret as u64, Ordering::Release);
    if ret != crate::errno::EPIPE {
        fail_with_hex("reason=q8c_foreign_waiter_wrong_ret ret", ret as u64);
    }
}

#[cfg(feature = "neo-test-q8c-blocked-kill-foreign-parked")]
extern "C" fn q8c_foreign_killer() -> ! {
    // Only the index: a fixture clone would still hold its channels at `exit`.
    let killer_handle_idx = q8c_foreign_fixture().killer_handle_idx;
    let rc = crate::arch::x86_64::syscall::debug_sys_kill_for_test(killer_handle_idx);
    Q8C_FOREIGN_KILL_RC.store(rc as u64, Ordering::Release);
    crate::sched::exit();
}

#[cfg(feature = "neo-test-q8c-blocked-kill-foreign-parked")]
fn wait_for_q8c_foreign_blocked(fixture: &Q8cForeignFixture) {
    for _ in 0..100_000 {
        if Q8C_FOREIGN_TARGET_STARTED.load(Ordering::Acquire) == 1
            && Q8C_FOREIGN_WAITER_STARTED.load(Ordering::Acquire) == 1
            && fixture
                .target_block_channel
                .debug_endpoint_is_recv_blocked(crate::ipc::EndpointSide::A)
            && fixture
                .foreign_channel
                .debug_endpoint_is_recv_blocked(crate::ipc::EndpointSide::A)
        {
            return;
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    fail("reason=q8c_foreign_threads_did_not_block");
}

#[cfg(feature = "neo-test-q8c-blocked-kill-foreign-parked")]
fn wait_for_q8c_foreign_kill_rc() -> i64 {
    for _ in 0..100_000 {
        let rc = Q8C_FOREIGN_KILL_RC.load(Ordering::Acquire);
        if rc != u64::MAX {
            return rc as i64;
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    fail("reason=q8c_foreign_killer_did_not_return");
}

#[cfg(feature = "neo-test-q8c-blocked-kill-foreign-parked")]
fn wait_for_q8c_foreign_wake(foreign_pid: crate::sched::process::ProcessId) -> i64 {
    for _ in 0..100_000 {
        let ret = Q8C_FOREIGN_WAKE_RET.load(Ordering::Acquire);
        if ret != u64::MAX {
            return ret as i64;
        }
        if crate::sched::process::get(foreign_pid).is_none() {
            fail("reason=q8c_foreign_process_zombified");
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    fail("reason=q8c_foreign_waiter_not_woken");
}

#[cfg(feature = "neo-test-q8c-blocked-kill-foreign-parked")]
fn wait_for_q8c_foreign_done() {
    for _ in 0..100_000 {
        if Q8C_FOREIGN_DONE.load(Ordering::Acquire) == 1 {
            return;
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    fail("reason=q8c_foreign_waiter_did_not_exit");
}

#[cfg(feature = "neo-test-q8c-blocked-kill-foreign-parked")]
fn setup_q8c_foreign_fixture() -> Q8cForeignFixture {
    use crate::ipc::EndpointSide;
    use crate::sched::process::{self, Handle, Process};

    let foreign_channel = crate::ipc::Channel::new();
    let target_block_channel = crate::ipc::Channel::new();
    let target_pmap = crate::mm::pmap::Pmap::new()
        .unwrap_or_else(|_| fail("reason=q8c_foreign_target_pmap_new_failed"));
    let foreign_pmap = crate::mm::pmap::Pmap::new()
        .unwrap_or_else(|_| fail("reason=q8c_foreign_proc_pmap_new_failed"));
    let killer_pmap = crate::mm::pmap::Pmap::new()
        .unwrap_or_else(|_| fail("reason=q8c_foreign_killer_pmap_new_failed"));
    let target = process::register(Process::new_user("q8c-foreign-target", target_pmap));
    let foreign = process::register(Process::new_user("q8c-foreign-grantee", foreign_pmap));
    let killer = process::register(Process::new_user("q8c-foreign-killer", killer_pmap));

    let source_cap_id = process::alloc_cap_id();
    process::install_cap(
        &target,
        Handle::Channel {
            channel: foreign_channel.clone(),
            side: EndpointSide::A,
            cap_id: source_cap_id,
            rights: process::full_channel_rights(),
        },
        None,
    )
    .unwrap_or_else(|_| fail("reason=q8c_foreign_source_install_failed"));
    process::install_cap(
        &target,
        Handle::Channel {
            channel: target_block_channel.clone(),
            side: EndpointSide::A,
            cap_id: process::alloc_cap_id(),
            rights: process::full_channel_rights(),
        },
        None,
    )
    .unwrap_or_else(|_| fail("reason=q8c_foreign_block_install_failed"));

    let foreign_handle_idx = process::complete_grant(
        target.pid,
        source_cap_id,
        process::full_channel_rights(),
        foreign.pid,
        process::full_channel_rights(),
    )
    .unwrap_or_else(|_| fail("reason=q8c_foreign_complete_grant_failed"));
    let killer_handle_idx = process::install_cap(
        &killer,
        Handle::Process {
            target: target.pid,
            cap_id: process::alloc_cap_id(),
            rights: process::full_process_rights(),
        },
        None,
    )
    .unwrap_or_else(|_| fail("reason=q8c_foreign_killer_handle_install_failed"));

    let fixture = Q8cForeignFixture {
        target_pid: target.pid,
        foreign_pid: foreign.pid,
        killer_pid: killer.pid,
        foreign_channel,
        target_block_channel,
        foreign_handle_idx,
        killer_handle_idx,
    };
    {
        let mut slot = Q8C_FOREIGN_FIXTURE.lock();
        *slot = Some(fixture.clone());
    }
    drop(target);
    drop(foreign);
    drop(killer);
    fixture
}

#[cfg(feature = "neo-test-q8c-blocked-kill-foreign-parked")]
fn run_q8c_blocked_kill_foreign_parked() -> ! {
    if crate::arch::x86_64::per_cpu::current_cpu_id() != 0 {
        fail("reason=test_not_on_bsp");
    }

    reset_q8c_foreign_state();
    let fixture = setup_q8c_foreign_fixture();

    let target = crate::sched::thread::Thread::new_kernel_for_process_test(
        "q8c-foreign-target-blocker",
        fixture.target_pid,
        q8c_foreign_target_blocker,
    );
    crate::sched::scheduler::push_ready(target);
    let foreign = crate::sched::thread::Thread::new_kernel_for_process_test(
        "q8c-foreign-grantee-waiter",
        fixture.foreign_pid,
        q8c_foreign_grantee_waiter,
    );
    crate::sched::scheduler::push_ready(foreign);
    wait_for_q8c_foreign_blocked(&fixture);

    let killer = crate::sched::thread::Thread::new_kernel_for_process_test(
        "q8c-foreign-killer",
        fixture.killer_pid,
        q8c_foreign_killer,
    );
    crate::sched::scheduler::push_ready(killer);

    let kill_rc = wait_for_q8c_foreign_kill_rc();
    if kill_rc != 0 {
        fail_with_hex("reason=q8c_foreign_kill_failed rc", kill_rc as u64);
    }
    if crate::sched::process::get(fixture.target_pid).is_some() {
        fail("reason=q8c_foreign_target_left_registered");
    }

    let foreign_ret = wait_for_q8c_foreign_wake(fixture.foreign_pid);
    if foreign_ret != crate::errno::EPIPE {
        fail_with_hex("reason=q8c_foreign_wrong_wake ret", foreign_ret as u64);
    }
    if crate::sched::process::get(fixture.foreign_pid).is_none() {
        fail("reason=q8c_foreign_process_not_live_after_wake");
    }
    if !fixture.foreign_channel.debug_endpoints_are_closed() {
        fail("reason=q8c_foreign_channel_not_closed");
    }
    if !fixture.target_block_channel.debug_endpoints_are_closed() {
        fail("reason=q8c_foreign_target_block_channel_not_closed");
    }

    Q8C_FOREIGN_ALLOW_EXIT.store(1, Ordering::Release);
    wait_for_q8c_foreign_done();
    wait_for_q8c_zombies_reaped();
    if crate::sched::process::get(fixture.target_pid).is_some() {
        fail("reason=q8c_foreign_target_process_left_registered");
    }
    if crate::sched::process::get(fixture.foreign_pid).is_some() {
        fail("reason=q8c_foreign_process_left_registered");
    }
    if crate::sched::process::get(fixture.killer_pid).is_some() {
        fail("reason=q8c_foreign_killer_process_left_registered");
    }
    reset_q8c_foreign_state();
    // Jarvis CP-67 N1: once every thread is reaped and the shared fixture is
    // cleared, this frame's copy is each channel's only owner. A count above 1
    // is a channel stranded on a dead thread's stack.
    let counts = (
        alloc::sync::Arc::strong_count(&fixture.target_block_channel),
        alloc::sync::Arc::strong_count(&fixture.foreign_channel),
    );
    serial_println!(
        "q8c_foreign channel_counts target_block={} foreign={}",
        counts.0,
        counts.1
    );
    if counts != (1, 1) {
        fail("reason=q8c_foreign_channel_arc_leaked");
    }
    crate::mm::frame_audit("q8c-blocked-kill-foreign-parked-post-reap");

    serial_println!(
        "NEO_TEST/1 event=PASS name={} mechanism=q8c_blocked_kill_foreign_parked kill_rc=0 foreign_wake=EPIPE foreign_zombified=false target_reaped=true channel_counts=1/1 frame_audit_clean=true",
        SCENARIO
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-q8c-close-peer-my-side-extract")]
extern "C" fn q8c_send_blocker() -> ! {
    Q8C_WORKER_STARTED.store(1, Ordering::Release);
    let pmap = alloc::sync::Arc::new(
        crate::mm::pmap::Pmap::new().unwrap_or_else(|_| fail("reason=q8c_close_pmap_new_failed")),
    );
    let ret = crate::arch::x86_64::without_interrupts(|| {
        q8c_channel_ref().send(crate::ipc::EndpointSide::A, Q8C_BUF_VA, 1, pmap)
    });
    fail_with_hex("reason=q8c_close_thread_woke ret", ret as u64);
}

#[cfg(feature = "neo-test-q8c-close-peer-my-side-extract")]
fn wait_for_q8c_send_blocked() {
    for _ in 0..100_000 {
        if Q8C_WORKER_STARTED.load(Ordering::Acquire) == 1
            && q8c_channel_ref().debug_endpoint_is_send_blocked(crate::ipc::EndpointSide::A)
        {
            return;
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    fail("reason=q8c_send_blocker_did_not_block");
}

#[cfg(feature = "neo-test-q8c-close-peer-my-side-extract")]
fn run_q8c_close_peer_my_side_extract() -> ! {
    if crate::arch::x86_64::per_cpu::current_cpu_id() != 0 {
        fail("reason=test_not_on_bsp");
    }

    reset_q8c_state();
    {
        let mut fixture = Q8C_FIXTURE.lock();
        *fixture = Some(Q8cFixture {
            pid: crate::sched::process::KERNEL_PID,
            channel: crate::ipc::Channel::new(),
        });
    }
    let worker = crate::sched::thread::Thread::new("q8c-send-blocker", q8c_send_blocker);
    crate::sched::scheduler::push_ready(worker);
    wait_for_q8c_send_blocked();

    let zombies_before = crate::sched::scheduler::debug_total_zombies();
    q8c_channel_ref().close_peer(
        crate::ipc::EndpointSide::A,
        crate::sched::process::KERNEL_PID,
    );
    if !q8c_channel_ref().debug_endpoints_are_closed() {
        fail("reason=q8c_close_channel_not_closed_both_sides");
    }
    let zombies_after = crate::sched::scheduler::debug_total_zombies();
    if zombies_after <= zombies_before {
        fail_with_hex(
            "reason=q8c_close_my_side_not_zombified zombies",
            zombies_after as u64,
        );
    }

    wait_for_q8c_zombies_reaped();
    reset_q8c_state();
    crate::mm::frame_audit("q8c-close-peer-my-side-post-reap");

    serial_println!(
        "NEO_TEST/1 event=PASS name={} mechanism=close_peer_my_side_extract detection=parked_thread_zombified channel_closed_both_sides=true frame_audit_clean=true",
        SCENARIO
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(any(
    feature = "neo-test-q7c-concurrent-munmap-smp",
    feature = "neo-test-q7c-missing-shootdown-detection"
))]
#[derive(Clone)]
struct Q7cMunmapFixture {
    pmap: alloc::sync::Arc<Pmap>,
    pid: crate::sched::process::ProcessId,
    va: u64,
    marker: u8,
}

#[cfg(any(
    feature = "neo-test-q7c-concurrent-munmap-smp",
    feature = "neo-test-q7c-missing-shootdown-detection"
))]
static Q7C_MUNMAP_FIXTURE: crate::sync::SwitchMutex<Option<Q7cMunmapFixture>> =
    crate::sync::SwitchMutex::new(None);

#[cfg(any(
    feature = "neo-test-q7c-concurrent-munmap-smp",
    feature = "neo-test-q7c-process-exit-during-thread-run",
    feature = "neo-test-q7c-missing-shootdown-detection"
))]
static Q7C_STAGE: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);

#[cfg(any(
    feature = "neo-test-q7c-concurrent-munmap-smp",
    feature = "neo-test-q7c-process-exit-during-thread-run",
    feature = "neo-test-q7c-missing-shootdown-detection"
))]
const Q7C_STAGE_TLB_WARMED: u32 = 1;
#[cfg(any(
    feature = "neo-test-q7c-concurrent-munmap-smp",
    feature = "neo-test-q7c-missing-shootdown-detection"
))]
const Q7C_STAGE_UNMAPPED: u32 = 2;
#[cfg(feature = "neo-test-q7c-concurrent-munmap-smp")]
const Q7C_STAGE_MUNMAP_FAULT_HANDLED: u32 = 3;
#[cfg(feature = "neo-test-q7c-missing-shootdown-detection")]
const Q7C_STAGE_MISSING_SHOOTDOWN_DETECTED: u32 = 3;
#[cfg(feature = "neo-test-q7c-process-exit-during-thread-run")]
const Q7C_STAGE_EXIT_REQUESTED: u32 = 2;
#[cfg(feature = "neo-test-q7c-process-exit-during-thread-run")]
const Q7C_STAGE_EXIT_DONE: u32 = 3;

#[cfg(any(
    feature = "neo-test-q7c-concurrent-munmap-smp",
    feature = "neo-test-q7c-missing-shootdown-detection"
))]
fn setup_q7c_munmap_fixture(name: &'static str, va: u64, marker: u8) -> Q7cMunmapFixture {
    let frame = alloc_frame_or_fail();
    unsafe {
        let dst = crate::mm::phys_to_virt(frame.start_address()).as_mut_ptr::<u8>();
        core::ptr::write_bytes(dst, marker, 0x1000);
    }

    let pmap = Pmap::new().unwrap_or_else(|_| fail("reason=pmap_new_failed"));
    pmap.map_user(
        VirtAddr::new(va),
        frame,
        PageTableFlags::PRESENT
            | PageTableFlags::WRITABLE
            | PageTableFlags::USER_ACCESSIBLE
            | PageTableFlags::NO_EXECUTE,
    )
    .unwrap_or_else(|_| fail("reason=map_user_failed"));

    let proc =
        crate::sched::process::register(crate::sched::process::Process::new_user(name, pmap));
    let pmap = proc
        .pmap
        .as_ref()
        .unwrap_or_else(|| fail("reason=missing_process_pmap"))
        .clone();

    Q7cMunmapFixture {
        pmap,
        pid: proc.pid,
        va,
        marker,
    }
}

#[cfg(any(
    feature = "neo-test-q7c-concurrent-munmap-smp",
    feature = "neo-test-q7c-missing-shootdown-detection"
))]
fn q7c_munmap_fixture_or_fail() -> Q7cMunmapFixture {
    Q7C_MUNMAP_FIXTURE
        .lock()
        .as_ref()
        .unwrap_or_else(|| fail("reason=missing_q7c_fixture"))
        .clone()
}

#[cfg(any(
    feature = "neo-test-q7c-concurrent-munmap-smp",
    feature = "neo-test-q7c-process-exit-during-thread-run",
    feature = "neo-test-q7c-missing-shootdown-detection"
))]
fn q7c_read_user_byte(ptr: *const u8) -> u8 {
    crate::arch::x86_64::with_user_access(|| unsafe { core::ptr::read_volatile(ptr) })
}

#[cfg(feature = "neo-test-q7c-concurrent-munmap-smp")]
fn pass_q7c_munmap_fault_from_reader() -> ! {
    EXPECTED_PAGE_FAULT.store(NO_EXPECTATION, Ordering::Release);
    crate::scenario::phase(crate::scenario::ScenarioPhase::Pass);
    frame("PASS", "trap=page_fault mechanism=q7c_munmap_shootdown");
    crate::log::flush();
    write_debug_exit_port(EXIT_SUCCESS);
    Q7C_STAGE.store(Q7C_STAGE_MUNMAP_FAULT_HANDLED, Ordering::Release);
    crate::arch::halt_forever();
}

#[cfg(feature = "neo-test-q7c-missing-shootdown-detection")]
fn pass_q7c_missing_shootdown_from_reader(stale: u8) -> ! {
    EXPECTED_PAGE_FAULT.store(NO_EXPECTATION, Ordering::Release);
    crate::scenario::phase(crate::scenario::ScenarioPhase::Pass);
    serial_println!(
        "NEO_TEST/1 event=PASS name={} detected=stale_tlb_read_after_unmap negative_feature=neo-test-missing-shootdown-negative value={:#x}",
        SCENARIO,
        stale
    );
    crate::log::flush();
    write_debug_exit_port(EXIT_SUCCESS);
    Q7C_STAGE.store(Q7C_STAGE_MISSING_SHOOTDOWN_DETECTED, Ordering::Release);
    crate::arch::halt_forever();
}

#[cfg(feature = "neo-test-q7c-concurrent-munmap-smp")]
extern "C" fn q7c_concurrent_munmap_reader() -> ! {
    let fixture = q7c_munmap_fixture_or_fail();
    let ptr = fixture.va as *const u8;
    let first = q7c_read_user_byte(ptr);
    if first != fixture.marker {
        fail_with_hex("reason=initial_read_marker_mismatch value", first as u64);
    }

    Q7C_STAGE.store(Q7C_STAGE_TLB_WARMED, Ordering::Release);
    while Q7C_STAGE.load(Ordering::Acquire) != Q7C_STAGE_UNMAPPED {
        core::hint::spin_loop();
    }

    EXPECTED_CR2.store(fixture.va, Ordering::Release);
    EXPECTED_PAGE_FAULT.store(EXPECT_Q7C_MUNMAP_PF, Ordering::Release);
    let stale = q7c_read_user_byte(ptr);
    serial_println!(
        "NEO_TEST/1 event=FAIL name={} reason=stale_read_after_munmap value={:#x}",
        SCENARIO,
        stale
    );
    debug_exit(EXIT_FAILURE);
}

#[cfg(feature = "neo-test-q7c-concurrent-munmap-smp")]
fn run_q7c_concurrent_munmap_smp() -> ! {
    if crate::arch::x86_64::per_cpu::current_cpu_id() != 0 {
        fail("reason=test_not_on_bsp");
    }

    wait_for_q7c_cpu1_or_fail();
    Q7C_STAGE.store(0, Ordering::Release);
    EXPECTED_PAGE_FAULT.store(NO_EXPECTATION, Ordering::Release);
    let fixture = setup_q7c_munmap_fixture("q7c-munmap", 0x0000_0000_0090_0000, 0x5a);
    let pid = fixture.pid;
    {
        let mut slot = Q7C_MUNMAP_FIXTURE.lock();
        *slot = Some(fixture.clone());
    }

    let reader = crate::sched::thread::Thread::new_kernel_for_process_test(
        "q7c-munmap-reader",
        pid,
        q7c_concurrent_munmap_reader,
    );
    if crate::sched::scheduler::place_thread_on_cpu(reader, 1).is_err() {
        fail("reason=place_reader_failed");
    }

    for _ in 0..1_000_000 {
        if Q7C_STAGE.load(Ordering::Acquire) == Q7C_STAGE_TLB_WARMED {
            break;
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    if Q7C_STAGE.load(Ordering::Acquire) != Q7C_STAGE_TLB_WARMED {
        fail("reason=reader_did_not_warm_tlb");
    }

    let unmapped = fixture
        .pmap
        .unmap_user(VirtAddr::new(fixture.va))
        .unwrap_or_else(|_| fail("reason=unmap_user_failed"));
    if unmapped.is_none() {
        fail("reason=unmap_user_missing_leaf");
    }
    Q7C_STAGE.store(Q7C_STAGE_UNMAPPED, Ordering::Release);

    for _ in 0..1_000_000 {
        if Q7C_STAGE.load(Ordering::Acquire) == Q7C_STAGE_MUNMAP_FAULT_HANDLED {
            debug_exit(EXIT_SUCCESS);
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    fail("reason=reader_no_terminal_after_unmap");
}

#[cfg(feature = "neo-test-q7c-missing-shootdown-detection")]
extern "C" fn q7c_missing_shootdown_reader() -> ! {
    let fixture = q7c_munmap_fixture_or_fail();
    let ptr = fixture.va as *const u8;
    let first = q7c_read_user_byte(ptr);
    if first != fixture.marker {
        fail_with_hex("reason=initial_read_marker_mismatch value", first as u64);
    }

    Q7C_STAGE.store(Q7C_STAGE_TLB_WARMED, Ordering::Release);
    while Q7C_STAGE.load(Ordering::Acquire) != Q7C_STAGE_UNMAPPED {
        core::hint::spin_loop();
    }

    EXPECTED_CR2.store(fixture.va, Ordering::Release);
    EXPECTED_PAGE_FAULT.store(EXPECT_Q7C_MISSING_SHOOTDOWN_PF, Ordering::Release);
    let stale = q7c_read_user_byte(ptr);
    if stale != fixture.marker {
        fail_with_hex("reason=stale_read_marker_mismatch value", stale as u64);
    }
    pass_q7c_missing_shootdown_from_reader(stale);
}

#[cfg(feature = "neo-test-q7c-missing-shootdown-detection")]
fn run_q7c_missing_shootdown_detection() -> ! {
    if crate::arch::x86_64::per_cpu::current_cpu_id() != 0 {
        fail("reason=test_not_on_bsp");
    }

    wait_for_q7c_cpu1_or_fail();
    Q7C_STAGE.store(0, Ordering::Release);
    EXPECTED_PAGE_FAULT.store(NO_EXPECTATION, Ordering::Release);
    let fixture = setup_q7c_munmap_fixture("q7c-missing-shootdown", 0x0000_0000_00a0_0000, 0xa7);
    let pid = fixture.pid;
    {
        let mut slot = Q7C_MUNMAP_FIXTURE.lock();
        *slot = Some(fixture.clone());
    }

    let reader = crate::sched::thread::Thread::new_kernel_for_process_test(
        "q7c-missing-shootdown-reader",
        pid,
        q7c_missing_shootdown_reader,
    );
    if crate::sched::scheduler::place_thread_on_cpu(reader, 1).is_err() {
        fail("reason=place_reader_failed");
    }

    for _ in 0..1_000_000 {
        if Q7C_STAGE.load(Ordering::Acquire) == Q7C_STAGE_TLB_WARMED {
            break;
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    if Q7C_STAGE.load(Ordering::Acquire) != Q7C_STAGE_TLB_WARMED {
        fail("reason=reader_did_not_warm_tlb");
    }

    let unmapped = fixture
        .pmap
        .unmap_user(VirtAddr::new(fixture.va))
        .unwrap_or_else(|_| fail("reason=unmap_user_failed"));
    if unmapped.is_none() {
        fail("reason=unmap_user_missing_leaf");
    }
    Q7C_STAGE.store(Q7C_STAGE_UNMAPPED, Ordering::Release);

    for _ in 0..1_000_000 {
        if Q7C_STAGE.load(Ordering::Acquire) == Q7C_STAGE_MISSING_SHOOTDOWN_DETECTED {
            debug_exit(EXIT_SUCCESS);
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    fail("reason=negative_reader_no_terminal_after_unmap");
}

#[cfg(feature = "neo-test-q7c-process-exit-during-thread-run")]
const Q7C_EXIT_VA: u64 = 0x0000_0000_00b0_0000;
#[cfg(feature = "neo-test-q7c-process-exit-during-thread-run")]
const Q7C_EXIT_MARKER: u8 = 0x6d;

#[cfg(feature = "neo-test-q7c-process-exit-during-thread-run")]
fn setup_q7c_process_exit_fixture() -> crate::sched::process::ProcessId {
    let frame = alloc_frame_or_fail();
    unsafe {
        let dst = crate::mm::phys_to_virt(frame.start_address()).as_mut_ptr::<u8>();
        core::ptr::write_bytes(dst, Q7C_EXIT_MARKER, 0x1000);
    }

    let pmap = Pmap::new().unwrap_or_else(|_| fail("reason=pmap_new_failed"));
    pmap.map_user(
        VirtAddr::new(Q7C_EXIT_VA),
        frame,
        PageTableFlags::PRESENT
            | PageTableFlags::WRITABLE
            | PageTableFlags::USER_ACCESSIBLE
            | PageTableFlags::NO_EXECUTE,
    )
    .unwrap_or_else(|_| fail("reason=map_user_failed"));

    let proc =
        crate::sched::process::register(crate::sched::process::Process::new_user("q7c-exit", pmap));
    let pid = proc.pid;
    drop(proc);
    pid
}

#[cfg(feature = "neo-test-q7c-process-exit-during-thread-run")]
extern "C" fn q7c_process_exit_runner() -> ! {
    let ptr = Q7C_EXIT_VA as *const u8;
    let first = q7c_read_user_byte(ptr);
    if first != Q7C_EXIT_MARKER {
        fail_with_hex("reason=initial_read_marker_mismatch value", first as u64);
    }

    Q7C_STAGE.store(Q7C_STAGE_TLB_WARMED, Ordering::Release);
    while Q7C_STAGE.load(Ordering::Acquire) != Q7C_STAGE_EXIT_REQUESTED {
        core::hint::spin_loop();
    }

    let second = q7c_read_user_byte(ptr);
    if second != Q7C_EXIT_MARKER {
        fail_with_hex("reason=second_read_marker_mismatch value", second as u64);
    }
    Q7C_STAGE.store(Q7C_STAGE_EXIT_DONE, Ordering::Release);
    crate::sched::exit();
}

#[cfg(feature = "neo-test-q7c-process-exit-during-thread-run")]
fn run_q7c_process_exit_during_thread_run() -> ! {
    if crate::arch::x86_64::per_cpu::current_cpu_id() != 0 {
        fail("reason=test_not_on_bsp");
    }

    wait_for_q7c_cpu1_or_fail();
    Q7C_STAGE.store(0, Ordering::Release);
    let pid = setup_q7c_process_exit_fixture();
    let runner = crate::sched::thread::Thread::new_kernel_for_process_test(
        "q7c-process-exit-runner",
        pid,
        q7c_process_exit_runner,
    );
    if crate::sched::scheduler::place_thread_on_cpu(runner, 1).is_err() {
        fail("reason=place_runner_failed");
    }

    for _ in 0..1_000_000 {
        if Q7C_STAGE.load(Ordering::Acquire) == Q7C_STAGE_TLB_WARMED {
            break;
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    if Q7C_STAGE.load(Ordering::Acquire) != Q7C_STAGE_TLB_WARMED {
        fail("reason=runner_did_not_start");
    }

    Q7C_STAGE.store(Q7C_STAGE_EXIT_REQUESTED, Ordering::Release);
    for _ in 0..1_000_000 {
        if Q7C_STAGE.load(Ordering::Acquire) == Q7C_STAGE_EXIT_DONE {
            break;
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    if Q7C_STAGE.load(Ordering::Acquire) != Q7C_STAGE_EXIT_DONE {
        fail("reason=runner_did_not_exit_loop");
    }

    for _ in 0..100_000 {
        crate::sched::yield_now();
        crate::sched::reap();
        if crate::sched::process::get(pid).is_none() {
            serial_println!(
                "NEO_TEST/1 event=PASS name={} exit_reaped=true teardown_shootdown=true q8c_blocked_kill_walk_active=true",
                SCENARIO
            );
            debug_exit(EXIT_SUCCESS);
        }
    }
    fail("reason=process_not_reaped");
}

