#[cfg(feature = "neo-test-irqsafe-mutex-bench")]
fn calibrate_cycles_per_tick() -> u64 {
    wait_for_next_tick();
    let tick = crate::arch::x86_64::timer::TICKS.load(Ordering::Acquire);
    let start = read_tsc();
    while crate::arch::x86_64::timer::TICKS.load(Ordering::Acquire) == tick {
        core::hint::spin_loop();
    }
    read_tsc().wrapping_sub(start)
}

#[cfg(feature = "neo-test-irqsafe-mutex-bench")]
fn wait_for_next_tick() {
    let tick = crate::arch::x86_64::timer::TICKS.load(Ordering::Acquire);
    while crate::arch::x86_64::timer::TICKS.load(Ordering::Acquire) == tick {
        core::hint::spin_loop();
    }
}

#[cfg(feature = "neo-test-irqsafe-mutex-bench")]
fn cycles_to_ns(cycles: u64, cycles_per_tick: u64) -> u64 {
    (((cycles as u128) * 10_000_000u128 + (cycles_per_tick as u128 / 2)) / cycles_per_tick as u128)
        as u64
}

#[cfg(feature = "neo-test-irqsafe-mutex-bench")]
fn read_tsc() -> u64 {
    let lo: u32;
    let hi: u32;
    // SAFETY: `lfence; rdtsc` only reads the CPU time-stamp counter and writes
    // EDX:EAX outputs. It does not touch memory or the stack.
    unsafe {
        asm!(
            "lfence",
            "rdtsc",
            out("eax") lo,
            out("edx") hi,
            options(nostack, preserves_flags)
        );
    }
    ((hi as u64) << 32) | lo as u64
}

#[cfg(feature = "neo-test-smep-catch")]
fn run_smep_catch() -> ! {
    if !crate::arch::x86_64::cpu_has_smep() {
        fail("reason=missing_cpuid_smep");
    }

    let user_va = 0x0000_0000_0040_0000;
    let (pmap, _frame) = user_code_page(user_va);
    EXPECTED_CR2.store(user_va, Ordering::Release);
    EXPECTED_PAGE_FAULT.store(EXPECT_SMEP_PF, Ordering::Release);

    unsafe {
        let old_cr4 = crate::arch::x86_64::read_cr4_raw();
        let (pml4, flags) = pmap.cr3();
        Cr3::write(pml4, flags);
        crate::arch::x86_64::write_cr4_raw(old_cr4 | (1 << 20));
        let f: extern "C" fn() = core::mem::transmute(user_va as usize);
        f();
    }

    fail("reason=smep_did_not_fault");
}

