// === Phase 2 BUILD-2 sub-commit 1: buddy frame allocator scenarios ======

/// Allocate at order 0 (forces split from the highest-non-empty order),
/// then free, verify coalesce returns the free list to its original
/// shape. The seed-order (the order from which the split chain
/// originated) is logged so future readers can reason about the test's
/// starting state. Per checkpoint Q3: seed must be ≥ order-1.
#[cfg(feature = "neo-test-buddy-split-coalesce")]
fn run_buddy_split_coalesce() -> ! {
    use x86_64::structures::paging::FrameAllocator;

    // Identify the seed-order: the highest non-empty order at boot.
    let seed_order = match crate::mm::frame::debug_highest_nonempty_order() {
        Some(o) if o >= 1 => o,
        Some(0) => {
            fail_with_hex("reason=seed_order_too_low order", 0);
        }
        Some(_) => unreachable!(),
        None => fail("reason=no_free_blocks_at_boot"),
    };

    // Snapshot pre-state at the seed-order and at order 0.
    let pre_seed_head = crate::mm::frame::debug_free_list_head(seed_order);
    let pre_zero_head = crate::mm::frame::debug_free_list_head(0);
    let pre_used = crate::mm::frames_in_use();

    // Allocate one frame at order 0 — forces split chain from seed_order
    // down to 0, populating intermediate orders' free lists with the
    // split-off buddy halves.
    let frame = crate::mm::with_frame_alloc(|fa| fa.allocate_frame())
        .unwrap_or_else(|| fail("reason=allocate_frame_returned_none"));
    let allocated_addr = frame.start_address().as_u64();
    let post_alloc_used = crate::mm::frames_in_use();
    if post_alloc_used != pre_used + 1 {
        fail_with_hex("reason=allocated_pages_not_plus_one used", post_alloc_used);
    }

    // Free the frame. Coalesce should chain back UP through every
    // split level, restoring the seed-order free list to its original
    // shape and emptying the intermediate orders.
    crate::mm::with_frame_alloc(|fa| fa.free(frame));
    let post_free_used = crate::mm::frames_in_use();
    if post_free_used != pre_used {
        fail_with_hex("reason=free_did_not_restore_used used", post_free_used);
    }

    // Order-0 head should be back to its pre-state (typically null).
    let post_zero_head = crate::mm::frame::debug_free_list_head(0);
    if post_zero_head != pre_zero_head {
        fail_with_hex("reason=order_zero_head_drift post", post_zero_head as u64);
    }
    // Seed-order head should be back to its pre-state too.
    let post_seed_head = crate::mm::frame::debug_free_list_head(seed_order);
    if post_seed_head != pre_seed_head {
        fail_with_hex("reason=seed_order_head_drift post", post_seed_head as u64);
    }

    serial_println!(
        "NEO_TEST/1 event=PASS name={} seed_order={} alloc_addr={:#x} used_baseline={}",
        SCENARIO,
        seed_order,
        allocated_addr,
        pre_used
    );
    debug_exit(EXIT_SUCCESS);
}

/// Allocate one block at MAX_ORDER (64 MiB at order 14). Verifies the
/// high end of the order range works. Skips with PASS-and-note if the
/// test VM doesn't have 64 MiB of free contiguous memory at MAX_ORDER
/// alignment.
/// B1a discriminator (`Plans/DECISION-2026-10-19-arthur-first-boot-model.md`
/// Amendment 1): xtask stages `/models/reclaim-probe.bin`, a deterministic
/// probe whose length is deliberately not a page multiple. The scenario:
/// - proves a consumable module is never borrowable as `'static`, and is taken
///   exactly once (the tombstone);
/// - checks every probe byte against the pattern xtask wrote;
/// - runs the forged-plan control (re-typed memmap ⇒ refused, nothing admitted);
/// - reclaims: the planned whole pages enter an admitted zone, the census
///   shows them, and `frames_in_use` is untouched;
/// - allocates, writes, reads back, frees and reallocates from the admitted
///   zone (order 0 and a 1 MiB block), ending with every admitted page free,
///   `frames_in_use` back at baseline and no refused free.
#[cfg(feature = "neo-test-boot-module-reclaim")]
fn run_boot_module_reclaim() -> ! {
    use crate::boot_modules;
    use x86_64::PhysAddr;

    const PROBE: &str = "/models/reclaim-probe.bin";
    // Must match xtask's `BOOT_MODULE_RECLAIM_PROBE_LEN` and pattern.
    const PROBE_LEN: usize = 6 * 1024 * 1024 + 2560;
    fn probe_byte(i: usize) -> u8 {
        ((i % 251) as u8) ^ 0x5a
    }

    crate::mm::boot_census("before_take");
    if boot_modules::find(PROBE).is_some() || crate::find_module_by_path_suffix(PROBE).is_some() {
        fail("reason=consumable_module_borrowable_before_take");
    }
    let Some(lease) = boot_modules::take(PROBE) else {
        fail("reason=probe_not_takeable");
    };
    if boot_modules::take(PROBE).is_some() {
        fail("reason=probe_taken_twice");
    }
    let bytes = lease.bytes();
    if bytes.len() != PROBE_LEN {
        fail_with_hex("reason=probe_len", bytes.len() as u64);
    }
    let mismatches = bytes
        .iter()
        .enumerate()
        .filter(|&(i, &b)| b != probe_byte(i))
        .count();
    if mismatches != 0 {
        fail_with_hex("reason=probe_bytes_mismatch count", mismatches as u64);
    }
    match lease.debug_forged_plan() {
        Err(boot_modules::ReclaimError::Plan(
            crate::mm::module_reclaim_logic::PlanRefusal::ForeignTypeOverlap,
        )) => {}
        other => {
            serial_println!("BOOTMOD forged_plan={:?}", other);
            fail("reason=forged_plan_not_refused");
        }
    }
    if crate::mm::frame::admitted_pages() != 0 {
        fail("reason=forged_plan_admitted_pages");
    }

    let baseline = crate::mm::frames_in_use();
    let pages = match lease.reclaim() {
        Ok(pages) => pages,
        Err(e) => {
            serial_println!("BOOTMOD reclaim_error={:?}", e);
            fail("reason=reclaim_refused");
        }
    };
    crate::mm::boot_census("after_reclaim");
    let whole = (PROBE_LEN / 4096) as u64;
    if pages + 1 < whole || pages > whole {
        fail_with_hex("reason=admitted_pages_out_of_range pages", pages);
    }
    if crate::mm::frame::admitted_pages() != pages || crate::mm::frames_in_use() != baseline {
        fail("reason=admission_accounting");
    }
    if boot_modules::find(PROBE).is_some() || boot_modules::take(PROBE).is_some() {
        fail("reason=probe_reacquirable_after_reclaim");
    }

    let write_read = |phys: u64, len: usize, seed: u8| -> bool {
        let virt = crate::mm::phys_to_virt(PhysAddr::new(phys)).as_mut_ptr::<u8>();
        // SAFETY: `phys` is a frame this scenario just allocated from the
        // admitted zone; it is HHDM-mapped (boot repair) and owned by us.
        let frame = unsafe { core::slice::from_raw_parts_mut(virt, len) };
        for (i, b) in frame.iter_mut().enumerate() {
            *b = (i as u8).wrapping_mul(7) ^ seed;
        }
        frame
            .iter()
            .enumerate()
            .all(|(i, &b)| b == (i as u8).wrapping_mul(7) ^ seed)
    };
    let Some(first) = crate::mm::with_frame_alloc(|fa| fa.allocate_admitted_blocks(0)) else {
        fail("reason=admitted_alloc_order0");
    };
    let first_addr = first.start_address().as_u64();
    if !write_read(first_addr, 4096, 0xa5) {
        fail("reason=admitted_frame_not_writable");
    }
    crate::mm::with_frame_alloc(|fa| fa.deallocate_blocks(first, 0));
    let Some(again) = crate::mm::with_frame_alloc(|fa| fa.allocate_admitted_blocks(0)) else {
        fail("reason=admitted_realloc_order0");
    };
    if again.start_address().as_u64() != first_addr {
        fail_with_hex(
            "reason=admitted_realloc_moved addr",
            again.start_address().as_u64(),
        );
    }
    crate::mm::with_frame_alloc(|fa| fa.deallocate_blocks(again, 0));
    // B1c (F4): the largest order the admitted span is guaranteed to hold
    // (the pure rule, host-proved at every alignment), allocated, written,
    // freed. OOM fails: no skip.
    let Some(big_order) =
        crate::mm::module_reclaim_logic::guaranteed_order(pages, crate::mm::frame::MAX_ORDER)
    else {
        fail("reason=admitted_span_empty");
    };
    let Some(big) = crate::mm::with_frame_alloc(|fa| fa.allocate_admitted_blocks(big_order)) else {
        fail_with_hex(
            "reason=admitted_guaranteed_order_oom order",
            big_order as u64,
        );
    };
    if !write_read(big.start_address().as_u64(), 4096 << big_order, 0x3c) {
        fail("reason=admitted_block_not_writable");
    }
    crate::mm::with_frame_alloc(|fa| fa.deallocate_blocks(big, big_order));
    serial_println!(
        "BOOTMOD admitted guaranteed_order={} pages={}",
        big_order,
        pages
    );

    crate::mm::boot_census("after_cycle");
    let (_, admitted) = crate::mm::with_frame_alloc(|fa| fa.free_pages_by_zone());
    let admitted_free: u64 = admitted.iter().flatten().sum();
    if admitted_free != pages {
        fail_with_hex("reason=admitted_pages_not_all_free free", admitted_free);
    }
    if crate::mm::frames_in_use() != baseline || crate::mm::frame::refused_frees() != 0 {
        fail("reason=frames_in_use_or_refused_frees");
    }
    serial_println!(
        "NEO_TEST/1 event=PASS name={} probe_bytes=ok tombstone=ok forged_plan=refused admitted_pages={} realloc_same=ok guaranteed_order_block=ok frames_in_use=baseline refused_frees=0",
        SCENARIO,
        pages
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-buddy-max-order")]
fn run_buddy_max_order() -> ! {
    let pre_used = crate::mm::frames_in_use();
    let max_order = crate::mm::frame::MAX_ORDER;

    let frame = crate::mm::with_frame_alloc(|fa| fa.allocate_blocks(max_order));
    match frame {
        Some(f) => {
            let pages = 1u64 << (max_order as u32);
            let post_alloc_used = crate::mm::frames_in_use();
            if post_alloc_used != pre_used + pages {
                fail_with_hex(
                    "reason=allocated_pages_not_plus_2_to_order used",
                    post_alloc_used,
                );
            }
            // Free at order 0 isn't right for an order-14 block; the
            // public free() is single-frame only in sub-commit 1. The
            // block leaks at test scope; it's fine because the test
            // exits via debug_exit (no leak audit on test exit).
            // Phase 5+ tensor allocator will need free_blocks(order);
            // not BUILD-2 sub-commit 1 scope.
            serial_println!(
                "NEO_TEST/1 event=PASS name={} max_order={} block_addr={:#x} pages={}",
                SCENARIO,
                max_order,
                f.start_address().as_u64(),
                pages
            );
            debug_exit(EXIT_SUCCESS);
        }
        None => {
            // Insufficient memory for a MAX_ORDER block — VM smaller
            // than 64 MiB or fragmented. PASS with a note so the
            // suite continues.
            serial_println!(
                "NEO_TEST/1 event=PASS name={} max_order={} skipped=true reason=oom_at_max_order",
                SCENARIO,
                max_order
            );
            debug_exit(EXIT_SUCCESS);
        }
    }
}

/// Exhaust the buddy by allocating frames in a loop. Verifies
/// `allocate_frame()` returns `None` on OOM rather than panicking
/// (Bible Article 15.3 anti-regression). Then frees the exhaustion
/// allocations and verifies the buddy recovers to a usable state.
/// Per ADR-012 §test scenarios.
#[cfg(feature = "neo-test-expect-pass-but-alloc-fail")]
fn run_expect_pass_but_alloc_fail() -> ! {
    use alloc::vec::Vec;
    use x86_64::structures::paging::{FrameAllocator, PhysFrame, Size4KiB};

    let pre_used = crate::mm::frames_in_use();
    let mut allocated: Vec<PhysFrame<Size4KiB>> = Vec::new();

    // Allocate until OOM. The kernel heap (linked_list_allocator) backs
    // the Vec; it draws from buddy via the heap's static range, so the
    // Vec's growth itself consumes some buddy pages indirectly through
    // the heap subsystem — fine, the test still observes OOM eventually.
    loop {
        match crate::mm::with_frame_alloc(|fa| fa.allocate_frame()) {
            Some(frame) => allocated.push(frame),
            None => break,
        }
        // Defensive bound: cap at ~500K frames (~2 GiB) so the test
        // can't hang forever if allocate_frame keeps returning Some
        // unexpectedly.
        if allocated.len() > 500_000 {
            fail_with_hex(
                "reason=alloc_exhaustion_did_not_return_none allocated_count",
                allocated.len() as u64,
            );
        }
    }

    let exhaustion_count = allocated.len() as u64;
    if exhaustion_count == 0 {
        fail("reason=allocator_returned_none_immediately");
    }

    // Verify counter math: used should have grown by exhaustion_count.
    let post_exhaust_used = crate::mm::frames_in_use();
    if post_exhaust_used != pre_used + exhaustion_count {
        fail_with_hex("reason=counter_skew_at_oom used", post_exhaust_used);
    }

    // Recovery: free everything and verify counter returns to baseline.
    while let Some(frame) = allocated.pop() {
        crate::mm::with_frame_alloc(|fa| fa.free(frame));
    }
    let post_recover_used = crate::mm::frames_in_use();
    if post_recover_used != pre_used {
        fail_with_hex("reason=counter_did_not_recover used", post_recover_used);
    }

    // After recovery, allocate one more to confirm the buddy is usable
    // again post-OOM.
    let recovery_frame = crate::mm::with_frame_alloc(|fa| fa.allocate_frame())
        .unwrap_or_else(|| fail("reason=allocator_dead_after_recovery"));
    crate::mm::with_frame_alloc(|fa| fa.free(recovery_frame));

    serial_println!(
        "NEO_TEST/1 event=PASS name={} exhaustion_count={} oom_returned_none=true recovery=clean",
        SCENARIO,
        exhaustion_count
    );
    debug_exit(EXIT_SUCCESS);
}

/// Round-trip identity at order 0: alloc → free → alloc returns the
/// same physical frame. Verifies the intrusive free list's LIFO
/// behavior — the most-recently-freed frame is the next-allocated one,
/// which is the cache-friendliness property the per-order intrusive
/// list provides over a FIFO alternative.
#[cfg(feature = "neo-test-buddy-alloc-free-alloc-returns-same")]
fn run_buddy_alloc_free_alloc_returns_same() -> ! {
    use x86_64::structures::paging::FrameAllocator;

    let frame_a = crate::mm::with_frame_alloc(|fa| fa.allocate_frame())
        .unwrap_or_else(|| fail("reason=first_allocate_returned_none"));
    let addr_a = frame_a.start_address().as_u64();

    crate::mm::with_frame_alloc(|fa| fa.free(frame_a));

    let frame_b = crate::mm::with_frame_alloc(|fa| fa.allocate_frame())
        .unwrap_or_else(|| fail("reason=second_allocate_returned_none"));
    let addr_b = frame_b.start_address().as_u64();

    if addr_a != addr_b {
        // LIFO discipline broken — free→alloc didn't return the freshly
        // freed frame. This isn't necessarily a correctness bug but is
        // a meaningful behavioral change worth surfacing as FAIL so
        // future BUILDs that change the free-list discipline (Phase 2
        // BUILD-4 SMP, per-CPU caches) make the change deliberately.
        serial_println!(
            "NEO_TEST/1 event=FAIL name={} reason=alloc_after_free_returned_different_frame addr_a={:#x} addr_b={:#x}",
            SCENARIO,
            addr_a,
            addr_b
        );
        debug_exit(EXIT_FAILURE);
    }

    crate::mm::with_frame_alloc(|fa| fa.free(frame_b));

    serial_println!(
        "NEO_TEST/1 event=PASS name={} addr={:#x} round_trip=identity",
        SCENARIO,
        addr_a
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-smep-catch")]
fn user_code_page(user_va: u64) -> (Pmap, PhysFrame<Size4KiB>) {
    let frame = alloc_frame_or_fail();
    unsafe {
        let dst = crate::mm::phys_to_virt(frame.start_address()).as_mut_ptr::<u8>();
        core::ptr::write_bytes(dst, 0x90, 0x1000);
        *dst = 0xC3; // ret; if SMEP is broken, control returns and we fail.
    }

    let pmap = Pmap::new().unwrap_or_else(|_| fail("reason=pmap_new_failed"));
    pmap.map_user(VirtAddr::new(user_va), frame, pmap_flags::USER_CODE)
        .unwrap_or_else(|_| fail("reason=map_user_code_failed"));
    (pmap, frame)
}

#[cfg(any(
    feature = "neo-test-smap-catch",
    feature = "neo-test-user-access-nesting"
))]
fn user_data_page(user_va: u64) -> (Pmap, PhysFrame<Size4KiB>) {
    let frame = alloc_frame_or_fail();
    unsafe {
        let dst = crate::mm::phys_to_virt(frame.start_address()).as_mut_ptr::<u8>();
        core::ptr::write_bytes(dst, 0xA5, 0x1000);
    }

    let pmap = Pmap::new().unwrap_or_else(|_| fail("reason=pmap_new_failed"));
    pmap.map_user(
        VirtAddr::new(user_va),
        frame,
        PageTableFlags::PRESENT | PageTableFlags::USER_ACCESSIBLE | PageTableFlags::NO_EXECUTE,
    )
    .unwrap_or_else(|_| fail("reason=map_user_data_failed"));
    (pmap, frame)
}

#[cfg(any(
    feature = "neo-test-smep-catch",
    feature = "neo-test-smap-catch",
    feature = "neo-test-user-access-nesting",
    feature = "neo-test-q7c-concurrent-munmap-smp",
    feature = "neo-test-q7c-process-exit-during-thread-run",
    feature = "neo-test-q7c-missing-shootdown-detection"
))]
fn alloc_frame_or_fail() -> PhysFrame<Size4KiB> {
    crate::mm::with_frame_alloc(|fa| fa.allocate_frame())
        .unwrap_or_else(|| fail("reason=out_of_frames"))
}

fn smep_error_code_matches(err: PageFaultErrorCode) -> bool {
    err.contains(PageFaultErrorCode::PROTECTION_VIOLATION)
        && err.contains(PageFaultErrorCode::INSTRUCTION_FETCH)
        && !err.contains(PageFaultErrorCode::USER_MODE)
}

fn smap_error_code_matches(err: PageFaultErrorCode) -> bool {
    err.contains(PageFaultErrorCode::PROTECTION_VIOLATION)
        && !err.contains(PageFaultErrorCode::INSTRUCTION_FETCH)
        && !err.contains(PageFaultErrorCode::USER_MODE)
}

fn frame(event: &str, extra: &str) {
    serial_println!("NEO_TEST/1 event={} name={} {}", event, SCENARIO, extra);
}

#[cfg_attr(not(feature = "neo-test-accel-intel-add-bringup"), allow(dead_code))]
fn info(extra: &str) {
    frame("INFO", extra);
    crate::log::flush();
}

/// OT-61 browser C0.5: exit code the real-std panic arm (`std-real-panic`) must
/// die with: the overlay's `abort_internal` -> `SYS_EXIT(134)` (128 + SIGABRT).
/// Kept equal to the overlay's `ABORT_EXIT_CODE` by an xtask host test.
#[cfg(feature = "neo-test-std-real-smoke")]
const STD_REAL_PANIC_EXIT_CODE: i32 = 134;

/// OT-61 browser C0.5: spawn the real-std panic arm (`/neo-std-real-panic`, a
/// sibling of `crate::spawn_std_real_smoke`'s ELF, same overlay-built std)
/// through the same ELF-loader / `spawn_user` / reap path, and return its exit
/// code. It panics on purpose; the scenario requires [`STD_REAL_PANIC_EXIT_CODE`]
/// (a hang or a 0 would mean the panic path is not a deterministic abort). Lives
/// here, not beside `spawn_std_real_smoke` in `main.rs`, so the default kernel
/// stays byte-identical (this file is compiled only for `neo-test`).
#[cfg(feature = "neo-test-std-real-smoke")]
fn spawn_std_real_panic() -> i32 {
    use crate::sched::{self, process};

    let bytes = crate::find_module_by_path_suffix("/neo-std-real-panic")
        .expect("limine: no /neo-std-real-panic module (did limine.conf/iso forget it?)");
    serial_println!(
        "[ kernel ] elf: std-real-panic module at 0x{:016x} size={} bytes",
        bytes.as_ptr() as usize,
        bytes.len()
    );
    let pid = process::spawn_user("std-real-panic", bytes, &[])
        .expect("spawn_user(std-real-panic) failed — C0.5 ELF-loader gap");
    serial_println!("[ kernel ] proc: std-real-panic spawned pid={}", pid.0);
    while process::any_user_process() {
        sched::yield_now();
        sched::reap();
    }
    let exit_code = process::take_spawned_exit_code(pid).unwrap_or_else(|| {
        serial_println!(
            "[ kernel ] proc: missing std-real-panic exit code (pid={})",
            pid.0
        );
        255
    });
    serial_println!("[ kernel ] proc: std-real-panic exit code {}", exit_code);
    exit_code
}

/// OT-61 C1.3: exit code of `std-real-threads` spawned without the
/// browser-runtime capability (its no-cap role; the binary's `NO_CAP_EXIT`).
#[cfg(feature = "neo-test-std-threads")]
const STD_THREADS_NO_CAP_EXIT_CODE: i32 = 41;

/// OT-61 C1.3: exit code of a std process whose worker thread panicked: the
/// overlay's `abort_internal` → `SYS_EXIT(134)`, ending the whole process.
#[cfg(feature = "neo-test-std-threads")]
const STD_REAL_ABORT_EXIT_CODE: i32 = 134;

/// OT-61 C1.3: spawn a real-std threads ELF (`module`: the battery or the
/// worker-panic check), with or without the root browser-runtime capability,
/// through the `spawn_user` / reap path, and return its exit code.
#[cfg(feature = "neo-test-std-threads")]
fn spawn_std_real_threads(module: &str, with_cap: bool) -> i32 {
    use crate::sched::{self, process};

    let bytes = crate::find_module_by_path_suffix(module)
        .unwrap_or_else(|| panic!("limine: no {module} module (did limine.conf/iso forget it?)"));
    let caps = [process::InheritedHandle {
        handle: process::root_browser_runtime_cap(),
        parent: None,
    }];
    let inherited: &[process::InheritedHandle] = if with_cap { &caps } else { &[] };
    let pid = process::spawn_user("std-real-threads", bytes, inherited)
        .expect("spawn_user(std-real-threads) failed");
    serial_println!(
        "[ kernel ] proc: {} spawned pid={} with_cap={}",
        module,
        pid.0,
        with_cap
    );
    while process::any_user_process() {
        sched::yield_now();
        sched::reap();
    }
    let exit_code = process::take_spawned_exit_code(pid).unwrap_or(255);
    serial_println!(
        "[ kernel ] proc: {} exit code {} (with_cap={})",
        module,
        exit_code,
        with_cap
    );
    exit_code
}

/// OT-61 C2.0: spawn a real-std ELF module (no inherited handles) through the
/// `spawn_user` / reap path and return its exit code.
#[cfg(any(feature = "neo-test-std-real-smoke", feature = "neo-test-std-entropy"))]
fn spawn_std_real_module(module: &str) -> i32 {
    spawn_std_real_module_with(module, &[])
}

/// The same, handing the module `handles` (indices 0..n). C2.1b.
#[cfg(any(
    feature = "neo-test-std-real-smoke",
    feature = "neo-test-std-entropy",
    feature = "neo-test-std-sealed",
    feature = "neo-test-std-sealed-ambient"
))]
fn spawn_std_real_module_with(
    module: &str,
    handles: &[crate::sched::process::InheritedHandle],
) -> i32 {
    use crate::sched::{self, process};

    let bytes = crate::find_module_by_path_suffix(module)
        .unwrap_or_else(|| panic!("limine: no {module} module (did limine.conf/iso forget it?)"));
    let pid = process::spawn_user("std-real-module", bytes, handles)
        .unwrap_or_else(|_| panic!("spawn_user({module}) failed"));
    serial_println!("[ kernel ] proc: {} spawned pid={}", module, pid.0);
    while process::any_user_process() {
        sched::yield_now();
        sched::reap();
    }
    let exit_code = process::take_spawned_exit_code(pid).unwrap_or(255);
    serial_println!("[ kernel ] proc: {} exit code {}", module, exit_code);
    exit_code
}

/// OT-83: the vector this `ring3_fault_*` scenario's probe raises.
#[cfg(feature = "neo-test-ring3-fault-ud")]
const RING3_FAULT_VECTOR: crate::user_fault_logic::Vector =
    crate::user_fault_logic::Vector::InvalidOpcode;
#[cfg(feature = "neo-test-ring3-fault-de")]
const RING3_FAULT_VECTOR: crate::user_fault_logic::Vector =
    crate::user_fault_logic::Vector::DivideError;
#[cfg(feature = "neo-test-ring3-fault-gp")]
const RING3_FAULT_VECTOR: crate::user_fault_logic::Vector =
    crate::user_fault_logic::Vector::GeneralProtection;
#[cfg(feature = "neo-test-ring3-fault-ss")]
const RING3_FAULT_VECTOR: crate::user_fault_logic::Vector =
    crate::user_fault_logic::Vector::StackSegment;
#[cfg(feature = "neo-test-ring3-fault-db")]
const RING3_FAULT_VECTOR: crate::user_fault_logic::Vector = crate::user_fault_logic::Vector::Debug;
#[cfg(feature = "neo-test-ring3-fault-xm")]
const RING3_FAULT_VECTOR: crate::user_fault_logic::Vector =
    crate::user_fault_logic::Vector::SimdFloatingPoint;
#[cfg(feature = "neo-test-ring3-fault-mf")]
const RING3_FAULT_VECTOR: crate::user_fault_logic::Vector =
    crate::user_fault_logic::Vector::X87FloatingPoint;

/// OT-83: spawn the user ELF staged as the module ending in `suffix` through
/// the ordinary loader / `spawn_user` / reap path, wait for it, and return
/// `(this scenario's vector name, exit code)`.
#[cfg(any(
    feature = "neo-test-ring3-fault-ud",
    feature = "neo-test-ring3-fault-de",
    feature = "neo-test-ring3-fault-gp",
    feature = "neo-test-ring3-fault-ss",
    feature = "neo-test-ring3-fault-db",
    feature = "neo-test-ring3-fault-xm",
    feature = "neo-test-ring3-fault-mf"
))]
fn ring3_fault_probe_run(suffix: &str, name: &'static str) -> (&'static str, i32) {
    use crate::sched::{self, process};

    let bytes = crate::find_module_by_path_suffix(suffix)
        .unwrap_or_else(|| panic!("limine: no {suffix} module (did the ISO forget it?)"));
    let pid = process::spawn_user(name, bytes, &[])
        .unwrap_or_else(|e| panic!("spawn_user({name}) failed: {e:?}"));
    serial_println!("[ ring3-fault ] spawned {} pid={}", name, pid.0);
    while process::any_user_process() {
        sched::yield_now();
        sched::reap();
    }
    let code = process::take_spawned_exit_code(pid).unwrap_or(255);
    serial_println!("[ ring3-fault ] {} exit code {}", name, code);
    (RING3_FAULT_VECTOR.name(), code)
}

#[cfg(any(
    feature = "neo-test-ring3-fault-ud",
    feature = "neo-test-ring3-fault-de",
    feature = "neo-test-ring3-fault-gp",
    feature = "neo-test-ring3-fault-ss",
    feature = "neo-test-ring3-fault-db",
    feature = "neo-test-ring3-fault-xm",
    feature = "neo-test-ring3-fault-mf"
))]
fn pass_ring3_fault(code: i32) -> ! {
    let mut line = alloc::string::String::new();
    let _ = core::fmt::Write::write_fmt(
        &mut line,
        format_args!(
            "ring3_fault={} process_killed_exit={} kernel_alive=true second_process_exit=0 opens=ot83",
            RING3_FAULT_VECTOR.name(),
            code
        ),
    );
    pass(&line)
}

/// OT-83 control: set just before the deliberate ring-0 `ud2`, so a #UD
/// raised anywhere earlier in boot cannot count as the control's pass.
#[cfg(feature = "neo-test-ring0-fault-halts")]
static RING0_FAULT_ARMED: core::sync::atomic::AtomicBool =
    core::sync::atomic::AtomicBool::new(false);

/// OT-83 control: called by `idt::halt_kernel_fault` on the ring-0 halt path.
/// PASS only for the armed ring-0 #UD; anything else fails by name.
#[cfg(feature = "neo-test-ring0-fault-halts")]
pub fn ring0_fault_reached_halt(vector: crate::user_fault_logic::Vector) {
    if RING0_FAULT_ARMED.load(Ordering::Acquire)
        && vector == crate::user_fault_logic::Vector::InvalidOpcode
    {
        pass("ring0_fault=#UD reached=halt_kernel_fault kill_path=not_taken opens=ot83");
    }
    serial_println!(
        "NEO_TEST/1 event=FAIL name={} reason=unexpected_ring0_fault vector={} armed={}",
        SCENARIO,
        vector.name(),
        RING0_FAULT_ARMED.load(Ordering::Acquire)
    );
    debug_exit(EXIT_FAILURE);
}

fn pass(extra: &str) -> ! {
    crate::scenario::phase(crate::scenario::ScenarioPhase::Pass);
    frame("PASS", extra);
    debug_exit(EXIT_SUCCESS);
}

fn fail(extra: &str) -> ! {
    crate::scenario::phase(crate::scenario::ScenarioPhase::Fail("FAIL"));
    frame("FAIL", extra);
    debug_exit(EXIT_FAILURE);
}

fn fail_with_hex(prefix: &str, value: u64) -> ! {
    crate::scenario::phase(crate::scenario::ScenarioPhase::Fail("FAIL"));
    serial_println!(
        "NEO_TEST/1 event=FAIL name={} {}={:#x}",
        SCENARIO,
        prefix,
        value
    );
    debug_exit(EXIT_FAILURE);
}

#[cfg(feature = "neo-test-tensor-create-query-drop")]
pub fn finish_tensor_create_query_drop_from_user_exit(code: i32) -> ! {
    let (allocs, frees) = crate::ai::tensor::debug_storage_counts();
    if code == 0 && allocs > 0 && allocs == frees {
        pass(
            "tensor=ok refcount=ok stale_handle=EBADF storage_freed=ok immutable_mutation_deferred=no_mutator",
        );
    }
    if code != 0 {
        serial_println!(
            "NEO_TEST/1 event=FAIL name={} reason=tensor_user_exit_nonzero code={}",
            SCENARIO,
            code
        );
        debug_exit(EXIT_FAILURE);
    }
    serial_println!(
        "NEO_TEST/1 event=FAIL name={} reason=tensor_storage_refcount_leak allocs={} frees={}",
        SCENARIO,
        allocs,
        frees
    );
    debug_exit(EXIT_FAILURE);
}

