// ── Zenbook lane: the boot log on screen ──

/// `fb-progress-console` mirrors kernel log lines onto the framebuffer:
/// - it is drawing by the time the scenario runs (started after `mm::init`);
/// - a printed marker line lights pixels in the text row it was printed on;
/// - the scenario phase indicator (an overlay) does not stop it;
/// - the first other drawer (`fb::fill_rect`) stops it.
#[cfg(feature = "neo-test-fb-progress")]
fn run_fb_progress_console() -> ! {
    use crate::drivers::fb::{self, Color, progress};

    if !progress::active_for_test() {
        fail("reason=fb_progress_not_active");
    }
    let (row, scale) =
        progress::cursor_for_test().unwrap_or_else(|| fail("reason=fb_progress_no_console"));
    serial_println!("FBPROG MARK 0123456789 ABCDEFGHIJ");
    let (width, _) = fb::dimensions();
    let (y0, y1) = (row * 16 * scale, (row + 1) * 16 * scale);
    let mut lit = 0usize;
    for y in y0..y1 {
        for x in 0..(34 * 8 * scale).min(width) {
            if fb::read_pixel(x, y) == Some(Color::TEXT.0) {
                lit += 1;
            }
        }
    }
    serial_println!("fb_progress row={} scale={} lit_pixels={}", row, scale, lit);
    if lit == 0 {
        fail("reason=fb_progress_line_not_drawn");
    }
    // The phase indicator is an overlay in the reserved band: it must not
    // stop the mirror.
    crate::scenario::phase(crate::scenario::ScenarioPhase::Cleanup);
    if !progress::active_for_test() {
        fail("reason=fb_progress_stopped_by_phase_indicator");
    }
    fb::fill_rect(0, 0, 1, 1, Color::BLACK);
    if progress::active_for_test() {
        fail("reason=fb_progress_did_not_yield");
    }
    pass(&alloc::format!(
        "fb_progress_console=ok row={row} scale={scale} lit_pixels={lit} overlay_kept=yes yields_to_drawers=yes"
    ));
}

/// Rows `[row, row + rows)` of the progress console: how many pixels are
/// lit in the text colour.
#[cfg(feature = "neo-test-fb-panic-holding-serial")]
fn fb_console_lit(row: usize, rows: usize, scale: usize) -> usize {
    use crate::drivers::fb::{self, Color};
    let (width, height) = fb::dimensions();
    let (y0, y1) = (row * 16 * scale, ((row + rows) * 16 * scale).min(height));
    let mut lit = 0;
    for y in y0..y1 {
        for x in 0..width {
            if fb::read_pixel(x, y) == Some(Color::TEXT.0) {
                lit += 1;
            }
        }
    }
    lit
}

/// Where the panic text must land, and what was lit there before it.
#[cfg(feature = "neo-test-fb-panic-holding-serial")]
static FB_PANIC_AT: spin::Mutex<Option<(usize, usize, usize)>> = spin::Mutex::new(None);

/// Draws made by the CPU-1 drawer (R1-3).
#[cfg(feature = "neo-test-fb-panic-holding-serial")]
static FB_PANIC_AP_DRAWS: core::sync::atomic::AtomicU64 = core::sync::atomic::AtomicU64::new(0);

/// R1-3: a live CPU that keeps drawing in the top-right corner (row 0, away
/// from the console rows the verdict counts), as a compositor would.
#[cfg(feature = "neo-test-fb-panic-holding-serial")]
extern "C" fn fb_panic_ap_drawer() -> ! {
    use crate::drivers::fb::{self, Color};
    loop {
        let (width, _) = fb::dimensions();
        fb::fill_rect(width.saturating_sub(16), 0, 16, 16, Color::ELECTRIC_BLUE);
        FB_PANIC_AP_DRAWS.fetch_add(1, Ordering::AcqRel);
        for _ in 0..10_000 {
            core::hint::spin_loop();
        }
    }
}

/// Janus F4: a CPU that panics while holding the serial lock (mid-print)
/// must still get its panic onto the screen, and onto the UART. The scenario
/// takes `SERIAL`, never releases it, and panics; `panic_failed` then checks
/// the panic lines lit the console rows below the cursor and reports PASS
/// over the UART while the lock is still held. The control
/// (`-control`) restores the blocking acquire: the panic path spins on the
/// lock forever and the run fails by timeout.
#[cfg(feature = "neo-test-fb-panic-holding-serial")]
fn run_fb_panic_holding_serial() -> ! {
    use crate::drivers::fb::progress;

    if !progress::active_for_test() {
        fail("reason=fb_progress_not_active");
    }
    let (row, scale) =
        progress::cursor_for_test().unwrap_or_else(|| fail("reason=fb_progress_no_console"));
    // R1-3: another CPU draws throughout (it takes the screen, so the mirror
    // is off until the panic takes it back).
    if !crate::sched::scheduler::cpu_scheduler_ready(1) {
        fail("reason=cpu1_scheduler_not_ready (needs NEO_SMP>=2)");
    }
    let drawer = crate::sched::thread::Thread::new("fb-panic-ap-drawer", fb_panic_ap_drawer);
    if crate::sched::scheduler::place_thread_on_cpu(drawer, 1).is_err() {
        fail("reason=fb_panic_ap_drawer_not_placed");
    }
    for _ in 0..1_000_000 {
        if FB_PANIC_AP_DRAWS.load(Ordering::Acquire) > 0 {
            break;
        }
        crate::sched::yield_now();
    }
    if FB_PANIC_AP_DRAWS.load(Ordering::Acquire) == 0 {
        fail("reason=fb_panic_ap_drawer_never_drew");
    }
    let before = fb_console_lit(row, 6, scale);
    *FB_PANIC_AT.lock() = Some((row, scale, before));
    serial_println!(
        "fb_panic_holding_serial: row={} scale={} lit_before={} - panicking holding SERIAL",
        row,
        scale,
        before
    );
    // #52 review item 4: the same, through a kernel-mode #GP.
    #[cfg(feature = "neo-test-fb-gp-holding-serial")]
    crate::drivers::console::serial::gp_holding_lock_for_test();
    #[cfg(not(feature = "neo-test-fb-gp-holding-serial"))]
    crate::drivers::console::serial::panic_holding_lock_for_test();
}

/// `fb_panic_holding_serial`, from the panic handler: the expected panic.
/// Prints and exits directly, as the other expected-panic verdicts do (no
/// phase overlay on the panic path). A failed check returns, and the panic
/// fails the run as any other.
#[cfg(feature = "neo-test-fb-panic-holding-serial")]
fn fb_panic_holding_serial_verdict() {
    let Some((row, scale, before)) = *FB_PANIC_AT.lock() else {
        serial_println!("fb_panic_holding_serial: unexpected panic before the scenario");
        return;
    };
    // R1-3: the CPU-1 drawer must have stopped at its first draw after the
    // panic (one draw may have been in flight), and the mirror stayed on.
    let settle = |draws: &mut u64| {
        for _ in 0..20_000_000 {
            core::hint::spin_loop();
        }
        let now = FB_PANIC_AP_DRAWS.load(Ordering::Acquire);
        let moved = now - *draws;
        *draws = now;
        moved
    };
    let mut draws = FB_PANIC_AP_DRAWS.load(Ordering::Acquire);
    settle(&mut draws);
    let ap_moved = settle(&mut draws);
    let active = crate::drivers::fb::progress::active_for_test();
    let lit = fb_console_lit(row, 6, scale);
    let held = crate::drivers::console::serial::locked_for_test();
    if ap_moved != 0 || !active {
        serial_println!(
            "fb_panic_holding_serial: verdict FAIL reason=other_cpu_still_drawing ap_draws_moved={} mirror_active={}",
            ap_moved,
            active
        );
        return;
    }
    // The panic's own lines reached the screen: at least the 20 cells of
    // "!!  KERNEL PANIC  !!" were drawn after the takeover, and the rows
    // below the cursor are lit (the rows held other text before, so a pixel
    // count alone cannot tell old from new).
    let cells = crate::drivers::fb::progress::panic_cells_for_test();
    if !held || cells < 20 || lit == 0 {
        serial_println!(
            "fb_panic_holding_serial: verdict FAIL serial_lock_held={} panic_cells={} lit_before={} lit_after={}",
            held,
            cells,
            before,
            lit
        );
        return;
    }
    // #52 review item 4: the panic came from the #GP's fatal path.
    #[cfg(feature = "neo-test-fb-gp-holding-serial")]
    if !crate::arch::x86_64::idt::fatal_gp_seen_for_test() {
        serial_println!("fb_gp_holding_serial: verdict FAIL reason=panic_not_from_gp_fatal_path");
        return;
    }
    #[cfg(feature = "neo-test-fb-gp-holding-serial")]
    serial_println!("fb_gp_holding_serial: fatal_trap=#GP panic_first=yes");
    serial_println!(
        "NEO_TEST/1 event=PASS name={} fb_panic_holding_serial=ok serial_lock_held=yes panic_cells={} lit_after={} serial=raw other_cpu=halted mirror_active=yes",
        SCENARIO,
        cells,
        lit
    );
    debug_exit(EXIT_SUCCESS);
}

// ── Zenbook lane: an unmarked disk is never written ──

/// Disk 0 (xtask `prepare_unmarked_storage_disk`) carries no valid marker,
/// only the BARE pre-seal magics at every probe offset (what armed a disk
/// before the markers were sealed). The kernel must never write it:
/// - a raw `write_block` is refused (`BlockError::WriteRefused`);
/// - the bare-metal log sink refuses to install on it;
/// - its bytes read back unchanged.
///
/// Disk 1 (`prepare_log_sink_storage_disk`) carries a sealed log-sink header
/// and nothing else, so only the sink's 16 MiB region is armed:
/// - a write inside the region lands;
/// - a write to LBA 0, and one straddling the region's end, are refused.
///
/// The control (`neo-test-block-write-guard-control`) builds the guard off:
/// the write lands and the scenario fails `unmarked_disk_written`.
/// OT-87 R4.1 (THINK §2a): the install claim on real drivers. Disk 0 is a
/// blank virtio disk with `serial=LOGANSOS-R41`, disk 1 one without a serial.
/// The rest of the §2a table is host KATs (`tools/install-claim-logic-tests`).
#[cfg(feature = "neo-test-install-claim")]
fn run_install_claim_identity() -> ! {
    use crate::drivers::block::claim_logic::Enumerated;
    use crate::drivers::block::claim_logic::{ClaimKind, Refusal};
    use crate::drivers::block::{self, BlockError, DmaBuffer, install_claim};
    // Five disks (tools/xtask): virtio-blk with serial=, virtio-blk without,
    // NVMe, SATA (AHCI), and a virtio twin of the first (same serial and
    // size, one sector different). Each driver reads its own identity.
    let rows = install_claim::enumerate();
    if rows.len() != 5 {
        fail("reason=install_claim_expected_five_disks");
    }
    let driver = |row: &Enumerated| {
        block::get_device(row.token.slot)
            .map(|d| d.identity().driver)
            .unwrap_or("")
    };
    let field = |row: &Enumerated, model: bool| {
        row.identity
            .as_ref()
            .map(|i| {
                if model {
                    i.model.clone()
                } else {
                    i.serial.clone()
                }
            })
            .unwrap_or_default()
    };
    let available = |row: &Enumerated| row.identity.as_ref().is_some_and(|i| i.available());
    let find = |want: &str, with_identity: bool| {
        rows.iter()
            .find(|r| driver(r) == want && available(r) == with_identity)
            .unwrap_or_else(|| fail("reason=install_claim_disk_missing"))
    };
    let a = find("virtio-blk", true);
    let b = find("virtio-blk", false);
    let nvme = find("nvme", true);
    let sata = find("ahci", true);
    let twin = rows
        .iter()
        .find(|r| r.token.slot != a.token.slot && r.identity == a.identity)
        .unwrap_or_else(|| fail("reason=install_claim_disk_missing"));
    for row in [a, b, nvme, sata, twin] {
        serial_println!(
            "install_claim identity slot={} driver={} serial={:?} model={:?} available={}",
            row.token.slot,
            driver(row),
            field(row, false),
            field(row, true),
            available(row)
        );
    }
    // virtio-blk has no model string; QEMU's NVMe and ATA models are fixed.
    if field(a, false) != "LOGANSOS-R41" {
        fail("reason=install_claim_virtio_get_id_serial");
    }
    if field(nvme, false) != "neoplutarch-nvme2" || field(nvme, true) != "QEMU NVMe Ctrl" {
        fail("reason=install_claim_nvme_identify_serial_model");
    }
    if field(sata, false) != "LOGANSOS-SATA" || field(sata, true) != "QEMU HARDDISK" {
        fail("reason=install_claim_ata_identify_serial_model");
    }
    // Capacity and sector size are read live from each device (Identify
    // Namespace, IDENTIFY words 100–103 and 106, the virtio config) and agree
    // with the probe's geometry.
    for row in &rows {
        let device = block::get_device(row.token.slot)
            .unwrap_or_else(|| fail("reason=install_claim_disk_missing"));
        let g = device.geometry();
        let id = row
            .identity
            .as_ref()
            .unwrap_or_else(|| fail("reason=install_claim_identity_missing"));
        if id.capacity_bytes != row.fingerprint.capacity
            || id.capacity_bytes != g.block_count * g.logical_block_size as u64
            || id.sector_size != g.logical_block_size
        {
            fail("reason=install_claim_live_capacity_disagrees");
        }
    }
    for row in &rows {
        let state = block::get_device(row.token.slot).map(|d| d.media_state());
        if state
            != Some(block::MediaState {
                generation: 0,
                alive: true,
            })
        {
            fail("reason=install_claim_media_state_not_initial");
        }
    }
    // Replacement with the same tuple (THINK §2a): a's enumeration presented
    // with the twin's token. Identity matches, the first MiB doesn't: refused
    // before any write, and the twin reads as it did.
    let mut forged = a.clone();
    forged.token = twin.token;
    if !matches!(
        install_claim::claim(&forged, ClaimKind::Fresh, None),
        Err(Refusal::ChangedSinceEnumeration)
    ) {
        fail("reason=install_claim_same_tuple_replacement_allowed");
    }
    if install_claim::enumerate()
        .iter()
        .find(|r| r.token == twin.token)
        .map(|r| r.fingerprint)
        != Some(twin.fingerprint)
    {
        fail("reason=install_claim_twin_written");
    }
    // A claimed write, flush, read-back and boundary check on each driver.
    for row in [nvme, sata] {
        let mut writer = install_claim::claim(row, ClaimKind::Fresh, None)
            .unwrap_or_else(|_| fail("reason=install_claim_fresh_refused"));
        let pattern = [0xa5_u8; 8192];
        let mut back = [0u8; 8192];
        if writer.write(8 * 512, &pattern).is_err()
            || writer.flush().is_err()
            || writer.read(8 * 512, &mut back).is_err()
            || back != pattern
            || writer.boundary().is_err()
        {
            fail("reason=install_claim_claimed_write_failed");
        }
    }
    // A destructive claim on the disk without identity is refused.
    match install_claim::claim(b, ClaimKind::Destructive, None) {
        Err(Refusal::IdentityUnavailable) => {}
        _ => fail("reason=install_claim_destructive_without_identity_allowed"),
    }
    // A stale token is refused.
    let mut stale = a.clone();
    stale.token.generation += 1;
    if !matches!(
        install_claim::claim(&stale, ClaimKind::Fresh, None),
        Err(Refusal::StaleToken)
    ) {
        fail("reason=install_claim_stale_token_allowed");
    }
    // The boot disk is refused.
    let mut booted = a.clone();
    booted.disk_guid = Some([0x4c; 16]);
    if !matches!(
        install_claim::claim(&booted, ClaimKind::Fresh, Some([0x4c; 16])),
        Err(Refusal::BootDisk)
    ) {
        fail("reason=install_claim_boot_disk_allowed");
    }
    let mut writer = match install_claim::claim(a, ClaimKind::Fresh, None) {
        Ok(writer) => writer,
        Err(_) => fail("reason=install_claim_fresh_refused"),
    };
    if !matches!(
        install_claim::claim(a, ClaimKind::Fresh, None),
        Err(Refusal::AlreadyClaimed)
    ) {
        fail("reason=install_claim_second_claim_allowed");
    }
    // The guard still refuses an ordinary write to the claimed disk, and
    // (R4.4, Muse's R4.3 note 1(a)) refuses it because the claim holds the
    // device, before the arming is consulted: xtask requires the claim's
    // refusal line, which only that check prints, so this holds even for an
    // extent the guard would arm (a Finish target's NeoFS partition).
    let device =
        block::get_device(a.token.slot).unwrap_or_else(|| fail("reason=install_claim_no_device"));
    let buffer = DmaBuffer::alloc_zeroed(512).unwrap_or_else(|_| fail("reason=install_claim_dma"));
    if device.write_block(4, core::slice::from_ref(&buffer)) != Err(BlockError::WriteRefused) {
        fail("reason=install_claim_guard_bypassed");
    }
    // The claimed write lands, is flushed, reads back, and passes the
    // step-boundary check (the expected windows carry it).
    let pattern = [0x5a_u8; 4096];
    if writer.write(4 * 512, &pattern).is_err() || writer.flush().is_err() {
        fail("reason=install_claim_claimed_write_failed");
    }
    let mut back = [0u8; 4096];
    if writer.read(4 * 512, &mut back).is_err() || back != pattern {
        fail("reason=install_claim_read_back_mismatch");
    }
    if writer.boundary().is_err() {
        fail("reason=install_claim_boundary_failed");
    }
    drop(writer);
    // The used claim's enumeration has expired (Muse's R4.1 review, item 1):
    // the slot moved to a new generation when the writer that wrote dropped.
    if !matches!(
        install_claim::claim(a, ClaimKind::Fresh, None),
        Err(Refusal::StaleToken)
    ) {
        fail("reason=install_claim_used_enumeration_allowed");
    }
    let again = install_claim::enumerate();
    let a_again = again
        .iter()
        .find(|r| r.token.slot == a.token.slot)
        .unwrap_or_else(|| fail("reason=install_claim_disk_missing"));
    // The old windows under the new token no longer match the disk: refused.
    let mut old_windows = a.clone();
    old_windows.token = a_again.token;
    if !matches!(
        install_claim::claim(&old_windows, ClaimKind::Fresh, None),
        Err(Refusal::ChangedSinceEnumeration)
    ) {
        fail("reason=install_claim_stale_enumeration_allowed");
    }
    // A fresh enumeration claims it again; the release reopened the device.
    match install_claim::claim(a_again, ClaimKind::Fresh, None) {
        Ok(writer) => drop(writer),
        Err(_) => fail("reason=install_claim_reclaim_refused"),
    }
    pass(
        "install_claim_identity=ok get_id=LOGANSOS-R41 nvme_identify=ok ata_identify=ok \
         no_serial=unavailable same_tuple_replacement=refused claimed_write_nvme=ok \
         claimed_write_ahci=ok \
         destructive=refused stale_token=refused boot_disk=refused second_claim=refused \
         guard_write=refused_by_claim claimed_write=ok boundary=ok used_enumeration=refused \
         stale_enumeration=refused",
    );
}

#[cfg(feature = "neo-test-block-write-guard")]
fn run_block_write_guard() -> ! {
    use crate::drivers::block::{self, BlockError, DmaBuffer};
    use crate::log::block_sink::{BlockDeviceLogSink, DEFAULT_REGION_OFFSET, DEFAULT_REGION_SIZE};

    // Judge contention (Plans/NOTE-2026-10-25-write-guard-judge-hang.md, CP-37):
    // a kthread starts judging disk 1 and is held inside the judgement's first
    // read; this thread then asks for the same judgement with interrupts OFF,
    // as a write syscall does. It must wait yielding with interrupts on, never
    // spin on the unfinished `Once` at IF=0 (the `arthur_memory_forgetting`
    // hang). Skipped under the guard-off control, whose judgement reads nothing.
    #[cfg(not(feature = "neo-test-block-write-guard-control"))]
    {
        let tick = || crate::arch::x86_64::timer::TICKS.load(Ordering::Acquire);
        block::pause_next_judgement_for_test(20);
        let judge = crate::sched::kthread::spawn_owned(
            "guard-judge",
            |_stop: crate::sched::kthread::KthreadStopToken| {
                let _ = block::writes_allowed(1);
                crate::sched::kthread::KthreadExitState::Success
            },
        );
        let deadline = tick() + 500;
        while !block::judgement_paused_for_test() {
            if tick() > deadline {
                fail("reason=judge_never_paused");
            }
            crate::sched::yield_now();
        }
        let (waits0, spins0) = block::judge_wait_counts_for_test();
        let waiter = crate::arch::x86_64::without_interrupts(|| block::writes_allowed(1));
        let (waits, spins) = block::judge_wait_counts_for_test();
        let _ = judge.join();
        serial_println!(
            "block_write_guard judge_contention waiter={:?} waited_yielding={} spun_if_off={}",
            waiter,
            waits - waits0,
            spins - spins0
        );
        if spins != spins0 {
            fail("reason=judge_waiter_spun_with_interrupts_off");
        }
        if waits == waits0 {
            fail("reason=judge_waiter_did_not_wait");
        }
        if waiter != Some(true) {
            fail("reason=judge_contention_wrong_judgement");
        }
    }

    const SEED: &[u8] = b"NEOPLUTARCH_UNMARKED_DISK_NEVER_WRITTEN";
    let Some(device) = block::get_device(0) else {
        fail("reason=guard_no_block_device");
    };
    let block_size = device.geometry().logical_block_size as usize;
    // OT-87 R4.3: the 4K variant runs only on 4096-byte logical sectors.
    #[cfg(feature = "neo-test-block-write-guard-4k")]
    for index in 0..2 {
        let size = block::get_device(index).map(|d| d.geometry().logical_block_size);
        serial_println!(
            "block_write_guard_4k device={} logical_block_size={:?}",
            index,
            size
        );
        if size != Some(4096) {
            fail("reason=guard_4k_disk_is_not_4096");
        }
    }
    let read_lba0 = || -> alloc::vec::Vec<u8> {
        let buffer =
            DmaBuffer::alloc_zeroed(block_size).unwrap_or_else(|_| fail("reason=guard_dma"));
        if device
            .read_block(0, core::slice::from_ref(&buffer))
            .is_err()
        {
            fail("reason=guard_read_failed");
        }
        // SAFETY: filled by the read; not shared with a request.
        unsafe { buffer.as_slice() }.to_vec()
    };
    let before = read_lba0();
    if !before.starts_with(SEED) {
        fail("reason=guard_seed_missing");
    }

    // A raw write of a different pattern to LBA 0.
    let pattern = DmaBuffer::alloc_zeroed(block_size).unwrap_or_else(|_| fail("reason=guard_dma"));
    // SAFETY: a fresh buffer owned here.
    unsafe { pattern.as_mut_slice().fill(0xee) };
    let write = device.write_block(0, core::slice::from_ref(&pattern));
    serial_println!("block_write_guard raw_write={:?}", write);

    // The bare-metal log sink on the same disk.
    let sink = BlockDeviceLogSink::new(device.clone(), DEFAULT_REGION_OFFSET, DEFAULT_REGION_SIZE)
        .unwrap_or_else(|_| fail("reason=guard_sink_geometry"));
    let sink_install = sink.install();
    serial_println!("block_write_guard sink_install={:?}", sink_install);

    let after = read_lba0();
    let unchanged = after == before;
    serial_println!(
        "block_write_guard lba0_unchanged={} writes_allowed={:?}",
        unchanged,
        block::writes_allowed(0)
    );
    if !unchanged {
        fail("reason=unmarked_disk_written");
    }
    if write != Err(BlockError::WriteRefused) {
        fail("reason=guard_write_not_refused");
    }
    if sink_install != Err(BlockError::WriteRefused) {
        fail("reason=guard_sink_not_refused");
    }
    if block::writes_allowed(0) != Some(false) {
        fail("reason=guard_state_not_refused");
    }

    // Disk 1: the sealed sink header arms its region and nothing else.
    let Some(sink_disk) = block::get_device(1) else {
        fail("reason=guard_no_sink_disk");
    };
    let block_size = sink_disk.geometry().logical_block_size as u64;
    let write_at = |offset: u64| {
        let buffer = DmaBuffer::alloc_zeroed(block_size as usize)
            .unwrap_or_else(|_| fail("reason=guard_dma"));
        // SAFETY: a fresh buffer owned here.
        unsafe { buffer.as_mut_slice().fill(0x5a) };
        sink_disk.write_block(offset / block_size, core::slice::from_ref(&buffer))
    };
    let inside = write_at(DEFAULT_REGION_OFFSET + 8192);
    let lba0 = write_at(0);
    let straddle = write_at(DEFAULT_REGION_OFFSET + DEFAULT_REGION_SIZE);
    serial_println!(
        "block_write_guard sink_disk inside={:?} lba0={:?} past_region={:?}",
        inside,
        lba0,
        straddle
    );
    if inside.is_err() {
        fail("reason=guard_sink_region_not_armed");
    }
    if lba0 != Err(BlockError::WriteRefused) || straddle != Err(BlockError::WriteRefused) {
        fail("reason=guard_sink_arming_not_scoped");
    }
    pass(
        "block_write_guard=ok raw_write=refused sink=refused lba0_unchanged=yes sink_disk=region_only judge_wait=yielding",
    );
}

// ── CP-68: the local APIC in x2APIC mode ──

/// CP-68: the kernel boots and runs its SMP IPI paths with the local APICs in
/// x2APIC mode (xtask boots this scenario on `-cpu max,+x2apic`).
///
/// - The resolved mode is x2APIC (Limine was asked for it and enabled it).
/// - Reschedule IPIs: 16 rounds to every AP, each confirmed by that CPU's
///   receive counter (the ICR's 32-bit destination and the EOI MSR).
/// - TLB shootdowns: 16 real broadcast shootdowns; every target ACKs with no
///   retry and no timeout (a lost IPI or EOI would retry, then panic).
/// - The MSI address for the BSP is the APIC-ID-0 doorbell.
///
/// The control (`+ xapic-only`) keeps the pre-CP-68 Limine request, so the
/// same CPU model comes up in xAPIC mode and the mode check fails.
#[cfg(feature = "neo-test-x2apic-smp")]
fn run_x2apic_smp_ipi() -> ! {
    use crate::arch::x86_64::apic;
    use crate::arch::x86_64::apic_logic::ApicMode;
    use crate::mm::tlb_shootdown;
    use crate::sched::wake_trace::ipi_recv_count;

    const ROUNDS: u64 = 16;
    const SPINS: u64 = 2_000_000;
    let mode = apic::mode();
    serial_println!("x2apic_smp mode={}", mode.name());
    if mode != ApicMode::X2Apic {
        fail(&alloc::format!(
            "reason=apic_mode_not_x2apic mode={}",
            mode.name()
        ));
    }

    // Every AP must be up and shootdown-ready before the IPI legs.
    let mut targets = tlb_shootdown::other_cpus_mask();
    for _ in 0..SPINS {
        if targets.count() >= 3 {
            break;
        }
        crate::sched::yield_now();
        targets = tlb_shootdown::other_cpus_mask();
    }
    let aps = targets.count();
    serial_println!("x2apic_smp aps_ready={}", aps);
    if aps < 3 {
        fail("reason=x2apic_aps_not_ready");
    }

    // Reschedule IPIs, each awaited on the receiving CPU's counter.
    let mut delivered = 0u64;
    for _ in 0..ROUNDS {
        for cpu in targets.iter() {
            let before = ipi_recv_count(cpu);
            apic::send_reschedule_ipi(cpu);
            let mut seen = false;
            for _ in 0..SPINS {
                if ipi_recv_count(cpu) > before {
                    seen = true;
                    break;
                }
                core::hint::spin_loop();
            }
            if !seen {
                fail(&alloc::format!(
                    "reason=x2apic_reschedule_ipi_lost cpu={cpu}"
                ));
            }
            delivered += 1;
        }
    }
    serial_println!(
        "x2apic_smp reschedule_ipis delivered={} expected={}",
        delivered,
        ROUNDS * aps as u64
    );

    // Broadcast TLB shootdowns: `shootdown` returns only once every target
    // has ACKed (it re-pokes after 1 ms and panics at the final deadline).
    tlb_shootdown::reset_test_counters();
    for _ in 0..ROUNDS {
        tlb_shootdown::shootdown(None, targets);
    }
    let (mut received, mut retries, mut timeouts) = (0u64, 0u64, 0u64);
    for cpu in targets.iter() {
        let c = tlb_shootdown::test_counters(cpu).unwrap_or_else(|| fail("reason=x2apic_counters"));
        received += c.ipis_received;
        // Re-pokes are counted on the target; a slow TCG vCPU may earn one
        // legitimately, so they are reported, not failed on.
        retries += c.retry_ipis_sent;
        timeouts += c.timeouts;
    }
    if let Some(c) = tlb_shootdown::test_counters(0) {
        timeouts += c.timeouts;
    }
    serial_println!(
        "x2apic_smp shootdowns rounds={} ipis_received={} expected={} retries={} timeouts={}",
        ROUNDS,
        received,
        ROUNDS * aps as u64,
        retries,
        timeouts
    );
    if received < ROUNDS * aps as u64 || timeouts != 0 {
        fail("reason=x2apic_shootdown_not_clean");
    }

    let msi = apic::msi_address_for_bsp();
    serial_println!("x2apic_smp msi_address={:#x}", msi.unwrap_or(0));
    if msi != Some(0xfee0_0000) {
        fail("reason=x2apic_msi_address_wrong");
    }

    pass(&alloc::format!(
        "x2apic_smp_ipi=ok mode=x2APIC aps={aps} reschedule_ipis={delivered} shootdowns={ROUNDS} shootdown_ipis={received} retries={retries} timeouts=0 msi=0xfee00000"
    ));
}

// ── CP-67: force-kill of a thread parked in IPC ──
// Stand-in processes (their own pid and address space, one user page at
// `ADMISSION_KILL_VA`) each make one blocking IPC syscall through the real
// dispatcher, and park in the channel.

/// (pid, syscall, a0, a1, a2, result, done) per stand-in caller.
#[cfg(any(feature = "neo-test-ipc-park-kill", feature = "neo-test-kill-at-exit"))]
#[allow(clippy::type_complexity)]
static IPC_CALLERS: crate::sync::SwitchMutex<[(u32, u64, u64, u64, u64, i64, bool); 8]> =
    crate::sync::SwitchMutex::new([(0, 0, 0, 0, 0, 0, false); 8]);

#[cfg(any(feature = "neo-test-ipc-park-kill", feature = "neo-test-kill-at-exit"))]
extern "C" fn ipc_kill_caller() -> ! {
    use crate::arch::x86_64::syscall::syscall_dispatch_for_test;
    let pid = crate::sched::current_pid().0;
    let call = crate::arch::x86_64::without_interrupts(|| {
        IPC_CALLERS.lock().iter().find(|c| c.0 == pid).copied()
    })
    .unwrap_or_else(|| fail("reason=ipc_caller_unknown"));
    let ret = syscall_dispatch_for_test(call.1, call.2, call.3, call.4);
    crate::arch::x86_64::without_interrupts(|| {
        if let Some(c) = IPC_CALLERS.lock().iter_mut().find(|c| c.0 == pid) {
            c.5 = ret;
            c.6 = true;
        }
    });
    crate::sched::exit();
}

/// One stand-in process holding `side` of `channel` (and, for a grant, the
/// model as its source handle), whose one thread makes syscall `num`. The
/// arguments after the channel handle are `rest(model_handle)`. Returns its pid.
#[cfg(feature = "neo-test-ipc-park-kill")]
fn ipc_kill_process(
    channel: &alloc::sync::Arc<crate::ipc::Channel>,
    side: crate::ipc::EndpointSide,
    model: Option<&alloc::sync::Arc<crate::ai::model::Model>>,
    num: u64,
    rest: impl Fn(u32) -> (u64, u64),
    slot: usize,
) -> u32 {
    use crate::arch::x86_64::syscall::admission_kill_process_for_test;
    use crate::sched::process::{self, Handle};
    let page = crate::mm::with_frame_alloc(|fa| {
        use x86_64::structures::paging::FrameAllocator;
        fa.allocate_frame()
    })
    .unwrap_or_else(|| fail("reason=ipc_out_of_frames"));
    let proc = admission_kill_process_for_test(page);
    let base = crate::mm::phys_to_virt(page.start_address()).as_mut_ptr::<u8>();
    // SAFETY: the fresh frame just mapped as the caller's user page, written
    // through its HHDM alias before its thread exists.
    unsafe { core::ptr::write_bytes(base, 0x5a, 4096) };
    let ch_h = process::install_cap(
        &proc,
        Handle::Channel {
            channel: channel.clone(),
            side,
            cap_id: process::alloc_cap_id(),
            rights: process::full_channel_rights(),
        },
        None,
    )
    .unwrap_or_else(|_| fail("reason=ipc_channel_handle"));
    let model_h = model.map_or(0, |m| {
        process::install_cap(
            &proc,
            Handle::Model {
                model: m.clone(),
                cap_id: process::alloc_cap_id(),
                rights: process::full_model_rights(),
            },
            None,
        )
        .unwrap_or_else(|_| fail("reason=ipc_model_handle"))
    });
    let (a1, a2) = rest(model_h);
    let pid = proc.pid;
    crate::arch::x86_64::without_interrupts(|| {
        IPC_CALLERS.lock()[slot] = (pid.0, num, ch_h as u64, a1, a2, 0, false);
    });
    let pmap = proc
        .pmap
        .clone()
        .unwrap_or_else(|| fail("reason=ipc_no_pmap"));
    let mut thread = crate::sched::thread::Thread::new("ipc-kill-caller", ipc_kill_caller);
    thread.bind_process_for_test(pid, pmap);
    if crate::sched::scheduler::place_thread_on_cpu(thread, 0).is_err() {
        fail("reason=ipc_place_thread_failed");
    }
    pid.0
}

#[cfg(feature = "neo-test-ipc-park-kill")]
fn ipc_kill_wait(spins: u64, done: impl Fn() -> bool) -> bool {
    for _ in 0..spins {
        if done() {
            return true;
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    done()
}

#[cfg(feature = "neo-test-ipc-park-kill")]
fn ipc_kill_result(slot: usize) -> Option<i64> {
    crate::arch::x86_64::without_interrupts(|| {
        let c = IPC_CALLERS.lock()[slot];
        c.6.then_some(c.5)
    })
}

#[cfg(any(feature = "neo-test-ipc-park-kill", feature = "neo-test-kill-at-exit"))]
fn ipc_kill_gone(pid: u32) -> bool {
    crate::sched::process::get(crate::sched::process::ProcessId(pid)).is_none()
}

// ── OT-98 (CP-98): a kill that races a natural exit ──

/// One stand-in process (as `ipc_kill_process`) whose thread makes syscall
/// `num` with the arguments `args` returns once the process exists (it can
/// install handles first). Its thread goes on CPU 0, where this harness runs
/// its kills (`kae_require_cpu0`); leg C and the F1 leg place theirs on other
/// CPUs. Returns its pid.
#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_process(
    num: u64,
    slot: usize,
    args: impl FnOnce(&alloc::sync::Arc<crate::sched::process::Process>) -> (u64, u64, u64),
) -> u32 {
    let (pid, thread) = kae_process_unstarted(num, slot, args);
    kae_start(thread);
    pid
}

/// `kae_process`, with the thread built but not yet placed: the process is
/// registered (so a wait on it parks) and has not run.
#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_process_unstarted(
    num: u64,
    slot: usize,
    args: impl FnOnce(&alloc::sync::Arc<crate::sched::process::Process>) -> (u64, u64, u64),
) -> (u32, alloc::boxed::Box<crate::sched::thread::Thread>) {
    kae_process_unstarted_with(num, slot, ipc_kill_caller, args)
}

/// `kae_process_unstarted`, with the thread running `entry`.
#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_process_unstarted_with(
    num: u64,
    slot: usize,
    entry: extern "C" fn() -> !,
    args: impl FnOnce(&alloc::sync::Arc<crate::sched::process::Process>) -> (u64, u64, u64),
) -> (u32, alloc::boxed::Box<crate::sched::thread::Thread>) {
    let proc = kae_new_process();
    let (a0, a1, a2) = args(&proc);
    let pid = proc.pid;
    crate::arch::x86_64::without_interrupts(|| {
        IPC_CALLERS.lock()[slot] = (pid.0, num, a0, a1, a2, 0, false);
    });
    let thread = kae_bound_thread(&proc, entry);
    drop(proc);
    (pid.0, thread)
}

/// A fresh stand-in process (one user page), registered, with no thread.
#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_new_process() -> alloc::sync::Arc<crate::sched::process::Process> {
    use crate::arch::x86_64::syscall::admission_kill_process_for_test;
    let page = crate::mm::with_frame_alloc(|fa| {
        use x86_64::structures::paging::FrameAllocator;
        fa.allocate_frame()
    })
    .unwrap_or_else(|| fail("reason=kae_out_of_frames"));
    admission_kill_process_for_test(page)
}

/// A kernel-built thread of `proc` running `entry`, with its address space and
/// (as every production user thread has) its process anchor, through which
/// it reads a force-kill at its syscall boundaries (OT-93).
#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_bound_thread(
    proc: &alloc::sync::Arc<crate::sched::process::Process>,
    entry: extern "C" fn() -> !,
) -> alloc::boxed::Box<crate::sched::thread::Thread> {
    let pmap = proc
        .pmap
        .clone()
        .unwrap_or_else(|| fail("reason=kae_no_pmap"));
    let mut thread = crate::sched::thread::Thread::new("kae-caller", entry);
    thread.bind_process_for_test(proc.pid, pmap);
    thread.set_process_anchor(proc.clone());
    thread
}

/// Place a stand-in's thread on `cpu`.
#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_start_on(thread: alloc::boxed::Box<crate::sched::thread::Thread>, cpu: u32) {
    if crate::sched::scheduler::place_thread_on_cpu(thread, cpu).is_err() {
        fail("reason=kae_place_thread_failed");
    }
}

/// The kills here run on CPU 0, with every stand-in that is not meant to run
/// concurrently with them (leg C, the F1 leg) on CPU 0 too. Nothing pins this
/// harness thread, so each leg checks it instead of assuming it (the comment
/// that said every thread was on the BSP was wrong: S1's SMP=4 panic).
#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_require_cpu0(leg: &str) {
    let cpu = crate::arch::x86_64::per_cpu::current_cpu_id();
    if cpu != 0 {
        serial_println!("kill_at_exit {} harness_cpu={}", leg, cpu);
        fail("reason=kae_harness_not_on_cpu0");
    }
}

#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_start(thread: alloc::boxed::Box<crate::sched::thread::Thread>) {
    kae_start_on(thread, 0);
}

/// A process handle to `target`, installed in `proc`.
#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_process_handle(proc: &alloc::sync::Arc<crate::sched::process::Process>, target: u32) -> u64 {
    use crate::sched::process::{self, Handle, ProcessId};
    process::install_cap(
        proc,
        Handle::Process {
            target: ProcessId(target),
            cap_id: process::alloc_cap_id(),
            rights: process::full_process_rights(),
        },
        None,
    )
    .unwrap_or_else(|_| fail("reason=kae_process_handle")) as u64
}

/// Yield until `done`, reaping only when `reap` (a pending zombie must stay
/// unreaped for the exited leg). False if `spins` ran out.
#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_wait(spins: u64, reap: bool, done: impl Fn() -> bool) -> bool {
    for _ in 0..spins {
        if done() {
            return true;
        }
        crate::sched::yield_now();
        if reap {
            crate::sched::reap();
        }
    }
    done()
}

/// Weak references to a process and its address space: both must die once
/// the process is gone and its threads are reaped.
#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_weak(
    pid: u32,
) -> (
    alloc::sync::Weak<crate::sched::process::Process>,
    Option<alloc::sync::Weak<crate::mm::pmap::Pmap>>,
) {
    let proc = crate::sched::process::get(crate::sched::process::ProcessId(pid))
        .unwrap_or_else(|| fail("reason=kae_process_missing"));
    let pmap = proc.pmap.as_ref().map(alloc::sync::Arc::downgrade);
    (alloc::sync::Arc::downgrade(&proc), pmap)
}

#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_freed(
    weak: &(
        alloc::sync::Weak<crate::sched::process::Process>,
        Option<alloc::sync::Weak<crate::mm::pmap::Pmap>>,
    ),
) -> bool {
    weak.0.strong_count() == 0 && weak.1.as_ref().is_none_or(|p| p.strong_count() == 0)
}

/// The legs' pauses (OT-98 FAIL-A, FAIL-B and the #202 F2 window): the pid
/// whose `terminate` (A) or reap (B) pauses, and the pid of the waiter P that
/// a stand-in K kills during the pause. 0 when disarmed.
#[cfg(feature = "neo-test-kill-at-exit")]
static KAE_PAUSE_TARGET: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);
#[cfg(feature = "neo-test-kill-at-exit")]
static KAE_PAUSE_LEG: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);
#[cfg(feature = "neo-test-kill-at-exit")]
static KAE_PAUSE_VICTIM: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);
/// Set during leg A's pause if the wait W2 started inside the window returned
/// before the kill completed (the #202 F2 defect).
#[cfg(feature = "neo-test-kill-at-exit")]
static KAE_WINDOW_WAIT_EARLY: core::sync::atomic::AtomicBool =
    core::sync::atomic::AtomicBool::new(false);
#[cfg(feature = "neo-test-kill-at-exit")]
const KAE_LEG_A: u32 = 1;
#[cfg(feature = "neo-test-kill-at-exit")]
const KAE_LEG_B: u32 = 2;
#[cfg(feature = "neo-test-kill-at-exit")]
const KAE_LEG_D: u32 = 4;
#[cfg(feature = "neo-test-kill-at-exit")]
const KAE_LEG_F: u32 = 6;
/// IPC_CALLERS slots of the pause's stand-ins: K (the kill) and W2 (the wait).
#[cfg(feature = "neo-test-kill-at-exit")]
const KAE_SLOT_K: usize = 5;
#[cfg(feature = "neo-test-kill-at-exit")]
const KAE_SLOT_W2: usize = 6;

#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_result(slot: usize) -> Option<i64> {
    crate::arch::x86_64::without_interrupts(|| {
        let c = IPC_CALLERS.lock()[slot];
        c.6.then_some(c.5)
    })
}

/// Disarm the pause and say whether `target` was the armed one for `leg`.
#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_take_pause(target: crate::sched::process::ProcessId, leg: u32) -> Option<u32> {
    use core::sync::atomic::Ordering;
    if KAE_PAUSE_LEG.load(Ordering::Acquire) != leg
        || KAE_PAUSE_TARGET.load(Ordering::Acquire) != target.0
    {
        return None;
    }
    KAE_PAUSE_TARGET.store(0, Ordering::Release);
    KAE_PAUSE_LEG.store(0, Ordering::Release);
    Some(KAE_PAUSE_VICTIM.load(Ordering::Acquire))
}

/// During the pause: a stand-in K kills `victim`; yield until it returns.
#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_kill_during_pause(victim: u32) {
    use crate::arch::x86_64::syscall::SYS_KILL;
    kae_process(SYS_KILL, KAE_SLOT_K, |p| {
        (kae_process_handle(p, victim), 0, 0)
    });
    if !kae_wait(200_000, false, || kae_result(KAE_SLOT_K).is_some()) {
        fail("reason=kae_pause_kill_never_returned");
    }
}

/// Leg C's, leg D's and the F1 leg's hold: the exit producers of this pid
/// stop in `record_exit_code`, before its claim, until released in arrival
/// order (`KAE_EXIT_RELEASED` counts the releases). 0 when disarmed.
#[cfg(feature = "neo-test-kill-at-exit")]
static KAE_EXIT_HOLD_PID: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);
#[cfg(feature = "neo-test-kill-at-exit")]
static KAE_EXIT_ARRIVED: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);
#[cfg(feature = "neo-test-kill-at-exit")]
static KAE_EXIT_RELEASED: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);
/// Producers past the claim, how many won it, and the winner's code.
#[cfg(feature = "neo-test-kill-at-exit")]
static KAE_EXIT_RECORDED: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);
#[cfg(feature = "neo-test-kill-at-exit")]
static KAE_EXIT_WINS: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);
#[cfg(feature = "neo-test-kill-at-exit")]
static KAE_EXIT_WIN_CODE: core::sync::atomic::AtomicI32 = core::sync::atomic::AtomicI32::new(0);

#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_arm_exit_hold(pid: u32) {
    use core::sync::atomic::Ordering;
    KAE_EXIT_ARRIVED.store(0, Ordering::Release);
    KAE_EXIT_RELEASED.store(0, Ordering::Release);
    KAE_EXIT_RECORDED.store(0, Ordering::Release);
    KAE_EXIT_WINS.store(0, Ordering::Release);
    KAE_EXIT_WIN_CODE.store(0, Ordering::Release);
    KAE_EXIT_HOLD_PID.store(pid, Ordering::Release);
}

#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_disarm_exit_hold() {
    KAE_EXIT_HOLD_PID.store(0, core::sync::atomic::Ordering::Release);
}

#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_exit_held(pid: crate::sched::process::ProcessId) -> bool {
    pid.0 != 0 && KAE_EXIT_HOLD_PID.load(core::sync::atomic::Ordering::Acquire) == pid.0
}

/// In `record_exit_code`, before the claim: an armed producer spins (Running,
/// inside its exit syscall) until its turn is released.
#[cfg(feature = "neo-test-kill-at-exit")]
pub fn kae_exit_hold(pid: crate::sched::process::ProcessId) {
    use core::sync::atomic::Ordering;
    if !kae_exit_held(pid) {
        return;
    }
    let ticket = KAE_EXIT_ARRIVED.fetch_add(1, Ordering::AcqRel);
    while KAE_EXIT_RELEASED.load(Ordering::Acquire) <= ticket {
        core::hint::spin_loop();
    }
}

/// In `record_exit_code`, after the claim: whether this producer won it.
#[cfg(feature = "neo-test-kill-at-exit")]
pub fn kae_exit_recorded(pid: crate::sched::process::ProcessId, code: i32, won: bool) {
    use core::sync::atomic::Ordering;
    if !kae_exit_held(pid) {
        return;
    }
    if won {
        KAE_EXIT_WIN_CODE.store(code, Ordering::Release);
        KAE_EXIT_WINS.fetch_add(1, Ordering::AcqRel);
    }
    KAE_EXIT_RECORDED.fetch_add(1, Ordering::AcqRel);
}

/// The F1 leg's two exit producers' codes.
#[cfg(feature = "neo-test-kill-at-exit")]
static KAE_F1_CODES: [core::sync::atomic::AtomicI32; 2] = [
    core::sync::atomic::AtomicI32::new(0),
    core::sync::atomic::AtomicI32::new(0),
];

/// An F1 producer: `SYS_EXIT(KAE_F1_CODES[i])` through the real dispatcher.
#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_sys_exit_producer(i: usize) -> ! {
    use crate::arch::x86_64::syscall::{SYS_EXIT, syscall_dispatch_for_test};
    let code = KAE_F1_CODES[i].load(core::sync::atomic::Ordering::Acquire);
    syscall_dispatch_for_test(SYS_EXIT, code as u32 as u64, 0, 0);
    crate::sched::exit();
}

#[cfg(feature = "neo-test-kill-at-exit")]
extern "C" fn kae_sys_exit_producer_0() -> ! {
    kae_sys_exit_producer(0)
}

#[cfg(feature = "neo-test-kill-at-exit")]
extern "C" fn kae_sys_exit_producer_1() -> ! {
    kae_sys_exit_producer(1)
}

/// An F1 producer: the fault kill's tail with `KAE_F1_CODES[1]`.
#[cfg(feature = "neo-test-kill-at-exit")]
extern "C" fn kae_fault_exit_producer_1() -> ! {
    let code = KAE_F1_CODES[1].load(core::sync::atomic::Ordering::Acquire);
    crate::sched::process::fault_exit_current_for_test(code)
}

/// Leg D: whether its pause also reaps the waiter it lets exit.
#[cfg(feature = "neo-test-kill-at-exit")]
static KAE_D_REAP_WAITER: core::sync::atomic::AtomicBool =
    core::sync::atomic::AtomicBool::new(false);

/// Leg D's pause, in `terminate(P)` after its first survivor count (P parked
/// in `sys_wait` on Q, so in no queue that count reads) and before its
/// `sys_wait` scan. Q, held in its `SYS_EXIT` on CPU 1, is released and
/// reaped here, which completes P's wait: P is woken Ready inside its syscall,
/// runs to its return, reads the kill and exits. So the scans that follow find
/// P in none of their queues; `terminate` must see that it left the kernel
/// (unreaped in a zombie ring, or, with `KAE_D_REAP_WAITER`, already reaped).
#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_d_pause(waiter: crate::sched::process::ProcessId, q: u32) {
    use crate::sched::process::ProcessId;
    use crate::sched::scheduler::zombie_pending;
    use core::sync::atomic::Ordering;
    KAE_EXIT_RELEASED.store(1, Ordering::Release);
    if !kae_wait(200_000, false, || zombie_pending(ProcessId(q))) {
        fail("reason=kae_d_target_never_exited");
    }
    // Q's reap completes P's wait (P is woken under Q's `waiters` lock).
    crate::sched::reap();
    if !kae_wait(200_000, false, || zombie_pending(waiter)) {
        fail("reason=kae_d_waiter_never_exited");
    }
    if KAE_D_REAP_WAITER.load(Ordering::Acquire) {
        crate::sched::reap();
        if zombie_pending(waiter) {
            fail("reason=kae_d_waiter_not_reaped");
        }
    }
}

// ── The PM's bounce on `66904ae1`: legs E, F and G, each killing from an AP ──

/// One-shot pause flags for legs E, F and G (0 disarmed), and their stages.
#[cfg(feature = "neo-test-kill-at-exit")]
static KAE_E_TARGET: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);
#[cfg(feature = "neo-test-kill-at-exit")]
static KAE_E_PAUSED: core::sync::atomic::AtomicBool = core::sync::atomic::AtomicBool::new(false);
#[cfg(feature = "neo-test-kill-at-exit")]
static KAE_E_REAPED: core::sync::atomic::AtomicBool = core::sync::atomic::AtomicBool::new(false);
#[cfg(feature = "neo-test-kill-at-exit")]
static KAE_F_TARGET: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);
#[cfg(feature = "neo-test-kill-at-exit")]
static KAE_F_STAGE: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);
#[cfg(feature = "neo-test-kill-at-exit")]
static KAE_G_TARGET: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);
#[cfg(feature = "neo-test-kill-at-exit")]
static KAE_G_PAUSED: core::sync::atomic::AtomicBool = core::sync::atomic::AtomicBool::new(false);

/// Leg F's stages: K paused in `terminate(P)`; the reaper paused after
/// popping P's zombie; K's scans done.
#[cfg(feature = "neo-test-kill-at-exit")]
const KAE_F_K_PAUSED: u32 = 1;
#[cfg(feature = "neo-test-kill-at-exit")]
const KAE_F_POPPED: u32 = 2;
#[cfg(feature = "neo-test-kill-at-exit")]
const KAE_F_SCANNED: u32 = 3;

/// Spin (not yield: the caller may be inside `SYS_KILL`'s interrupts-off
/// section on an AP) until `done`, with interrupts enabled meanwhile, so this
/// CPU still acks the TLB shootdowns the BSP's reaps send. False after about
/// `cycles` TSC cycles.
#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_spin_until(cycles: u64, done: impl Fn() -> bool) -> bool {
    crate::arch::x86_64::with_interrupts_enabled(|| kae_spin_masked(cycles, done))
}

/// `kae_spin_until` with the caller's interrupt state (leg G holds an
/// endpoint guard, an IRQ-safe lock).
#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_spin_masked(cycles: u64, done: impl Fn() -> bool) -> bool {
    // SAFETY: RDTSC has no side effects.
    let start = unsafe { core::arch::x86_64::_rdtsc() };
    while !done() {
        // SAFETY: as above.
        if unsafe { core::arch::x86_64::_rdtsc() }.wrapping_sub(start) > cycles {
            return false;
        }
        core::hint::spin_loop();
    }
    true
}

/// About 20 s of TSC at QEMU's rate: a bound on a wait that must end.
#[cfg(feature = "neo-test-kill-at-exit")]
const KAE_SPIN_BOUND: u64 = 60_000_000_000;

/// Leg E's pause, in `terminate(P)` after its survivor count and before
/// `DYING`'s insert (item 1): P, held Running in `SYS_EXIT` on CPU 2, is
/// released, exits at its return, and is reaped on the BSP before the kill
/// goes on.
#[cfg(feature = "neo-test-kill-at-exit")]
pub fn kae_after_survivor_count(target: crate::sched::process::ProcessId) {
    use core::sync::atomic::Ordering;
    if target.0 == 0
        || KAE_E_TARGET
            .compare_exchange(target.0, 0, Ordering::AcqRel, Ordering::Acquire)
            .is_err()
    {
        return;
    }
    KAE_EXIT_RELEASED.store(1, Ordering::Release);
    KAE_E_PAUSED.store(true, Ordering::Release);
    if !kae_spin_until(KAE_SPIN_BOUND, || KAE_E_REAPED.load(Ordering::Acquire)) {
        fail("reason=kae_e_survivor_never_reaped");
    }
}

/// Leg F's pause in the reaper, after it popped P's zombie and before it
/// frees P (item 2): until K's scans and checks are done.
#[cfg(feature = "neo-test-kill-at-exit")]
pub fn kae_after_reap_pop(pid: crate::sched::process::ProcessId) {
    use core::sync::atomic::Ordering;
    if pid.0 == 0
        || KAE_F_TARGET.load(Ordering::Acquire) != pid.0
        || KAE_F_STAGE
            .compare_exchange(
                KAE_F_K_PAUSED,
                KAE_F_POPPED,
                Ordering::AcqRel,
                Ordering::Acquire,
            )
            .is_err()
    {
        return;
    }
    if !kae_spin_until(KAE_SPIN_BOUND, || {
        KAE_F_STAGE.load(Ordering::Acquire) == KAE_F_SCANNED
    }) {
        fail("reason=kae_f_scans_never_done");
    }
}

/// After `terminate`'s scans and checks: leg F's reaper may go on.
#[cfg(feature = "neo-test-kill-at-exit")]
pub fn kae_after_scans(target: crate::sched::process::ProcessId) {
    use core::sync::atomic::Ordering;
    if target.0 != 0 && KAE_F_TARGET.load(Ordering::Acquire) == target.0 {
        let _ = KAE_F_STAGE.compare_exchange(
            KAE_F_POPPED,
            KAE_F_SCANNED,
            Ordering::AcqRel,
            Ordering::Acquire,
        );
    }
}

/// Leg F's pause, in `terminate(P)` (on CPU 1) after P's removal: Q, held in
/// `SYS_EXIT` on CPU 2, is released, and K waits until the BSP's reaper has
/// woken P (Q's reap), P has exited at its return, and the reaper has popped
/// P's zombie and paused (`kae_after_reap_pop`).
#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_f_pause() {
    use core::sync::atomic::Ordering;
    KAE_EXIT_RELEASED.store(1, Ordering::Release);
    KAE_F_STAGE.store(KAE_F_K_PAUSED, Ordering::Release);
    if !kae_spin_until(KAE_SPIN_BOUND, || {
        KAE_F_STAGE.load(Ordering::Acquire) == KAE_F_POPPED
    }) {
        fail("reason=kae_f_never_popped");
    }
}

/// Leg G's pause, in `close_peer` with the waiter P extracted and not yet
/// woken (item 3): until the kill K, released now on CPU 1, returns, or about
/// 0.1 s. Fixed, the endpoint guard is held here, so K's channel scan waits
/// for it and finds P woken; the control (`-control-g`) has dropped it, so K
/// finishes first and finds P nowhere.
#[cfg(feature = "neo-test-kill-at-exit")]
pub fn kae_close_peer_transit(pid: crate::sched::process::ProcessId) {
    use core::sync::atomic::Ordering;
    if pid.0 == 0
        || KAE_G_TARGET
            .compare_exchange(pid.0, 0, Ordering::AcqRel, Ordering::Acquire)
            .is_err()
    {
        return;
    }
    KAE_G_PAUSED.store(true, Ordering::Release);
    kae_spin_masked(300_000_000, || kae_result(KAE_SLOT_K).is_some());
}

/// A stand-in K on `cpu` that calls `SYS_KILL` on `victim` through the real
/// dispatcher (which runs `terminate` with interrupts off, as for ring 3),
/// once `gate` holds. Returns K's pid.
#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_kill_from(cpu: u32, victim: u32, gate: fn() -> bool) -> u32 {
    use crate::arch::x86_64::syscall::SYS_KILL;
    KAE_K_GATE.store(gate as usize, core::sync::atomic::Ordering::Release);
    let (k, thread) = kae_process_unstarted_with(SYS_KILL, KAE_SLOT_K, kae_gated_caller, |p| {
        (kae_process_handle(p, victim), 0, 0)
    });
    kae_start_on(thread, cpu);
    k
}

/// `kae_kill_from`'s gate, as a `fn() -> bool` address (0: open).
#[cfg(feature = "neo-test-kill-at-exit")]
static KAE_K_GATE: core::sync::atomic::AtomicUsize = core::sync::atomic::AtomicUsize::new(0);

#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_gate_open() -> bool {
    true
}

#[cfg(feature = "neo-test-kill-at-exit")]
extern "C" fn kae_gated_caller() -> ! {
    let gate = KAE_K_GATE.load(core::sync::atomic::Ordering::Acquire);
    if gate != 0 {
        // SAFETY: stored from a `fn() -> bool` by `kae_kill_from`.
        let gate: fn() -> bool = unsafe { core::mem::transmute(gate) };
        if !kae_spin_until(KAE_SPIN_BOUND, gate) {
            fail("reason=kae_killer_gate_never_opened");
        }
    }
    ipc_kill_caller()
}

/// Every kill so far found its target's thread (`note_kill_unlocated`).
#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_require_located(leg: &str) {
    let n = crate::sched::process::kill_unlocated_count();
    if n != 0 {
        serial_println!("kill_at_exit {} unlocated_kills={}", leg, n);
        fail("reason=kae_kill_unlocated");
    }
}

/// Leg A's pause, in `terminate(Q)` between Q's removal from `PROCESSES` and
/// its completion: K kills P (parked in `sys_wait` on Q), and W2 starts a
/// `sys_wait` on Q, which must park until the kill completes.
#[cfg(feature = "neo-test-kill-at-exit")]
pub fn kae_in_terminate(target: crate::sched::process::ProcessId) {
    use crate::arch::x86_64::syscall::SYS_WAIT;
    use crate::sched::process::{self, ProcessId};
    if let Some(q) = kae_take_pause(target, KAE_LEG_D) {
        return kae_d_pause(target, q);
    }
    if kae_take_pause(target, KAE_LEG_F).is_some() {
        return kae_f_pause();
    }
    let Some(victim) = kae_take_pause(target, KAE_LEG_A) else {
        return;
    };
    kae_kill_during_pause(victim);
    let q = target.0;
    kae_process(SYS_WAIT, KAE_SLOT_W2, |p| (kae_process_handle(p, q), 0, 0));
    kae_wait(200_000, false, || {
        process::waiter_count_for_test(ProcessId(q)) == 1 || kae_result(KAE_SLOT_W2).is_some()
    });
    if kae_result(KAE_SLOT_W2).is_some() {
        KAE_WINDOW_WAIT_EARLY.store(true, core::sync::atomic::Ordering::Release);
    }
}

/// Leg B's pause, in Q's reap between taking Q's waiters out of its queue and
/// the point they used to be woken: K kills P (Q's waiter).
#[cfg(feature = "neo-test-kill-at-exit")]
pub fn kae_after_waiters_taken(target: crate::sched::process::ProcessId) {
    if let Some(victim) = kae_take_pause(target, KAE_LEG_B) {
        kae_kill_during_pause(victim);
    }
}

/// OT-98 (CP-98): `terminate` must handle every state its target can be in,
/// on `NEO_SMP=4`. Each leg runs `ROUNDS` times. The kills run on CPU 0, and
/// so do the stand-ins, except where a leg places one elsewhere.
///
/// - **Leg C** (S1's SMP=4 panic): a child on CPU 1 is held Running inside
///   `SYS_EXIT`, before `record_exit_code`. `terminate` (CPU 0) wins the claim,
///   must count the child as a survivor and defer: its waiter must still be
///   parked when the kill returns, and get ESRCH only after the child,
///   released, exits and is reaped. Control: `-control-c` (no survivor count)
///   panics.
/// - **Exited leg:** a child calls `SYS_EXIT(7)`; once its thread waits
///   unreaped in a zombie ring, `terminate` must return ESRCH, and a waiter
///   that arrives after the kill must get exit code 7 at the reap. Before
///   OT-98 the kill claimed the process and `terminate`'s assertion panicked.
/// - **Wait leg:** Q parks in `SYS_RECV` with no peer; P parks in `SYS_WAIT`
///   on Q. `terminate(P)` must zombify P's thread out of Q's queue, then
///   `terminate(Q)` its recv park. Both processes and address spaces must be
///   freed: a waiter freed raw while owning `Arc<Process>` of Q would pin Q
///   (CP-30). Before OT-98, `terminate(P)` found nothing and panicked.
/// - **Leg D** (Janus #174 F2, the completion-to-Ready barrier): P's wait on Q
///   completes inside `terminate(P)`, between its first survivor count and its
///   `sys_wait` scan, and P exits at its syscall return before the scans end
///   (`kae_d_pause`); half the rounds also reap it there. The kill must
///   return 0, and a wait on P must complete only after P's reap. Control:
///   `-control-d` panics.
/// - **Legs A and B** (FAIL-A, FAIL-B): see their pauses. In leg B the killed
///   waiter may already have run to its end (a stand-in ends without
///   `SYS_EXIT`, so it never claims), which `terminate` must also accept.
/// - **F1 leg** (Janus #174 F1): two exit producers of one process (two
///   `SYS_EXIT`s, or a `SYS_EXIT` and a fault exit), on CPUs 1 and 2, held
///   past their entry checks before the claim, released one after the other
///   or together. Exactly one wins, and the waiter gets the winner's code.
///   Control: `-control-f1` (the code stored before the claim) fails
///   `kae_f1_loser_changed_code`.
/// - **Race leg:** `RACE` rounds of a child calling `SYS_EXIT(7)` and a kill
///   after `i % 5` yields; each kill returns 0 or ESRCH, nothing leaks, and
///   both outcomes are reported.
///
/// The control (`neo-test-kill-at-exit-control`) claims the natural exit at
/// the reap and skips the `sys_wait` extraction, as before OT-98: it must
/// FAIL. In the exited leg the kill then wins the claim and returns 0
/// (`kae_kill_of_exited_not_esrch`): `terminate` finds the zombie, so it no
/// longer panics there, but the waiter would lose the exit code.
#[cfg(feature = "neo-test-kill-at-exit")]
fn run_kill_at_exit() -> ! {
    use crate::arch::x86_64::syscall::{SYS_EXIT, SYS_WAIT};
    use crate::errno::ESRCH;
    use crate::ipc::Channel;
    use crate::sched::process::{self, ProcessId, encode_wait_exit_code};
    use crate::sched::scheduler::zombie_pending;

    const ROUNDS: usize = 16;
    const RACE: usize = 200;
    const SPINS: u64 = 200_000;
    const CODE: u64 = 7;
    let result = |slot: usize| {
        crate::arch::x86_64::without_interrupts(|| {
            let c = IPC_CALLERS.lock()[slot];
            c.6.then_some(c.5)
        })
    };

    // Leg E (the PM's bounce, item 1): K on CPU 1 kills P, which is held
    // Running inside SYS_EXIT on CPU 2. K's survivor count sees P; in K's
    // pause after it, P is released, exits at its return, and the BSP reaps
    // it, finding P still registered ("natural reap skipped"). Then K moves P
    // to DYING. W's wait on P must still complete.
    for _ in 0..ROUNDS {
        use core::sync::atomic::Ordering;
        kae_require_cpu0("leg_e");
        let (p, p_thread) = kae_process_unstarted(SYS_EXIT, 2, |_| (5, 0, 0));
        let w = kae_process(SYS_WAIT, 1, |proc| (kae_process_handle(proc, p), 0, 0));
        if !kae_wait(SPINS, false, || {
            process::waiter_count_for_test(ProcessId(p)) == 1
        }) {
            fail("reason=kae_e_waiter_never_parked");
        }
        let (weak_p, weak_w) = (kae_weak(p), kae_weak(w));
        kae_arm_exit_hold(p);
        kae_start_on(p_thread, 2);
        if !kae_wait(SPINS, false, || {
            KAE_EXIT_ARRIVED.load(Ordering::Acquire) == 1
        }) {
            fail("reason=kae_e_survivor_never_held");
        }
        KAE_E_PAUSED.store(false, Ordering::Release);
        KAE_E_REAPED.store(false, Ordering::Release);
        KAE_E_TARGET.store(p, Ordering::Release);
        let k = kae_kill_from(1, p, kae_gate_open);
        if !kae_wait(SPINS, false, || KAE_E_PAUSED.load(Ordering::Acquire)) {
            fail("reason=kae_e_kill_never_paused");
        }
        // The survivor exits and is reaped while the kill is paused.
        let reaped =
            |pid: u32| process::get(ProcessId(pid)).is_some_and(|proc| proc.live_threads() == 0);
        if !kae_wait(SPINS, true, || reaped(p)) {
            fail("reason=kae_e_survivor_not_reaped");
        }
        KAE_E_REAPED.store(true, Ordering::Release);
        if !kae_wait(SPINS, true, || {
            kae_result(KAE_SLOT_K).is_some()
                && result(1).is_some()
                && [p, w, k].iter().all(|&pid| ipc_kill_gone(pid))
                && kae_freed(&weak_p)
                && kae_freed(&weak_w)
        }) {
            serial_println!(
                "kill_at_exit leg_e kill={:?} wait={:?}",
                kae_result(KAE_SLOT_K),
                result(1)
            );
            fail("reason=kae_e_wait_hung");
        }
        kae_disarm_exit_hold();
        if kae_result(KAE_SLOT_K) != Some(0) || result(1) != Some(ESRCH) {
            serial_println!(
                "kill_at_exit leg_e kill={:?} wait={:?}",
                kae_result(KAE_SLOT_K),
                result(1)
            );
            fail("reason=kae_e_results");
        }
    }
    kae_require_located("leg_e");

    // Leg C: the child Running inside `SYS_EXIT` on another CPU.
    for _ in 0..ROUNDS {
        use core::sync::atomic::Ordering;
        kae_require_cpu0("leg_c");
        let (c, c_thread) = kae_process_unstarted(SYS_EXIT, 0, |_| (CODE, 0, 0));
        let w = kae_process(SYS_WAIT, 1, |p| (kae_process_handle(p, c), 0, 0));
        if !kae_wait(SPINS, false, || {
            process::waiter_count_for_test(ProcessId(c)) == 1
        }) {
            fail("reason=kae_c_waiter_never_parked");
        }
        let (weak_c, weak_w) = (kae_weak(c), kae_weak(w));
        kae_arm_exit_hold(c);
        kae_start_on(c_thread, 1);
        if !kae_wait(SPINS, false, || {
            KAE_EXIT_ARRIVED.load(Ordering::Acquire) == 1
        }) {
            fail("reason=kae_c_child_never_held");
        }
        kae_require_cpu0("leg_c_kill");
        let killed = process::terminate(ProcessId(c));
        if killed != 0 {
            serial_println!("kill_at_exit leg_c kill={}", killed);
            fail("reason=kae_c_kill_failed");
        }
        // The child is still inside its syscall: the kill completes at its
        // reap, not before.
        if result(1).is_some() || process::waiter_count_for_test(ProcessId(c)) != 1 {
            fail("reason=kae_c_wait_before_survivor");
        }
        KAE_EXIT_RELEASED.store(1, Ordering::Release);
        if !kae_wait(SPINS, true, || {
            result(1).is_some() && ipc_kill_gone(w) && kae_freed(&weak_c) && kae_freed(&weak_w)
        }) {
            fail("reason=kae_c_not_completed");
        }
        kae_disarm_exit_hold();
        // The child lost the claim (the kill's), so it changed nothing.
        if KAE_EXIT_RECORDED.load(Ordering::Acquire) != 1
            || KAE_EXIT_WINS.load(Ordering::Acquire) != 0
        {
            fail("reason=kae_c_child_claimed");
        }
        if result(1) != Some(ESRCH) {
            serial_println!("kill_at_exit leg_c wait={:?}", result(1));
            fail("reason=kae_c_wait_result");
        }
    }

    kae_require_located("leg_c");

    for _ in 0..ROUNDS {
        let c = kae_process(SYS_EXIT, 0, |_| (CODE, 0, 0));
        let weak_c = kae_weak(c);
        if !kae_wait(SPINS, false, || zombie_pending(ProcessId(c))) {
            fail("reason=kae_child_never_exited");
        }
        let killed = process::terminate(ProcessId(c));
        if killed != ESRCH {
            serial_println!("kill_at_exit exited_leg kill={}", killed);
            fail("reason=kae_kill_of_exited_not_esrch");
        }
        let w = kae_process(SYS_WAIT, 1, |p| (kae_process_handle(p, c), 0, 0));
        let weak_w = kae_weak(w);
        if !kae_wait(SPINS, false, || {
            process::waiter_count_for_test(ProcessId(c)) == 1
        }) {
            fail("reason=kae_waiter_never_parked");
        }
        if !kae_wait(SPINS, true, || {
            result(1).is_some() && ipc_kill_gone(c) && ipc_kill_gone(w)
        }) {
            fail("reason=kae_exited_leg_not_completed");
        }
        if result(1) != Some(encode_wait_exit_code(CODE as i32)) {
            serial_println!("kill_at_exit exited_leg wait={:?}", result(1));
            fail("reason=kae_wait_lost_exit_code");
        }
        if !kae_wait(SPINS, true, || kae_freed(&weak_c) && kae_freed(&weak_w)) {
            fail("reason=kae_exited_leg_leak");
        }
    }

    kae_require_located("exited");

    for _ in 0..ROUNDS {
        let ch = Channel::new();
        let q = kae_recv_parker(&ch);
        let p = kae_process(SYS_WAIT, 3, |proc| (kae_process_handle(proc, q), 0, 0));
        if !kae_wait(SPINS, true, || {
            process::waiter_count_for_test(ProcessId(q)) == 1
        }) {
            fail("reason=kae_wait_never_parked");
        }
        let (weak_p, weak_q) = (kae_weak(p), kae_weak(q));
        let kill_p = process::terminate(ProcessId(p));
        let kill_q = process::terminate(ProcessId(q));
        if kill_p != 0 || kill_q != 0 {
            serial_println!("kill_at_exit wait_leg kill_p={} kill_q={}", kill_p, kill_q);
            fail("reason=kae_wait_leg_kill_failed");
        }
        if !kae_wait(SPINS, true, || {
            ipc_kill_gone(p) && ipc_kill_gone(q) && kae_freed(&weak_p) && kae_freed(&weak_q)
        }) {
            fail("reason=kae_wait_leg_leak");
        }
        if result(2).is_some() || result(3).is_some() {
            fail("reason=kae_killed_caller_returned");
        }
        if alloc::sync::Arc::strong_count(&ch) != 1 {
            fail("reason=kae_channel_leak");
        }
    }

    kae_require_located("wait");

    // Leg D: P's wait completes, and P exits, between terminate(P)'s scans.
    for round in 0..ROUNDS {
        use core::sync::atomic::Ordering;
        kae_require_cpu0("leg_d");
        let reap_waiter = round % 2 == 1;
        let (q, q_thread) = kae_process_unstarted(SYS_EXIT, 2, |_| (5, 0, 0));
        let p = kae_process(SYS_WAIT, 3, |proc| (kae_process_handle(proc, q), 0, 0));
        if !kae_wait(SPINS, false, || {
            process::waiter_count_for_test(ProcessId(q)) == 1
        }) {
            fail("reason=kae_d_wait_never_parked");
        }
        let w2 = kae_process(SYS_WAIT, KAE_SLOT_W2, |proc| {
            (kae_process_handle(proc, p), 0, 0)
        });
        if !kae_wait(SPINS, false, || {
            process::waiter_count_for_test(ProcessId(p)) == 1
        }) {
            fail("reason=kae_d_w2_never_parked");
        }
        let (weak_p, weak_q, weak_w2) = (kae_weak(p), kae_weak(q), kae_weak(w2));
        kae_arm_exit_hold(q);
        kae_start_on(q_thread, 1);
        if !kae_wait(SPINS, false, || {
            KAE_EXIT_ARRIVED.load(Ordering::Acquire) == 1
        }) {
            fail("reason=kae_d_target_never_held");
        }
        KAE_D_REAP_WAITER.store(reap_waiter, Ordering::Release);
        KAE_PAUSE_VICTIM.store(q, Ordering::Release);
        KAE_PAUSE_LEG.store(KAE_LEG_D, Ordering::Release);
        KAE_PAUSE_TARGET.store(p, Ordering::Release);
        let kill_p = process::terminate(ProcessId(p));
        if KAE_PAUSE_TARGET.load(Ordering::Acquire) != 0 {
            fail("reason=kae_d_never_paused");
        }
        if kill_p != 0 {
            serial_println!("kill_at_exit leg_d kill_p={}", kill_p);
            fail("reason=kae_d_kill_failed");
        }
        // Unreaped, P can still be... nothing, but the kill waits for its
        // reap (a wait on a killed process returns once it is all gone).
        if !reap_waiter && kae_result(KAE_SLOT_W2).is_some() {
            fail("reason=kae_d_wait_before_reap");
        }
        if !kae_wait(SPINS, true, || {
            [p, q, w2].iter().all(|&pid| ipc_kill_gone(pid))
                && kae_result(KAE_SLOT_W2).is_some()
                && kae_freed(&weak_p)
                && kae_freed(&weak_q)
                && kae_freed(&weak_w2)
        }) {
            fail("reason=kae_d_leak");
        }
        kae_disarm_exit_hold();
        if kae_result(KAE_SLOT_W2) != Some(ESRCH) || result(3).is_some() {
            serial_println!(
                "kill_at_exit leg_d w2={:?} p={:?}",
                kae_result(KAE_SLOT_W2),
                result(3)
            );
            fail("reason=kae_d_results");
        }
    }

    kae_require_located("leg_d");

    // Leg A (FAIL-A, and the #202 F2 window): P waits on Q (parked in a recv
    // with no peer); `terminate(Q)` pauses between Q's removal and its
    // completion, and in the pause K kills P, then W2 starts a wait on Q.
    for _ in 0..ROUNDS {
        use core::sync::atomic::Ordering;
        let ch = Channel::new();
        let q = kae_recv_parker(&ch);
        let p = kae_process(SYS_WAIT, 3, |proc| (kae_process_handle(proc, q), 0, 0));
        if !kae_wait(SPINS, true, || {
            process::waiter_count_for_test(ProcessId(q)) == 1
        }) {
            fail("reason=kae_a_wait_never_parked");
        }
        let (weak_p, weak_q) = (kae_weak(p), kae_weak(q));
        KAE_WINDOW_WAIT_EARLY.store(false, Ordering::Release);
        KAE_PAUSE_VICTIM.store(p, Ordering::Release);
        KAE_PAUSE_LEG.store(KAE_LEG_A, Ordering::Release);
        KAE_PAUSE_TARGET.store(q, Ordering::Release);
        let kill_q = process::terminate(ProcessId(q));
        let kill_p = kae_result(KAE_SLOT_K);
        if kill_q != 0 || kill_p != Some(0) {
            serial_println!("kill_at_exit leg_a kill_q={} kill_p={:?}", kill_q, kill_p);
            fail("reason=kae_a_kill_failed");
        }
        if KAE_WINDOW_WAIT_EARLY.load(Ordering::Acquire) {
            fail("reason=kae_a_wait_returned_inside_teardown");
        }
        let (k, w2) = crate::arch::x86_64::without_interrupts(|| {
            let c = IPC_CALLERS.lock();
            (c[KAE_SLOT_K].0, c[KAE_SLOT_W2].0)
        });
        if !kae_wait(SPINS, true, || {
            [p, q, k, w2].iter().all(|&pid| ipc_kill_gone(pid))
                && kae_freed(&weak_p)
                && kae_freed(&weak_q)
        }) {
            fail("reason=kae_a_leak");
        }
        if kae_result(KAE_SLOT_W2) != Some(ESRCH) {
            serial_println!(
                "kill_at_exit leg_a window_wait={:?}",
                kae_result(KAE_SLOT_W2)
            );
            fail("reason=kae_a_window_wait_result");
        }
        if alloc::sync::Arc::strong_count(&ch) != 1 {
            fail("reason=kae_a_channel_leak");
        }
    }

    kae_require_located("leg_a");

    // Leg B (FAIL-B): P waits on Q, which then exits; the reap of Q pauses
    // after taking Q's waiters out of its queue, and in the pause K kills P.
    for _ in 0..ROUNDS {
        use core::sync::atomic::Ordering;
        let (q, q_thread) = kae_process_unstarted(SYS_EXIT, 2, |_| (5, 0, 0));
        let p = kae_process(SYS_WAIT, 3, |proc| (kae_process_handle(proc, q), 0, 0));
        if !kae_wait(SPINS, false, || {
            process::waiter_count_for_test(ProcessId(q)) == 1
        }) {
            fail("reason=kae_b_wait_never_parked");
        }
        let (weak_p, weak_q) = (kae_weak(p), kae_weak(q));
        KAE_PAUSE_VICTIM.store(p, Ordering::Release);
        KAE_PAUSE_LEG.store(KAE_LEG_B, Ordering::Release);
        KAE_PAUSE_TARGET.store(q, Ordering::Release);
        kae_start(q_thread);
        if !kae_wait(SPINS, true, || kae_result(KAE_SLOT_K).is_some()) {
            fail("reason=kae_b_reap_never_paused");
        }
        if kae_result(KAE_SLOT_K) != Some(0) {
            serial_println!("kill_at_exit leg_b kill_p={:?}", kae_result(KAE_SLOT_K));
            fail("reason=kae_b_kill_failed");
        }
        let k = crate::arch::x86_64::without_interrupts(|| IPC_CALLERS.lock()[KAE_SLOT_K].0);
        if !kae_wait(SPINS, true, || {
            [p, q, k].iter().all(|&pid| ipc_kill_gone(pid))
                && kae_freed(&weak_p)
                && kae_freed(&weak_q)
        }) {
            fail("reason=kae_b_leak");
        }
    }

    kae_require_located("leg_b");

    // Leg F (item 2): K on CPU 1 kills P, which waits on Q (held in SYS_EXIT
    // on CPU 2). In K's pause after P's removal, Q is released and reaped
    // (which wakes P), P exits at its return, and the reaper pops P's zombie
    // and pauses before freeing it, until K's scans and checks are done. K
    // must find P being reaped; W2's wait on P must complete.
    for _ in 0..ROUNDS {
        use crate::sched::scheduler::zombie_pending;
        use core::sync::atomic::Ordering;
        kae_require_cpu0("leg_f");
        let (q, q_thread) = kae_process_unstarted(SYS_EXIT, 2, |_| (5, 0, 0));
        let p = kae_process(SYS_WAIT, 3, |proc| (kae_process_handle(proc, q), 0, 0));
        if !kae_wait(SPINS, false, || {
            process::waiter_count_for_test(ProcessId(q)) == 1
        }) {
            fail("reason=kae_f_wait_never_parked");
        }
        let w2 = kae_process(SYS_WAIT, KAE_SLOT_W2, |proc| {
            (kae_process_handle(proc, p), 0, 0)
        });
        if !kae_wait(SPINS, false, || {
            process::waiter_count_for_test(ProcessId(p)) == 1
        }) {
            fail("reason=kae_f_w2_never_parked");
        }
        let (weak_p, weak_q, weak_w2) = (kae_weak(p), kae_weak(q), kae_weak(w2));
        kae_arm_exit_hold(q);
        kae_start_on(q_thread, 2);
        if !kae_wait(SPINS, false, || {
            KAE_EXIT_ARRIVED.load(Ordering::Acquire) == 1
        }) {
            fail("reason=kae_f_target_never_held");
        }
        KAE_F_STAGE.store(0, Ordering::Release);
        KAE_F_TARGET.store(p, Ordering::Release);
        KAE_PAUSE_VICTIM.store(0, Ordering::Release);
        KAE_PAUSE_LEG.store(KAE_LEG_F, Ordering::Release);
        KAE_PAUSE_TARGET.store(p, Ordering::Release);
        let k = kae_kill_from(1, p, kae_gate_open);
        if !kae_wait(SPINS, false, || {
            KAE_F_STAGE.load(Ordering::Acquire) == KAE_F_K_PAUSED
        }) {
            fail("reason=kae_f_kill_never_paused");
        }
        // Q exits; its reap wakes P, which exits at its return (the kill is
        // published); then the reap of P pauses after the pop.
        if !kae_wait(SPINS, false, || zombie_pending(ProcessId(q))) {
            fail("reason=kae_f_target_never_exited");
        }
        crate::sched::reap();
        if !kae_wait(SPINS, false, || zombie_pending(ProcessId(p))) {
            fail("reason=kae_f_waiter_never_exited");
        }
        crate::sched::reap();
        if KAE_F_STAGE.load(Ordering::Acquire) != KAE_F_SCANNED {
            fail("reason=kae_f_reap_never_paused");
        }
        KAE_F_TARGET.store(0, Ordering::Release);
        if !kae_wait(SPINS, true, || {
            kae_result(KAE_SLOT_K).is_some()
                && kae_result(KAE_SLOT_W2).is_some()
                && [p, q, w2, k].iter().all(|&pid| ipc_kill_gone(pid))
                && kae_freed(&weak_p)
                && kae_freed(&weak_q)
                && kae_freed(&weak_w2)
        }) {
            fail("reason=kae_f_not_completed");
        }
        kae_disarm_exit_hold();
        if kae_result(KAE_SLOT_K) != Some(0) || kae_result(KAE_SLOT_W2) != Some(ESRCH) {
            serial_println!(
                "kill_at_exit leg_f kill={:?} w2={:?}",
                kae_result(KAE_SLOT_K),
                kae_result(KAE_SLOT_W2)
            );
            fail("reason=kae_f_results");
        }
        kae_require_located("leg_f");
    }

    // Leg G (item 3): X holds side B of `ch`, P is parked in a recv on side
    // A. `terminate(X)` closes B: `close_peer` extracts P and pauses before
    // waking it, while K on CPU 1 kills P. K must find P (woken under the
    // endpoint guard, Ready inside its recv); P's process must be freed.
    for _ in 0..ROUNDS {
        use core::sync::atomic::Ordering;
        kae_require_cpu0("leg_g");
        let ch = Channel::new();
        let p = kae_recv_parker(&ch);
        let ch2 = Channel::new();
        let x = kae_recv_parker_holding(&ch2, &ch);
        let (weak_p, weak_x) = (kae_weak(p), kae_weak(x));
        KAE_G_PAUSED.store(false, Ordering::Release);
        KAE_G_TARGET.store(p, Ordering::Release);
        let k = kae_kill_from(1, p, || {
            KAE_G_PAUSED.load(core::sync::atomic::Ordering::Acquire)
        });
        let kill_x = process::terminate(ProcessId(x));
        if kill_x != 0 || !KAE_G_PAUSED.load(Ordering::Acquire) {
            serial_println!("kill_at_exit leg_g kill_x={}", kill_x);
            fail("reason=kae_g_close_never_paused");
        }
        if !kae_wait(SPINS, true, || {
            kae_result(KAE_SLOT_K).is_some()
                && [p, x, k].iter().all(|&pid| ipc_kill_gone(pid))
                && kae_freed(&weak_p)
                && kae_freed(&weak_x)
        }) {
            fail("reason=kae_g_not_completed");
        }
        if kae_result(KAE_SLOT_K) != Some(0) {
            serial_println!("kill_at_exit leg_g kill={:?}", kae_result(KAE_SLOT_K));
            fail("reason=kae_g_results");
        }
        if alloc::sync::Arc::strong_count(&ch) != 1 || alloc::sync::Arc::strong_count(&ch2) != 1 {
            fail("reason=kae_g_channel_leak");
        }
        kae_require_located("leg_g");
    }

    // F1 leg: two exit producers past their entry checks; the loser changes
    // nothing.
    for round in 0..ROUNDS {
        use core::sync::atomic::Ordering;
        kae_require_cpu0("leg_f1");
        let together = round % 2 == 1;
        let fault = (round / 2) % 2 == 1;
        KAE_F1_CODES[0].store(7, Ordering::Release);
        KAE_F1_CODES[1].store(if fault { 139 } else { 9 }, Ordering::Release);
        let x = kae_new_process();
        let xp = x.pid.0;
        let t0 = kae_bound_thread(&x, kae_sys_exit_producer_0);
        let t1 = kae_bound_thread(
            &x,
            if fault {
                kae_fault_exit_producer_1
            } else {
                kae_sys_exit_producer_1
            },
        );
        drop(x);
        let w = kae_process(SYS_WAIT, 1, |p| (kae_process_handle(p, xp), 0, 0));
        if !kae_wait(SPINS, false, || {
            process::waiter_count_for_test(ProcessId(xp)) == 1
        }) {
            fail("reason=kae_f1_waiter_never_parked");
        }
        let (weak_x, weak_w) = (kae_weak(xp), kae_weak(w));
        kae_arm_exit_hold(xp);
        kae_start_on(t0, 1);
        kae_start_on(t1, 2);
        if !kae_wait(SPINS, false, || {
            KAE_EXIT_ARRIVED.load(Ordering::Acquire) == 2
        }) {
            fail("reason=kae_f1_producers_never_held");
        }
        if together {
            KAE_EXIT_RELEASED.store(2, Ordering::Release);
        } else {
            KAE_EXIT_RELEASED.store(1, Ordering::Release);
            if !kae_wait(SPINS, false, || {
                KAE_EXIT_RECORDED.load(Ordering::Acquire) == 1
            }) {
                fail("reason=kae_f1_first_never_recorded");
            }
            KAE_EXIT_RELEASED.store(2, Ordering::Release);
        }
        if !kae_wait(SPINS, false, || {
            KAE_EXIT_RECORDED.load(Ordering::Acquire) == 2
        }) {
            fail("reason=kae_f1_never_recorded");
        }
        if KAE_EXIT_WINS.load(Ordering::Acquire) != 1 {
            serial_println!(
                "kill_at_exit leg_f1 wins={}",
                KAE_EXIT_WINS.load(Ordering::Acquire)
            );
            fail("reason=kae_f1_not_one_winner");
        }
        let win = KAE_EXIT_WIN_CODE.load(Ordering::Acquire);
        if !kae_wait(SPINS, true, || {
            result(1).is_some()
                && ipc_kill_gone(xp)
                && ipc_kill_gone(w)
                && kae_freed(&weak_x)
                && kae_freed(&weak_w)
        }) {
            fail("reason=kae_f1_not_completed");
        }
        kae_disarm_exit_hold();
        if result(1) != Some(encode_wait_exit_code(win)) {
            serial_println!(
                "kill_at_exit leg_f1 round={} fault={} together={} win={} wait={:?}",
                round,
                fault,
                together,
                win,
                result(1)
            );
            fail("reason=kae_f1_loser_changed_code");
        }
    }

    let (mut killed, mut exited) = (0usize, 0usize);
    for i in 0..RACE {
        kae_require_cpu0("race");
        let c = kae_process(SYS_EXIT, 4, |_| (CODE, 0, 0));
        let weak_c = kae_weak(c);
        for _ in 0..(i % 5) {
            crate::sched::yield_now();
        }
        match process::terminate(ProcessId(c)) {
            0 => killed += 1,
            ESRCH => exited += 1,
            other => {
                serial_println!("kill_at_exit race round={} kill={}", i, other);
                fail("reason=kae_race_kill_result");
            }
        }
        if !kae_wait(SPINS, true, || ipc_kill_gone(c) && kae_freed(&weak_c)) {
            fail("reason=kae_race_leak");
        }
    }
    // Both outcomes must occur: a kill with no yield lands before the child
    // runs, and one after a few yields after it exits.
    if exited == 0 || killed == 0 {
        serial_println!("kill_at_exit race killed={} exited={}", killed, exited);
        fail("reason=kae_race_one_outcome_only");
    }

    pass(&alloc::format!(
        "kill_at_exit=ok leg_e_rounds={ROUNDS} leg_c_rounds={ROUNDS} exited_rounds={ROUNDS} wait_rounds={ROUNDS} leg_d_rounds={ROUNDS} leg_a_rounds={ROUNDS} leg_b_rounds={ROUNDS} leg_f_rounds={ROUNDS} leg_g_rounds={ROUNDS} leg_f1_rounds={ROUNDS} race_rounds={RACE} race_killed={killed} race_exited={exited}"
    ));
}

/// A stand-in X parked in `SYS_RECV` on side A of `ch`, also holding side B
/// of `other` (leg G: X's teardown closes it).
#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_recv_parker_holding(
    ch: &alloc::sync::Arc<crate::ipc::Channel>,
    other: &alloc::sync::Arc<crate::ipc::Channel>,
) -> u32 {
    use crate::arch::x86_64::syscall::{ADMISSION_KILL_VA, SYS_RECV};
    use crate::ipc::EndpointSide;
    use crate::sched::process::{self, Handle};
    let x = kae_process(SYS_RECV, 4, |p| {
        let h = process::install_cap(
            p,
            Handle::Channel {
                channel: ch.clone(),
                side: EndpointSide::A,
                cap_id: process::alloc_cap_id(),
                rights: process::full_channel_rights(),
            },
            None,
        )
        .unwrap_or_else(|_| fail("reason=kae_channel_handle"));
        process::install_cap(
            p,
            Handle::Channel {
                channel: other.clone(),
                side: EndpointSide::B,
                cap_id: process::alloc_cap_id(),
                rights: process::full_channel_rights(),
            },
            None,
        )
        .unwrap_or_else(|_| fail("reason=kae_channel_handle"));
        (h as u64, ADMISSION_KILL_VA + 0x100, 1)
    });
    if !kae_wait(200_000, true, || ch.parked_for_test(EndpointSide::A)) {
        fail("reason=kae_recv_never_parked");
    }
    x
}

/// A stand-in Q parked in `SYS_RECV` on side A of `ch`, with no peer.
#[cfg(feature = "neo-test-kill-at-exit")]
fn kae_recv_parker(ch: &alloc::sync::Arc<crate::ipc::Channel>) -> u32 {
    use crate::arch::x86_64::syscall::{ADMISSION_KILL_VA, SYS_RECV};
    use crate::ipc::EndpointSide;
    use crate::sched::process::{self, Handle};
    let q = kae_process(SYS_RECV, 2, |p| {
        let h = process::install_cap(
            p,
            Handle::Channel {
                channel: ch.clone(),
                side: EndpointSide::A,
                cap_id: process::alloc_cap_id(),
                rights: process::full_channel_rights(),
            },
            None,
        )
        .unwrap_or_else(|_| fail("reason=kae_channel_handle"));
        (h as u64, ADMISSION_KILL_VA, 1)
    });
    if !kae_wait(200_000, true, || ch.parked_for_test(EndpointSide::A)) {
        fail("reason=kae_recv_never_parked");
    }
    q
}

/// CP-67: a thread force-killed while parked in a channel is extracted from
/// the endpoint and reaped with its stack freed raw. Nothing its syscall
/// frame owned may leak.
///
/// - Rendezvous leg (no kill): a receiver parks, a sender completes it; both
///   return 1, so the anchor's take-back path drops it exactly once.
/// - Kill legs: a thread parks in `SYS_RECV`, `SYS_SEND`, `SYS_GRANT` (its
///   source is a model handle) and `SYS_RECV_GRANT`, each on its own
///   channel with no peer; `terminate` its process.
/// - After each, the channel's count returns to the harness's one, and the
///   model's to its baseline.
///
/// The control (`neo-test-ipc-park-kill-control`) keeps the channel on the
/// syscall frame and the grant's source handle alive across the park: each
/// kill leaks one channel count, and the grant leg a model count.
#[cfg(feature = "neo-test-ipc-park-kill")]
fn run_ipc_park_kill() -> ! {
    use crate::arch::x86_64::syscall::{
        ADMISSION_KILL_VA, SYS_GRANT, SYS_RECV, SYS_RECV_GRANT, SYS_SEND,
    };
    use crate::ipc::{Channel, EndpointSide};
    use crate::sched::process::{self, ProcessId};
    use alloc::sync::Arc;

    const SPINS: u64 = 200_000;
    let model = match crate::ai::model::Model::from_neom_bytes(
        &VALID_TRANSFORMER_NEOM,
        crate::fs::FileProvenance::synthetic_always_valid(),
        None,
    ) {
        Ok(m) => Arc::new(m),
        Err(_) => fail("reason=ipc_model_parse_failed"),
    };
    let buf = |_| (ADMISSION_KILL_VA, 1);

    // Rendezvous leg: recv parks on A, send on B completes it.
    let chw = Channel::new();
    let pr = ipc_kill_process(&chw, EndpointSide::A, None, SYS_RECV, buf, 0);
    if !ipc_kill_wait(SPINS, || chw.parked_for_test(EndpointSide::A)) {
        fail("reason=ipc_rendezvous_recv_never_parked");
    }
    let ps = ipc_kill_process(&chw, EndpointSide::B, None, SYS_SEND, buf, 1);
    if !ipc_kill_wait(SPINS, || {
        ipc_kill_result(0).is_some()
            && ipc_kill_result(1).is_some()
            && ipc_kill_gone(pr)
            && ipc_kill_gone(ps)
    }) {
        fail("reason=ipc_rendezvous_not_completed");
    }
    for _ in 0..100 {
        crate::sched::yield_now();
        crate::sched::reap();
    }
    let rendezvous = (
        ipc_kill_result(0),
        ipc_kill_result(1),
        Arc::strong_count(&chw),
    );
    serial_println!(
        "ipc_kill rendezvous recv={:?} send={:?} channel_count={}",
        rendezvous.0,
        rendezvous.1,
        rendezvous.2
    );
    if rendezvous.0 != Some(1) || rendezvous.1 != Some(1) {
        fail("reason=ipc_rendezvous_wrong_results");
    }
    if rendezvous.2 != 1 {
        fail("reason=ipc_rendezvous_channel_count");
    }

    let model0 = Arc::strong_count(&model);
    // (name, syscall, grant source) per kill leg.
    let legs: [(&str, u64, bool); 4] = [
        ("recv", SYS_RECV, false),
        ("send", SYS_SEND, false),
        ("grant", SYS_GRANT, true),
        ("recv_grant", SYS_RECV_GRANT, false),
    ];
    let mut leaked: Option<&str> = None;
    for (i, (name, num, grant)) in legs.iter().enumerate() {
        let ch = Channel::new();
        let slot = 2 + i;
        let pid = ipc_kill_process(
            &ch,
            EndpointSide::A,
            grant.then_some(&model),
            *num,
            |model_h| match *num {
                SYS_GRANT => (model_h as u64, 0xffff),
                SYS_RECV_GRANT => (0xffff, 0),
                _ => (ADMISSION_KILL_VA, 1),
            },
            slot,
        );
        if !ipc_kill_wait(SPINS, || ch.parked_for_test(EndpointSide::A)) {
            fail("reason=ipc_kill_caller_never_parked");
        }
        let parked_count = Arc::strong_count(&ch);
        let terminated = process::terminate(ProcessId(pid));
        let gone = ipc_kill_wait(SPINS, || ipc_kill_gone(pid));
        for _ in 0..100 {
            crate::sched::yield_now();
            crate::sched::reap();
        }
        let count = Arc::strong_count(&ch);
        let model_count = Arc::strong_count(&model);
        serial_println!(
            "ipc_kill leg={} terminate={} gone={} returned={:?} channel_count parked={} after={} model_count={}/{}",
            name,
            terminated,
            gone,
            ipc_kill_result(slot),
            parked_count,
            count,
            model_count,
            model0
        );
        if !gone || ipc_kill_result(slot).is_some() {
            fail("reason=ipc_kill_victim_not_killed");
        }
        if leaked.is_none() && (count != 1 || model_count != model0) {
            leaked = Some(name);
        }
    }
    if let Some(name) = leaked {
        fail(&alloc::format!(
            "reason=ipc_park_kill_arc_leaked leg={name}"
        ));
    }
    pass(
        "ipc_park_kill=ok rendezvous=1/1 legs=recv,send,grant,recv_grant channel_count=1 model_count=baseline",
    );
}

/// Phase 7 BUILD-3 (ISC-5): the capability-mediated tensor-sharing + dedup gate — the
/// **global-view ownership** capability. Two paths to "N principals, one physical
/// copy": an explicit RO capability grant, and implicit content-hash dedup on load.
/// Asserts (both paths): one physical allocation (alloc count, not handle count),
/// N RO readers, a RW attempt by an RO grantee DENIED at the op boundary, revocation
/// removes a reader, last-ref-drop frees the one copy, and §9.5 `resident_bytes` is
/// never double-counted (counted once, to the owner). Kernel-level: real `Process`
/// objects drive the Phase-2 derive/grant/revoke machinery directly.
#[cfg(feature = "neo-test-accel-tensor-sharing")]
fn run_accel_tensor_sharing() -> ! {
    use alloc::sync::Arc;

    use crate::ai::model::Model;
    use crate::ai::sharing;
    use crate::ai::tensor::{self, Device, Dtype, MAX_RANK, Tensor, TensorCreateDesc};
    use crate::arch::x86_64::syscall::tensor_write_checked;
    use crate::drivers::accel::accounting;
    use crate::sched::process::{
        self, Handle, Process, full_model_rights, full_tensor_rights, readonly_tensor_rights,
    };

    fn mk_proc(name: &'static str) -> Arc<Process> {
        let pmap =
            crate::mm::pmap::Pmap::new().unwrap_or_else(|_| fail("reason=sharing_pmap_failed"));
        process::register(Process::new_user(name, pmap))
    }
    fn cap_id_of(proc: &Arc<Process>, h: u32) -> process::CapId {
        proc.handles
            .lock()
            .get(h)
            .map(|handle| handle.cap_id())
            .unwrap_or_else(|| fail("reason=sharing_handle_missing"))
    }

    // ───────────────────────── Part A: explicit RO sharing ─────────────────────────
    let owner = mk_proc("share-owner");
    let r1 = mk_proc("share-reader1");
    let r2 = mk_proc("share-reader2");

    let (allocs0, frees0) = tensor::debug_storage_counts();

    // Owner creates a MUTABLE 4×f32 tensor — so the RO denial below is proven a
    // *capability* fact, not the tensor's own object-level immutability.
    let mut dims = [0u64; MAX_RANK];
    dims[0] = 4;
    let desc = TensorCreateDesc {
        rank: 1,
        dtype: Dtype::F32.as_abi(),
        mutable: 1,
        _pad: 0,
        dims,
        data_ptr: 0,
        data_len: 16,
    };
    let data = [0u8; 16];
    let tensor = match Tensor::from_desc_and_bytes(desc, &data) {
        Ok(t) => Arc::new(t),
        Err(_) => fail("reason=sharing_tensor_create_failed"),
    };
    let tid = tensor.id();
    let bytes = tensor.byte_len() as u64;

    let (allocs1, _) = tensor::debug_storage_counts();
    if allocs1 - allocs0 != 1 {
        fail("reason=sharing_not_one_physical_alloc");
    }

    // Owner holds the full (USE|WRITE) capability.
    let owner_slot = crate::ai::arena::alloc(tensor.clone(), crate::ai::arena::default_home());
    let owner_h = match process::install_cap(
        &owner,
        Handle::Tensor {
            slot: owner_slot,
            meta: tensor.meta(),
            cap_id: process::alloc_cap_id(),
            rights: full_tensor_rights(),
        },
        None,
    ) {
        Ok(idx) => idx,
        Err(_) => fail("reason=sharing_owner_install_failed"),
    };
    // The table entry owns the count now (BUILD-O1b creator-transfer).
    crate::ai::arena::release(owner_slot);

    // Owner derives a per-reader RO capability (USE, no WRITE) and grants it over the
    // Phase-2 capability machinery. Returns (owner's derived handle for independent
    // revoke, the reader's granted handle).
    let derive_and_grant = |reader: &Arc<Process>| -> (u32, u32) {
        let d_h = match process::derive_handle(owner.pid, owner_h, readonly_tensor_rights()) {
            Ok(idx) => idx,
            Err(_) => fail("reason=sharing_derive_failed"),
        };
        let d_cap = cap_id_of(&owner, d_h);
        let g_h = match process::complete_grant(
            owner.pid,
            d_cap,
            readonly_tensor_rights(),
            reader.pid,
            readonly_tensor_rights(),
        ) {
            Ok(idx) => idx,
            Err(_) => fail("reason=sharing_grant_failed"),
        };
        (d_h, g_h)
    };

    let (d1_h, r1_g) = derive_and_grant(&r1);
    let (_d2_h, r2_g) = derive_and_grant(&r2);

    // ISC-1/5: ONE physical copy — sharing allocated nothing.
    let (allocs2, _) = tensor::debug_storage_counts();
    if allocs2 != allocs1 {
        fail("reason=sharing_grant_allocated_a_copy");
    }
    // ISC-5: N RO readers (owner + 2 grantees), one physical copy.
    if sharing::readers(tid).len() != 3 {
        fail("reason=sharing_reader_count_not_3");
    }

    // ISC-2: a RW op by an RO grantee is DENIED at the op boundary; the owner (WRITE)
    // is allowed on the SAME mutable tensor — so it is the capability, not the object,
    // that gates the write.
    let write_data = [1u8; 16];
    if tensor_write_checked(r1.pid, r1_g, 0, &write_data) != crate::errno::EPERM {
        fail("reason=sharing_ro_write_not_denied");
    }
    if tensor_write_checked(owner.pid, owner_h, 0, &write_data) != 0 {
        fail("reason=sharing_owner_write_denied");
    }

    // ISC-4: §9.5 residency counted ONCE, to the owner; readers add zero.
    if accounting::usage(Device::Cpu, owner.pid).resident_bytes != bytes {
        fail("reason=sharing_owner_residency_wrong");
    }
    if accounting::usage(Device::Cpu, r1.pid).resident_bytes != 0
        || accounting::usage(Device::Cpu, r2.pid).resident_bytes != 0
    {
        fail("reason=sharing_reader_residency_double_counted");
    }
    let record = sharing::SharedRecord {
        owner: owner.pid.0,
        bytes,
    };
    let principals = [owner.pid.0, r1.pid.0, r2.pid.0];
    if sharing::total_resident_bytes(&record, &principals) != bytes {
        fail("reason=sharing_total_residency_inflated");
    }

    // ISC-2/5: revocation removes a reader. Revoking the owner's derived cap D1 walks
    // the derivation graph and invalidates r1's granted descendant.
    if process::revoke_handle(owner.pid, d1_h).is_err() {
        fail("reason=sharing_revoke_failed");
    }
    let after_revoke = sharing::readers(tid);
    if after_revoke.len() != 2 || after_revoke.contains(&r1.pid) {
        fail("reason=sharing_revoke_did_not_remove_reader");
    }
    // r1's revoked cap can no longer write (or read): the op boundary now rejects it.
    if tensor_write_checked(r1.pid, r1_g, 0, &write_data) == 0 {
        fail("reason=sharing_revoked_reader_still_writable");
    }

    // ISC-1/5: last-ref-drop frees the one physical copy. Drop every remaining
    // reference — owner's caps, r2's granted cap, and the gate's local Arc.
    owner.handles.lock().remove(owner_h);
    owner.handles.lock().remove(_d2_h);
    r2.handles.lock().remove(r2_g);
    drop(tensor);
    let (_, frees1) = tensor::debug_storage_counts();
    if frees1 - frees0 != 1 {
        fail("reason=sharing_last_drop_did_not_free");
    }
    // Residency released on the free (counted once, released once).
    if accounting::usage(Device::Cpu, owner.pid).resident_bytes != 0 {
        fail("reason=sharing_residency_not_released");
    }
    if sharing::is_registered(tid) {
        fail("reason=sharing_registry_not_cleaned");
    }

    // ───────────────────────── Part B: content-hash dedup on load ─────────────────────────
    let la = mk_proc("dedup-loader-a");
    let lb = mk_proc("dedup-loader-b");

    let (b_allocs0, _) = tensor::debug_storage_counts();
    let prov_a = crate::fs::FileProvenance::synthetic_always_valid();
    let model_a = match Model::from_neom_bytes(&VALID_TRANSFORMER_NEOM, prov_a, Some(la.pid)) {
        Ok(m) => Arc::new(m),
        Err(_) => fail("reason=dedup_load_a_failed"),
    };
    let (b_allocs1, _) = tensor::debug_storage_counts();
    if b_allocs1 <= b_allocs0 {
        fail("reason=dedup_first_load_no_alloc");
    }

    // Second principal loads the IDENTICAL model: every immutable weight dedups against
    // the resident copy — no new physical allocation (ISC-3/5: one physical copy).
    let prov_b = crate::fs::FileProvenance::synthetic_always_valid();
    let model_b = match Model::from_neom_bytes(&VALID_TRANSFORMER_NEOM, prov_b, Some(lb.pid)) {
        Ok(m) => Arc::new(m),
        Err(_) => fail("reason=dedup_load_b_failed"),
    };
    let (b_allocs2, _) = tensor::debug_storage_counts();
    if b_allocs2 != b_allocs1 {
        fail("reason=dedup_second_load_allocated_copy");
    }

    // Install both models as capabilities so the cross-process reader scan sees both
    // principals referencing the shared weights.
    if process::install_cap(
        &la,
        Handle::Model {
            model: model_a.clone(),
            cap_id: process::alloc_cap_id(),
            rights: full_model_rights(),
        },
        None,
    )
    .is_err()
    {
        fail("reason=dedup_model_a_install_failed");
    }
    if process::install_cap(
        &lb,
        Handle::Model {
            model: model_b.clone(),
            cap_id: process::alloc_cap_id(),
            rights: full_model_rights(),
        },
        None,
    )
    .is_err()
    {
        fail("reason=dedup_model_b_install_failed");
    }

    let weight_id = model_a
        .first_weight_id()
        .unwrap_or_else(|| fail("reason=dedup_model_no_weights"));
    // ISC-3/5: two principals, one physical weight copy.
    if sharing::readers(weight_id).len() != 2 {
        fail("reason=dedup_not_two_readers");
    }
    // ISC-4: deduped residency counted once — to the first loader; the second adds zero.
    if accounting::usage(Device::Cpu, la.pid).resident_bytes == 0 {
        fail("reason=dedup_owner_no_residency");
    }
    if accounting::usage(Device::Cpu, lb.pid).resident_bytes != 0 {
        fail("reason=dedup_second_loader_double_counted");
    }
    // The ownership trace fires on the live dedup share.
    sharing::trace_shared(weight_id);

    pass(
        "accel_tensor_sharing=ok explicit_grant=ok dedup_on_load=ok one_physical_copy=alloc_count n_ro_readers=scan rw_by_ro=denied revoke_removes_reader=ok last_drop_frees=ok no_double_count=resident_once trace=accel-share",
    );
}

#[cfg(feature = "neo-test-accel-sim-async-poll")]
fn run_accel_sim_async_poll() -> ! {
    use crate::ai::ops::{OpKind, TensorView};
    use crate::ai::tensor::Dtype;
    use crate::drivers::accel::{self, AccelError, DispatchStatus, OpBatch};

    let Some((_, sim)) = accel::find_device_by_driver("accel_sim") else {
        fail("reason=accel_sim_missing");
    };
    let lhs_shape = accel_test_shape2(1, 2);
    let rhs_shape = accel_test_shape2(2, 2);
    let output_shape = accel_test_shape2(1, 2);
    let mut lhs = [0u8; 8];
    let mut rhs = [0u8; 16];
    let mut out = [0u8; 8];
    write_test_u32(&mut lhs, 0, 0x3f80_0000);
    write_test_u32(&mut lhs, 1, 0x4000_0000);
    write_test_u32(&mut rhs, 0, 0x4040_0000);
    write_test_u32(&mut rhs, 1, 0x4080_0000);
    write_test_u32(&mut rhs, 2, 0x40a0_0000);
    write_test_u32(&mut rhs, 3, 0x40c0_0000);
    let views = [
        TensorView {
            dtype: Dtype::F32,
            shape: &lhs_shape,
            bytes: &lhs,
        },
        TensorView {
            dtype: Dtype::F32,
            shape: &rhs_shape,
            bytes: &rhs,
        },
    ];
    let mut batch = OpBatch {
        op: OpKind::Matmul,
        inputs: &views,
        output_shape: &output_shape,
        output: &mut out,
    };
    let token = match sim.dispatch(&mut batch) {
        Ok(token) => token,
        Err(_) => fail("reason=accel_sim_dispatch_failed"),
    };
    if sim.poll(token) != DispatchStatus::Pending {
        fail("reason=accel_sim_initial_poll_not_pending");
    }
    if read_test_u32(&out, 0) != 0 || read_test_u32(&out, 1) != 0 {
        fail("reason=accel_sim_output_written_before_wait");
    }
    if sim.wait(token, None).is_err() {
        fail("reason=accel_sim_wait_failed");
    }
    if sim.poll(token) != DispatchStatus::Complete {
        fail("reason=accel_sim_poll_after_wait_not_complete");
    }
    if read_test_u32(&out, 0) != 0x4150_0000 || read_test_u32(&out, 1) != 0x4180_0000 {
        fail("reason=accel_sim_matmul_oracle_mismatch");
    }

    let bad_shape = accel_test_shape2(1, 1);
    let bad_input = [0u8; 1];
    let bad_views = [TensorView {
        dtype: Dtype::I8,
        shape: &bad_shape,
        bytes: &bad_input,
    }];
    let mut bad_out = [0u8; 1];
    let mut bad_batch = OpBatch {
        op: OpKind::Identity,
        inputs: &bad_views,
        output_shape: &bad_shape,
        output: &mut bad_out,
    };
    if !matches!(sim.dispatch(&mut bad_batch), Err(AccelError::Unsupported)) {
        fail("reason=accel_sim_unsupported_dtype_not_clean");
    }

    let (arena_allocs, arena_frees) = crate::drivers::accel::accel_sim::debug_arena_counts();
    if arena_allocs != arena_frees || crate::drivers::accel::accel_sim::debug_pending_count() != 0 {
        fail("reason=accel_sim_async_leak");
    }
    pass(
        "accel_sim=ok async=Pending_then_Complete wait=drives_completion dispatch=matmul storage_freed=ok",
    );
}

#[cfg(feature = "neo-test-virtio-accel-identity-roundtrip")]
fn run_virtio_accel_identity_roundtrip() -> ! {
    use core::time::Duration;

    use crate::ai::ops::{OpKind, TensorView};
    use crate::ai::tensor::{Device, Dtype, Shape};
    use crate::drivers::accel::{
        self, AccelDispatchKind, AccelMemoryKind, DispatchStatus, OpBatch,
    };

    let Some((index, driver)) = accel::find_device_by_driver("virtio_accel") else {
        fail("reason=virtio_accel_missing");
    };
    if index != 2 {
        fail("reason=virtio_accel_registry_index_bad");
    }
    let descriptor = driver.descriptor();
    if descriptor.device != Device::Accel(2)
        || descriptor.memory != AccelMemoryKind::DmaBuffer
        || descriptor.dispatch != AccelDispatchKind::Asynchronous
    {
        fail("reason=virtio_accel_descriptor_bad");
    }
    let probe = crate::drivers::accel::virtio_accel::last_probe_snapshot();
    if !probe.seen
        || !probe.probe_ok
        || !probe.common_config
        || !probe.notify_config
        || !probe.isr_config
        || !probe.device_config
        || (!probe.msix_configured && !probe.msi_configured)
        || !probe.queue_ready
    {
        fail("reason=virtio_accel_probe_incomplete");
    }
    if probe.supported_ops & 1 == 0 || probe.supported_dtypes & ((1 << 0) | (1 << 5)) == 0 {
        fail("reason=virtio_accel_config_missing_identity_f32_i32");
    }

    let dma_before = crate::drivers::block::dma::debug_live_buffers();
    let completions_before = crate::drivers::accel::virtio_accel::debug_completion_count();
    let irq_completions_before = crate::drivers::accel::virtio_accel::debug_irq_completion_count();
    let interrupts_before = crate::drivers::accel::virtio_accel::debug_interrupt_count();
    let publish_before = crate::drivers::accel::virtio_accel::debug_descriptor_publish_barriers();
    let notify_before =
        crate::drivers::accel::virtio_accel::debug_notification_suppression_barriers();

    let mut dims = [0u64; crate::ai::tensor::MAX_RANK];
    dims[0] = 2;
    let shape = match Shape::new(1, dims) {
        Ok(shape) => shape,
        Err(_) => fail("reason=virtio_accel_shape_create_failed"),
    };
    let mut input = [0u8; 8];
    let mut out = [0u8; 8];
    write_test_u32(&mut input, 0, 0x3f80_0000);
    write_test_u32(&mut input, 1, 0x4000_0000);
    let views = [TensorView {
        dtype: Dtype::F32,
        shape: &shape,
        bytes: &input,
    }];
    let mut batch = OpBatch {
        op: OpKind::Identity,
        inputs: &views,
        output_shape: &shape,
        output: &mut out,
    };
    let token = match driver.dispatch(&mut batch) {
        Ok(token) => token,
        Err(_) => fail("reason=virtio_accel_identity_dispatch_failed"),
    };
    if token.device != Device::Accel(2) {
        fail("reason=virtio_accel_token_device_bad");
    }
    match driver.poll(token) {
        DispatchStatus::Pending => {
            // The completion IRQ can land between `poll` returning Pending and
            // these reads, copying the output in the meantime (`poll_used`
            // copies, then counts the IRQ completion). Output already there is
            // only a defect if no IRQ completion accounts for it, so wait
            // briefly for the handler's count before failing. The handler
            // counts a few instructions after its copy, so the bound is ample.
            if read_test_u32(&out, 0) != 0 || read_test_u32(&out, 1) != 0 {
                let mut spins = 0u32;
                while crate::drivers::accel::virtio_accel::debug_irq_completion_count()
                    <= irq_completions_before
                {
                    spins += 1;
                    if spins >= 1_000_000 {
                        fail("reason=virtio_accel_output_written_before_irq");
                    }
                    core::hint::spin_loop();
                }
            }
        }
        DispatchStatus::Complete => {
            if crate::drivers::accel::virtio_accel::debug_interrupt_count() <= interrupts_before
                || crate::drivers::accel::virtio_accel::debug_irq_completion_count()
                    <= irq_completions_before
            {
                fail("reason=virtio_accel_completion_not_irq_driven");
            }
        }
        DispatchStatus::Failed(_) => fail("reason=virtio_accel_initial_poll_failed"),
    }
    if !crate::drivers::accel::virtio_accel::debug_last_desc_oracle_match()
        || !crate::drivers::accel::virtio_accel::debug_last_input_oracle_match()
    {
        fail("reason=virtio_accel_request_byte_oracle_mismatch");
    }
    if driver.wait(token, Some(Duration::from_secs(3))).is_err() {
        fail("reason=virtio_accel_identity_wait_failed");
    }
    if driver.poll(token) != DispatchStatus::Complete {
        fail("reason=virtio_accel_poll_after_wait_not_complete");
    }
    if read_test_u32(&out, 0) != 0x3f80_0000 || read_test_u32(&out, 1) != 0x4000_0000 {
        fail("reason=virtio_accel_identity_output_oracle_mismatch");
    }
    if !crate::drivers::accel::virtio_accel::debug_last_status_oracle_match() {
        fail("reason=virtio_accel_status_byte_oracle_mismatch");
    }
    if crate::drivers::accel::virtio_accel::debug_interrupt_count() <= interrupts_before
        || crate::drivers::accel::virtio_accel::debug_irq_completion_count()
            <= irq_completions_before
    {
        fail("reason=virtio_accel_completion_not_irq_driven");
    }
    if crate::drivers::accel::virtio_accel::debug_completion_count() <= completions_before {
        fail("reason=virtio_accel_completion_counter_not_observed");
    }
    if crate::drivers::accel::virtio_accel::debug_descriptor_publish_barriers() <= publish_before
        || crate::drivers::accel::virtio_accel::debug_notification_suppression_barriers()
            <= notify_before
    {
        fail("reason=virtio_accel_barrier_missing");
    }
    if crate::drivers::accel::virtio_accel::debug_in_flight_dma_buffers() != 0 {
        fail("reason=virtio_accel_in_flight_dma_not_released");
    }
    if crate::drivers::block::dma::debug_live_buffers() != dma_before {
        fail("reason=virtio_accel_dma_live_leak");
    }
    pass(
        "virtio_accel=ok op=identity output=byte_oracle irq_completion=ok descriptor_status_oracles=ok",
    );
}

#[cfg(feature = "neo-test-virtio-accel-forward-equiv")]
fn run_virtio_accel_forward_equiv() -> ! {
    use alloc::sync::Arc;

    use crate::ai::exec;
    use crate::drivers::accel::{self, AccelDispatchKind, AccelMemoryKind};

    const EXPECTED: [u8; 12] = [
        0xea, 0xd1, 0x30, 0x43, 0x7d, 0x7f, 0x40, 0x43, 0x0e, 0x2d, 0x50, 0x43,
    ];

    let Some((virtio_index, virtio)) = accel::find_device_by_driver("virtio_accel") else {
        fail("reason=virtio_accel_missing");
    };
    let Some((cpu_index, cpu)) = accel::find_device_by_driver("accel_cpu") else {
        fail("reason=accel_cpu_missing");
    };
    if cpu_index != 0 || virtio_index != 2 {
        fail("reason=virtio_accel_registry_order_bad");
    }
    let descriptor = virtio.descriptor();
    if descriptor.device != crate::ai::tensor::Device::Accel(2)
        || descriptor.memory != AccelMemoryKind::DmaBuffer
        || descriptor.dispatch != AccelDispatchKind::Asynchronous
    {
        fail("reason=virtio_accel_descriptor_bad");
    }
    virtio_accel_assert_full_config();
    let dma_before = crate::drivers::block::dma::debug_live_buffers();
    virtio_accel_add_oracle(virtio.as_ref());

    let model = virtio_accel_load_valid_mlp_model();
    let input = Arc::new(virtio_accel_mlp_input());
    let inputs = [input.clone()];
    let cpu_outputs = match exec::run_with_driver(&model, &inputs, cpu.as_ref()) {
        Ok(outputs) => outputs,
        Err(_) => fail("reason=virtio_accel_cpu_run_failed"),
    };
    let virtio_outputs = match exec::run_with_driver(&model, &inputs, virtio.as_ref()) {
        Ok(outputs) => outputs,
        Err(_) => fail("reason=virtio_accel_run_failed"),
    };
    if cpu_outputs.len() != 1 || virtio_outputs.len() != 1 {
        fail("reason=virtio_accel_output_count_bad");
    }
    if cpu_outputs[0].bytes() != EXPECTED || virtio_outputs[0].bytes() != EXPECTED {
        fail("reason=virtio_accel_oracle_mismatch");
    }
    if virtio_outputs[0].bytes() != cpu_outputs[0].bytes() {
        fail("reason=virtio_accel_cross_device_mismatch");
    }

    drop(virtio_outputs);
    drop(cpu_outputs);
    drop(inputs);
    drop(input);
    drop(model);
    if crate::drivers::accel::virtio_accel::debug_in_flight_dma_buffers() != 0 {
        fail("reason=virtio_accel_in_flight_dma_not_released");
    }
    if crate::drivers::block::dma::debug_live_buffers() != dma_before {
        fail("reason=virtio_accel_dma_live_leak");
    }
    let (allocs, frees) = crate::ai::tensor::debug_storage_counts();
    if allocs != frees {
        fail("reason=virtio_accel_forward_storage_leak");
    }
    pass(
        "virtio_accel=ok model=valid_mlp output=oracle cross_device=accel_cpu add_data_oracle=ok storage_freed=ok",
    );
}

#[cfg(feature = "neo-test-virtio-accel-migrate-roundtrip")]
fn run_virtio_accel_migrate_roundtrip() -> ! {
    use alloc::sync::Arc;

    use crate::ai::exec;
    use crate::ai::tensor::{Device, Tensor, TensorCreateDesc, tensor_migrate};
    use crate::drivers::accel;

    const EXPECTED: [u8; 12] = [
        0xea, 0xd1, 0x30, 0x43, 0x7d, 0x7f, 0x40, 0x43, 0x0e, 0x2d, 0x50, 0x43,
    ];

    let Some((_, virtio)) = accel::find_device_by_driver("virtio_accel") else {
        fail("reason=virtio_accel_missing");
    };
    let Some((_, cpu)) = accel::find_device_by_driver("accel_cpu") else {
        fail("reason=accel_cpu_missing");
    };
    virtio_accel_assert_full_config();
    virtio_accel_add_oracle(virtio.as_ref());

    let dma_before = crate::drivers::block::dma::debug_live_buffers();
    for iter in 0..8usize {
        let mut storage = match virtio.alloc(16, crate::ai::tensor::PAGE_SIZE) {
            Ok(storage) => storage,
            Err(_) => fail("reason=virtio_accel_alloc_loop_failed"),
        };
        let mut src = [0u8; 16];
        for (idx, byte) in src.iter_mut().enumerate() {
            *byte = (iter as u8).wrapping_mul(19).wrapping_add(idx as u8);
        }
        let original = src;
        if virtio.copy_to_device(&mut storage, &src).is_err() {
            fail("reason=virtio_accel_copy_to_failed");
        }
        src.fill(0xa5);
        let mut first = [0u8; 16];
        if virtio.copy_from_device(&mut first, &storage).is_err() || first != original {
            fail("reason=virtio_accel_copy_from_non_identity_failed");
        }
        first.fill(0x5a);
        let mut second = [0u8; 16];
        if virtio.copy_from_device(&mut second, &storage).is_err() || second != original {
            fail("reason=virtio_accel_host_mutation_aliased_dma");
        }
        virtio.free(storage);
    }
    if crate::drivers::block::dma::debug_live_buffers() != dma_before {
        fail("reason=virtio_accel_copy_loop_dma_leak");
    }

    let initial = [
        0x00, 0x00, 0x80, 0x3f, 0x00, 0x00, 0x00, 0x40, 0x00, 0x00, 0x40, 0x40, 0x00, 0x00, 0x80,
        0x40,
    ];
    let mut dims = [0u64; crate::ai::tensor::MAX_RANK];
    dims[0] = 4;
    let desc = TensorCreateDesc {
        rank: 1,
        dtype: crate::ai::tensor::Dtype::F32.as_abi(),
        mutable: 1,
        _pad: 0,
        dims,
        data_ptr: 0,
        data_len: initial.len() as u64,
    };
    {
        let mut tensor = match Tensor::from_desc_and_bytes(desc, &initial) {
            Ok(tensor) => tensor,
            Err(_) => fail("reason=virtio_accel_tensor_create_failed"),
        };
        if tensor_migrate(&mut tensor, Device::Accel(2)).is_err() {
            fail("reason=virtio_accel_tensor_migrate_to_virtio_failed");
        }
        if tensor.device() != Device::Accel(2)
            || tensor.query_desc(1).device != Device::Accel(2).as_abi()
            || crate::drivers::block::dma::debug_live_buffers() <= dma_before
        {
            fail("reason=virtio_accel_tensor_not_dma_resident");
        }
        if tensor_migrate(&mut tensor, Device::Cpu).is_err() {
            fail("reason=virtio_accel_tensor_migrate_to_cpu_failed");
        }
        if tensor.device() != Device::Cpu || tensor.bytes() != initial.as_slice() {
            fail("reason=virtio_accel_roundtrip_bytes_changed");
        }
    }
    if crate::drivers::block::dma::debug_live_buffers() != dma_before {
        fail("reason=virtio_accel_tensor_roundtrip_dma_leak");
    }

    let model = virtio_accel_load_valid_mlp_model();
    let mut migrated_input = virtio_accel_mlp_input();
    if tensor_migrate(&mut migrated_input, Device::Accel(2)).is_err() {
        fail("reason=virtio_accel_mlp_input_migrate_failed");
    }
    if migrated_input.device() != Device::Accel(2) {
        fail("reason=virtio_accel_mlp_input_not_dma_resident");
    }
    let migrated_input = Arc::new(migrated_input);
    let cpu_input = Arc::new(virtio_accel_mlp_input());
    let migrated_inputs = [migrated_input.clone()];
    let cpu_inputs = [cpu_input.clone()];
    let virtio_outputs = match exec::run_with_driver(&model, &migrated_inputs, virtio.as_ref()) {
        Ok(outputs) => outputs,
        Err(_) => fail("reason=virtio_accel_migrated_run_failed"),
    };
    let cpu_outputs = match exec::run_with_driver(&model, &cpu_inputs, cpu.as_ref()) {
        Ok(outputs) => outputs,
        Err(_) => fail("reason=virtio_accel_migrated_cpu_run_failed"),
    };
    if virtio_outputs.len() != 1
        || cpu_outputs.len() != 1
        || virtio_outputs[0].bytes() != EXPECTED
        || cpu_outputs[0].bytes() != EXPECTED
        || virtio_outputs[0].bytes() != cpu_outputs[0].bytes()
    {
        fail("reason=virtio_accel_migrated_forward_mismatch");
    }

    drop(virtio_outputs);
    drop(cpu_outputs);
    drop(migrated_inputs);
    drop(cpu_inputs);
    drop(migrated_input);
    drop(cpu_input);
    drop(model);
    if crate::drivers::accel::virtio_accel::debug_in_flight_dma_buffers() != 0 {
        fail("reason=virtio_accel_migrate_in_flight_dma_not_released");
    }
    if crate::drivers::block::dma::debug_live_buffers() != dma_before {
        fail("reason=virtio_accel_migrate_dma_live_leak");
    }
    let (allocs, frees) = crate::ai::tensor::debug_storage_counts();
    if allocs != frees {
        fail("reason=virtio_accel_migrate_storage_leak");
    }
    pass(
        "virtio_accel=ok copy=non_identity tensor_migrate=cpu_virtio_cpu migrated_forward=oracle add_data_oracle=ok storage_freed=ok",
    );
}

// BUILD-4b-2 ISC-3/4 forward-pass-equivalence references. The accel_intel scenario
// embeds the alid_transformer_block model (input(1,4) -> LayerNorm -> MatMul(4x4) ->
// Gelu -> RmsNorm -> Softmax) in the kernel image rather than mounting it from a disk,
// so the blind OptiPlex run gains no new disk/mount hardware dependency. Under
// accel_intel: MatMul + Gelu route to the GPU; LayerNorm/RmsNorm/Softmax fall back to
// accel_cpu. References computed + self-checked in tools/ai-ops-tests
// (transformer_forward_references_match_embedded):
