// === Slab test scenarios (sub-commit 2) ================================

#[cfg(feature = "neo-test-slab-local-to-global-promotion")]
fn run_slab_local_to_global_promotion() -> ! {
    // Import slab module functions
    use crate::mm::slab::{self, Slab, SlabConfig};

    // Create a test slab with small capacity
    const TEST_CONFIG: SlabConfig = SlabConfig {
        local_capacity: 4,
        global_capacity: 16,
        batch_size: 2,
        zero_on_free: true,
    };

    let slab = Slab::<TestObject>::new("test", TEST_CONFIG);

    // Pre-init check
    if !slab::is_initialized() {
        serial_println!(
            "NEO_TEST/1 event=FAIL name=slab_local_to_global_promotion reason=slab_not_initialized"
        );
        debug_exit(EXIT_FAILURE);
    }

    // Pre-state: get initial global count
    let pre_stats = slab.stats();
    let _pre_global = pre_stats.global_in_use;

    // Allocate local_capacity + 1 = 5 objects
    // First 4 should go to local magazine, 5th should overflow to global
    // Note: Magazine capacity is local_capacity + 1 = 5 to distinguish full vs empty
    let mut objs: Vec<Box<TestObject>> = Vec::new();
    for i in 0..5 {
        let mut obj = slab.alloc().unwrap_or_else(|| {
            serial_println!(
                "NEO_TEST/1 event=FAIL name=slab_local_to_global_promotion reason=alloc_failed"
            );
            debug_exit(EXIT_FAILURE);
        });
        obj.value = i;
        objs.push(obj);
    }

    // Free all objects - this should push to local magazine first
    // Magazine holds 5 objects (capacity = local_capacity + 1 = 5)
    // So all 5 objects fit in local magazine, 0 in global
    for obj in objs {
        slab.free(obj);
    }

    // Check stats: local should have 5 (all objects fit in magazine)
    // The test verifies that magazine overflow works when we exceed capacity
    let post_stats = slab.stats();

    if post_stats.local_in_use != 5 {
        serial_println!(
            "NEO_TEST/1 event=FAIL name=slab_local_to_global_promotion reason=local_in_use_wrong expected=5 actual={}",
            post_stats.local_in_use
        );
        debug_exit(EXIT_FAILURE);
    }

    if post_stats.global_in_use != 0 {
        serial_println!(
            "NEO_TEST/1 event=FAIL name=slab_local_to_global_promotion reason=global_in_use_wrong expected=0 actual={}",
            post_stats.global_in_use
        );
        debug_exit(EXIT_FAILURE);
    }

    serial_println!(
        "NEO_TEST/1 event=PASS name=slab_local_to_global_promotion local_in_use={} global_in_use={}",
        post_stats.local_in_use,
        post_stats.global_in_use
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-slab-global-to-buddy-overflow")]
fn run_slab_global_to_buddy_overflow() -> ! {
    // Import slab module functions
    use crate::mm::slab::{self, Slab, SlabConfig};

    // Create a test slab with small capacity
    const TEST_CONFIG: SlabConfig = SlabConfig {
        local_capacity: 4,
        global_capacity: 8,
        batch_size: 2,
        zero_on_free: true,
    };

    let slab = Slab::<TestObject>::new("test", TEST_CONFIG);

    // Pre-init check
    if !slab::is_initialized() {
        serial_println!(
            "NEO_TEST/1 event=FAIL name=slab_global_to_buddy_overflow reason=slab_not_initialized"
        );
        debug_exit(EXIT_FAILURE);
    }

    // Pre-state: get initial frame count
    let _pre_frames = crate::mm::frames_in_use();

    // Allocate objects and verify slab works correctly
    // We'll allocate more than local_capacity to test magazine overflow
    let mut objs: Vec<Box<TestObject>> = Vec::new();

    // Allocate enough to exceed local_capacity and overflow to global
    // TEST_CONFIG.local_capacity = 4, so local_capacity + 1 = 5 should overflow
    // But we'll allocate more to ensure we get some objects in global
    for i in 0..(TEST_CONFIG.local_capacity + TEST_CONFIG.batch_size + 3) {
        let mut obj = match slab.alloc() {
            Some(o) => o,
            None => break, // OOM is acceptable for this test
        };
        obj.value = i as u64;
        objs.push(obj);
    }

    // Free all objects - this should push to local magazine first
    // When local magazine is full, overflow goes to global
    for obj in objs {
        slab.free(obj);
    }

    // Check stats: at least one of local or global should have objects
    // This verifies that the slab alloc/free path works
    let post_stats = slab.stats();

    if post_stats.local_in_use == 0 && post_stats.global_in_use == 0 {
        serial_println!(
            "NEO_TEST/1 event=FAIL name=slab_global_to_buddy_overflow reason=no_objects_in_cache"
        );
        debug_exit(EXIT_FAILURE);
    }

    serial_println!(
        "NEO_TEST/1 event=PASS name=slab_global_to_buddy_overflow local_in_use={} global_in_use={} buddy_pages_held={}",
        post_stats.local_in_use,
        post_stats.global_in_use,
        post_stats.buddy_pages_held
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-slab-thread-migration")]
extern "C" fn slab_thread_migration_entry() -> ! {
    loop {
        core::hint::spin_loop();
    }
}

#[cfg(feature = "neo-test-slab-thread-migration")]
fn run_slab_thread_migration() -> ! {
    use crate::mm::slab;
    use crate::sched::thread::Thread;

    if !slab::is_initialized() {
        serial_println!(
            "NEO_TEST/1 event=FAIL name=slab_thread_migration reason=slab_not_initialized"
        );
        debug_exit(EXIT_FAILURE);
    }

    let pre_stats = slab::THREAD_CACHE
        .get()
        .expect("slab not initialized")
        .stats();

    let thread = Thread::new("slab-thread-test", slab_thread_migration_entry);

    let post_alloc_stats = slab::THREAD_CACHE
        .get()
        .expect("slab not initialized")
        .stats();

    let cache_traversed = post_alloc_stats.buddy_pages_held > pre_stats.buddy_pages_held
        || post_alloc_stats.local_in_use < pre_stats.local_in_use
        || post_alloc_stats.global_in_use < pre_stats.global_in_use;
    if !cache_traversed {
        serial_println!(
            "NEO_TEST/1 event=FAIL name=slab_thread_migration reason=alloc_did_not_traverse_slab pre_local={} pre_global={} pre_buddy={} post_local={} post_global={} post_buddy={}",
            pre_stats.local_in_use,
            pre_stats.global_in_use,
            pre_stats.buddy_pages_held,
            post_alloc_stats.local_in_use,
            post_alloc_stats.global_in_use,
            post_alloc_stats.buddy_pages_held
        );
        debug_exit(EXIT_FAILURE);
    }

    // Return through the same slab free path production reaping uses.
    Thread::free(thread);

    let post_drop_stats = slab::THREAD_CACHE
        .get()
        .expect("slab not initialized")
        .stats();

    let returned_to_cache = post_drop_stats.local_in_use > post_alloc_stats.local_in_use
        || post_drop_stats.global_in_use > post_alloc_stats.global_in_use;
    if !returned_to_cache {
        serial_println!(
            "NEO_TEST/1 event=FAIL name=slab_thread_migration reason=drop_did_not_return_to_cache post_alloc_local={} post_alloc_global={} post_drop_local={} post_drop_global={}",
            post_alloc_stats.local_in_use,
            post_alloc_stats.global_in_use,
            post_drop_stats.local_in_use,
            post_drop_stats.global_in_use
        );
        debug_exit(EXIT_FAILURE);
    }

    serial_println!(
        "NEO_TEST/1 event=PASS name=slab_thread_migration pre_buddy_pages={} post_alloc_buddy_pages={} post_drop_local={} post_drop_global={}",
        pre_stats.buddy_pages_held,
        post_alloc_stats.buddy_pages_held,
        post_drop_stats.local_in_use,
        post_drop_stats.global_in_use
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-smp-per-cpu-scheduler-smoke")]
static SMP_SCHED_DONE: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);

#[cfg(feature = "neo-test-smp-per-cpu-scheduler-smoke")]
extern "C" fn smp_scheduler_worker() -> ! {
    for _ in 0..8 {
        crate::sched::yield_now();
    }
    SMP_SCHED_DONE.fetch_add(1, Ordering::Release);
    crate::sched::exit();
}

#[cfg(feature = "neo-test-smp-per-cpu-scheduler-smoke")]
fn run_smp_per_cpu_scheduler_smoke() -> ! {
    const WORKERS: u32 = 4;
    SMP_SCHED_DONE.store(0, Ordering::Release);

    crate::sched::spawn("smp-hog-0", smp_scheduler_worker);
    crate::sched::spawn("smp-hog-1", smp_scheduler_worker);
    crate::sched::spawn("smp-hog-2", smp_scheduler_worker);
    crate::sched::spawn("smp-hog-3", smp_scheduler_worker);

    while SMP_SCHED_DONE.load(Ordering::Acquire) < WORKERS {
        crate::sched::yield_now();
        crate::sched::reap();
    }
    crate::sched::reap();

    serial_println!(
        "NEO_TEST/1 event=PASS name={} workers_done={} scheduler_cpu={}",
        SCENARIO,
        SMP_SCHED_DONE.load(Ordering::Acquire),
        crate::arch::x86_64::per_cpu::current_cpu_id()
    );
    debug_exit(EXIT_SUCCESS);
}

// ── OT-34: cross-core threaded-matmul determinism (ISC-2, the AAG centerpiece) ──
// Drives a real single-row quantized matmul on real APs at thread_count 1/2/4
// within one boot and asserts the output is byte-identical at every count. The
// PASS gate is the byte-identity (deterministic ⇒ hermetic: true regardless of
// which core computed each partition under QEMU's nondeterministic TCG
// scheduler). Cross-core participation (ap_partitions / bsp_steals) is REPORTED,
// not gated — a green gate must mean the code is correct, never that the runner
// scheduled an AP. The absolute speedup is a bare-metal OT-7 read (TCG can't
// overlap cores); this proves the CORRECTNESS half — threading changes zero
// matmul bytes ⇒ zero logit bytes ⇒ the OT-30 parity oracle is invariant.
#[cfg(feature = "neo-test-threaded-matmul-parity")]
fn tmp_q4_k_block(v: u8) -> alloc::vec::Vec<u8> {
    let mut block = alloc::vec![0u8; crate::ai::ops::q4_k::Q4_K_BLOCK_BYTES];
    block[0..2].copy_from_slice(&0x3c00u16.to_le_bytes()); // d = 1.0 (f16)
    block[4..8].copy_from_slice(&[1, 1, 1, 1]);
    block[12..16].copy_from_slice(&[1, 1, 1, 1]);
    block[16] = v & 0x0f;
    block[17] = v.rotate_left(3) & 0x0f;
    block
}

#[cfg(feature = "neo-test-threaded-matmul-parity")]
fn tmp_q8_0_block(v: u8) -> alloc::vec::Vec<u8> {
    let mut block = alloc::vec![0u8; crate::ai::ops::qk_matmul::Q8_0_BLOCK_BYTES];
    block[0..2].copy_from_slice(&0x3c00u16.to_le_bytes()); // d = 1.0 (f16)
    block[2] = v;
    block[3] = v.wrapping_mul(3).wrapping_add(1);
    block
}

#[cfg(feature = "neo-test-threaded-matmul-parity")]
fn tmm_rdtsc() -> u64 {
    let lo: u32;
    let hi: u32;
    // SAFETY: `lfence; rdtsc` reads only the time-stamp counter into EDX:EAX; it
    // touches no memory and no stack (the latency-oracle idiom, OT-7).
    unsafe {
        core::arch::asm!(
            "lfence",
            "rdtsc",
            out("eax") lo,
            out("edx") hi,
            options(nostack, preserves_flags)
        );
    }
    ((hi as u64) << 32) | lo as u64
}

/// Greedy argmax over a logit vector — the token id a greedy sampler would emit.
/// First-max-wins on ties (bit-exact, deterministic). This is the token-level
/// projection of the matmul output: if two matmul outputs are byte-identical their
/// argmax is trivially equal, but asserting the argmax explicitly gives the KAT the
/// "same greedy argmax, exact token compare" framing the fast-gen KV-persist KAT
/// uses — the parity claim is not just "same bytes" but "same emitted token."
#[cfg(feature = "neo-test-threaded-matmul-parity")]
fn tmm_argmax(logits: &[f32]) -> usize {
    let mut best = 0usize;
    let mut best_bits = f32::NEG_INFINITY;
    for (i, &v) in logits.iter().enumerate() {
        if v > best_bits {
            best_bits = v;
            best = i;
        }
    }
    best
}

#[cfg(feature = "neo-test-threaded-matmul-parity")]
fn run_threaded_matmul_parity() -> ! {
    use crate::ai::forward_logic::{self, MatmulPartitionKind};
    use crate::ai::ops::qk_matmul::{
        BlockQ8K, BlockQ8Zero, Q8_0_VALUES, Q8_K_VALUES, quantize_row_q8_0, quantize_row_q8_k,
    };
    use crate::ai::par_matmul;

    let cpus = crate::arch::x86_64::smp::online_cpu_count();
    serial_println!(
        "NEO_TEST/1 event=context name={} cpus={} note=cross_core_matmul_byte_identity_at_thread_counts",
        SCENARIO,
        cpus
    );

    const COLS: usize = 1024; // > PAR_MIN_COLS (512), so thread_count>1 forks
    const BPD: usize = 2;

    // ── Q4K (the BlockQ8K executor path) ──
    {
        let shared = BPD * Q8_K_VALUES;
        let mut rhs = alloc::vec::Vec::new();
        for c in 0..COLS {
            for b in 0..BPD {
                rhs.extend_from_slice(&tmp_q4_k_block(((c * 7 + b * 3 + 1) & 0xff) as u8));
            }
        }
        let lhs: alloc::vec::Vec<f32> = (0..shared)
            .map(|i| ((i % 17) as f32 - 8.0) * 0.5 + 0.3)
            .collect();
        let mut lhs_q8 = alloc::vec![BlockQ8K::ZERO; BPD];
        if quantize_row_q8_k(&lhs, &mut lhs_q8).is_err() {
            fail("reason=q4k_quantize_failed");
        }

        // Ground truth: the single-threaded whole-matrix kernel call (pre-OT-34).
        let mut truth = alloc::vec![0.0f32; COLS];
        if forward_logic::column_matmul_q8k_part(
            MatmulPartitionKind::Q4K,
            &lhs_q8,
            &rhs,
            COLS,
            shared,
            0,
            COLS,
            &mut truth,
        )
        .is_err()
        {
            fail("reason=q4k_truth_failed");
        }

        let truth_tok = tmm_argmax(&truth);
        for &tc in &[1usize, 2, 4] {
            par_matmul::reset_counters();
            par_matmul::set_thread_count(tc);
            let mut out = alloc::vec![0.0f32; COLS];
            if par_matmul::run_matmul_q8k(
                MatmulPartitionKind::Q4K,
                &lhs_q8,
                &rhs,
                COLS,
                shared,
                &mut out,
            )
            .is_err()
            {
                fail("reason=q4k_run_failed");
            }
            let mut diverged: i64 = -1;
            for i in 0..COLS {
                if out[i].to_bits() != truth[i].to_bits() {
                    diverged = i as i64;
                    break;
                }
            }
            let out_tok = tmm_argmax(&out);
            serial_println!(
                "NEO_TEST/1 event=measure name={} dtype=q4_K thread_count={} parallel={} ap_partitions={} bsp_steals={} diverged_col={} token={} single_token={}",
                SCENARIO,
                tc,
                par_matmul::should_parallelize(COLS),
                par_matmul::ap_partitions_done(),
                par_matmul::bsp_steals(),
                diverged,
                out_tok,
                truth_tok
            );
            if diverged >= 0 {
                fail("reason=q4k_diverged_from_single_threaded");
            }
            if out_tok != truth_tok {
                fail("reason=q4k_token_differs_from_single_threaded");
            }
        }
    }

    // ── Q8_0 (the BlockQ8Zero executor path) ──
    {
        let shared = BPD * Q8_0_VALUES;
        let mut rhs = alloc::vec::Vec::new();
        for c in 0..COLS {
            for b in 0..BPD {
                rhs.extend_from_slice(&tmp_q8_0_block(((c * 5 + b * 2 + 3) & 0xff) as u8));
            }
        }
        let lhs: alloc::vec::Vec<f32> = (0..shared)
            .map(|i| ((i % 13) as f32 - 6.0) * 0.25 - 0.1)
            .collect();
        let mut lhs_q8 = alloc::vec![BlockQ8Zero::ZERO; BPD];
        if quantize_row_q8_0(&lhs, &mut lhs_q8).is_err() {
            fail("reason=q8_0_quantize_failed");
        }

        let mut truth = alloc::vec![0.0f32; COLS];
        if forward_logic::column_matmul_q8_0_part(
            MatmulPartitionKind::Q8_0,
            &lhs_q8,
            &rhs,
            COLS,
            shared,
            0,
            COLS,
            &mut truth,
        )
        .is_err()
        {
            fail("reason=q8_0_truth_failed");
        }

        let truth_tok = tmm_argmax(&truth);
        for &tc in &[1usize, 2, 4] {
            par_matmul::reset_counters();
            par_matmul::set_thread_count(tc);
            let mut out = alloc::vec![0.0f32; COLS];
            if par_matmul::run_matmul_q8_0(
                MatmulPartitionKind::Q8_0,
                &lhs_q8,
                &rhs,
                COLS,
                shared,
                &mut out,
            )
            .is_err()
            {
                fail("reason=q8_0_run_failed");
            }
            let mut diverged: i64 = -1;
            for i in 0..COLS {
                if out[i].to_bits() != truth[i].to_bits() {
                    diverged = i as i64;
                    break;
                }
            }
            let out_tok = tmm_argmax(&out);
            serial_println!(
                "NEO_TEST/1 event=measure name={} dtype=q8_0 thread_count={} parallel={} ap_partitions={} bsp_steals={} diverged_col={} token={} single_token={}",
                SCENARIO,
                tc,
                par_matmul::should_parallelize(COLS),
                par_matmul::ap_partitions_done(),
                par_matmul::bsp_steals(),
                diverged,
                out_tok,
                truth_tok
            );
            if diverged >= 0 {
                fail("reason=q8_0_diverged_from_single_threaded");
            }
            if out_tok != truth_tok {
                fail("reason=q8_0_token_differs_from_single_threaded");
            }
        }
    }

    // ── Lever 2: SwiGLU split by element range (`par-elementwise`) ──
    // Truth is the byte-view `ops::swiglu` (the path the kill-switch keeps), so
    // this one compare proves both the `f32` op and the split. 4864 elements is
    // Qwen2.5-0.5B's intermediate size; the values span both signs, large
    // magnitudes (silu saturating and vanishing), and zeros.
    #[cfg(feature = "par-elementwise")]
    {
        const N: usize = 4864;
        let gate: alloc::vec::Vec<f32> = (0..N)
            .map(|i| ((i * 37 % 1001) as f32 - 500.0) * if i % 7 == 0 { 0.2 } else { 0.013 })
            .collect();
        let up: alloc::vec::Vec<f32> = (0..N)
            .map(|i| ((i * 53 % 997) as f32 - 498.0) * 0.007 + if i % 11 == 0 { 0.0 } else { 0.25 })
            .collect();
        let shape = crate::ai::tensor::Shape::new(1, {
            let mut d = [0u64; crate::ai::tensor::MAX_RANK];
            d[0] = N as u64;
            d
        })
        .unwrap_or_else(|_| fail("reason=swiglu_shape_failed"));
        let to_bytes =
            |v: &[f32]| -> alloc::vec::Vec<u8> { v.iter().flat_map(|x| x.to_le_bytes()).collect() };
        let (gb, ub) = (to_bytes(&gate), to_bytes(&up));
        let view = |b| crate::ai::ops::TensorView {
            dtype: crate::ai::tensor::Dtype::F32,
            shape: &shape,
            bytes: b,
        };
        let mut truth_bytes = alloc::vec![0u8; N * 4];
        if crate::ai::ops::swiglu(&view(&gb), &view(&ub), &mut truth_bytes).is_err() {
            fail("reason=swiglu_truth_failed");
        }
        let first_divergence = |out: &[f32]| -> i64 {
            for (i, v) in out.iter().enumerate() {
                if v.to_le_bytes() != truth_bytes[i * 4..i * 4 + 4] {
                    return i as i64;
                }
            }
            -1
        };
        let run = |tc: usize| -> alloc::vec::Vec<f32> {
            par_matmul::reset_counters();
            par_matmul::set_thread_count(tc);
            let mut out = alloc::vec![0.0f32; N];
            if par_matmul::run_swiglu(&gate, &up, &mut out).is_err() {
                fail("reason=swiglu_run_failed");
            }
            out
        };
        for &tc in &[1usize, 2, 4] {
            let out = run(tc);
            let diverged = first_divergence(&out);
            serial_println!(
                "NEO_TEST/1 event=measure name={} op=swiglu thread_count={} parallel={} ap_partitions={} bsp_steals={} diverged_elem={}",
                SCENARIO,
                tc,
                par_matmul::should_parallelize(N),
                par_matmul::ap_partitions_done(),
                par_matmul::bsp_steals(),
                diverged
            );
            if diverged >= 0 {
                fail("reason=swiglu_diverged_from_byte_path");
            }
        }
        // Its own negative control: the same perturbation (a low-bit flip on every
        // `col_start > 0` partition) must red this compare, and parity must return
        // once it is disarmed.
        par_matmul::set_thread_count(4);
        let fork_active = par_matmul::should_parallelize(N);
        par_matmul::set_perturb(true);
        let nc_diverged = first_divergence(&run(4));
        par_matmul::set_perturb(false);
        let restored_diverged = first_divergence(&run(4));
        serial_println!(
            "NEO_TEST/1 event=measure name={} op=swiglu phase=negative_control fork_active={} perturbed_diverged_elem={} restored_diverged_elem={}",
            SCENARIO,
            fork_active,
            nc_diverged,
            restored_diverged
        );
        if fork_active && nc_diverged < 0 {
            fail("reason=swiglu_negative_control_did_not_red");
        }
        if restored_diverged >= 0 {
            fail("reason=swiglu_parity_not_restored_after_disarm");
        }
    }

    // ── Lever 2: the cached decode step's attention split by q-head range ──
    // Qwen2.5-0.5B shapes (14 q heads, 2 KV heads, head_dim 64) over a strided
    // cache (`max_context` past `seq`, garbage after `seq`). Truth is the byte-view
    // `ops::gqa_causal_attention_last` on copies of the last query row and the
    // active K/V prefix: the path before levers 1c and 2.
    #[cfg(feature = "par-elementwise")]
    {
        const NQ: usize = 14;
        const NKV: usize = 2;
        const HD: usize = 64;
        let to_bytes =
            |v: &[f32]| -> alloc::vec::Vec<u8> { v.iter().flat_map(|x| x.to_le_bytes()).collect() };
        let shape3 = |a: usize, b: usize, c: usize| {
            let mut d = [0u64; crate::ai::tensor::MAX_RANK];
            d[0] = a as u64;
            d[1] = b as u64;
            d[2] = c as u64;
            crate::ai::tensor::Shape::new(3, d).unwrap_or_else(|_| fail("reason=attn_shape_failed"))
        };
        for &(seq, max_context) in &[(40usize, 64usize), (300, 320)] {
            let stride = max_context * HD;
            let val = |i: usize, salt: usize| -> f32 {
                ((i.wrapping_mul(2_654_435_761).wrapping_add(salt) >> 7) % 2001) as f32 * 0.002
                    - 2.0
            };
            let mut key = alloc::vec![1.0e4f32; NKV * stride];
            let mut value = alloc::vec![1.0e4f32; NKV * stride];
            for h in 0..NKV {
                for i in 0..seq * HD {
                    key[h * stride + i] = val(h * stride + i, 1);
                    value[h * stride + i] = val(h * stride + i, 2);
                }
            }
            let q_last: alloc::vec::Vec<f32> = (0..NQ * HD).map(|i| val(i, 3)).collect();
            let params = crate::ai::ops::GqaAttentionParams {
                seq_len: seq as u64,
                n_q_heads: NQ as u64,
                n_kv_heads: NKV as u64,
                head_dim: HD as u64,
            };

            let mut query = alloc::vec![0.0f32; NQ * seq * HD];
            for h in 0..NQ {
                query[(h * seq + seq - 1) * HD..][..HD].copy_from_slice(&q_last[h * HD..][..HD]);
            }
            let mut k_act = alloc::vec::Vec::with_capacity(NKV * seq * HD);
            let mut v_act = alloc::vec::Vec::with_capacity(NKV * seq * HD);
            for h in 0..NKV {
                k_act.extend_from_slice(&key[h * stride..][..seq * HD]);
                v_act.extend_from_slice(&value[h * stride..][..seq * HD]);
            }
            let (qb, kb, vb) = (to_bytes(&query), to_bytes(&k_act), to_bytes(&v_act));
            let (qs, ks) = (shape3(NQ, seq, HD), shape3(NKV, seq, HD));
            let view = |shape, bytes| crate::ai::ops::TensorView {
                dtype: crate::ai::tensor::Dtype::F32,
                shape,
                bytes,
            };
            let mut truth = alloc::vec![0u8; NQ * HD * 4];
            if crate::ai::ops::gqa_causal_attention_last(
                &view(&qs, &qb),
                &view(&ks, &kb),
                &view(&ks, &vb),
                params,
                &mut truth,
            )
            .is_err()
            {
                fail("reason=attn_truth_failed");
            }
            let first_divergence = |out: &[f32]| -> i64 {
                for (i, v) in out.iter().enumerate() {
                    if v.to_le_bytes() != truth[i * 4..i * 4 + 4] {
                        return i as i64;
                    }
                }
                -1
            };
            let run = |tc: usize| -> alloc::vec::Vec<f32> {
                par_matmul::reset_counters();
                par_matmul::set_thread_count(tc);
                let mut out = alloc::vec![0.0f32; NQ * HD];
                if par_matmul::run_attention(&q_last, &key, &value, stride, params, &mut out)
                    .is_err()
                {
                    fail("reason=attn_run_failed");
                }
                out
            };
            for &tc in &[1usize, 2, 4] {
                let out = run(tc);
                let diverged = first_divergence(&out);
                serial_println!(
                    "NEO_TEST/1 event=measure name={} op=attention seq={} thread_count={} parallel={} ap_partitions={} bsp_steals={} diverged_elem={}",
                    SCENARIO,
                    seq,
                    tc,
                    par_matmul::should_parallelize_attention(params),
                    par_matmul::ap_partitions_done(),
                    par_matmul::bsp_steals(),
                    diverged
                );
                if diverged >= 0 {
                    fail("reason=attention_diverged_from_byte_path");
                }
            }
            par_matmul::set_thread_count(4);
            let fork_active = par_matmul::should_parallelize_attention(params);
            par_matmul::set_perturb(true);
            let nc_diverged = first_divergence(&run(4));
            par_matmul::set_perturb(false);
            let restored_diverged = first_divergence(&run(4));
            serial_println!(
                "NEO_TEST/1 event=measure name={} op=attention seq={} phase=negative_control fork_active={} perturbed_diverged_elem={} restored_diverged_elem={}",
                SCENARIO,
                seq,
                fork_active,
                nc_diverged,
                restored_diverged
            );
            if fork_active && nc_diverged < 0 {
                fail("reason=attention_negative_control_did_not_red");
            }
            if restored_diverged >= 0 {
                fail("reason=attention_parity_not_restored_after_disarm");
            }
        }
        // Below the threshold the step stays on one core.
        let short = crate::ai::ops::GqaAttentionParams {
            seq_len: 8,
            n_q_heads: NQ as u64,
            n_kv_heads: NKV as u64,
            head_dim: HD as u64,
        };
        if par_matmul::should_parallelize_attention(short) {
            fail("reason=attention_forks_below_threshold");
        }
    }

    // ── NEGATIVE CONTROL (falsifiability): arm the partition-boundary perturbation
    // and prove the SAME byte-parity compare that passes above now REDS. This is
    // the B2b / fast-gen discipline — a parity KAT that cannot fail is not a proof.
    // The perturbation is a single sub-ULP mantissa-bit flip on the col_start>0
    // partitions (see par_matmul::run_disjoint): invisible to the token argmax, so
    // ONLY the byte-exact compare catches it — exactly the "usually matches"
    // reduction the determinism rule forbids. We then DISARM and re-run to prove
    // parity is restored (the perturbation, not a latent bug, was the sole cause).
    {
        const NC_COLS: usize = 1024;
        let shared = BPD * Q8_K_VALUES;
        let mut rhs = alloc::vec::Vec::new();
        for c in 0..NC_COLS {
            for b in 0..BPD {
                rhs.extend_from_slice(&tmp_q4_k_block(((c * 11 + b * 5 + 2) & 0xff) as u8));
            }
        }
        let lhs: alloc::vec::Vec<f32> = (0..shared)
            .map(|i| ((i % 19) as f32 - 9.0) * 0.4 + 0.2)
            .collect();
        let mut lhs_q8 = alloc::vec![BlockQ8K::ZERO; BPD];
        if quantize_row_q8_k(&lhs, &mut lhs_q8).is_err() {
            fail("reason=nc_quantize_failed");
        }
        let mut truth = alloc::vec![0.0f32; NC_COLS];
        if forward_logic::column_matmul_q8k_part(
            MatmulPartitionKind::Q4K,
            &lhs_q8,
            &rhs,
            NC_COLS,
            shared,
            0,
            NC_COLS,
            &mut truth,
        )
        .is_err()
        {
            fail("reason=nc_truth_failed");
        }

        let run_tc4 = |lhs_q8: &[BlockQ8K], rhs: &[u8]| -> alloc::vec::Vec<f32> {
            par_matmul::reset_counters();
            par_matmul::set_thread_count(4);
            let mut out = alloc::vec![0.0f32; NC_COLS];
            if par_matmul::run_matmul_q8k(
                MatmulPartitionKind::Q4K,
                lhs_q8,
                rhs,
                NC_COLS,
                shared,
                &mut out,
            )
            .is_err()
            {
                fail("reason=nc_run_failed");
            }
            out
        };
        let first_divergence = |out: &[f32]| -> i64 {
            for i in 0..NC_COLS {
                if out[i].to_bits() != truth[i].to_bits() {
                    return i as i64;
                }
            }
            -1
        };

        // Whether the fork actually engages here (needs > 1 online CPU AND
        // thread_count > 1 AND width past PAR_MIN_COLS). The CI QEMU gate runs
        // NEO_SMP=4 so it does; a NEO_SMP=1 run falls to single-threaded, where the
        // col_start>0 perturbation legitimately never fires — the negative control
        // is then not exercised (reported, not failed), exactly like the positive
        // path stays byte-identical at any -smp.
        par_matmul::set_thread_count(4);
        let fork_active = par_matmul::should_parallelize(NC_COLS);

        // Armed: with the fork active the perturbed threaded run MUST diverge from
        // the single-threaded truth (the negative control reds).
        par_matmul::set_perturb(true);
        let perturbed = run_tc4(&lhs_q8, &rhs);
        let nc_diverged = first_divergence(&perturbed);
        par_matmul::set_perturb(false);
        // Disarmed: parity restored, byte-identical again (always, at any -smp).
        let restored = run_tc4(&lhs_q8, &rhs);
        let restored_diverged = first_divergence(&restored);
        serial_println!(
            "NEO_TEST/1 event=measure name={} phase=negative_control fork_active={} perturbed_diverged_col={} restored_diverged_col={}",
            SCENARIO,
            fork_active,
            nc_diverged,
            restored_diverged
        );
        if fork_active && nc_diverged < 0 {
            fail("reason=negative_control_did_not_red");
        }
        if restored_diverged >= 0 {
            fail("reason=parity_not_restored_after_disarm");
        }
    }

    // ── ISC-3: OT-7 latency measurement (relative ratio, TCG-virtualized) ──
    // rdtsc median-of-N (the OT-7 idiom) of a single-thread whole matmul (T1) vs
    // one 1/N-column partition's compute (Tp). T1/Tp ≈ N is the MODELED per-core
    // speedup basis (each core does ~1/N the work). TCG serializes vCPUs so it
    // cannot show wall-clock overlap; the absolute silicon speedup is a bare-metal
    // OT-7 read (benchmark-or-it-didn't-happen — no unmodeled claim here).
    {
        const M_COLS: usize = 4096; // FFN-scale width — a matmul worth threading
        const M_BPD: usize = 2;
        let shared = M_BPD * Q8_K_VALUES;
        let bpd = shared / Q8_K_VALUES;
        let bb = crate::ai::ops::q4_k::Q4_K_BLOCK_BYTES;
        let mut rhs = alloc::vec::Vec::new();
        for c in 0..M_COLS {
            for b in 0..M_BPD {
                rhs.extend_from_slice(&tmp_q4_k_block(((c * 7 + b * 3 + 1) & 0xff) as u8));
            }
        }
        let lhs: alloc::vec::Vec<f32> = (0..shared)
            .map(|i| ((i % 17) as f32 - 8.0) * 0.5 + 0.3)
            .collect();
        let mut lhs_q8 = alloc::vec![BlockQ8K::ZERO; M_BPD];
        if quantize_row_q8_k(&lhs, &mut lhs_q8).is_err() {
            fail("reason=latency_quantize_failed");
        }
        // Median-of-8 (4 warmup) cycles to compute `cols` columns single-threaded.
        let bench = |cols: usize, rhs_sub: &[u8]| -> u64 {
            let mut out = alloc::vec![0.0f32; cols];
            for _ in 0..4 {
                let _ = forward_logic::column_matmul_q8k_part(
                    MatmulPartitionKind::Q4K,
                    &lhs_q8,
                    rhs_sub,
                    cols,
                    shared,
                    0,
                    cols,
                    &mut out,
                );
            }
            let mut s = [0u64; 8];
            for slot in s.iter_mut() {
                let t0 = tmm_rdtsc();
                let _ = forward_logic::column_matmul_q8k_part(
                    MatmulPartitionKind::Q4K,
                    &lhs_q8,
                    rhs_sub,
                    cols,
                    shared,
                    0,
                    cols,
                    &mut out,
                );
                *slot = tmm_rdtsc().wrapping_sub(t0);
            }
            s.sort_unstable();
            s[4]
        };
        let t1 = bench(M_COLS, &rhs);
        let quarter = M_COLS / 4;
        let half = M_COLS / 2;
        let tp4 = bench(quarter, &rhs[0..quarter * bpd * bb]);
        let tp2 = bench(half, &rhs[0..half * bpd * bb]);
        let ratio4 = if tp4 == 0 {
            0
        } else {
            t1.saturating_mul(1000) / tp4
        };
        let ratio2 = if tp2 == 0 {
            0
        } else {
            t1.saturating_mul(1000) / tp2
        };
        serial_println!(
            "NEO_TEST/1 event=measure name={} op=matmul_latency cols={} t1_cycles={} quarter_partition_cycles={} half_partition_cycles={} modeled_speedup_4way_permille={} modeled_speedup_2way_permille={} note=tcg_virtualized_no_wall_overlap_absolute_is_baremetal_ot7",
            SCENARIO,
            M_COLS,
            t1,
            tp4,
            tp2,
            ratio4,
            ratio2
        );
    }

    par_matmul::set_perturb(false); // belt-and-suspenders: never leave the knob armed

    // ── Image A's steal grace in time (Chad, relay #52 items 3/6) ──
    // AP slot 1 is held (its `ap_poll` skips it), so the BSP must steal it.
    // With the calibrated TSC the steal may come only once the grace has run
    // from the publish stamp: a grace truncated to 0 cycles (item 3) steals on
    // the first look and fails here. The output stays byte-identical.
    #[cfg(feature = "neo-test-threaded-matmul-parity-grace-time")]
    let grace_detail = {
        // A fixed 1 GHz rate and a 500 ms grace (500M cycles), through the
        // production threshold: hermetic (no dependence on this runner's LAPIC
        // calibration) and far longer than the BSP's own partition under TCG
        // (~50M cycles), so a threshold truncated to 0 steals early and fails.
        // The expected threshold is written out here, not taken from the
        // production helper: a helper regressed to 0 must not make the
        // timing check vacuous (Chad, relay #53 R6).
        const EXPECTED_GRACE_CYCLES: u64 = 500_000_000; // 1 GHz x 500 ms
        let lapic_hz = crate::arch::x86_64::lapic_timer::tsc_hz();
        par_matmul::set_grace_for_test(1_000_000_000, 500_000);
        let Some(grace) = par_matmul::steal_grace_cycles() else {
            fail("reason=grace_override_not_applied");
        };
        if cpus < 2 {
            fail("reason=grace_time_needs_two_cpus");
        }
        let shared = BPD * Q8_K_VALUES;
        let mut rhs = alloc::vec::Vec::new();
        for c in 0..COLS {
            for b in 0..BPD {
                rhs.extend_from_slice(&tmp_q4_k_block(((c * 5 + b * 11 + 2) & 0xff) as u8));
            }
        }
        let lhs: alloc::vec::Vec<f32> = (0..shared)
            .map(|i| ((i % 13) as f32 - 6.0) * 0.25 + 0.1)
            .collect();
        let mut lhs_q8 = alloc::vec![BlockQ8K::ZERO; BPD];
        if quantize_row_q8_k(&lhs, &mut lhs_q8).is_err() {
            fail("reason=grace_quantize_failed");
        }
        let mut truth = alloc::vec![0.0f32; COLS];
        if forward_logic::column_matmul_q8k_part(
            MatmulPartitionKind::Q4K,
            &lhs_q8,
            &rhs,
            COLS,
            shared,
            0,
            COLS,
            &mut truth,
        )
        .is_err()
        {
            fail("reason=grace_truth_failed");
        }
        par_matmul::hold_slot_for_test(1);
        par_matmul::reset_counters();
        par_matmul::reset_steal_decisions_for_test();
        par_matmul::set_thread_count(cpus.min(4));
        let mut out = alloc::vec![0.0f32; COLS];
        let run = par_matmul::run_matmul_q8k(
            MatmulPartitionKind::Q4K,
            &lhs_q8,
            &rhs,
            COLS,
            shared,
            &mut out,
        );
        par_matmul::hold_slot_for_test(0);
        par_matmul::set_grace_for_test(0, 0);
        if run.is_err() {
            fail("reason=grace_run_failed");
        }
        let steals = par_matmul::bsp_steals();
        let aps = par_matmul::ap_partitions_done();
        // Every successful steal's elapsed cycles at its eligibility
        // decision (before the claim and the compute): the smallest of them.
        let waited = par_matmul::min_steal_decision_cycles();
        let identical = out
            .iter()
            .zip(&truth)
            .all(|(a, b)| a.to_bits() == b.to_bits());
        serial_println!(
            "NEO_TEST/1 event=measure name={} phase=steal_grace path=calibrated grace_cycles={} expected_grace_cycles={} grace_rate=override_1ghz_500ms lapic_tsc_hz={} held_slot=1 bsp_steals={} ap_partitions={} min_steal_decision_cycles={} identical={}",
            SCENARIO,
            grace,
            EXPECTED_GRACE_CYCLES,
            lapic_hz,
            steals,
            aps,
            waited,
            identical
        );
        if !identical {
            fail("reason=grace_steal_output_differs");
        }
        if steals == 0 {
            fail("reason=held_slot_not_stolen");
        }
        // `waited` is u64::MAX only with no steal, which fails above.
        if waited < EXPECTED_GRACE_CYCLES {
            fail(&alloc::format!(
                "reason=stole_before_grace min_steal_decision_cycles={} expected_grace_cycles={} grace_cycles={}",
                waited,
                EXPECTED_GRACE_CYCLES,
                grace
            ));
        }
        // The production threshold agrees with the independent one.
        if grace != EXPECTED_GRACE_CYCLES {
            fail(&alloc::format!(
                "reason=grace_threshold_mismatch grace_cycles={} expected_grace_cycles={}",
                grace,
                EXPECTED_GRACE_CYCLES
            ));
        }
        alloc::format!(
            " steal_grace=calibrated_override grace_cycles={} min_steal_decision_cycles={}",
            grace,
            waited
        )
    };
    #[cfg(not(feature = "neo-test-threaded-matmul-parity-grace-time"))]
    let grace_detail = alloc::string::String::new();

    par_matmul::set_thread_count(1); // restore the conservative single-threaded default
    pass(&alloc::format!(
        "q4_K=byte_identical q8_0=byte_identical token=identical thread_counts=1,2,4 gate=determinism negative_control=red_then_restored participation=reported latency=measured_relative{}",
        grace_detail
    ));
}

// ── Input queue flood — pointer motion must never evict a keystroke ───────────
// Real qemu-xhci + usb-kbd + usb-mouse, driven by HMP: xtask types TYPED with
// `sendkey` and floods `mouse_move` between every keystroke. The harness plays
// a focused client that is busy (does not drain) while input keeps being
// pumped through the production HID decode -> `route_event` path -- the shape
// of a multi-window desktop, where every client's RECV pumps the shared HID
// drains whether or not it holds focus. Afterwards it drains the queue and
// demands every keystroke, in order. Under ADR-074's original drop-oldest rule
// the flood evicts the keys (the control); under `input_queue_logic` it cannot.
#[cfg(feature = "neo-test-input-queue-flood")]
fn run_input_queue_flood() -> ! {
    use crate::atrium::focus::InputFocus;
    use crate::atrium::input_logic::{INPUT_EVENT_KEY, INPUT_EVENT_POINTER, KEY_PRESSED};
    use crate::drivers::usb::{hid_keyboard, hid_mouse};
    use alloc::sync::Arc;
    use alloc::vec::Vec;

    /// Letters and digits only, so every byte is one plain HID usage.
    const TYPED: &[u8] = b"thequickbrownfox0123456789";
    const TICK_HZ: u64 = 100;
    let ticks = || crate::arch::x86_64::timer::TICKS.load(Ordering::Acquire);
    let usage = |b: u8| -> u8 {
        match b {
            b'a'..=b'z' => 0x04 + (b - b'a'),
            b'1'..=b'9' => 0x1e + (b - b'1'),
            _ => 0x27, // '0'
        }
    };
    // Production reaches DELIVERY only from syscall bodies (interrupts off);
    // mirror that here so the scenario never takes it with IF=1 (CP-37).
    let pump = || {
        crate::arch::x86_64::without_interrupts(|| {
            hid_keyboard::pump_routed_events();
            hid_mouse::pump_routed_events();
        })
    };

    if !hid_mouse::is_bound() {
        fail("reason=input_flood_mouse_not_bound");
    }
    let focus = Arc::new(InputFocus::new());
    focus.activate();
    let (kb0, _, _) = hid_keyboard::debug_counters();
    let (mouse0, _, _, _) = hid_mouse::debug_counters();
    serial_println!(
        "INPUTFLOOD ready typed={} policy={}",
        TYPED.len(),
        if cfg!(feature = "atrium-input-queue-legacy") {
            "legacy-drop-oldest"
        } else {
            "class-aware"
        }
    );

    // Each `sendkey` is a press report and a release report.
    let want_reports = 2 * TYPED.len() as u64;
    // Well inside xtask's per-run timeout, so a lost keyboard report surfaces
    // as `input_flood_typing_timeout`, not a generic harness timeout.
    let deadline = ticks() + 90 * TICK_HZ;
    loop {
        pump();
        let (kb, _, _) = hid_keyboard::debug_counters();
        if kb - kb0 >= want_reports {
            break;
        }
        if ticks() > deadline {
            fail_with_hex("reason=input_flood_typing_timeout kb_reports", kb - kb0);
        }
        core::hint::spin_loop();
    }
    // Trailing motion after the last key still has to be routed.
    let settle = ticks() + TICK_HZ;
    while ticks() < settle {
        pump();
        core::hint::spin_loop();
    }

    let (queued, dropped) = crate::arch::x86_64::without_interrupts(|| focus.debug_queue_stats());
    let (mouse1, _, _, _) = hid_mouse::debug_counters();
    let mut keys = Vec::new();
    let mut pointer_events = 0usize;
    while let Some(event) = crate::arch::x86_64::without_interrupts(|| focus.try_recv()) {
        if event.kind == INPUT_EVENT_KEY && event.flags & KEY_PRESSED != 0 {
            keys.push(event.code as u8);
        } else if event.kind == INPUT_EVENT_POINTER {
            pointer_events += 1;
        }
    }
    let want: Vec<u8> = TYPED.iter().map(|&b| usage(b)).collect();
    let mouse_reports = mouse1 - mouse0;
    serial_println!(
        "INPUTFLOOD drained queued={} dropped={} mouse_reports={} pointer_events_kept={} key_presses_kept={} key_presses_typed={}",
        queued,
        dropped,
        mouse_reports,
        pointer_events,
        keys.len(),
        want.len()
    );
    // Non-vacuity: the flood really happened and really overflowed the queue.
    // QEMU coalesces each HMP burst into a few reports (~120 per run observed),
    // so the report floor is loose; `dropped > 0` is the pressure proof.
    if mouse_reports < 60 || dropped == 0 {
        fail("reason=input_flood_vacuous_no_overflow");
    }
    if keys != want {
        fail("reason=keystrokes_evicted_by_pointer_flood");
    }
    pass(
        "keystrokes_kept=all_in_order pointer_flood=overflowed_queue eviction=motion_first source=real_usb_hid_hmp",
    )
}

// S1-F1 discriminator (Codex cross-check, Chad): a HID report drained while
// another CPU holds DELIVERY used to be consumed, reposted and lost. A kthread
// holds DELIVERY almost continuously on another CPU while xtask types through
// a real usb-kbd; every press AND release must still arrive, in order.
#[cfg(feature = "neo-test-hid-contention")]
static HID_HOLDER_CPU: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(u32::MAX);
#[cfg(feature = "neo-test-hid-contention")]
static HID_HOLDS: AtomicU64 = AtomicU64::new(0);
#[cfg(feature = "neo-test-hid-contention")]
static HID_HOLDER_STOP: core::sync::atomic::AtomicBool = core::sync::atomic::AtomicBool::new(false);
#[cfg(feature = "neo-test-hid-contention")]
static HID_HOLDER_DONE: core::sync::atomic::AtomicBool = core::sync::atomic::AtomicBool::new(false);

#[cfg(feature = "neo-test-hid-contention")]
extern "C" fn hid_contention_holder() -> ! {
    HID_HOLDER_CPU.store(
        crate::arch::x86_64::per_cpu::current_cpu_id(),
        Ordering::Release,
    );
    while !HID_HOLDER_STOP.load(Ordering::Acquire) {
        crate::arch::x86_64::without_interrupts(|| {
            crate::atrium::focus::debug_with_delivery_held(|| {
                for _ in 0..20_000 {
                    core::hint::spin_loop();
                }
            })
        });
        HID_HOLDS.fetch_add(1, Ordering::Relaxed);
    }
    HID_HOLDER_DONE.store(true, Ordering::Release);
    crate::sched::exit();
}

/// Jarvis F1 phase: holds `DELIVERY` continuously (IF=0) until released, so
/// a key decoded meanwhile is certainly still staged at the handoff.
#[cfg(feature = "neo-test-hid-contention")]
static HANDOFF_RELEASE: core::sync::atomic::AtomicBool = core::sync::atomic::AtomicBool::new(false);
#[cfg(feature = "neo-test-hid-contention")]
static HANDOFF_HOLDING: core::sync::atomic::AtomicBool = core::sync::atomic::AtomicBool::new(false);
#[cfg(feature = "neo-test-hid-contention")]
static HANDOFF_DONE: core::sync::atomic::AtomicBool = core::sync::atomic::AtomicBool::new(false);

#[cfg(feature = "neo-test-hid-contention")]
extern "C" fn hid_handoff_holder() -> ! {
    crate::arch::x86_64::without_interrupts(|| {
        crate::atrium::focus::debug_with_delivery_held(|| {
            HANDOFF_HOLDING.store(true, Ordering::Release);
            while !HANDOFF_RELEASE.load(Ordering::Acquire) {
                core::hint::spin_loop();
            }
        })
    });
    HANDOFF_DONE.store(true, Ordering::Release);
    crate::sched::exit();
}

/// CP-56 teardown phase (#55): a thread on another CPU keeps taking
/// `DELIVERY` (and pumping the real HID devices) while a focus-holding
/// process is killed, so the dying focus's `Drop` meets a live session.
#[cfg(feature = "neo-test-hid-contention")]
static TEARDOWN_STOP: core::sync::atomic::AtomicBool = core::sync::atomic::AtomicBool::new(false);
#[cfg(feature = "neo-test-hid-contention")]
static TEARDOWN_HOLDS: AtomicU64 = AtomicU64::new(0);
#[cfg(feature = "neo-test-hid-contention")]
static TEARDOWN_DONE: core::sync::atomic::AtomicBool = core::sync::atomic::AtomicBool::new(false);

#[cfg(feature = "neo-test-hid-contention")]
extern "C" fn hid_teardown_contender() -> ! {
    while !TEARDOWN_STOP.load(Ordering::Acquire) {
        crate::arch::x86_64::without_interrupts(|| {
            crate::drivers::usb::hid_keyboard::pump_routed_events();
            crate::drivers::usb::hid_mouse::pump_routed_events();
            crate::atrium::focus::debug_with_delivery_held(|| {
                for _ in 0..2_000 {
                    core::hint::spin_loop();
                }
            });
        });
        TEARDOWN_HOLDS.fetch_add(1, Ordering::Relaxed);
    }
    TEARDOWN_DONE.store(true, Ordering::Release);
    crate::sched::exit();
}

/// The focus holder's only thread: alive until it is killed.
#[cfg(feature = "neo-test-hid-contention")]
extern "C" fn hid_focus_holder_spin() -> ! {
    loop {
        crate::sched::yield_now();
    }
}

/// CP-56 (#55): kill a process whose handle is the last reference to the
/// ACTIVE input focus, mid-session (contender on another CPU, events
/// queued), from a caller with interrupts ON — the shape of every teardown
/// that drops its drained handles after `without_interrupts` returns. The
/// focus's `Drop` must take `DELIVERY` IF=0 regardless: witness delta 0.
#[cfg(feature = "neo-test-hid-contention")]
fn hid_teardown_kill_focus_holder() {
    use crate::atrium::focus::{InputFocus, route_event};
    use crate::atrium::input_logic::InputEventV1;
    use crate::sched::process::{self, Handle, Process};
    use alloc::sync::Arc;

    let ticks = || crate::arch::x86_64::timer::TICKS.load(Ordering::Acquire);
    let pmap = crate::mm::pmap::Pmap::new()
        .unwrap_or_else(|_| fail("reason=hid_teardown_pmap_new_failed"));
    let proc = process::register(Process::new_user("hid-focus-holder", pmap));
    let pid = proc.pid;
    let held = Arc::new(InputFocus::new());
    if !held.activate() {
        fail("reason=hid_teardown_activate_failed");
    }
    let weak = Arc::downgrade(&held);
    process::install_cap(
        &proc,
        Handle::InputFocus {
            focus: held,
            cap_id: process::alloc_cap_id(),
            rights: process::client_input_focus_rights(),
        },
        None,
    )
    .unwrap_or_else(|_| fail("reason=hid_teardown_install_cap_failed"));
    drop(proc);
    // Mid-session: the focus holds queued input when it dies.
    for code in 0..8u8 {
        if !route_event(InputEventV1::key(0x04 + code, 0, true)) {
            fail("reason=hid_teardown_event_not_routed");
        }
    }

    let me = crate::arch::x86_64::per_cpu::current_cpu_id();
    let other = if me == 0 { 1 } else { 0 };
    let contender =
        crate::sched::thread::Thread::new("hid-teardown-contender", hid_teardown_contender);
    if crate::sched::scheduler::place_thread_on_cpu(contender, other).is_err() {
        fail("reason=hid_teardown_place_contender_failed");
    }
    let wait = ticks() + 5 * 100;
    while TEARDOWN_HOLDS.load(Ordering::Acquire) < 16 {
        if ticks() > wait {
            fail("reason=hid_teardown_contender_not_running");
        }
        crate::sched::yield_now();
    }
    let victim = crate::sched::thread::Thread::new_kernel_for_process_test(
        "hid-focus-holder",
        pid,
        hid_focus_holder_spin,
    );
    crate::sched::scheduler::push_ready(victim);

    let witness0 = crate::atrium::focus::debug_delivery_if_on_acquisitions();
    x86_64::instructions::interrupts::enable();
    let kill_rc = process::terminate(pid);
    let witness = crate::atrium::focus::debug_delivery_if_on_acquisitions() - witness0;
    let dropped = weak.strong_count() == 0;
    // The dead focus no longer routes: nothing is active.
    let route_cleared = !route_event(InputEventV1::key(0x04, 0, true));
    TEARDOWN_STOP.store(true, Ordering::Release);
    let wait = ticks() + 5 * 100;
    while !TEARDOWN_DONE.load(Ordering::Acquire) {
        if ticks() > wait {
            fail("reason=hid_teardown_contender_did_not_stop");
        }
        crate::sched::yield_now();
    }
    for _ in 0..100_000 {
        crate::sched::reap();
        if crate::sched::scheduler::debug_total_zombies() == 0 {
            break;
        }
        crate::sched::yield_now();
    }
    serial_println!(
        "HIDCONTEND teardown kill_rc={} focus_dropped={} route_cleared={} delivery_if_on={}",
        kill_rc,
        dropped,
        route_cleared,
        witness
    );
    if kill_rc != 0 {
        fail_with_hex("reason=hid_teardown_terminate_failed rc", kill_rc as u64);
    }
    if !dropped {
        fail("reason=hid_teardown_vacuous_focus_not_dropped_by_kill");
    }
    if !route_cleared {
        fail("reason=hid_teardown_dead_focus_still_routes");
    }
    if witness != 0 {
        fail("reason=delivery_taken_with_interrupts_enabled_in_teardown");
    }
}

// OT-22 rung 1: SYS_WAIT_ANY's kernel legs. A waiter is a kernel thread of
// a registered process (so the wait resolves that process's handles), and a
// sender is a second thread doing a real `Channel::send` of zero bytes (no
// copy, so no user buffers are needed): the production fire path.
#[cfg(feature = "neo-test-wait-any-core")]
static WA_CHANNEL: crate::sync::SwitchMutex<
    Option<(
        alloc::sync::Arc<crate::ipc::Channel>,
        alloc::sync::Arc<crate::mm::pmap::Pmap>,
    )>,
> = crate::sync::SwitchMutex::new(None);
#[cfg(feature = "neo-test-wait-any-core")]
static WA_HANDLE: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(u32::MAX);
#[cfg(feature = "neo-test-wait-any-core")]
static WA_ITEMS: core::sync::atomic::AtomicUsize = core::sync::atomic::AtomicUsize::new(1);
#[cfg(feature = "neo-test-wait-any-core")]
static WA_DEADLINE_NS: AtomicU64 = AtomicU64::new(u64::MAX);
#[cfg(feature = "neo-test-wait-any-core")]
static WA_RESULT: core::sync::atomic::AtomicI64 = core::sync::atomic::AtomicI64::new(0);
#[cfg(feature = "neo-test-wait-any-core")]
static WA_RETURN_TICK: AtomicU64 = AtomicU64::new(0);
#[cfg(feature = "neo-test-wait-any-core")]
static WA_WAITER_DONE: core::sync::atomic::AtomicBool = core::sync::atomic::AtomicBool::new(false);
#[cfg(feature = "neo-test-wait-any-core")]
static WA_SEND_TICK: AtomicU64 = AtomicU64::new(0);
#[cfg(feature = "neo-test-wait-any-core")]
static WA_SENDER_DONE: core::sync::atomic::AtomicBool = core::sync::atomic::AtomicBool::new(false);
/// Race leg: the waiter's pid; the sender sends once that pid is registered.
#[cfg(feature = "neo-test-wait-any-core")]
static WA_RACE_PID: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(u32::MAX);

#[cfg(feature = "neo-test-wait-any-core")]
extern "C" fn wa_waiter() -> ! {
    use crate::arch::x86_64::syscall::{WAIT_KIND_CHANNEL, WaitItem, wait_any_items};
    let item = [WaitItem {
        handle: WA_HANDLE.load(Ordering::Acquire),
        kind: WAIT_KIND_CHANNEL,
    }];
    let n = WA_ITEMS.load(Ordering::Acquire);
    let r = wait_any_items(&item[..n], WA_DEADLINE_NS.load(Ordering::Acquire));
    WA_RETURN_TICK.store(
        crate::arch::x86_64::timer::TICKS.load(Ordering::Acquire),
        Ordering::Release,
    );
    WA_RESULT.store(r, Ordering::Release);
    WA_WAITER_DONE.store(true, Ordering::Release);
    loop {
        crate::sched::yield_now();
    }
}

#[cfg(feature = "neo-test-wait-any-core")]
extern "C" fn wa_sender() -> ! {
    use crate::ipc::EndpointSide;
    let race_pid = WA_RACE_PID.load(Ordering::Acquire);
    if race_pid != u32::MAX {
        // Race leg: fire only once the waiter is in the table, i.e. inside
        // the window the race hook holds open before the park.
        // Back off between polls: a tight loop on the table lock from this
        // CPU starves the waiter's `register` on the BSP (an unfair spin,
        // IF=0, so the BSP takes no ticks while it waits).
        while crate::sched::wait_any::debug_entries(Some(crate::sched::process::ProcessId(
            race_pid,
        ))) == 0
        {
            for _ in 0..2_000 {
                core::hint::spin_loop();
            }
        }
    }
    let (channel, pmap) = WA_CHANNEL
        .lock()
        .as_ref()
        .map(|(c, p)| (c.clone(), p.clone()))
        .expect("channel armed");
    WA_SEND_TICK.store(
        crate::arch::x86_64::timer::TICKS.load(Ordering::Acquire),
        Ordering::Release,
    );
    let _ = crate::arch::x86_64::without_interrupts(|| channel.send(EndpointSide::B, 0, 0, pmap));
    WA_SENDER_DONE.store(true, Ordering::Release);
    crate::sched::exit();
}

/// One registered process holding side A of a fresh channel; returns its pid
/// and arms `WA_CHANNEL` / `WA_HANDLE`.
#[cfg(feature = "neo-test-wait-any-core")]
fn wa_arm(name: &'static str) -> crate::sched::process::ProcessId {
    use crate::ipc::EndpointSide;
    use crate::sched::process::{self, Handle, Process};
    let pmap = crate::mm::pmap::Pmap::new().unwrap_or_else(|_| fail("reason=wa_pmap_new_failed"));
    let proc = process::register(Process::new_user(name, pmap));
    let pid = proc.pid;
    let pmap = proc
        .pmap
        .as_ref()
        .cloned()
        .expect("user process has a pmap");
    let channel = crate::ipc::Channel::new();
    let handle = process::install_cap(
        &proc,
        Handle::Channel {
            channel: channel.clone(),
            side: EndpointSide::A,
            cap_id: process::alloc_cap_id(),
            rights: process::full_channel_rights(),
        },
        None,
    )
    .unwrap_or_else(|_| fail("reason=wa_install_cap_failed"));
    WA_HANDLE.store(handle, Ordering::Release);
    *WA_CHANNEL.lock() = Some((channel, pmap));
    pid
}

#[cfg(feature = "neo-test-wait-any-core")]
fn wa_spawn_waiter(pid: crate::sched::process::ProcessId, items: usize, deadline_ns: u64) {
    WA_WAITER_DONE.store(false, Ordering::Release);
    WA_ITEMS.store(items, Ordering::Release);
    WA_DEADLINE_NS.store(deadline_ns, Ordering::Release);
    let waiter =
        crate::sched::thread::Thread::new_kernel_for_process_test("wa-waiter", pid, wa_waiter);
    crate::sched::scheduler::push_ready(waiter);
}

#[cfg(feature = "neo-test-wait-any-core")]
fn wa_until(what: &str, mut done: impl FnMut() -> bool) {
    let deadline = crate::arch::x86_64::timer::TICKS.load(Ordering::Acquire) + 1000;
    while !done() {
        if crate::arch::x86_64::timer::TICKS.load(Ordering::Acquire) > deadline {
            serial_println!("WAITANY timeout waiting for {}", what);
            fail("reason=wait_any_core_leg_timeout");
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
}

/// Retire a waiter thread (it spins after recording its result) by killing
/// its process, then reap.
#[cfg(feature = "neo-test-wait-any-core")]
fn wa_retire(pid: crate::sched::process::ProcessId) {
    let _ = crate::sched::process::terminate(pid);
    for _ in 0..100_000 {
        crate::sched::reap();
        if crate::sched::scheduler::debug_total_zombies() == 0 {
            break;
        }
        crate::sched::yield_now();
    }
    *WA_CHANNEL.lock() = None;
}

/// Complete the rendezvous the sender is parked in (side A recv, 0 bytes).
#[cfg(feature = "neo-test-wait-any-core")]
fn wa_release_sender() {
    use crate::ipc::EndpointSide;
    let (channel, pmap) = WA_CHANNEL
        .lock()
        .as_ref()
        .map(|(c, p)| (c.clone(), p.clone()))
        .expect("channel armed");
    let _ = crate::arch::x86_64::without_interrupts(|| channel.recv(EndpointSide::A, 0, 0, pmap));
    wa_until("sender done", || WA_SENDER_DONE.load(Ordering::Acquire));
}

/// Rebind leg: set when the sibling's reinstall did not land in the closed
/// slot (the leg would then not test a reuse).
#[cfg(feature = "neo-test-wait-any-core")]
static WA_REBIND_SLOT_MOVED: core::sync::atomic::AtomicBool =
    core::sync::atomic::AtomicBool::new(false);

/// Rebind leg's sibling: a second thread of the waiter's process. Once the
/// waiter is between its first scan and its registration, close its handle
/// (the removal fires channel A's key; nobody is registered yet) and install
/// a fresh channel B, which lands in the same lowest-free slot.
#[cfg(feature = "neo-test-wait-any-core")]
extern "C" fn wa_rebind_sibling() -> ! {
    use crate::ipc::EndpointSide;
    use crate::sched::process::{self, Handle};
    use crate::sched::wait_any::{REBIND_DONE, REBIND_IN_WINDOW};
    while !REBIND_IN_WINDOW.load(Ordering::Acquire) {
        core::hint::spin_loop();
    }
    let proc = process::get(crate::sched::current_pid()).expect("rebind process");
    let h = WA_HANDLE.load(Ordering::Acquire);
    let _ = crate::arch::x86_64::without_interrupts(|| proc.handles.lock().remove(h));
    let channel = crate::ipc::Channel::new();
    let idx = process::install_cap(
        &proc,
        Handle::Channel {
            channel: channel.clone(),
            side: EndpointSide::A,
            cap_id: process::alloc_cap_id(),
            rights: process::full_channel_rights(),
        },
        None,
    )
    .unwrap_or(u32::MAX);
    WA_REBIND_SLOT_MOVED.store(idx != h, Ordering::Release);
    let pmap = proc
        .pmap
        .as_ref()
        .cloned()
        .expect("user process has a pmap");
    drop(proc);
    *WA_CHANNEL.lock() = Some((channel, pmap));
    REBIND_DONE.store(true, Ordering::Release);
    // Stay alive: this process's last thread exiting would tear it down
    // under the waiter. `wa_retire` kills both.
    loop {
        crate::sched::yield_now();
    }
}

/// Revoke leg: a process whose only handle is side A of `channel`, recorded
/// as derived from `parent` (an ancestor's cap). Arms `WA_HANDLE`.
#[cfg(feature = "neo-test-wait-any-core")]
fn wa_arm_derived(
    name: &'static str,
    channel: alloc::sync::Arc<crate::ipc::Channel>,
    parent: crate::sched::process::CapId,
) -> crate::sched::process::ProcessId {
    use crate::ipc::EndpointSide;
    use crate::sched::process::{self, Handle, Process};
    let pmap = crate::mm::pmap::Pmap::new().unwrap_or_else(|_| fail("reason=wa_pmap_new_failed"));
    let proc = process::register(Process::new_user(name, pmap));
    let handle = process::install_cap(
        &proc,
        Handle::Channel {
            channel,
            side: EndpointSide::A,
            cap_id: process::alloc_cap_id(),
            rights: process::full_channel_rights(),
        },
        Some(parent),
    )
    .unwrap_or_else(|_| fail("reason=wa_install_cap_failed"));
    WA_HANDLE.store(handle, Ordering::Release);
    proc.pid
}

#[cfg(feature = "neo-test-wait-any-core")]
fn run_wait_any_core() -> ! {
    use crate::sched::wait_any::{self, STATS};
    let ticks = || crate::arch::x86_64::timer::TICKS.load(Ordering::Acquire);
    let ns = |t: u64| t * 10_000_000;
    if crate::arch::x86_64::per_cpu::current_cpu_id() != 0 {
        fail("reason=test_not_on_bsp");
    }

    // --- Leg 1, the IPC wake is real: an IPC-only wait (no input, a far
    // deadline) must end on the sender's fire, within a tick of the send.
    // `wait-multiplex-no-ipc-fire` compiles the fire out: it must time out.
    let pid = wa_arm("wa-ipc");
    let ipc0 = STATS.ipc_wakes.load(Ordering::Relaxed);
    let parks0 = STATS.parks.load(Ordering::Relaxed);
    wa_spawn_waiter(pid, 1, ns(ticks() + 300));
    wa_until("waiter parked", || {
        STATS.parks.load(Ordering::Relaxed) > parks0 && wait_any::debug_entries(Some(pid)) == 1
    });
    WA_SENDER_DONE.store(false, Ordering::Release);
    WA_RACE_PID.store(u32::MAX, Ordering::Release);
    crate::sched::scheduler::push_ready(crate::sched::thread::Thread::new("wa-sender", wa_sender));
    wa_until("waiter returned", || WA_WAITER_DONE.load(Ordering::Acquire));
    let result = WA_RESULT.load(Ordering::Acquire);
    let latency = WA_RETURN_TICK
        .load(Ordering::Acquire)
        .saturating_sub(WA_SEND_TICK.load(Ordering::Acquire));
    let ipc_wakes = STATS.ipc_wakes.load(Ordering::Relaxed) - ipc0;
    serial_println!(
        "WAITANY ipc result={} latency_ticks={} ipc_wakes={}",
        result,
        latency,
        ipc_wakes
    );
    // Within a few ticks of the send (scheduling jitter), against the 300
    // ticks a missing fire costs (the control).
    if result != 1 || ipc_wakes != 1 || latency > 5 {
        fail("reason=wait_any_ipc_wake_missing");
    }
    wa_release_sender();
    wa_retire(pid);

    // --- Leg 2, CP-14: a send landing between the readiness check and the
    // park. The race hook holds that window open; the sender (on CPU 1)
    // fires inside it. Every wait must still end on the send, never the
    // deadline, and the window must actually have been hit.
    const RACE_ROUNDS: usize = 16;
    if !crate::sched::scheduler::cpu_scheduler_ready(1) {
        fail("reason=wait_any_race_needs_smp");
    }
    wait_any::RACE_SPIN.store(2_000_000, Ordering::Relaxed);
    let fired0 = STATS.fired_before_park.load(Ordering::Relaxed);
    let mut woken = 0;
    for _ in 0..RACE_ROUNDS {
        let pid = wa_arm("wa-race");
        WA_RACE_PID.store(pid.0, Ordering::Release);
        WA_SENDER_DONE.store(false, Ordering::Release);
        let sender = crate::sched::thread::Thread::new("wa-race-sender", wa_sender);
        if crate::sched::scheduler::place_thread_on_cpu(sender, 1).is_err() {
            fail("reason=wait_any_place_sender_failed");
        }
        wa_spawn_waiter(pid, 1, ns(ticks() + 300));
        wa_until("race waiter returned", || {
            WA_WAITER_DONE.load(Ordering::Acquire)
        });
        if WA_RESULT.load(Ordering::Acquire) == 1 {
            woken += 1;
        }
        wa_release_sender();
        wa_retire(pid);
    }
    wait_any::RACE_SPIN.store(0, Ordering::Relaxed);
    WA_RACE_PID.store(u32::MAX, Ordering::Release);
    let fired_before_park = STATS.fired_before_park.load(Ordering::Relaxed) - fired0;
    serial_println!(
        "WAITANY race rounds={} woken={} fired_before_park={}",
        RACE_ROUNDS,
        woken,
        fired_before_park
    );
    if woken != RACE_ROUNDS {
        fail("reason=wait_any_race_lost_wakeup");
    }
    if fired_before_park == 0 {
        fail("reason=wait_any_race_vacuous_window_never_hit");
    }

    // --- Leg 3, the deadline: an empty wait ends at its deadline, by the
    // tick, no earlier and at most one tick late.
    let pid = wa_arm("wa-deadline");
    let tick0 = STATS.tick_wakes.load(Ordering::Relaxed);
    let due = ticks() + 50;
    wa_spawn_waiter(pid, 0, ns(due));
    wa_until("deadline waiter returned", || {
        WA_WAITER_DONE.load(Ordering::Acquire)
    });
    let result = WA_RESULT.load(Ordering::Acquire);
    let at = WA_RETURN_TICK.load(Ordering::Acquire);
    let tick_wakes = STATS.tick_wakes.load(Ordering::Relaxed) - tick0;
    serial_println!(
        "WAITANY deadline result={} late_ticks={} tick_wakes={}",
        result,
        at.saturating_sub(due),
        tick_wakes
    );
    if result != crate::errno::ETIMEDOUT || at < due || at > due + 1 || tick_wakes == 0 {
        fail("reason=wait_any_deadline_wrong");
    }
    wa_retire(pid);

    // --- Leg 4, kill while parked (CP-30/33): its entry is purged, the
    // parked thread is zombified and reaped, nothing leaks a slot.
    let pid = wa_arm("wa-kill");
    let parks0 = STATS.parks.load(Ordering::Relaxed);
    wa_spawn_waiter(pid, 1, u64::MAX);
    wa_until("kill waiter parked", || {
        STATS.parks.load(Ordering::Relaxed) > parks0 && wait_any::debug_entries(Some(pid)) == 1
    });
    let rc = crate::sched::process::terminate(pid);
    for _ in 0..100_000 {
        crate::sched::reap();
        if crate::sched::scheduler::debug_total_zombies() == 0 {
            break;
        }
        crate::sched::yield_now();
    }
    let left = wait_any::debug_entries(None);
    let zombies = crate::sched::scheduler::debug_total_zombies();
    *WA_CHANNEL.lock() = None;
    serial_println!(
        "WAITANY kill rc={} entries_left={} zombies={}",
        rc,
        left,
        zombies
    );
    if rc != 0 || left != 0 || zombies != 0 {
        fail("reason=wait_any_kill_while_parked_leaked");
    }

    // --- Leg 5, rebind (Jarvis rung-1 F1): a sibling thread in the waiter's
    // own process closes the waiter's handle and reuses its slot for channel
    // B while the waiter is between its first scan and its registration (the
    // close's fire finds nobody). A send on B must wake the waiter: its
    // second scan sees the handle name another channel and it starts over.
    // `wait-multiplex-no-identity-check`: it parks on A, which nothing
    // fires, and only its deadline ends it.
    {
        use crate::sched::wait_any::{REBIND_DONE, REBIND_IN_WINDOW, REBIND_PID};
        let pid = wa_arm("wa-rebind");
        let retries0 = STATS.identity_retries.load(Ordering::Relaxed);
        let parks0 = STATS.parks.load(Ordering::Relaxed);
        let ipc0 = STATS.ipc_wakes.load(Ordering::Relaxed);
        REBIND_DONE.store(false, Ordering::Release);
        REBIND_IN_WINDOW.store(false, Ordering::Release);
        REBIND_PID.store(pid.0, Ordering::Release);
        let sibling = crate::sched::thread::Thread::new_kernel_for_process_test(
            "wa-rebind-sibling",
            pid,
            wa_rebind_sibling,
        );
        if crate::sched::scheduler::place_thread_on_cpu(sibling, 1).is_err() {
            fail("reason=wait_any_place_sibling_failed");
        }
        wa_spawn_waiter(pid, 1, ns(ticks() + 300));
        wa_until("rebound waiter parked", || {
            REBIND_DONE.load(Ordering::Acquire)
                && (STATS.parks.load(Ordering::Relaxed) > parks0
                    || WA_WAITER_DONE.load(Ordering::Acquire))
                && wait_any::debug_entries(Some(pid)) <= 1
        });
        if WA_REBIND_SLOT_MOVED.load(Ordering::Acquire) {
            fail("reason=wait_any_rebind_slot_not_reused");
        }
        WA_SENDER_DONE.store(false, Ordering::Release);
        WA_RACE_PID.store(u32::MAX, Ordering::Release);
        crate::sched::scheduler::push_ready(crate::sched::thread::Thread::new(
            "wa-sender",
            wa_sender,
        ));
        wa_until("rebound waiter returned", || {
            WA_WAITER_DONE.load(Ordering::Acquire)
        });
        let result = WA_RESULT.load(Ordering::Acquire);
        let latency = WA_RETURN_TICK
            .load(Ordering::Acquire)
            .saturating_sub(WA_SEND_TICK.load(Ordering::Acquire));
        let retries = STATS.identity_retries.load(Ordering::Relaxed) - retries0;
        let ipc_wakes = STATS.ipc_wakes.load(Ordering::Relaxed) - ipc0;
        serial_println!(
            "WAITANY rebind result={} latency_ticks={} identity_retries={} ipc_wakes={}",
            result,
            latency,
            retries,
            ipc_wakes
        );
        if result != 1 || latency > 5 || retries == 0 || ipc_wakes != 1 {
            fail("reason=wait_any_rebind_stranded");
        }
        wa_release_sender();
        wa_retire(pid);
    }

    // --- Leg 6, revoke (Jarvis rung-1 F1): the waiter's handle is derived
    // from an ancestor's cap, and the ancestor revokes it while the waiter is
    // parked on that channel alone with no deadline. No channel traffic
    // happens: the handle removal must wake the wait, which returns EBADF.
    // `wait-multiplex-no-handle-fire`: it sleeps on.
    {
        let ancestor = wa_arm("wa-revoke-root");
        let root_h = WA_HANDLE.load(Ordering::Acquire);
        let ancestor_proc = crate::sched::process::get(ancestor).expect("ancestor");
        let root_cap = crate::arch::x86_64::without_interrupts(|| {
            ancestor_proc.handles.lock().get(root_h).map(|h| h.cap_id())
        })
        .unwrap_or_else(|| fail("reason=wa_root_handle_missing"));
        drop(ancestor_proc);
        let channel = WA_CHANNEL
            .lock()
            .as_ref()
            .map(|(c, _)| c.clone())
            .expect("channel armed");
        let pid = wa_arm_derived("wa-revoke", channel, root_cap);
        let parks0 = STATS.parks.load(Ordering::Relaxed);
        let ipc0 = STATS.ipc_wakes.load(Ordering::Relaxed);
        let handle0 = STATS.handle_wakes.load(Ordering::Relaxed);
        wa_spawn_waiter(pid, 1, u64::MAX);
        wa_until("revoke waiter parked", || {
            STATS.parks.load(Ordering::Relaxed) > parks0 && wait_any::debug_entries(Some(pid)) == 1
        });
        let rc = crate::sched::process::revoke_handle(ancestor, root_h);
        let t0 = ticks();
        while !WA_WAITER_DONE.load(Ordering::Acquire) && ticks() < t0 + 100 {
            crate::sched::yield_now();
            crate::sched::reap();
        }
        let done = WA_WAITER_DONE.load(Ordering::Acquire);
        let result = WA_RESULT.load(Ordering::Acquire);
        let handle_wakes = STATS.handle_wakes.load(Ordering::Relaxed) - handle0;
        let ipc_wakes = STATS.ipc_wakes.load(Ordering::Relaxed) - ipc0;
        serial_println!(
            "WAITANY revoke rc={} returned={} result={} handle_wakes={} ipc_wakes={}",
            if rc.is_ok() { 0 } else { -1 },
            done,
            result,
            handle_wakes,
            ipc_wakes
        );
        if !done {
            fail("reason=wait_any_revoke_stranded");
        }
        if rc.is_err() || result != crate::errno::EBADF || handle_wakes == 0 || ipc_wakes != 0 {
            fail("reason=wait_any_revoke_wrong");
        }
        // The ancestor has no thread (it only holds the root cap), so it is
        // left registered: `terminate` needs a thread to stop.
        wa_retire(pid);
    }
    pass(
        "wait_any=ok ipc=woken_by_send race=no_lost_wakeup deadline=tick_exact kill=purged rebind=rewatched revoke=ebadf",
    )
}

#[cfg(feature = "neo-test-hid-contention")]
fn run_hid_contention() -> ! {
    use crate::arch::x86_64::per_cpu;
    use crate::atrium::focus::InputFocus;
    use crate::atrium::input_logic::{INPUT_EVENT_KEY, KEY_PRESSED};
    use crate::drivers::usb::hid_keyboard;
    use alloc::sync::Arc;
    use alloc::vec::Vec;

    /// Must equal xtask's `HID_CONTENTION_HID_STEPS` command.
    const TYPED: &[u8] = b"abcdefghij";
    const TICK_HZ: u64 = 100;
    let ticks = || crate::arch::x86_64::timer::TICKS.load(Ordering::Acquire);
    // Production reaches DELIVERY only with interrupts off (CP-37).
    let pump = || {
        crate::arch::x86_64::without_interrupts(|| {
            hid_keyboard::pump_routed_events();
            crate::drivers::usb::hid_mouse::pump_routed_events();
        })
    };

    if !hid_keyboard::is_bound() || !crate::drivers::usb::hid_mouse::is_bound() {
        fail("reason=hid_contention_devices_not_bound");
    }
    let focus = Arc::new(InputFocus::new());
    crate::arch::x86_64::without_interrupts(|| focus.activate());

    // The holder runs on ANOTHER CPU (placed there explicitly): DELIVERY
    // held for tens of microseconds at a time, released for a few
    // instructions, interrupts off only while held.
    let me = per_cpu::current_cpu_id();
    let target = if me == 0 { 1 } else { 0 };
    let holder = crate::sched::thread::Thread::new("hid-contention-holder", hid_contention_holder);
    if crate::sched::scheduler::place_thread_on_cpu(holder, target).is_err() {
        fail("reason=hid_contention_place_holder_failed");
    }
    let wait = ticks() + 5 * TICK_HZ;
    while HID_HOLDS.load(Ordering::Acquire) < 8 {
        if ticks() > wait {
            fail("reason=hid_contention_holder_never_ran");
        }
        core::hint::spin_loop();
    }
    let holder_cpu = HID_HOLDER_CPU.load(Ordering::Acquire);
    if holder_cpu == me {
        fail("reason=hid_contention_holder_colocated");
    }
    let (kb0, _, _) = hid_keyboard::debug_counters();
    let (mouse0, _, _, _) = crate::drivers::usb::hid_mouse::debug_counters();
    serial_println!(
        "HIDCONTEND ready typed={} path={} pump_cpu={} holder_cpu={}",
        TYPED.len(),
        if cfg!(feature = "atrium-input-stage-legacy") {
            "legacy-direct"
        } else {
            "staged"
        },
        me,
        holder_cpu
    );

    // Each `sendkey` is a press report and a release report; the
    // Super+Escape chord is four (Super down, Escape down, Escape up, Super
    // up); the button is a press and a release. All drain while the holder
    // runs.
    let want_reports = 2 * TYPED.len() as u64 + 4;
    let deadline = ticks() + 60 * TICK_HZ;
    loop {
        pump();
        let (kb, _, _) = hid_keyboard::debug_counters();
        let (mouse, _, _, _) = crate::drivers::usb::hid_mouse::debug_counters();
        if kb - kb0 >= want_reports && mouse - mouse0 >= 2 {
            break;
        }
        if ticks() > deadline {
            fail_with_hex("reason=hid_contention_typing_timeout kb_reports", kb - kb0);
        }
        core::hint::spin_loop();
    }
    let linger = ticks() + TICK_HZ / 5;
    while ticks() < linger {
        pump();
        core::hint::spin_loop();
    }
    HID_HOLDER_STOP.store(true, Ordering::Release);
    let wait = ticks() + 5 * TICK_HZ;
    while !HID_HOLDER_DONE.load(Ordering::Acquire) {
        if ticks() > wait {
            fail("reason=hid_contention_holder_did_not_stop");
        }
        core::hint::spin_loop();
    }
    // Contention over: what was staged must now flush.
    let settle = ticks() + TICK_HZ / 2;
    while ticks() < settle {
        pump();
        core::hint::spin_loop();
    }

    let (contended, stage_dropped) = crate::atrium::focus::debug_stage_stats();
    let mut got = Vec::new();
    let mut buttons_seen = Vec::new();
    while let Some(event) = crate::arch::x86_64::without_interrupts(|| focus.try_recv()) {
        if event.kind == INPUT_EVENT_KEY {
            got.push((event.code as u8, event.flags & KEY_PRESSED != 0));
        } else if event.kind == crate::atrium::input_logic::INPUT_EVENT_POINTER {
            buttons_seen.push(event.flags);
        }
    }
    let sak_pending = crate::atrium::focus::take_sak();
    let sak_latched = crate::atrium::focus::debug_sak_latched();
    let raw_buttons = crate::atrium::focus::raw_buttons();
    let want: Vec<(u8, bool)> = TYPED
        .iter()
        .flat_map(|&b| [(0x04 + (b - b'a'), true), (0x04 + (b - b'a'), false)])
        .collect();
    serial_println!(
        "HIDCONTEND drained key_events={} expected={} flush_contended={} stage_dropped={} holds={}",
        got.len(),
        want.len(),
        contended,
        stage_dropped,
        HID_HOLDS.load(Ordering::Relaxed)
    );
    serial_println!(
        "HIDCONTEND sak pending={} latched={} pointer_events={} last_buttons={} raw_buttons={}",
        sak_pending,
        sak_latched,
        buttons_seen.len(),
        buttons_seen.last().copied().unwrap_or(0xff),
        raw_buttons
    );
    // The letters only: Escape (the chord key) reaches no client, ever.
    if got != want {
        fail("reason=hid_reports_lost_under_delivery_contention");
    }
    // Jarvis F1: a chord pressed while DELIVERY is held is still exactly one
    // pending system action.
    if sak_pending != crate::atrium::sak_logic::sak_bit(crate::atrium::sak_logic::KEY_ESCAPE)
        || sak_latched != 1
    {
        fail("reason=sak_chord_not_latched_exactly_once");
    }
    // Jarvis F2: the press reached the client and the release left no stale
    // button state, in the delivered stream or in the raw latch.
    if !buttons_seen.iter().any(|&b| b & 1 != 0)
        || buttons_seen.last() != Some(&0)
        || raw_buttons != 0
    {
        fail("reason=button_release_not_reconciled");
    }
    // Non-vacuity: the pump really met the lock held at least once.
    if contended == 0 && !cfg!(feature = "atrium-input-stage-legacy") {
        fail("reason=hid_contention_vacuous_no_contention");
    }

    // --- Jarvis F1: a key decoded for A must never reach B after a handoff.
    // A holder on the other CPU keeps DELIVERY the whole time; xtask types
    // one more key ('z') on this prompt; it is decoded and staged for A.
    let holder = crate::sched::thread::Thread::new("hid-handoff-holder", hid_handoff_holder);
    if crate::sched::scheduler::place_thread_on_cpu(holder, target).is_err() {
        fail("reason=hid_handoff_place_holder_failed");
    }
    let wait = ticks() + 5 * TICK_HZ;
    while !HANDOFF_HOLDING.load(Ordering::Acquire) {
        if ticks() > wait {
            fail("reason=hid_handoff_holder_never_held");
        }
        core::hint::spin_loop();
    }
    let (kb1, _, _) = hid_keyboard::debug_counters();
    let (contended1, _) = crate::atrium::focus::debug_stage_stats();
    let handoff0 = crate::atrium::focus::debug_handoff_dropped();
    serial_println!("HIDCONTEND handoff armed focus=A");
    let deadline = ticks() + 60 * TICK_HZ;
    loop {
        pump();
        let (kb, _, _) = hid_keyboard::debug_counters();
        if kb - kb1 >= 2 {
            break;
        }
        if ticks() > deadline {
            fail_with_hex("reason=hid_handoff_typing_timeout kb_reports", kb - kb1);
        }
        core::hint::spin_loop();
    }
    let (contended2, _) = crate::atrium::focus::debug_stage_stats();
    if contended2 == contended1 {
        fail("reason=hid_handoff_vacuous_key_not_staged");
    }
    HANDOFF_RELEASE.store(true, Ordering::Release);
    let wait = ticks() + 5 * TICK_HZ;
    while !HANDOFF_DONE.load(Ordering::Acquire) {
        if ticks() > wait {
            fail("reason=hid_handoff_holder_did_not_release");
        }
        core::hint::spin_loop();
    }
    // The handoff: B takes the keyboard before anything flushes.
    let focus_b = Arc::new(InputFocus::new());
    crate::arch::x86_64::without_interrupts(|| focus_b.activate());
    let settle = ticks() + TICK_HZ / 2;
    while ticks() < settle {
        pump();
        core::hint::spin_loop();
    }
    let mut b_events = 0usize;
    while crate::arch::x86_64::without_interrupts(|| focus_b.try_recv()).is_some() {
        b_events += 1;
    }
    let mut a_events = 0usize;
    while crate::arch::x86_64::without_interrupts(|| focus.try_recv()).is_some() {
        a_events += 1;
    }
    let handoff_dropped = crate::atrium::focus::debug_handoff_dropped() - handoff0;
    serial_println!(
        "HIDCONTEND handoff b_events={} a_events={} handoff_dropped={}",
        b_events,
        a_events,
        handoff_dropped
    );
    if b_events != 0 {
        fail("reason=staged_key_crossed_focus_handoff");
    }
    if handoff_dropped < 2 {
        fail("reason=hid_handoff_batch_not_discarded");
    }

    // --- Jarvis F2 (CP-37): `PRIMARY` and the device lock are spinning
    // `SwitchMutex`es the RECV pump takes with interrupts OFF, so every
    // acquisition must be IF=0: one held IF=1 by a preempted fd-0 reader
    // deadlocks a same-CPU pump. Drive the fd-0 entry points with interrupts
    // ON (the exact shape that took `PRIMARY` IF=1) and the RECV pump with
    // them OFF; every acquisition site counts an IF=1 entry.
    let violations0 = crate::drivers::usb::hid_keyboard::debug_if_on_acquisitions();
    x86_64::instructions::interrupts::enable();
    for _ in 0..64 {
        let _ = hid_keyboard::try_read_byte();
        let _ = crate::drivers::usb::hid_mouse::try_read_pointer_event();
        pump();
    }
    let violations = crate::drivers::usb::hid_keyboard::debug_if_on_acquisitions() - violations0;
    serial_println!(
        "HIDCONTEND mixed_if fd0_reads=64 if_on_acquisitions={}",
        violations
    );
    if violations != 0 {
        fail("reason=hid_lock_taken_with_interrupts_enabled");
    }
    hid_teardown_kill_focus_holder();
    pass(
        "press_release_pairs=all_in_order contention=exercised sak=latched_once buttons=reconciled handoff=fail_closed mixed_if=no_deadlock teardown=if_off source=real_usb_hid_hmp",
    )
}

// DI-1a B-ref discriminator (THINK §8.3): an in-kernel stand-in for the WM
// claims the pointer route and handles REAL usb-mouse records: forward once,
// replay refused, drop, a dead target refused without consuming, a stale tag
// refused, reclaim kills the old route, and releasing the route restores
// ADR-074's kind-2 route.
/// OT-66 L2b (Jarvis #160 items 1, 6, 7). Super+L takes no lock, so on SMP it
/// can land between any route check and its effect. Each leg arms one point
/// (`focus::race`) there and runs what the other CPU would, on this CPU:
/// - recv: Super+L between a client's receive check and its pop;
/// - forward: Super+L between a forward's lock check and its enqueue;
/// - queued: a key queued before Super+L, then an unlock;
/// - drop: the lock focus dies while locked; a route read between its stores.
///
/// No key or record from before a lock may reach the client after it.
#[cfg(feature = "neo-test-lock-route-races")]
fn run_lock_route_races() -> ! {
    use crate::arch::x86_64::without_interrupts as off;
    use crate::atrium::focus::{self, InputFocus, Stage, race};
    use crate::atrium::input_logic::{INPUT_EVENT_POINTER, InputEventV1};
    use crate::atrium::pointer_route_logic::INPUT_EVENT_POINTER_REC;
    use alloc::sync::Arc;

    let key = |code: u8| InputEventV1::key(code, 0, true);
    let arm = |point: u8| {
        race::HITS.store(0, Ordering::Release);
        race::ARMED.store(point, Ordering::Release);
    };
    let hit = |why: &str| {
        if race::HITS.load(Ordering::Acquire) != 1 {
            fail(why);
        }
    };

    let client = Arc::new(InputFocus::new());
    let lock = Arc::new(InputFocus::new());
    if !off(|| client.activate()) {
        fail("reason=lock_race_activate_failed");
    }
    if !off(|| focus::register_lock_route(&lock)) {
        fail("reason=lock_race_register_failed");
    }
    let Ok(route) = off(|| focus::claim_pointer_route(false)) else {
        fail("reason=lock_race_claim_failed");
    };
    // Non-vacuity: unlocked, a key reaches the client.
    off(|| focus::route_event(key(0x04)));
    if off(|| client.try_recv()).is_none() {
        fail("reason=lock_race_unlocked_key_lost");
    }
    serial_println!("LOCKRACE ready client=active lock=registered pointer=claimed");

    // Item 1: Super+L between the receive's check and its pop.
    off(|| focus::route_event(key(0x05)));
    arm(race::RECV);
    let got = off(|| client.try_recv());
    hit("reason=lock_race_recv_point_not_reached");
    if got.is_some() {
        fail("reason=lock_race_recv_returned_key_after_latch");
    }
    if client.is_active() || !lock.is_active() {
        fail("reason=lock_race_recv_not_locked");
    }
    if !off(|| focus::release_lock_route(&client)) {
        fail("reason=lock_race_release_failed");
    }
    if off(|| client.try_recv()).is_some() {
        fail("reason=lock_race_recv_key_crossed_lock");
    }
    serial_println!("LOCKRACE recv latch_between_check_and_pop delivered=none");

    // Item 6: Super+L between a forward's lock check and its enqueue.
    let mut stage = Stage::with_capacity(focus::INPUT_STAGE_CAPACITY);
    focus::stage_event(
        &mut stage,
        InputEventV1 {
            kind: INPUT_EVENT_POINTER,
            flags: 0,
            code: 0,
            x: 3,
            y: 0,
        },
    );
    off(|| focus::flush_pointer_staged(&mut stage));
    let Some(record) = core::iter::from_fn(|| off(|| route.try_recv()))
        .find(|e| e.kind == INPUT_EVENT_POINTER_REC)
    else {
        fail("reason=lock_race_no_record_minted");
    };
    arm(race::FORWARD);
    if off(|| focus::forward_record(&route, record.code, Some(&client), 5, 5)).is_err() {
        fail("reason=lock_race_forward_refused");
    }
    hit("reason=lock_race_forward_point_not_reached");
    if off(|| client.try_recv()).is_some() {
        fail("reason=lock_race_forward_delivered_while_locked");
    }
    if !off(|| focus::release_lock_route(&client)) {
        fail("reason=lock_race_release_failed");
    }
    if off(|| client.try_recv()).is_some() {
        fail("reason=lock_race_forward_record_crossed_lock");
    }
    serial_println!("LOCKRACE forward latch_between_check_and_enqueue delivered=none");

    // A key queued before Super+L, then an unlock.
    off(|| focus::route_event(key(0x06)));
    if !focus::engage_lock_route() {
        fail("reason=lock_race_engage_failed");
    }
    if off(|| client.try_recv()).is_some() {
        fail("reason=lock_race_queued_key_while_locked");
    }
    if !off(|| focus::release_lock_route(&client)) {
        fail("reason=lock_race_release_failed");
    }
    if off(|| client.try_recv()).is_some() {
        fail("reason=lock_race_queued_key_crossed_lock");
    }
    off(|| focus::route_event(key(0x07)));
    if off(|| client.try_recv()).is_none() {
        fail("reason=lock_race_key_after_unlock_lost");
    }
    serial_println!("LOCKRACE queued key_before_latch delivered=none after_unlock=delivered");

    // Item 7: the lock focus dies while locked; a route read between its
    // stores must not see the client's route.
    if !focus::engage_lock_route() {
        fail("reason=lock_race_engage_failed");
    }
    race::WATCH.store(client.debug_id(), Ordering::Release);
    arm(race::DROP);
    off(|| drop(lock));
    hit("reason=lock_race_drop_point_not_reached");
    if race::WATCHED_ROUTE.load(Ordering::Acquire) {
        fail("reason=lock_race_drop_reopened_client_route");
    }
    if client.receivable() {
        fail("reason=lock_race_drop_not_fail_closed");
    }
    // A new WM activates the client: only input from now on reaches it.
    if !off(|| client.activate()) {
        fail("reason=lock_race_reactivate_failed");
    }
    off(|| focus::route_event(key(0x08)));
    match off(|| client.try_recv()) {
        Some(e) if e.code == 0x08 => {}
        _ => fail("reason=lock_race_key_after_reactivate_wrong"),
    }
    serial_println!("LOCKRACE drop route_between_stores client=closed");
    pass("lock_route_races recv=closed forward=closed queued=closed drop=closed")
}

/// OT-88 A0k (`ipc-try-send`): `try_send` and `try_grant` complete only with
/// the peer already parked in its receive, and otherwise change nothing.
/// - idle: an idle peer is EAGAIN; nothing parks on either side;
/// - parked: a receiver parked on CPU 1 gets the bytes;
/// - race: CPU 1 receives 200 times in a row while the BSP retries each send
///   until it lands; every message arrives exactly once, in order;
/// - sending: a peer parked in its own send is EAGAIN, and its send is still
///   there for a receive;
/// - grant: an idle peer is EAGAIN with nothing installed; a parked
///   `recv_grant` gets exactly one handle;
/// - closed: EPIPE.
#[cfg(feature = "neo-test-ipc-try-send")]
mod ipc_try_send {
    use super::*;
    pub static FIXTURE: spin::Mutex<Option<SmpRendezvousFixture>> = spin::Mutex::new(None);
    pub static ROUNDS_DONE: AtomicU64 = AtomicU64::new(0);
    pub static FAILED: AtomicU64 = AtomicU64::new(0);
    pub static SENT: AtomicU64 = AtomicU64::new(0);
    pub static GRANT_CHANNEL: spin::Mutex<Option<alloc::sync::Arc<crate::ipc::Channel>>> =
        spin::Mutex::new(None);
    pub static GRANT_RECIPIENT: AtomicU64 = AtomicU64::new(0);
    pub static GRANT_RESULT: core::sync::atomic::AtomicI64 =
        core::sync::atomic::AtomicI64::new(i64::MIN);
    pub const ROUNDS: u64 = 201;
    pub static GRANTOR_PAYLOAD: spin::Mutex<Option<crate::ipc::GrantPayload>> =
        spin::Mutex::new(None);
    pub static GRANTOR_RESULT: core::sync::atomic::AtomicI64 =
        core::sync::atomic::AtomicI64::new(i64::MIN);

    /// CPU 1: one `grant` from side B (parks until the BSP takes it).
    pub extern "C" fn grantor() -> ! {
        let channel = GRANT_CHANNEL
            .lock()
            .clone()
            .unwrap_or_else(|| fail("reason=grant_channel_missing"));
        let payload = GRANTOR_PAYLOAD
            .lock()
            .unwrap_or_else(|| fail("reason=grantor_payload_missing"));
        let r = crate::arch::x86_64::without_interrupts(|| {
            channel.grant(crate::ipc::EndpointSide::B, payload)
        });
        GRANTOR_RESULT.store(r, Ordering::Release);
        crate::sched::exit();
    }

    pub fn fixture() -> SmpRendezvousFixture {
        FIXTURE
            .lock()
            .clone()
            .unwrap_or_else(|| fail("reason=try_send_fixture_missing"))
    }

    /// CPU 1: receive ROUNDS messages; round r carries sequence r.
    pub extern "C" fn receiver() -> ! {
        let f = fixture();
        for seq in 0..ROUNDS {
            let n = crate::arch::x86_64::without_interrupts(|| {
                f.channel.recv(
                    crate::ipc::EndpointSide::B,
                    f.recv_va,
                    f.len,
                    f.receiver_pmap.clone(),
                )
            });
            if n != f.len as i64 {
                FAILED.store(1, Ordering::Release);
                break;
            }
            verify_rendezvous_payload(&f, seq as u32, 0);
            ROUNDS_DONE.store(seq + 1, Ordering::Release);
            // A delivery runs this thread on the sender's CPU at once
            // (consumer-first), so it re-parks before the sender tries again.
            // Yield first on two rounds in three, so tries also land while it
            // is between receives.
            for _ in 0..(seq % 3) {
                crate::sched::yield_now();
            }
        }
        crate::sched::exit();
    }

    /// PR #15 review item 1: the receiver's read-only destination page.
    pub const RO_VA: u64 = 0x0000_0000_00b0_0000;
    pub static RO_RESULT: core::sync::atomic::AtomicI64 =
        core::sync::atomic::AtomicI64::new(i64::MIN);

    /// CPU 1: one `recv` on side B into the receiver's read-only page.
    pub extern "C" fn ro_receiver() -> ! {
        let f = fixture();
        let r = crate::arch::x86_64::without_interrupts(|| {
            f.channel.recv(
                crate::ipc::EndpointSide::B,
                RO_VA,
                f.len,
                f.receiver_pmap.clone(),
            )
        });
        RO_RESULT.store(r, Ordering::Release);
        crate::sched::exit();
    }

    /// CPU 1: one ordinary send from side B (the receiver page carries it).
    pub extern "C" fn sender() -> ! {
        let f = fixture();
        let n = crate::arch::x86_64::without_interrupts(|| {
            f.channel.send(
                crate::ipc::EndpointSide::B,
                f.recv_va,
                f.len,
                f.receiver_pmap.clone(),
            )
        });
        SENT.store(if n == f.len as i64 { 1 } else { 2 }, Ordering::Release);
        crate::sched::exit();
    }

    /// CPU 1: one `recv_grant` on side B for the fixture recipient.
    pub extern "C" fn grant_receiver() -> ! {
        let channel = GRANT_CHANNEL
            .lock()
            .clone()
            .unwrap_or_else(|| fail("reason=grant_channel_missing"));
        let pid = crate::sched::process::ProcessId(GRANT_RECIPIENT.load(Ordering::Acquire) as u32);
        let r = crate::arch::x86_64::without_interrupts(|| {
            channel.recv_grant(
                crate::ipc::EndpointSide::B,
                pid,
                crate::sched::process::full_channel_rights(),
            )
        });
        GRANT_RESULT.store(r, Ordering::Release);
        crate::sched::exit();
    }
}

#[cfg(feature = "neo-test-ipc-try-send")]
fn run_ipc_try_send() -> ! {
    const A: crate::ipc::EndpointSide = crate::ipc::EndpointSide::A;
    const B: crate::ipc::EndpointSide = crate::ipc::EndpointSide::B;
    use crate::sched::process::{self, Handle, Process};
    use ipc_try_send::*;
    use x86_64::instructions::interrupts::without_interrupts;

    let spin_until = |what: &str, cond: &dyn Fn() -> bool| {
        for _ in 0..2_000_000u64 {
            if cond() {
                return;
            }
            crate::sched::yield_now();
            crate::sched::reap();
        }
        serial_println!("TRYSEND timeout waiting for {}", what);
        fail("reason=try_send_timeout");
    };
    spin_until("cpu1", &|| crate::sched::scheduler::cpu_scheduler_ready(1));
    let f = create_rendezvous_fixture();
    *FIXTURE.lock() = Some(f.clone());
    let try_send = || {
        without_interrupts(|| {
            f.channel
                .try_send(A, f.send_va, f.len, f.sender_pmap.clone())
        })
    };

    // idle.
    write_rendezvous_payload(&f, 0, 0);
    if try_send() != crate::errno::EAGAIN {
        fail("reason=try_send_idle_not_eagain");
    }
    if f.channel.debug_endpoint_is_send_blocked(A) || f.channel.debug_endpoint_is_recv_blocked(B) {
        fail("reason=try_send_idle_parked");
    }

    // parked.
    let t = crate::sched::thread::Thread::new("try-send-recv", receiver);
    if crate::sched::scheduler::place_thread_on_cpu(t, 1).is_err() {
        fail("reason=try_send_place_receiver");
    }
    spin_until("receiver parked", &|| {
        f.channel.debug_endpoint_is_recv_blocked(B)
    });
    if try_send() != f.len as i64 {
        fail("reason=try_send_parked_not_delivered");
    }
    spin_until("round 0", &|| ROUNDS_DONE.load(Ordering::Acquire) >= 1);
    serial_println!("TRYSEND idle=eagain parked=delivered");

    // race.
    let mut eagain = 0u64;
    for seq in 1..ROUNDS {
        write_rendezvous_payload(&f, seq as u32, 0);
        loop {
            let r = try_send();
            if r == f.len as i64 {
                break;
            }
            if r != crate::errno::EAGAIN {
                fail_with_hex("reason=try_send_race_error r", r as u64);
            }
            eagain += 1;
            if FAILED.load(Ordering::Acquire) != 0 {
                fail("reason=try_send_receiver_failed");
            }
            core::hint::spin_loop();
        }
        // No wait for the receiver here: the next try lands while it is
        // between receives (EAGAIN) or parked again. The sender page is
        // copied at each delivery, so rewriting it can't change a message.
    }
    spin_until("last round", &|| {
        ROUNDS_DONE.load(Ordering::Acquire) >= ROUNDS || FAILED.load(Ordering::Acquire) != 0
    });
    if FAILED.load(Ordering::Acquire) != 0 || ROUNDS_DONE.load(Ordering::Acquire) != ROUNDS {
        fail("reason=try_send_race_lost_or_duplicated");
    }
    serial_println!(
        "TRYSEND race rounds={} eagain_retries={}",
        ROUNDS - 1,
        eagain
    );
    // Non-vacuity: the race met the window between receives.
    if eagain == 0 {
        fail("reason=try_send_race_vacuous");
    }

    // sending: B parks in its own send; A's try is EAGAIN and leaves it.
    let t = crate::sched::thread::Thread::new("try-send-send", sender);
    {
        // The receiver page carries B's payload.
        let base =
            crate::mm::phys_to_virt(x86_64::PhysAddr::new(f.receiver_phys)).as_mut_ptr::<u8>();
        let payload = make_rendezvous_payload(999, 1);
        unsafe { core::ptr::copy_nonoverlapping(payload.as_ptr(), base, payload.len()) };
    }
    if crate::sched::scheduler::place_thread_on_cpu(t, 1).is_err() {
        fail("reason=try_send_place_sender");
    }
    spin_until("sender parked", &|| {
        f.channel.debug_endpoint_is_send_blocked(B)
    });
    if try_send() != crate::errno::EAGAIN {
        fail("reason=try_send_vs_sender_not_eagain");
    }
    if !f.channel.debug_endpoint_is_send_blocked(B) {
        fail("reason=try_send_disturbed_parked_sender");
    }
    let n = without_interrupts(|| f.channel.recv(A, f.send_va, f.len, f.sender_pmap.clone()));
    if n != f.len as i64 {
        fail("reason=try_send_parked_sender_lost");
    }
    let got = unsafe {
        let base = crate::mm::phys_to_virt(x86_64::PhysAddr::new(f.sender_phys)).as_ptr::<u8>();
        core::slice::from_raw_parts(base, f.len).to_vec()
    };
    if got != make_rendezvous_payload(999, 1) {
        fail("reason=try_send_parked_sender_bytes");
    }
    spin_until("sender done", &|| SENT.load(Ordering::Acquire) != 0);
    serial_println!("TRYSEND sending_peer=eagain its_send=kept");

    // grant.
    let grantor = process::register(Process::new_user(
        "try-grantor",
        crate::mm::pmap::Pmap::new().unwrap_or_else(|_| fail("reason=try_grant_pmap")),
    ));
    let recipient = process::register(Process::new_user(
        "try-recipient",
        crate::mm::pmap::Pmap::new().unwrap_or_else(|_| fail("reason=try_grant_pmap")),
    ));
    let source_cap = process::alloc_cap_id();
    process::install_cap(
        &grantor,
        Handle::Channel {
            channel: crate::ipc::Channel::new(),
            side: A,
            cap_id: source_cap,
            rights: process::full_channel_rights(),
        },
        None,
    )
    .unwrap_or_else(|_| fail("reason=try_grant_source"));
    let channel = crate::ipc::Channel::new();
    *GRANT_CHANNEL.lock() = Some(channel.clone());
    GRANT_RECIPIENT.store(recipient.pid.0 as u64, Ordering::Release);
    let payload = crate::ipc::GrantPayload {
        grantor_pid: grantor.pid,
        source_cap_id: source_cap,
        offered: process::full_channel_rights(),
    };
    let held = || without_interrupts(|| recipient.handles.lock().live_count());
    if without_interrupts(|| channel.try_grant(A, payload)) != crate::errno::EAGAIN {
        fail("reason=try_grant_idle_not_eagain");
    }
    if held() != 0 || channel.debug_endpoint_is_grant_blocked(A) {
        fail("reason=try_grant_idle_changed_something");
    }
    let t = crate::sched::thread::Thread::new("try-grant-recv", grant_receiver);
    if crate::sched::scheduler::place_thread_on_cpu(t, 1).is_err() {
        fail("reason=try_grant_place");
    }
    spin_until("recv_grant parked", &|| {
        channel.debug_endpoint_is_recv_grant_blocked(B)
    });
    if without_interrupts(|| channel.try_grant(A, payload)) != 0 {
        fail("reason=try_grant_parked_not_installed");
    }
    spin_until("grant result", &|| {
        GRANT_RESULT.load(Ordering::Acquire) != i64::MIN
    });
    if GRANT_RESULT.load(Ordering::Acquire) < 0 || held() != 1 {
        fail("reason=try_grant_not_exactly_one_handle");
    }
    serial_println!("TRYSEND grant idle=eagain parked=one_handle");

    // recv grant: idle is EAGAIN with nothing installed; a grantor parked
    // in its grant on CPU 1 is taken, and exactly one handle arrives.
    let channel = crate::ipc::Channel::new();
    *GRANT_CHANNEL.lock() = Some(channel.clone());
    *GRANTOR_PAYLOAD.lock() = Some(payload);
    let all = process::full_channel_rights();
    if without_interrupts(|| channel.try_recv_grant(A, recipient.pid, all)) != crate::errno::EAGAIN
    {
        fail("reason=try_recv_grant_idle_not_eagain");
    }
    if held() != 1 || channel.debug_endpoint_is_recv_grant_blocked(A) {
        fail("reason=try_recv_grant_idle_changed_something");
    }
    let t = crate::sched::thread::Thread::new("try-grantor", ipc_try_send::grantor);
    if crate::sched::scheduler::place_thread_on_cpu(t, 1).is_err() {
        fail("reason=try_recv_grant_place");
    }
    spin_until("grantor parked", &|| {
        channel.debug_endpoint_is_grant_blocked(B)
    });
    if without_interrupts(|| channel.try_recv_grant(A, recipient.pid, all)) < 0 {
        fail("reason=try_recv_grant_parked_not_taken");
    }
    spin_until("grantor done", &|| {
        GRANTOR_RESULT.load(Ordering::Acquire) != i64::MIN
    });
    if GRANTOR_RESULT.load(Ordering::Acquire) != 0 || held() != 2 {
        fail("reason=try_recv_grant_not_exactly_one_handle");
    }
    serial_println!("TRYSEND recv_grant idle=eagain parked=one_handle");

    // read-only destination (PR #15 review item 1): a receiver parked on a
    // MAP_READ-only page gets EFAULT, and the page is not written.
    let ro_frame = {
        use x86_64::structures::paging::FrameAllocator;
        crate::mm::with_frame_alloc(|fa| fa.allocate_frame())
            .unwrap_or_else(|| fail("reason=try_send_ro_frame"))
    };
    let ro_base = crate::mm::phys_to_virt(ro_frame.start_address()).as_mut_ptr::<u8>();
    unsafe { core::ptr::write_bytes(ro_base, 0x5A, 4096) };
    f.receiver_pmap
        .map_user(
            x86_64::VirtAddr::new(RO_VA),
            ro_frame,
            crate::mm::pmap::flags::USER_DATA_RO,
        )
        .unwrap_or_else(|_| fail("reason=try_send_ro_map"));
    write_rendezvous_payload(&f, 7, 0);
    let t = crate::sched::thread::Thread::new("try-send-ro", ro_receiver);
    if crate::sched::scheduler::place_thread_on_cpu(t, 1).is_err() {
        fail("reason=try_send_place_ro");
    }
    spin_until("ro receiver parked", &|| {
        f.channel.debug_endpoint_is_recv_blocked(B)
    });
    if try_send() != crate::errno::EFAULT {
        fail("reason=try_send_ro_dest_not_efault");
    }
    spin_until("ro receiver done", &|| {
        RO_RESULT.load(Ordering::Acquire) != i64::MIN
    });
    if RO_RESULT.load(Ordering::Acquire) != crate::errno::EFAULT {
        fail("reason=try_send_ro_receiver_not_efault");
    }
    let untouched = unsafe { core::slice::from_raw_parts(ro_base, f.len) }
        .iter()
        .all(|&b| b == 0x5A);
    if !untouched {
        fail("reason=try_send_ro_dest_written");
    }
    serial_println!("TRYSEND ro_dest=efault untouched=yes");

    // closed.
    f.channel.close_peer(A, process::ProcessId(u32::MAX));
    if try_send() != crate::errno::EPIPE {
        fail("reason=try_send_closed_not_epipe");
    }
    pass(
        "ipc_try_send idle=eagain parked=delivered race=exactly_once sending=eagain grant=one_or_none recv_grant=one_or_none ro_dest=efault closed=epipe",
    )
}

/// Jarvis (#61): a key repeat is checked against the activation epoch, then
/// staged; the focus can move, or Super+L engage the lock, in between (on
/// another CPU). Each leg runs that other CPU's step on this CPU at the exact
/// point, through the same `key_repeat::poll` / `deliver` the pumps call.
/// No repeat checked under one owner may reach another, or the lock screen.
/// The control (`neo-test-key-repeat-epoch-control`) stages with a fresh
/// epoch read, the pre-fix shape, and must FAIL
/// `reason=repeat_crossed_focus_change`.
#[cfg(feature = "neo-test-key-repeat-epoch")]
fn run_key_repeat_epoch() -> ! {
    use crate::arch::x86_64::without_interrupts as off;
    use crate::atrium::focus::{self, InputFocus, Stage};
    use crate::atrium::key_repeat;
    use crate::atrium::key_repeat_logic::{KEY_REPEAT, KeyRepeat};
    use alloc::sync::Arc;

    const BACKSPACE: u8 = 0x2a;
    const T0: u64 = 1_000_000_000;
    const DUE: u64 = T0 + 500_000_000;
    // A held key, pressed under the current epoch, with a repeat due.
    let held = || {
        let mut r = KeyRepeat::new();
        r.on_key(BACKSPACE, 0, true, T0, focus::activation_epoch());
        r
    };
    let none = |f: &Arc<InputFocus>, why: &str| {
        if let Some(e) = off(|| f.try_recv()) {
            serial_println!("KEYREPEAT got code={:#x} flags={:#x}", e.code, e.flags);
            fail(why);
        }
    };

    let a = Arc::new(InputFocus::new());
    let b = Arc::new(InputFocus::new());
    let lock = Arc::new(InputFocus::new());
    if !off(|| a.activate()) {
        fail("reason=repeat_epoch_activate_failed");
    }
    if !off(|| focus::register_lock_route(&lock)) {
        fail("reason=repeat_epoch_register_failed");
    }
    let mut stage = Stage::with_capacity(focus::INPUT_STAGE_CAPACITY);

    // Non-vacuity: nothing moves, the repeat reaches the owner.
    let mut r = held();
    let Some((event, epoch)) = key_repeat::poll(&mut r, DUE) else {
        fail("reason=repeat_epoch_no_repeat_due");
    };
    key_repeat::deliver(&mut stage, event, epoch);
    focus::flush_staged(&mut stage);
    match off(|| a.try_recv()) {
        Some(e) if e.code == BACKSPACE as u16 && e.flags & KEY_REPEAT != 0 => {}
        _ => fail("reason=repeat_epoch_repeat_lost"),
    }
    serial_println!("KEYREPEAT baseline delivered=owner");

    // Focus moves to B between the check (poll) and the stage.
    let mut r = held();
    let Some((event, epoch)) = key_repeat::poll(&mut r, DUE) else {
        fail("reason=repeat_epoch_no_repeat_due");
    };
    if !off(|| b.activate()) {
        fail("reason=repeat_epoch_activate_failed");
    }
    key_repeat::deliver(&mut stage, event, epoch);
    focus::flush_staged(&mut stage);
    none(&b, "reason=repeat_crossed_focus_change");
    none(&a, "reason=repeat_reached_old_owner_after_change");
    serial_println!("KEYREPEAT focus_change between_check_and_stage delivered=none");

    // Super+L between the check and the stage.
    let mut r = held();
    let Some((event, epoch)) = key_repeat::poll(&mut r, DUE) else {
        fail("reason=repeat_epoch_no_repeat_due");
    };
    if !focus::engage_lock_route() {
        fail("reason=repeat_epoch_engage_failed");
    }
    key_repeat::deliver(&mut stage, event, epoch);
    focus::flush_staged(&mut stage);
    none(&lock, "reason=repeat_reached_lock_screen");
    if !off(|| focus::release_lock_route(&b)) {
        fail("reason=repeat_epoch_release_failed");
    }
    none(&b, "reason=repeat_crossed_lock");
    serial_println!("KEYREPEAT lock between_check_and_stage delivered=none");

    // Super+L between the stage and the flush.
    let mut r = held();
    let Some((event, epoch)) = key_repeat::poll(&mut r, DUE) else {
        fail("reason=repeat_epoch_no_repeat_due");
    };
    key_repeat::deliver(&mut stage, event, epoch);
    if !focus::engage_lock_route() {
        fail("reason=repeat_epoch_engage_failed");
    }
    focus::flush_staged(&mut stage);
    none(&lock, "reason=staged_repeat_reached_lock_screen");
    if !off(|| focus::release_lock_route(&b)) {
        fail("reason=repeat_epoch_release_failed");
    }
    focus::flush_staged(&mut stage);
    none(&b, "reason=staged_repeat_crossed_lock");
    serial_println!("KEYREPEAT lock between_stage_and_flush delivered=none");

    // The legacy routed path: the epoch is compared under DELIVERY.
    let mut r = held();
    let Some((event, epoch)) = key_repeat::poll(&mut r, DUE) else {
        fail("reason=repeat_epoch_no_repeat_due");
    };
    if !off(|| a.activate()) {
        fail("reason=repeat_epoch_activate_failed");
    }
    if off(|| focus::route_event_at(event, epoch)) {
        fail("reason=legacy_repeat_routed_after_focus_change");
    }
    none(&a, "reason=legacy_repeat_crossed_focus_change");
    // And its non-vacuity: the current epoch routes.
    if !off(|| focus::route_event_at(event, focus::activation_epoch())) {
        fail("reason=legacy_repeat_not_routed");
    }
    if off(|| a.try_recv()).is_none() {
        fail("reason=legacy_repeat_lost");
    }
    serial_println!(
        "KEYREPEAT legacy route_checked_under_delivery stale={}",
        focus::debug_stage_stale()
    );
    pass(
        "key_repeat_epoch baseline=delivered focus_change=dropped lock_before_stage=dropped lock_before_flush=discarded legacy=dropped",
    )
}

#[cfg(feature = "neo-test-di1-forward")]
fn run_di1_forward() -> ! {
    use crate::atrium::focus::{ForwardError, InputFocus, claim_pointer_route, forward_record};
    use crate::atrium::input_logic::{INPUT_EVENT_POINTER, InputEventV1};
    use crate::atrium::pointer_route_logic::{
        INPUT_EVENT_POINTER_ABS, INPUT_EVENT_POINTER_REC, PHASE_DOWN,
    };
    use crate::drivers::usb::hid_mouse;
    use alloc::sync::Arc;
    use alloc::vec::Vec;

    const TICK_HZ: u64 = 100;
    let ticks = || crate::arch::x86_64::timer::TICKS.load(Ordering::Acquire);
    // Pump until `n` more mouse reports arrived, then settle briefly.
    let pump_reports = |n: u64, why: &str| {
        let (start, _, _, _) = hid_mouse::debug_counters();
        let deadline = ticks() + 30 * TICK_HZ;
        loop {
            crate::arch::x86_64::without_interrupts(hid_mouse::pump_routed_events);
            let (now, _, _, _) = hid_mouse::debug_counters();
            if now - start >= n {
                break;
            }
            if ticks() > deadline {
                serial_println!("DI1FWD timeout waiting for {}", why);
                fail_with_hex("reason=di1_mouse_reports_timeout got", now - start);
            }
            core::hint::spin_loop();
        }
        let settle = ticks() + TICK_HZ / 5;
        while ticks() < settle {
            crate::arch::x86_64::without_interrupts(hid_mouse::pump_routed_events);
        }
    };
    let drain = |f: &Arc<InputFocus>| -> Vec<InputEventV1> {
        core::iter::from_fn(|| crate::arch::x86_64::without_interrupts(|| f.try_recv())).collect()
    };

    if !hid_mouse::is_bound() {
        fail("reason=di1_mouse_not_bound");
    }
    let client = Arc::new(InputFocus::new());
    crate::arch::x86_64::without_interrupts(|| client.activate());
    let gen0 = crate::atrium::focus::debug_session_generation();
    let Ok(route) = crate::arch::x86_64::without_interrupts(|| claim_pointer_route(false)) else {
        fail("reason=di1_claim_failed");
    };
    if crate::arch::x86_64::without_interrupts(|| claim_pointer_route(false)).is_ok() {
        fail("reason=di1_second_claim_not_refused");
    }
    serial_println!("DI1FWD ready route=claimed generation={}", gen0 + 1);

    // xtask: one move, a left press, its release.
    pump_reports(3, "move+press+release");
    let records: Vec<InputEventV1> = drain(&route)
        .into_iter()
        .filter(|e| e.kind == INPUT_EVENT_POINTER_REC)
        .collect();
    let leaked = drain(&client);
    serial_println!(
        "DI1FWD records={} client_events_before_forward={}",
        records.len(),
        leaked.len()
    );
    // While a route is live, nothing reaches the client unforwarded.
    if !leaked.is_empty() {
        fail("reason=di1_client_saw_unforwarded_pointer");
    }
    let Some(down) = records.iter().find(|e| e.flags & 1 != 0) else {
        fail("reason=di1_no_press_record");
    };
    let Some(up) = records.iter().rev().find(|e| e.flags & 0x1f == 0) else {
        fail("reason=di1_no_release_record");
    };
    let (down, up) = (down.code, up.code);

    // A never-activated target has no route: refused, and nothing consumed.
    let stranger = Arc::new(InputFocus::new());
    if crate::arch::x86_64::without_interrupts(|| {
        forward_record(&route, down, Some(&stranger), 0, 0)
    }) != Err(ForwardError::NoTarget)
    {
        fail("reason=di1_dead_target_not_refused");
    }
    // Forward the press: the client gets the RECORD's buttons and phase at
    // the WM's coordinates.
    if crate::arch::x86_64::without_interrupts(|| {
        forward_record(&route, down, Some(&client), 12, -3)
    })
    .is_err()
    {
        fail("reason=di1_forward_failed");
    }
    let got = drain(&client);
    let want = InputEventV1 {
        kind: INPUT_EVENT_POINTER_ABS,
        flags: 1,
        code: PHASE_DOWN,
        x: 12,
        y: -3,
    };
    if got != [want] {
        serial_println!("DI1FWD forwarded got={:?}", got);
        fail("reason=di1_forwarded_event_wrong");
    }
    // Exactly once.
    if crate::arch::x86_64::without_interrupts(|| {
        forward_record(&route, down, Some(&client), 12, -3)
    }) != Err(ForwardError::Already)
    {
        fail("reason=di1_replay_not_refused");
    }
    // Drop the release; dropping again is refused too; nothing delivered.
    if crate::arch::x86_64::without_interrupts(|| forward_record(&route, up, None, 0, 0)).is_err()
        || crate::arch::x86_64::without_interrupts(|| forward_record(&route, up, None, 0, 0))
            != Err(ForwardError::Already)
    {
        fail("reason=di1_drop_not_once");
    }
    if crate::arch::x86_64::without_interrupts(|| {
        forward_record(&route, up.wrapping_add(500), None, 0, 0)
    }) != Err(ForwardError::Stale)
    {
        fail("reason=di1_unminted_tag_not_stale");
    }
    if !drain(&client).is_empty() {
        fail("reason=di1_drop_delivered");
    }

    // Reclaim (WM restart): a new generation; the old route is dead.
    let Ok(route2) = crate::arch::x86_64::without_interrupts(|| claim_pointer_route(true)) else {
        fail("reason=di1_reclaim_failed");
    };
    let gen2 = crate::atrium::focus::debug_session_generation();
    if gen2 != gen0 + 2 || route.receivable() || !route2.receivable() {
        fail("reason=di1_reclaim_generation_wrong");
    }
    if crate::arch::x86_64::without_interrupts(|| forward_record(&route, down, Some(&client), 0, 0))
        != Err(ForwardError::NotRoute)
    {
        fail("reason=di1_old_route_still_forwards");
    }
    serial_println!("DI1FWD reclaimed generation={}", gen2);
    pump_reports(1, "move after reclaim");
    let fresh: Vec<InputEventV1> = drain(&route2);
    if fresh.is_empty() || fresh[0].kind != INPUT_EVENT_POINTER_REC || fresh[0].code != 1 {
        serial_println!("DI1FWD fresh={:?}", fresh);
        fail("reason=di1_reclaimed_route_not_fresh");
    }

    // Release the route: the mouse falls back to ADR-074's kind-2 route.
    drop(route2);
    drop(route);
    serial_println!("DI1FWD released");
    pump_reports(1, "move after release");
    let fallback = drain(&client);
    if !fallback.iter().any(|e| e.kind == INPUT_EVENT_POINTER) {
        serial_println!("DI1FWD fallback={:?}", fallback);
        fail("reason=di1_release_did_not_restore_adr074");
    }

    // Jarvis (#46 RETURN F3 / CP-54): the live client route set is capped,
    // so every id lookup under DELIVERY is bounded; the pointer route is
    // outside the cap and can always be (re)claimed.
    let cap = crate::atrium::focus::INPUT_ROUTE_CAP;
    let mut flood = Vec::new();
    let mut refused = 0usize;
    for _ in 0..cap + 4 {
        let f = Arc::new(InputFocus::new());
        if crate::arch::x86_64::without_interrupts(|| f.activate()) {
            flood.push(f);
        } else {
            refused += 1;
        }
    }
    let route3 = crate::arch::x86_64::without_interrupts(|| claim_pointer_route(true));
    serial_println!(
        "DI1FWD route_cap cap={} activated={} refused={} pointer_claim_under_flood={}",
        cap,
        flood.len(),
        refused,
        route3.is_ok()
    );
    // The client focus above still holds a route: the flood gets cap - 1.
    if flood.len() + 1 != cap || refused != 5 || route3.is_err() {
        fail("reason=di1_route_set_not_capped");
    }
    drop(route3);
    drop(flood);
    let again = Arc::new(InputFocus::new());
    if !crate::arch::x86_64::without_interrupts(|| again.activate()) {
        fail("reason=di1_dead_routes_not_reclaimed_after_cap");
    }
    pass(
        "forward=record_buttons_once replay=refused drop=once stale=refused dead_target=refused reclaim=new_generation release=adr074 route_cap=bounded source=real_usb_mouse_hmp",
    )
}

// ── USB HID boot-protocol MOUSE — the GUI pointer (Milestone-A input) ──────────
// Hermetic driver gate mirroring `input_path_console`. Boots with a real
// qemu-xhci + usb-mouse on the root port: proves the mouse ENUMERATES + BINDS on
// the real xHCI/claim/interrupt-EP/arena-fenced stack (I-14 inherited, no new
// master), then injects hand-laid boot mouse reports through the bound driver's
// REAL decode + bounded-queue + counter path and asserts the pointer events
// (buttons + signed dX/dY + wheel), the idle-suppression trap, and the I-14(b)
// drop cap — all deterministic (no dependence on QEMU mouse-input routing). Real
// physical motion → event is the bare-metal plug-in-a-mouse close.
/// Zenbook USB input lane: two xHCIs at the Intel addresses (0x0d, the
/// Type-C subsystem's; 0x14, the south one), the keyboard and mouse on the
/// second. The census must see both, choose the second, and both devices must
/// bind. Its control chooses the first in scan order and FAILs
/// `hid_not_bound` (after the evidence hold, which it also exercises).
#[cfg(feature = "neo-test-usb-xhci-select")]
fn run_usb_xhci_select() -> ! {
    use crate::drivers::usb::{self, xhci};

    let (count, chosen) = xhci::census_for_test();
    serial_println!(
        "NEO_TEST/1 event=INFO name={} census={} chosen={:?}",
        SCENARIO,
        count,
        chosen
    );
    if count != 2 {
        fail("reason=census_not_two_controllers");
    }
    // 2 s for a bind (already done by the boot scan), a 1 s hold, a 0.5 s
    // input check (nothing is typed: it must report NOTHING RECEIVED).
    usb::input_evidence_hold_for(200, 100, 50);
    // Image A (`boot-evidence-holds` off): the same summary, no wait.
    let ticks = || crate::arch::x86_64::timer::TICKS.load(core::sync::atomic::Ordering::Relaxed);
    let start = ticks();
    let bound_now = usb::input_evidence_summary();
    let took = ticks() - start;
    serial_println!(
        "NEO_TEST/1 event=INFO name={} no_wait_summary bound={} ticks={}",
        SCENARIO,
        bound_now,
        took
    );
    if !bound_now || took > 5 {
        fail("reason=no_wait_summary_waited_or_unbound");
    }
    if !xhci::keyboard_bound() || !xhci::mouse_bound() {
        serial_println!(
            "NEO_TEST/1 event=FAIL name={} reason=hid_not_bound chosen={:?} keyboard={} mouse={}",
            SCENARIO,
            chosen,
            xhci::keyboard_bound(),
            xhci::mouse_bound()
        );
        debug_exit(EXIT_FAILURE);
    }
    if chosen != Some(1) {
        fail("reason=wrong_controller_chosen");
    }
    serial_println!(
        "NEO_TEST/1 event=PASS name={} usb_xhci_select=ok census=2 chosen=1 reason=usb2-device-connected keyboard=bound mouse=bound summary=printed no_wait_summary=ok",
        SCENARIO
    );
    debug_exit(EXIT_SUCCESS);
}

/// Zenbook USB input lane: no device at boot. xtask hot-adds a usb-kbd,
/// types `a`, removes it, adds it again and types `b`. The port service must
/// enumerate both plugs, see the unplug, and the re-plugged keyboard must
/// deliver. Its control never starts the service and FAILs
/// `hotplug_not_bound`.
#[cfg(feature = "neo-test-usb-hotplug")]
fn run_usb_hotplug() -> ! {
    use crate::drivers::usb::{self, hid_keyboard, xhci};

    fn wait_for(ticks: u64, mut done: impl FnMut() -> bool) -> bool {
        let start = crate::arch::x86_64::timer::TICKS.load(core::sync::atomic::Ordering::Relaxed);
        loop {
            if done() {
                return true;
            }
            let now = crate::arch::x86_64::timer::TICKS.load(core::sync::atomic::Ordering::Relaxed);
            if now.saturating_sub(start) >= ticks {
                return false;
            }
            usb::nap_ticks(5);
        }
    }
    fn wait_for_byte(want: u8) -> bool {
        wait_for(1000, || hid_keyboard::try_read_byte() == Some(want))
    }
    let counters = || xhci::hotplug::counters();

    if hid_keyboard::is_bound() {
        fail("reason=keyboard_bound_before_plug");
    }
    // CP-81: a kernel thread's nap parks on its tick deadline, stays parked
    // until it, is woken by the tick, and a deadline already passed does not
    // park. The control (never parks: the old yield loop) FAILs here.
    {
        let (parked, woken_early, woken, past_skips, slept) = crate::sched::tick_sleep::selftest();
        serial_println!(
            "NEO_TEST/1 event=INFO name={} tick-sleep parked={} woken_early={} woken={} past_skips={} slept_ticks={}",
            SCENARIO,
            parked,
            woken_early,
            woken,
            past_skips,
            slept
        );
        if !parked || woken_early || !woken || !past_skips || slept < 20 {
            fail("reason=tick_sleep_not_parked");
        }
    }
    serial_println!(
        "NEO_TEST/1 event=INFO name={} hotplug=ready-for-plug",
        SCENARIO
    );
    if !wait_for(1500, hid_keyboard::is_bound) {
        let (passes, enumerated, detached) = counters();
        serial_println!(
            "NEO_TEST/1 event=FAIL name={} reason=hotplug_not_bound passes={} enumerated={} detached={}",
            SCENARIO,
            passes,
            enumerated,
            detached
        );
        debug_exit(EXIT_FAILURE);
    }
    serial_println!("NEO_TEST/1 event=INFO name={} hotplug=type-first", SCENARIO);
    if !wait_for_byte(b'a') {
        fail("reason=no_key_after_plug");
    }
    serial_println!("NEO_TEST/1 event=INFO name={} hotplug=unplug-now", SCENARIO);
    if !wait_for(1000, || counters().2 >= 1) {
        fail("reason=unplug_not_seen");
    }
    serial_println!("NEO_TEST/1 event=INFO name={} hotplug=replug-now", SCENARIO);
    if !wait_for(1500, || counters().1 >= 2) {
        fail("reason=replug_not_enumerated");
    }
    serial_println!(
        "NEO_TEST/1 event=INFO name={} hotplug=type-second",
        SCENARIO
    );
    if !wait_for_byte(b'b') {
        fail("reason=no_key_after_replug");
    }
    xhci::log_usb_summary();
    let (passes, enumerated, detached) = counters();
    // Every nap of the port service and this thread parked: none found the
    // table full, so none yield-spun.
    let (parked, full, spins) = crate::sched::tick_sleep::counters();
    if parked == 0 || full != 0 || spins != 0 {
        serial_println!(
            "NEO_TEST/1 event=FAIL name={} reason=tick_sleep_spun parked={} full={} spins={}",
            SCENARIO,
            parked,
            full,
            spins
        );
        debug_exit(EXIT_FAILURE);
    }
    serial_println!(
        "NEO_TEST/1 event=PASS name={} usb_hotplug=ok plug=enumerated key_a=delivered unplug=seen replug=enumerated key_b=delivered passes={} enumerated={} detached={} sleep=parked:{},full:0,spins:0 port_loops={}",
        SCENARIO,
        passes,
        enumerated,
        detached,
        parked,
        usb::port_service_loops()
    );
    debug_exit(EXIT_SUCCESS);
}

/// i8042 lane: keys typed into QEMU's PS/2 keyboard (HMP `sendkey`; no USB
/// keyboard is attached, so QEMU routes them to the i8042) decode to exactly
/// the HID key events the USB boot keyboard would produce: usage, modifier
/// byte, press then release. The script (xtask `PS2_KEYBOARD_HMP_STEPS`)
/// covers a plain letter and digit, a shifted letter, an `E0` key (Up), a
/// right-hand modifier (`E0 1D`), the `E1` Pause sequence and Enter. The
/// test drains without the polled fallback, so every byte must have come
/// through IRQ1 on the I/O APIC.
///
/// The control (`neo-test-ps2-keyboard-control`) leaves the controller
/// untranslated: the keyboard's set 2 is read as set 1 and the decode fails.
/// The QEMU stand-in for the RTL8125 containment legs: QEMU's own rtl8139
/// (10ec:8139). Only its PCI COMMAND register is exercised.
#[cfg(any(feature = "neo-test-rtl8125-absent", feature = "neo-test-rtl8125-vtd"))]
fn rtl8125_stand_in() -> crate::drivers::pci::Device {
    let Some(dev) = crate::drivers::pci::enumerate_all()
        .into_iter()
        .find(|d| d.vendor_id == 0x10ec && d.device_id == 0x8139)
    else {
        fail("stand_in_missing (no 10ec:8139 on the bus)");
    };
    dev
}

/// RTL8125 rung 1, no device: the boot probe reported absent, and the
/// containment seam on a host with no IOMMU leaves Bus Master Enable clear
/// even when firmware left it set. Control: the opt-in forced on.
#[cfg(feature = "neo-test-rtl8125-absent")]
fn run_rtl8125_absent() -> ! {
    use crate::drivers::net::rtl8125::{self, BindStatus};
    use alloc::format;

    if rtl8125::status() != BindStatus::Absent {
        fail(&format!("not_absent status={:?}", rtl8125::status()));
    }
    // Image A's on-screen summary: with no device it re-prints exactly the
    // boot probe's `absent` line under its header.
    let kept = rtl8125::kept_boot_lines();
    let reprinted = rtl8125::evidence_summary();
    serial_println!(
        "RTL8125SUMMARY kept={} reprinted={} first={:?}",
        kept.len(),
        reprinted,
        kept.first()
    );
    if reprinted != 1 || kept.len() != 1 || kept[0] != "rtl8125: pci 10ec:8125 absent" {
        fail(&format!(
            "summary_lines kept={:?} reprinted={}",
            kept, reprinted
        ));
    }
    let dev = rtl8125_stand_in();
    // Firmware (a UEFI PXE stack) may leave bus mastering on: start there.
    crate::drivers::pci::enable_bus_mastering(dev);
    if !rtl8125::bus_master_set(dev) {
        fail("stand_in_bme_preset_failed");
    }
    let admits_before = crate::drivers::dma_arena::fence_admits();
    let grants_before = rtl8125::bus_master_grants();
    let opt_in = cfg!(feature = "neo-test-rtl8125-absent-control");
    let mode = rtl8125::bind_containment(dev, opt_in);
    let cleared_at_bind = !rtl8125::bus_master_set(dev);
    // The driver's next step would be the rings; the grant follows them.
    let granted = rtl8125::grant_bus_master(dev, mode);
    let bme = rtl8125::bus_master_set(dev);
    let admits = crate::drivers::dma_arena::fence_admits() - admits_before;
    let grants = rtl8125::bus_master_grants() - grants_before;
    serial_println!(
        "RTL8125ABSENT status=absent mode={:?} cleared_at_bind={} granted={} bme={} grants={} fence_admits={}",
        mode,
        cleared_at_bind,
        granted,
        bme,
        grants,
        admits
    );
    if bme {
        fail(&format!("bus_master_set mode={:?}", mode));
    }
    if !cleared_at_bind || granted || grants != 0 {
        fail(&format!(
            "containment_path cleared_at_bind={} granted={} grants={}",
            cleared_at_bind, granted, grants
        ));
    }
    if admits != 0 {
        fail(&format!("dma_touched fence_admits={}", admits));
    }
    pass("rtl8125=absent dma=blocked(no-iommu) bme=0 summary=absent");
}

/// RTL8125 rung 1, the VT-d leg on QEMU's intel-iommu: the stand-in is moved
/// into the fence domain, the mode is `iommu`, Bus Master Enable is clear
/// after bind and set only by the grant.
#[cfg(feature = "neo-test-rtl8125-vtd")]
fn run_rtl8125_vtd() -> ! {
    use crate::drivers::net::rtl8125::{self, BindStatus};
    use alloc::format;

    if rtl8125::status() != BindStatus::Absent {
        fail(&format!("not_absent status={:?}", rtl8125::status()));
    }
    if !crate::drivers::iommu::enabled() {
        fail("vtd_not_enabled");
    }
    let dev = rtl8125_stand_in();
    crate::drivers::pci::enable_bus_mastering(dev);
    let mode = rtl8125::bind_containment(dev, false);
    let cleared_at_bind = !rtl8125::bus_master_set(dev);
    let granted = rtl8125::grant_bus_master(dev, mode);
    let bme = rtl8125::bus_master_set(dev);
    serial_println!(
        "RTL8125VTD mode={:?} cleared_at_bind={} granted={} bme={}",
        mode,
        cleared_at_bind,
        granted,
        bme
    );
    if !cleared_at_bind {
        fail("bme_not_cleared_at_bind");
    }
    if format!("{:?}", mode) != "Iommu" || !granted || !bme {
        fail(&format!(
            "not_fenced mode={:?} granted={} bme={}",
            mode, granted, bme
        ));
    }
    pass("rtl8125 dma=iommu bme=granted-after-bind");
}

#[cfg(feature = "neo-test-ps2-keyboard")]
fn run_ps2_keyboard() -> ! {
    use crate::atrium::input_logic::InputEventV1;
    use crate::drivers::ps2::i8042;
    use alloc::vec::Vec;

    const TICK_HZ: u64 = 100;
    // (usage, modifiers, locks, pressed), in order.
    const EXPECTED: &[(u8, u8, u8, bool)] = &[
        (0x04, 0x00, 0, true), // a
        (0x04, 0x00, 0, false),
        (0x1E, 0x00, 0, true), // 1
        (0x1E, 0x00, 0, false),
        (0x05, 0x02, 0, true), // shift-b (left Shift held)
        (0x05, 0x02, 0, false),
        (0x52, 0x00, 0, true), // Up (E0 48)
        (0x52, 0x00, 0, false),
        (0x06, 0x10, 0, true), // ctrl_r-c (E0 1D, right Ctrl)
        (0x06, 0x10, 0, false),
        (0x48, 0x00, 0, true), // Pause (E1 1D 45 E1 9D C5)
        (0x48, 0x00, 0, false),
        (0x28, 0x00, 0, true), // Enter
        (0x28, 0x00, 0, false),
        (0x33, 0x02, 0, true), // shift-semicolon: `:`
        (0x33, 0x02, 0, false),
        (0x34, 0x20, 0, true), // shift_r-apostrophe: `"` (right Shift)
        (0x34, 0x20, 0, false),
        (0x39, 0x00, 1, true), // Caps Lock on (the press carries it)
        (0x39, 0x00, 1, false),
        (0x04, 0x00, 1, true), // a, under Caps Lock: `A`
        (0x04, 0x00, 1, false),
        (0x39, 0x00, 0, true), // Caps Lock off again
        (0x39, 0x00, 0, false),
        (0x5F, 0x00, 0, true), // keypad 7 (0x47)
        (0x5F, 0x00, 0, false),
        (0x55, 0x00, 0, true), // keypad * (0x37)
        (0x55, 0x00, 0, false),
        (0x54, 0x00, 0, true), // keypad / (E0 35)
        (0x54, 0x00, 0, false),
        (0x58, 0x00, 0, true), // keypad Enter (E0 1C)
        (0x58, 0x00, 0, false),
        (0x53, 0x00, 2, true), // Num Lock off (the press carries it)
        (0x53, 0x00, 2, false),
        (0x60, 0x00, 2, true), // keypad 8, Num Lock off: Up
        (0x60, 0x00, 2, false),
        (0x53, 0x00, 0, true), // Num Lock on again
        (0x53, 0x00, 0, false),
    ];
    // The usages the keypad presses act as (after `effective_usage`), from
    // keypad 7 on: 7, *, /, Enter, Num Lock, Up (keypad 8), Num Lock.
    const KEYPAD_ACTS_AS: &[u8] = &[0x5F, 0x55, 0x54, 0x58, 0x53, 0x52, 0x53];
    // The text the presses after Enter type, through the shared US keymap.
    const TEXT_AFTER_ENTER: &[u8] = b":\"A7*/";
    let ticks = || crate::arch::x86_64::timer::TICKS.load(Ordering::Acquire);

    serial_println!("PS2KBD ready");
    let mut got: Vec<InputEventV1> = Vec::new();
    // Bounded by the TSC as well as the tick: a lost EOI stops the tick too,
    // and the diagnostics below must still print.
    // SAFETY: RDTSC has no side effect.
    let tsc = || unsafe { core::arch::x86_64::_rdtsc() };
    let tsc_deadline = tsc() + 40_000_000_000;
    let deadline = ticks() + 20 * TICK_HZ;
    // Each pass leaves interrupts ON for a real window. `drain_events` and
    // `yield_now` are both IF=0 sections; back to back, the `sti` ending one
    // is followed directly by the `cli` starting the next, and the STI
    // interrupt shadow means no interrupt is recognised between them. Under
    // TCG that starved IRQ1 and the tick for whole seconds (QEMU's 16-byte
    // PS/2 queue then overflowed, or the run stalled).
    let window = || {
        for _ in 0..2_000 {
            core::hint::spin_loop();
        }
    };
    while got.len() < EXPECTED.len() && ticks() < deadline && tsc() < tsc_deadline {
        i8042::drain_events(&mut got);
        window();
        crate::sched::yield_now();
    }
    // Anything trailing (a mis-decode can produce extra events).
    let settle = ticks() + TICK_HZ / 2;
    let tsc_settle = tsc() + 1_000_000_000;
    while ticks() < settle && tsc() < tsc_settle {
        i8042::drain_events(&mut got);
        window();
        crate::sched::yield_now();
    }
    let (isr, irr) = crate::arch::x86_64::apic::isr_irr_for_test(i8042::VECTOR);
    serial_println!(
        "ps2_keyboard diag cpu={} ticks={} status={:#04x} lapic_isr={} lapic_irr={} ioapic_low={:x?}",
        crate::arch::x86_64::per_cpu::current_cpu_id(),
        ticks(),
        i8042::status_for_test(),
        isr,
        irr,
        crate::arch::x86_64::ioapic::routed_low_for_test()
    );
    let counters = i8042::Counters::now();
    serial_println!("{}", counters);
    for (i, e) in got.iter().enumerate() {
        serial_println!(
            "ps2_keyboard event[{}] usage={:#04x} modifiers={:#04x} pressed={}",
            i,
            e.code,
            e.x,
            e.flags & crate::atrium::input_logic::KEY_PRESSED != 0
        );
    }
    let want: Vec<InputEventV1> = EXPECTED
        .iter()
        .map(|&(usage, modifiers, locks, pressed)| {
            InputEventV1::key_locked(usage, modifiers, locks, pressed)
        })
        .collect();
    if got != want {
        fail_with_hex(
            "reason=ps2_keyboard_decode_mismatch events",
            got.len() as u64,
        );
    }
    let enter = got.iter().position(|e| e.code == 0x28).unwrap_or(got.len());
    let text: Vec<u8> = got[enter..]
        .iter()
        .filter(|e| e.flags & crate::atrium::input_logic::KEY_PRESSED != 0)
        .filter_map(|e| {
            crate::drivers::keymap_us_logic::printable(e.code as u8, e.x as u8, e.y as u8)
        })
        .collect();
    serial_println!(
        "ps2_keyboard text={:?}",
        core::str::from_utf8(&text).unwrap_or("<non-utf8>")
    );
    if text != TEXT_AFTER_ENTER {
        fail_with_hex("reason=ps2_keyboard_text_mismatch len", text.len() as u64);
    }
    let keypad = got.iter().position(|e| e.code == 0x5F).unwrap_or(got.len());
    let acts_as: Vec<u8> = got[keypad..]
        .iter()
        .filter(|e| e.flags & crate::atrium::input_logic::KEY_PRESSED != 0)
        .map(|e| {
            crate::drivers::keymap_us_logic::effective_usage(e.code as u8, e.x as u8, e.y as u8)
        })
        .collect();
    if acts_as != KEYPAD_ACTS_AS {
        fail_with_hex(
            "reason=ps2_keyboard_keypad_mismatch len",
            acts_as.len() as u64,
        );
    }
    // The hook never polls: every byte came through IRQ1 on the I/O APIC.
    if counters.irqs == 0 || counters.polled != 0 || counters.irq_bytes != counters.bytes {
        fail_with_hex("reason=ps2_keyboard_not_via_irq1 irqs", counters.irqs);
    }
    pass(
        "ps2_keyboard=ok decode=hid_usage_exact irq1=ioapic e0=up,ctrl_r e1=pause text=colon,quote,caps keypad=digits,ops,enter,numlock_nav",
    );
}

/// Key auto-repeat: xtask holds Backspace 1.5 s, then Escape 1.5 s, then
/// types 'x' (`PS2_KEY_REPEAT_HMP_STEPS`), into QEMU's PS/2 keyboard. Every
/// event is stamped with the clock value the repeat state machine itself used
/// (`drain_events_stamped`), so the timing checks are exact, with no slack.
/// Backspace must give its press, at least 3 repeats and its release, with
/// nothing repeating after the release, and repeat k (from 0) must come no
/// sooner than press + 500 ms + k/30 s: that rejects a first repeat at
/// 490 ms and a run 30 ms apart. Adjacent repeats are not held to 33 ms each,
/// because the clock is the 10 ms tick: correct repeats land on tick edges,
/// 30 or 40 ms apart. Escape and 'x' must give exactly a press and a release.
#[cfg(feature = "neo-test-ps2-key-repeat")]
fn run_ps2_key_repeat() -> ! {
    use crate::atrium::input_logic::{InputEventV1, KEY_PRESSED};
    use crate::atrium::key_repeat::NS_PER_TICK;
    use crate::atrium::key_repeat_logic::{DELAY_NS, INTERVAL_NS, KEY_REPEAT};
    use crate::drivers::ps2::i8042;
    use alloc::vec::Vec;

    const TICK_HZ: u64 = 100;
    const BACKSPACE: u16 = 0x2A;
    const ESCAPE: u16 = 0x29;
    const X: u16 = 0x1B;
    let ticks = || crate::arch::x86_64::timer::TICKS.load(Ordering::Acquire);
    // SAFETY: RDTSC has no side effect.
    let tsc = || unsafe { core::arch::x86_64::_rdtsc() };
    // The IF=1 window between passes (CP-73; see `run_ps2_keyboard`).
    let window = || {
        for _ in 0..2_000 {
            core::hint::spin_loop();
        }
    };

    serial_println!("PS2REP ready");
    let mut got: Vec<(InputEventV1, u64)> = Vec::new();
    let x_released = |got: &Vec<(InputEventV1, u64)>| {
        got.iter()
            .any(|(e, _)| e.code == X && e.flags & KEY_PRESSED == 0)
    };
    let deadline = ticks() + 30 * TICK_HZ;
    let tsc_deadline = tsc() + 60_000_000_000;
    while !x_released(&got) && ticks() < deadline && tsc() < tsc_deadline {
        i8042::drain_events_stamped(&mut got);
        window();
        crate::sched::yield_now();
    }
    let (repeats_counted, typematic) = crate::atrium::key_repeat::counters();
    serial_println!("{}", i8042::Counters::now());
    serial_println!(
        "key-repeat: rep={} typematic={} events={}",
        repeats_counted,
        typematic,
        got.len()
    );
    for (i, (e, t)) in got.iter().enumerate() {
        serial_println!(
            "ps2_key_repeat event[{}] usage={:#04x} flags={:#04x} tick={}",
            i,
            e.code,
            e.flags,
            t / NS_PER_TICK
        );
    }
    let is = |e: &InputEventV1, code: u16, flags: u8| e.code == code && e.flags == flags;
    let press = KEY_PRESSED;
    let repeat = KEY_PRESSED | KEY_REPEAT;
    // Backspace: press, repeats, release.
    let Some(((first, t_press), rest)) = got.split_first() else {
        fail("reason=key_repeat_no_events");
    };
    if !is(first, BACKSPACE, press) {
        fail_with_hex(
            "reason=key_repeat_first_not_backspace usage",
            first.code as u64,
        );
    }
    let repeats: Vec<u64> = rest
        .iter()
        .take_while(|(e, _)| is(e, BACKSPACE, repeat))
        .map(|(_, t)| *t)
        .collect();
    if repeats.is_empty() {
        fail("reason=key_repeat_none");
    }
    let after: Vec<InputEventV1> = rest[repeats.len()..].iter().map(|(e, _)| *e).collect();
    let want_after = [
        InputEventV1::key(BACKSPACE as u8, 0, false),
        InputEventV1::key(ESCAPE as u8, 0, true),
        InputEventV1::key(ESCAPE as u8, 0, false),
        InputEventV1::key(X as u8, 0, true),
        InputEventV1::key(X as u8, 0, false),
    ];
    if after != want_after {
        fail_with_hex("reason=key_repeat_tail_mismatch events", after.len() as u64);
    }
    if repeats.len() < 3 {
        fail_with_hex("reason=key_repeat_too_few repeats", repeats.len() as u64);
    }
    // Exact: the stamps are the times the state machine was given.
    for (k, t) in repeats.iter().enumerate() {
        let earliest = t_press + DELAY_NS + k as u64 * INTERVAL_NS;
        if *t < earliest {
            if k == 0 {
                fail_with_hex("reason=key_repeat_too_early ms", (t - t_press) / 1_000_000);
            }
            fail_with_hex("reason=key_repeat_too_fast repeat", k as u64);
        }
    }
    if repeats_counted != repeats.len() as u64 {
        fail_with_hex("reason=key_repeat_counter_mismatch rep", repeats_counted);
    }
    let min_gap_ns = repeats.windows(2).map(|w| w[1] - w[0]).min().unwrap_or(0);
    serial_println!(
        "PS2REP backspace repeats={} first_after_ms={} span_ms={} min_gap_ms={}",
        repeats.len(),
        (repeats[0] - t_press) / 1_000_000,
        (repeats[repeats.len() - 1] - repeats[0]) / 1_000_000,
        min_gap_ns / 1_000_000
    );
    pass("ps2_key_repeat=ok held=repeats(k>=500ms+k/30s) release=stops escape=no_repeat");
}

/// I2C-HID touchpad lane: the driver on a machine that is not the Zenbook
/// (QEMU's DSDT is `BOCHS`/`BXPCDSDT`). The quirk must not match and
/// nothing may be probed; then two proofs that need no device:
/// - the bounded timeout: the driver's own MMIO register access and TSC
///   clock, aimed at a zeroed RAM page standing in for a controller that
///   never answers, must return `Timeout(Enable)` within the handshake
///   budget (twice: the bare handshake and a whole transfer);
/// - I-14(a) at run time: the ISR body runs to completion while this
///   context holds, with IF=0, all nine: the AI-governance `ARENA`,
///   `RESERVATIONS`, `INFLIGHT`, `TABLE` and `RECENCY` locks, `DELIVERY`,
///   the driver's `STATE` and `BOOT_LINES`, and the `BUS_OWNER` flag;
/// - the photo replay: the boot-console replay image A's touchpad check
///   runs must reprint the `i2c-hid: no match (...)` line.
///
/// The control (`neo-test-i2c-hid-absent-control`) forces the match. The
/// driver must then fail closed (no controller at 00:19.1: bounded, no
/// hang), and this scenario FAILs `i2c_hid_probed_without_match`.
#[cfg(feature = "neo-test-i2c-hid-absent")]
fn run_i2c_hid_absent() -> ! {
    use crate::drivers::i2c_hid::dw_logic::{Error, Stage};
    use crate::drivers::i2c_hid::quirk_logic::Verdict;
    use crate::drivers::i2c_hid::touchpad;

    let verdict = touchpad::verdict_for_test();
    let probed = touchpad::probed_for_test();
    serial_println!(
        "i2c_hid_absent verdict={:?} probed={} {}",
        verdict,
        probed,
        touchpad::Counters::now()
    );
    if probed {
        fail("reason=i2c_hid_probed_without_match");
    }
    match verdict {
        Some(Verdict::OemMismatch { .. }) | Some(Verdict::NoTemplate) | Some(Verdict::NoDsdt) => {}
        _ => fail("reason=i2c_hid_unexpected_verdict"),
    }

    let (enable, transfer, elapsed) = touchpad::no_controller_timeout_for_test();
    let budget = touchpad::handshake_budget_for_test();
    serial_println!(
        "i2c_hid_absent no-controller enable={:?} transfer={:?} tsc={} handshake_budget={}",
        enable,
        transfer,
        elapsed,
        budget
    );
    if enable != Err(Error::Timeout(Stage::Enable))
        || transfer != Err(Error::Timeout(Stage::Enable))
    {
        fail("reason=i2c_hid_no_controller_not_timeout");
    }
    // Two handshakes, each bounded by the budget (plus loop slack).
    if elapsed < 2 * budget || elapsed > 4 * budget {
        fail_with_hex("reason=i2c_hid_timeout_unbounded tsc", elapsed);
    }

    let added = touchpad::isr_with_driver_locks_held_for_test();
    if added != 1 {
        fail_with_hex("reason=i2c_hid_isr_not_run irqs", added);
    }
    if !touchpad::bus_owner_was_held_for_test() {
        fail("reason=i2c_hid_isr_test_bus_owner_not_held");
    }

    let (replayed, no_match_first) = touchpad::replay_boot_lines_for_test();
    serial_println!(
        "i2c_hid_absent replay lines={} no_match_first={}",
        replayed,
        no_match_first
    );
    if replayed == 0 || !no_match_first {
        fail_with_hex(
            "reason=i2c_hid_no_match_not_replayed lines",
            replayed as u64,
        );
    }
    // CP-81: the service thread's IRQ wait parks, stays parked, and the ISR
    // body wakes it; with an interrupt already pending it does not park.
    let (parked, woken_early, woken_by_isr, skipped) = touchpad::irq_wait_for_test();
    serial_println!(
        "i2c_hid_absent irq-wait parked={} woken_early={} woken_by_isr={} skipped_when_pending={}",
        parked,
        woken_early,
        woken_by_isr,
        skipped
    );
    if !parked || woken_early || !woken_by_isr || !skipped {
        fail("reason=i2c_hid_irq_wait_not_parked_or_not_woken");
    }
    // Image A's not-working hold, on the no-match path: 1 s, and it must
    // last the whole second (no keyboard is typed on).
    // Image A (`boot-evidence-holds` off): the same lines, no hold.
    let ticks = || crate::arch::x86_64::timer::TICKS.load(core::sync::atomic::Ordering::Relaxed);
    let start = ticks();
    let (lines, ready) = touchpad::evidence_lines();
    let took = ticks() - start;
    serial_println!(
        "i2c_hid_absent no-hold lines={} ready={} ticks={}",
        lines,
        ready,
        took
    );
    if lines == 0 || ready || took > 5 {
        fail_with_hex("reason=i2c_hid_no_hold_lines_waited ticks", took);
    }
    let (held_ticks, ended_early) = touchpad::not_working_hold_for_test(100);
    serial_println!(
        "i2c_hid_absent hold ticks={} ended_early={}",
        held_ticks,
        ended_early
    );
    if held_ticks < 100 || ended_early {
        fail_with_hex("reason=i2c_hid_not_working_not_held ticks", held_ticks);
    }
    pass(
        "i2c_hid_absent=ok quirk=no-match probed=no timeout=bounded isr=completes-holding(arena,reservations,inflight,table,recency,delivery,state,boot_lines,bus) replay=no-match no-hold=lines hold=held irq-wait=parks,isr-wakes",
    );
}

#[cfg(feature = "neo-test-usb-hid-mouse")]
fn run_usb_hid_mouse() -> ! {
    use crate::drivers::usb::hid_logic::{MOUSE_BTN_LEFT, MOUSE_BTN_MIDDLE, PointerEvent};
    use crate::drivers::usb::hid_mouse;

    // 1) The real usb-mouse enumerated + bound (enumeration → claim → SET_PROTOCOL
    //    boot → report buffers posted). is_bound() is the gate observable.
    if !hid_mouse::is_bound() {
        fail("reason=usb_hid_mouse_not_bound");
    }

    // 2) Inject the dispatch's anchor vector through the driver's real decode +
    //    queue, read it back via the consumer API, assert the pointer event.
    let expect = |bytes: &[u8], want: Option<PointerEvent>, tag: &str| {
        if !hid_mouse::debug_inject_report(bytes) {
            fail("reason=usb_hid_mouse_inject_no_device");
        }
        let got = hid_mouse::try_read_pointer_event();
        if got != want {
            serial_println!(
                "NEO_TEST/1 event=FAIL name={} reason=usb_hid_mouse_decode_mismatch case={} got={:?} want={:?}",
                SCENARIO,
                tag,
                got,
                want
            );
            debug_exit(EXIT_FAILURE);
        }
    };

    // Anchor: left down, dX=+5, dY=−5, wheel=+2 (USB HID 1.11 §B.2 + the dispatch).
    expect(
        &[0x01, 0x05, 0xFB, 0x02],
        Some(PointerEvent {
            buttons: MOUSE_BTN_LEFT,
            dx: 5,
            dy: -5,
            wheel: 2,
        }),
        "anchor_left_5_-5_wheel2",
    );
    // Signed-delta trap: 0xFF = −1 (both axes).
    expect(
        &[0x01, 0xFF, 0xFF, 0x00],
        Some(PointerEvent {
            buttons: MOUSE_BTN_LEFT,
            dx: -1,
            dy: -1,
            wheel: 0,
        }),
        "neg_delta",
    );
    // Variable-length trap: 3-byte report (no wheel byte) → wheel=0. Buttons back
    // to 0 (a release, so it emits despite zero motion on this report? dX=10 ≠ 0).
    expect(
        &[0x00, 0x0A, 0x00],
        Some(PointerEvent {
            buttons: 0,
            dx: 10,
            dy: 0,
            wheel: 0,
        }),
        "three_byte_no_wheel",
    );
    // Wheel-only (middle button change, zero motion) still emits.
    expect(
        &[0x04, 0x00, 0x00, 0x03],
        Some(PointerEvent {
            buttons: MOUSE_BTN_MIDDLE,
            dx: 0,
            dy: 0,
            wheel: 3,
        }),
        "wheel_only_middle",
    );
    // Idle-repeat suppression: same buttons (0x04), zero motion/wheel → NO event.
    if !hid_mouse::debug_inject_report(&[0x04, 0x00, 0x00, 0x00]) {
        fail("reason=usb_hid_mouse_inject_no_device");
    }
    if hid_mouse::try_read_pointer_event().is_some() {
        fail("reason=usb_hid_mouse_idle_report_emitted_event");
    }

    // 3) I-14(b) bounded queue: flood past the cap → excess DROPPED, never queued
    //    unboundedly. Drain first so the queue starts empty, then inject cap+extra
    //    distinct-motion reports WITHOUT reading (so the queue fills and overflows).
    while hid_mouse::try_read_pointer_event().is_some() {}
    let cap = hid_mouse::debug_pending_cap();
    let flood = cap + 8;
    for i in 0..flood {
        // Alternate dX sign so every report is a distinct motion event (never
        // idle-suppressed), guaranteeing the queue actually fills.
        let dx = if i % 2 == 0 { 1u8 } else { 0xFFu8 };
        hid_mouse::debug_inject_report(&[0x00, dx, 0x00, 0x00]);
    }
    let (reports, events, ep_errors, dropped) = hid_mouse::debug_counters();
    if dropped == 0 {
        serial_println!(
            "NEO_TEST/1 event=FAIL name={} reason=usb_hid_mouse_queue_cap_not_enforced reports={} events={} dropped={}",
            SCENARIO,
            reports,
            events,
            dropped
        );
        debug_exit(EXIT_FAILURE);
    }
    // 4) Init continues, no endpoint errors on the real bound device.
    if ep_errors != 0 {
        serial_println!(
            "NEO_TEST/1 event=FAIL name={} reason=usb_hid_mouse_ep_errors ep_errors={}",
            SCENARIO,
            ep_errors
        );
        debug_exit(EXIT_FAILURE);
    }

    serial_println!(
        "NEO_TEST/1 event=measure name={} bound=true reports={} events={} dropped={} cap={} ep_errors={}",
        SCENARIO,
        reports,
        events,
        dropped,
        cap,
        ep_errors
    );
    pass(
        "usb_hid_mouse=ok enumerated=ok bound=ok boot_protocol=true decode=buttons+signed_dxdy+wheel idle_suppressed=true i14b_queue_cap=enforced i14=inherited_xhci_arena_fenced_no_new_master init_continues=true",
    );
}

#[cfg(feature = "neo-test-smp-block-release-smoke")]
type SmpBlockSlot = Option<alloc::boxed::Box<crate::sched::thread::Thread>>;

#[cfg(feature = "neo-test-smp-block-release-smoke")]
static SMP_BLOCK_SLOT: crate::sync::SwitchMutex<SmpBlockSlot> = crate::sync::SwitchMutex::new(None);
#[cfg(feature = "neo-test-smp-block-release-smoke")]
static SMP_BLOCK_STAGE: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);
#[cfg(feature = "neo-test-smp-block-release-smoke")]
static SMP_BLOCKED_CPU: core::sync::atomic::AtomicU32 =
    core::sync::atomic::AtomicU32::new(u32::MAX);
#[cfg(feature = "neo-test-smp-block-release-smoke")]
static SMP_COMPLETER_CPU: core::sync::atomic::AtomicU32 =
    core::sync::atomic::AtomicU32::new(u32::MAX);
#[cfg(feature = "neo-test-smp-block-release-smoke")]
static SMP_RESUMED_CPU: core::sync::atomic::AtomicU32 =
    core::sync::atomic::AtomicU32::new(u32::MAX);

#[cfg(feature = "neo-test-smp-block-release-smoke")]
const SMP_BLOCK_STAGE_DONE: u32 = 3;
#[cfg(feature = "neo-test-smp-block-release-smoke")]
const SMP_BLOCK_RETURN: i64 = 0x3b;

#[cfg(feature = "neo-test-smp-block-release-smoke")]
extern "C" fn smp_block_release_blocker() -> ! {
    let blocked_cpu = crate::arch::x86_64::per_cpu::current_cpu_id();
    SMP_BLOCKED_CPU.store(blocked_cpu, Ordering::Release);

    let guard = SMP_BLOCK_SLOT.lock();
    let ret = crate::sched::scheduler::block_current_into_with_guard(guard, |slot, waiter| {
        *slot = Some(waiter);
        SMP_BLOCK_STAGE.store(1, Ordering::Release);
    });

    if ret != SMP_BLOCK_RETURN {
        fail_with_hex("reason=blocked_return_mismatch ret", ret as u64);
    }

    let resumed_cpu = crate::arch::x86_64::per_cpu::current_cpu_id();
    SMP_RESUMED_CPU.store(resumed_cpu, Ordering::Release);
    SMP_BLOCK_STAGE.store(SMP_BLOCK_STAGE_DONE, Ordering::Release);
    crate::sched::exit();
}

#[cfg(feature = "neo-test-smp-block-release-smoke")]
extern "C" fn smp_block_release_releaser() -> ! {
    let completer_cpu = crate::arch::x86_64::per_cpu::current_cpu_id();
    SMP_COMPLETER_CPU.store(completer_cpu, Ordering::Release);

    loop {
        let waiter = {
            let mut slot = SMP_BLOCK_SLOT.lock();
            slot.take()
        };

        if let Some(waiter) = waiter {
            crate::sched::scheduler::wake_thread_front(waiter, SMP_BLOCK_RETURN);
            crate::sched::yield_now();
            crate::sched::exit();
        }

        crate::sched::yield_now();
    }
}

#[cfg(feature = "neo-test-smp-block-release-smoke")]
fn run_smp_block_release_smoke() -> ! {
    if crate::arch::x86_64::per_cpu::current_cpu_id() != 0 {
        fail("reason=test_not_on_bsp");
    }

    {
        let mut slot = SMP_BLOCK_SLOT.lock();
        *slot = None;
    }
    SMP_BLOCK_STAGE.store(0, Ordering::Release);
    SMP_BLOCKED_CPU.store(u32::MAX, Ordering::Release);
    SMP_COMPLETER_CPU.store(u32::MAX, Ordering::Release);
    SMP_RESUMED_CPU.store(u32::MAX, Ordering::Release);

    for _ in 0..100_000 {
        if crate::sched::scheduler::cpu_scheduler_ready(1) {
            break;
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    if !crate::sched::scheduler::cpu_scheduler_ready(1) {
        fail("reason=cpu1_scheduler_not_ready");
    }

    let releaser =
        crate::sched::thread::Thread::new("smp-block-release-releaser", smp_block_release_releaser);
    if crate::sched::scheduler::place_thread_on_cpu(releaser, 1).is_err() {
        fail("reason=place_releaser_failed");
    }
    crate::sched::spawn("smp-block-release-blocker", smp_block_release_blocker);

    for _ in 0..1_000_000 {
        if SMP_BLOCK_STAGE.load(Ordering::Acquire) == SMP_BLOCK_STAGE_DONE {
            break;
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }

    if SMP_BLOCK_STAGE.load(Ordering::Acquire) != SMP_BLOCK_STAGE_DONE {
        fail("reason=block_release_timeout");
    }
    crate::sched::reap();

    let blocked_cpu = SMP_BLOCKED_CPU.load(Ordering::Acquire);
    let completer_cpu = SMP_COMPLETER_CPU.load(Ordering::Acquire);
    let resumed_cpu = SMP_RESUMED_CPU.load(Ordering::Acquire);

    if blocked_cpu == completer_cpu {
        fail_with_hex("reason=not_cross_cpu blocked_cpu", blocked_cpu as u64);
    }
    if completer_cpu != 1 {
        fail_with_hex(
            "reason=wrong_completer_cpu completer_cpu",
            completer_cpu as u64,
        );
    }
    if resumed_cpu != completer_cpu {
        fail_with_hex("reason=wrong_resumed_cpu resumed_cpu", resumed_cpu as u64);
    }

    serial_println!(
        "NEO_TEST/1 event=PASS name={} blocked_cpu={} completer_cpu={} resumed_cpu={} release_path=asm",
        SCENARIO,
        blocked_cpu,
        completer_cpu,
        resumed_cpu
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(any(
    feature = "neo-test-smp-send-blocks-first-then-completes",
    feature = "neo-test-smp-recv-blocks-first-then-completes"
))]
#[derive(Clone)]
struct SmpSendRecvFixture {
    channel: alloc::sync::Arc<crate::ipc::Channel>,
    sender_pmap: alloc::sync::Arc<crate::mm::pmap::Pmap>,
    receiver_pmap: alloc::sync::Arc<crate::mm::pmap::Pmap>,
    send_va: u64,
    recv_va: u64,
    len: usize,
    receiver_phys: u64,
}

#[cfg(any(
    feature = "neo-test-smp-send-blocks-first-then-completes",
    feature = "neo-test-smp-recv-blocks-first-then-completes"
))]
static SMP_SEND_RECV_FIXTURE: crate::sync::SwitchMutex<Option<SmpSendRecvFixture>> =
    crate::sync::SwitchMutex::new(None);
#[cfg(any(
    feature = "neo-test-smp-send-blocks-first-then-completes",
    feature = "neo-test-smp-recv-blocks-first-then-completes"
))]
static SMP_SEND_RECV_BLOCKED_CPU: core::sync::atomic::AtomicU32 =
    core::sync::atomic::AtomicU32::new(u32::MAX);
#[cfg(any(
    feature = "neo-test-smp-send-blocks-first-then-completes",
    feature = "neo-test-smp-recv-blocks-first-then-completes"
))]
static SMP_SEND_RECV_COMPLETER_CPU: core::sync::atomic::AtomicU32 =
    core::sync::atomic::AtomicU32::new(u32::MAX);
#[cfg(any(
    feature = "neo-test-smp-send-blocks-first-then-completes",
    feature = "neo-test-smp-recv-blocks-first-then-completes"
))]
static SMP_SEND_RECV_RESUMED_CPU: core::sync::atomic::AtomicU32 =
    core::sync::atomic::AtomicU32::new(u32::MAX);
#[cfg(any(
    feature = "neo-test-smp-send-blocks-first-then-completes",
    feature = "neo-test-smp-recv-blocks-first-then-completes"
))]
static SMP_SEND_RECV_COMPLETER_DONE: core::sync::atomic::AtomicU32 =
    core::sync::atomic::AtomicU32::new(0);

#[cfg(any(
    feature = "neo-test-smp-send-blocks-first-then-completes",
    feature = "neo-test-smp-recv-blocks-first-then-completes"
))]
const SMP_SEND_RECV_PAYLOAD: [u8; 8] = *b"NEO_SC3B";

#[cfg(any(
    feature = "neo-test-smp-send-blocks-first-then-completes",
    feature = "neo-test-smp-recv-blocks-first-then-completes"
))]
fn reset_smp_send_recv_state() {
    {
        let mut fixture = SMP_SEND_RECV_FIXTURE.lock();
        *fixture = None;
    }
    SMP_SEND_RECV_BLOCKED_CPU.store(u32::MAX, Ordering::Release);
    SMP_SEND_RECV_COMPLETER_CPU.store(u32::MAX, Ordering::Release);
    SMP_SEND_RECV_RESUMED_CPU.store(u32::MAX, Ordering::Release);
    SMP_SEND_RECV_COMPLETER_DONE.store(0, Ordering::Release);
}

#[cfg(any(
    feature = "neo-test-smp-send-blocks-first-then-completes",
    feature = "neo-test-smp-recv-blocks-first-then-completes"
))]
fn setup_smp_send_recv_fixture() {
    use x86_64::structures::paging::FrameAllocator;

    const SEND_VA: u64 = 0x0000_0000_0070_0000;
    const RECV_VA: u64 = 0x0000_0000_0080_0000;

    let channel = crate::ipc::Channel::new();
    let sender_pmap = alloc::sync::Arc::new(
        crate::mm::pmap::Pmap::new().unwrap_or_else(|_| fail("reason=sender_pmap_new_failed")),
    );
    let receiver_pmap = alloc::sync::Arc::new(
        crate::mm::pmap::Pmap::new().unwrap_or_else(|_| fail("reason=receiver_pmap_new_failed")),
    );

    let sender_frame = crate::mm::with_frame_alloc(|fa| fa.allocate_frame())
        .unwrap_or_else(|| fail("reason=sender_frame_alloc_failed"));
    let receiver_frame = crate::mm::with_frame_alloc(|fa| fa.allocate_frame())
        .unwrap_or_else(|| fail("reason=receiver_frame_alloc_failed"));

    sender_pmap
        .map_user(
            x86_64::VirtAddr::new(SEND_VA),
            sender_frame,
            crate::mm::pmap::flags::USER_DATA_RW,
        )
        .unwrap_or_else(|_| fail("reason=sender_map_user_failed"));
    receiver_pmap
        .map_user(
            x86_64::VirtAddr::new(RECV_VA),
            receiver_frame,
            crate::mm::pmap::flags::USER_DATA_RW,
        )
        .unwrap_or_else(|_| fail("reason=receiver_map_user_failed"));

    // SAFETY: the two frames were freshly allocated above and are mapped via
    // HHDM. The test owns them through the Pmap mappings for this boot.
    unsafe {
        let src = crate::mm::phys_to_virt(sender_frame.start_address()).as_mut_ptr::<u8>();
        for (idx, byte) in SMP_SEND_RECV_PAYLOAD.iter().enumerate() {
            core::ptr::write_volatile(src.add(idx), *byte);
        }
        let dst = crate::mm::phys_to_virt(receiver_frame.start_address()).as_mut_ptr::<u8>();
        core::ptr::write_bytes(dst, 0, SMP_SEND_RECV_PAYLOAD.len());
    }

    let mut fixture = SMP_SEND_RECV_FIXTURE.lock();
    *fixture = Some(SmpSendRecvFixture {
        channel,
        sender_pmap,
        receiver_pmap,
        send_va: SEND_VA,
        recv_va: RECV_VA,
        len: SMP_SEND_RECV_PAYLOAD.len(),
        receiver_phys: receiver_frame.start_address().as_u64(),
    });
}

#[cfg(any(
    feature = "neo-test-smp-send-blocks-first-then-completes",
    feature = "neo-test-smp-recv-blocks-first-then-completes"
))]
fn smp_send_recv_fixture() -> SmpSendRecvFixture {
    let fixture = SMP_SEND_RECV_FIXTURE.lock();
    match fixture.as_ref() {
        Some(fixture) => fixture.clone(),
        None => fail("reason=fixture_missing"),
    }
}

#[cfg(any(
    feature = "neo-test-smp-send-blocks-first-then-completes",
    feature = "neo-test-smp-recv-blocks-first-then-completes"
))]
fn verify_smp_recv_payload(fixture: &SmpSendRecvFixture) {
    let base = crate::mm::phys_to_virt(x86_64::PhysAddr::new(fixture.receiver_phys)).as_ptr::<u8>();

    // SAFETY: `receiver_phys` is the start of the receiver frame allocated in
    // setup, and `fixture.len` is the static payload length within that page.
    unsafe {
        for (idx, expected) in SMP_SEND_RECV_PAYLOAD.iter().enumerate() {
            let actual = core::ptr::read_volatile(base.add(idx));
            if actual != *expected {
                fail_with_hex("reason=payload_mismatch index", idx as u64);
            }
        }
    }
}

#[cfg(any(
    feature = "neo-test-smp-send-blocks-first-then-completes",
    feature = "neo-test-smp-recv-blocks-first-then-completes"
))]
fn wait_for_cpu1_scheduler_or_fail() {
    for _ in 0..100_000 {
        if crate::sched::scheduler::cpu_scheduler_ready(1) {
            return;
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    fail("reason=cpu1_scheduler_not_ready");
}

#[cfg(any(
    feature = "neo-test-smp-send-blocks-first-then-completes",
    feature = "neo-test-smp-recv-blocks-first-then-completes"
))]
fn wait_for_send_recv_completion_or_fail() {
    for _ in 0..1_000_000 {
        if SMP_SEND_RECV_RESUMED_CPU.load(Ordering::Acquire) != u32::MAX
            && SMP_SEND_RECV_COMPLETER_DONE.load(Ordering::Acquire) == 1
        {
            return;
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    fail("reason=send_recv_completion_timeout");
}

#[cfg(any(
    feature = "neo-test-smp-send-blocks-first-then-completes",
    feature = "neo-test-smp-recv-blocks-first-then-completes"
))]
fn wait_for_send_recv_blocker_started_or_fail(reason: &str) {
    for _ in 0..100_000 {
        if SMP_SEND_RECV_BLOCKED_CPU.load(Ordering::Acquire) != u32::MAX {
            return;
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    fail(reason);
}

#[cfg(any(
    feature = "neo-test-smp-send-blocks-first-then-completes",
    feature = "neo-test-smp-recv-blocks-first-then-completes"
))]
fn validate_send_recv_cpus() -> (u32, u32, u32) {
    let blocked_cpu = SMP_SEND_RECV_BLOCKED_CPU.load(Ordering::Acquire);
    let completer_cpu = SMP_SEND_RECV_COMPLETER_CPU.load(Ordering::Acquire);
    let resumed_cpu = SMP_SEND_RECV_RESUMED_CPU.load(Ordering::Acquire);

    if blocked_cpu == u32::MAX {
        fail("reason=blocked_cpu_missing");
    }
    if completer_cpu == u32::MAX {
        fail("reason=completer_cpu_missing");
    }
    if resumed_cpu == u32::MAX {
        fail("reason=resumed_cpu_missing");
    }
    if blocked_cpu == completer_cpu {
        fail_with_hex("reason=not_cross_cpu blocked_cpu", blocked_cpu as u64);
    }
    if completer_cpu != 1 {
        fail_with_hex(
            "reason=wrong_completer_cpu completer_cpu",
            completer_cpu as u64,
        );
    }
    if resumed_cpu != completer_cpu {
        fail_with_hex("reason=wrong_resumed_cpu resumed_cpu", resumed_cpu as u64);
    }

    (blocked_cpu, completer_cpu, resumed_cpu)
}

#[cfg(feature = "neo-test-smp-send-blocks-first-then-completes")]
extern "C" fn smp_send_blocks_sender() -> ! {
    let fixture = smp_send_recv_fixture();
    let ret = crate::arch::x86_64::without_interrupts(|| {
        SMP_SEND_RECV_BLOCKED_CPU.store(
            crate::arch::x86_64::per_cpu::current_cpu_id(),
            Ordering::Release,
        );
        fixture.channel.send(
            crate::ipc::EndpointSide::A,
            fixture.send_va,
            fixture.len,
            fixture.sender_pmap.clone(),
        )
    });
    if ret != fixture.len as i64 {
        fail_with_hex("reason=send_return_mismatch ret", ret as u64);
    }
    SMP_SEND_RECV_RESUMED_CPU.store(
        crate::arch::x86_64::per_cpu::current_cpu_id(),
        Ordering::Release,
    );
    crate::sched::exit();
}

#[cfg(feature = "neo-test-smp-send-blocks-first-then-completes")]
extern "C" fn smp_send_blocks_receiver() -> ! {
    let fixture = smp_send_recv_fixture();
    let ret = crate::arch::x86_64::without_interrupts(|| {
        SMP_SEND_RECV_COMPLETER_CPU.store(
            crate::arch::x86_64::per_cpu::current_cpu_id(),
            Ordering::Release,
        );
        fixture.channel.recv(
            crate::ipc::EndpointSide::B,
            fixture.recv_va,
            fixture.len,
            fixture.receiver_pmap.clone(),
        )
    });
    if ret != fixture.len as i64 {
        fail_with_hex("reason=recv_return_mismatch ret", ret as u64);
    }
    verify_smp_recv_payload(&fixture);
    SMP_SEND_RECV_COMPLETER_DONE.store(1, Ordering::Release);
    crate::sched::exit();
}

#[cfg(feature = "neo-test-smp-send-blocks-first-then-completes")]
fn run_smp_send_blocks_first_then_completes() -> ! {
    if crate::arch::x86_64::per_cpu::current_cpu_id() != 0 {
        fail("reason=test_not_on_bsp");
    }

    wait_for_cpu1_scheduler_or_fail();
    reset_smp_send_recv_state();
    setup_smp_send_recv_fixture();

    crate::sched::spawn("smp-send-blocks-sender", smp_send_blocks_sender);
    wait_for_send_recv_blocker_started_or_fail("reason=sender_did_not_start");

    let receiver =
        crate::sched::thread::Thread::new("smp-send-blocks-receiver", smp_send_blocks_receiver);
    if crate::sched::scheduler::place_thread_on_cpu(receiver, 1).is_err() {
        fail("reason=place_receiver_failed");
    }

    wait_for_send_recv_completion_or_fail();
    crate::sched::reap();
    let (blocked_cpu, completer_cpu, resumed_cpu) = validate_send_recv_cpus();

    serial_println!(
        "NEO_TEST/1 event=PASS name={} blocked_cpu={} completer_cpu={} resumed_cpu={}",
        SCENARIO,
        blocked_cpu,
        completer_cpu,
        resumed_cpu
    );
    debug_exit(EXIT_SUCCESS);
}

