#[cfg(feature = "neo-test-smp-grant-cross-cpu")]
#[derive(Clone)]
struct SmpGrantFixture {
    channel: alloc::sync::Arc<crate::ipc::Channel>,
    grantor_pid: crate::sched::process::ProcessId,
    recipient_pid: crate::sched::process::ProcessId,
    source_cap_id: crate::sched::process::CapId,
    expected_rights: crate::sched::process::CapRights,
}

#[cfg(feature = "neo-test-smp-grant-cross-cpu")]
static SMP_GRANT_FIXTURE: crate::sync::SwitchMutex<Option<SmpGrantFixture>> =
    crate::sync::SwitchMutex::new(None);
#[cfg(feature = "neo-test-smp-grant-cross-cpu")]
static SMP_GRANT_BLOCKED_CPU: core::sync::atomic::AtomicU32 =
    core::sync::atomic::AtomicU32::new(u32::MAX);
#[cfg(feature = "neo-test-smp-grant-cross-cpu")]
static SMP_GRANT_COMPLETER_CPU: core::sync::atomic::AtomicU32 =
    core::sync::atomic::AtomicU32::new(u32::MAX);
#[cfg(feature = "neo-test-smp-grant-cross-cpu")]
static SMP_GRANT_RESUMED_CPU: core::sync::atomic::AtomicU32 =
    core::sync::atomic::AtomicU32::new(u32::MAX);
#[cfg(feature = "neo-test-smp-grant-cross-cpu")]
static SMP_GRANT_COMPLETER_DONE: core::sync::atomic::AtomicU32 =
    core::sync::atomic::AtomicU32::new(0);
#[cfg(feature = "neo-test-smp-grant-cross-cpu")]
static SMP_GRANT_HANDLE_IDX: core::sync::atomic::AtomicU32 =
    core::sync::atomic::AtomicU32::new(u32::MAX);

#[cfg(feature = "neo-test-smp-grant-cross-cpu")]
const SMP_GRANT_SOURCE_RIGHTS: crate::sched::process::CapRights =
    crate::sched::process::CapRights::new(
        crate::sched::process::meta_rights::USE | crate::sched::process::meta_rights::GRANT,
        crate::sched::process::channel_rights::SEND,
    );
#[cfg(feature = "neo-test-smp-grant-cross-cpu")]
const SMP_GRANT_OFFERED_RIGHTS: crate::sched::process::CapRights =
    crate::sched::process::CapRights::new(
        crate::sched::process::meta_rights::USE | crate::sched::process::meta_rights::GRANT,
        crate::sched::process::channel_rights::SEND,
    );
#[cfg(feature = "neo-test-smp-grant-cross-cpu")]
const SMP_GRANT_MAX_RIGHTS: crate::sched::process::CapRights =
    crate::sched::process::CapRights::new(
        crate::sched::process::meta_rights::USE,
        crate::sched::process::channel_rights::SEND | crate::sched::process::channel_rights::RECV,
    );

#[cfg(feature = "neo-test-smp-grant-cross-cpu")]
fn pack_cap_rights(rights: crate::sched::process::CapRights) -> u16 {
    ((rights.meta as u16) << 8) | rights.semantic as u16
}

#[cfg(feature = "neo-test-smp-grant-cross-cpu")]
fn reset_smp_grant_state() {
    {
        let mut fixture = SMP_GRANT_FIXTURE.lock();
        *fixture = None;
    }
    SMP_GRANT_BLOCKED_CPU.store(u32::MAX, Ordering::Release);
    SMP_GRANT_COMPLETER_CPU.store(u32::MAX, Ordering::Release);
    SMP_GRANT_RESUMED_CPU.store(u32::MAX, Ordering::Release);
    SMP_GRANT_COMPLETER_DONE.store(0, Ordering::Release);
    SMP_GRANT_HANDLE_IDX.store(u32::MAX, Ordering::Release);
}

#[cfg(feature = "neo-test-smp-grant-cross-cpu")]
fn setup_smp_grant_fixture() {
    use crate::ipc::EndpointSide;
    use crate::sched::process::{self, Handle, Process};

    let grant_channel = crate::ipc::Channel::new();
    let transferred_channel = crate::ipc::Channel::new();
    let grantor_pmap =
        crate::mm::pmap::Pmap::new().unwrap_or_else(|_| fail("reason=grantor_pmap_new_failed"));
    let recipient_pmap =
        crate::mm::pmap::Pmap::new().unwrap_or_else(|_| fail("reason=recipient_pmap_new_failed"));
    let grantor = process::register(Process::new_user("smp-grantor", grantor_pmap));
    let recipient = process::register(Process::new_user("smp-recipient", recipient_pmap));

    let root_cap_id = process::alloc_cap_id();
    let root_idx = process::install_cap(
        &grantor,
        Handle::Channel {
            channel: transferred_channel,
            side: EndpointSide::A,
            cap_id: root_cap_id,
            rights: process::full_channel_rights(),
        },
        None,
    )
    .unwrap_or_else(|_| fail("reason=smp_grant_install_cap_failed"));
    let source_idx = process::derive_handle(grantor.pid, root_idx, SMP_GRANT_SOURCE_RIGHTS)
        .unwrap_or_else(|_| fail("reason=derive_source_cap_failed"));
    let source_cap_id = crate::arch::x86_64::without_interrupts(|| {
        grantor
            .handles
            .lock()
            .get(source_idx)
            .unwrap_or_else(|| fail("reason=source_cap_missing"))
            .cap_id()
    });
    let expected_rights = SMP_GRANT_SOURCE_RIGHTS
        .intersection(SMP_GRANT_OFFERED_RIGHTS)
        .intersection(SMP_GRANT_MAX_RIGHTS);

    let mut fixture = SMP_GRANT_FIXTURE.lock();
    *fixture = Some(SmpGrantFixture {
        channel: grant_channel,
        grantor_pid: grantor.pid,
        recipient_pid: recipient.pid,
        source_cap_id,
        expected_rights,
    });
}

#[cfg(feature = "neo-test-smp-grant-cross-cpu")]
fn smp_grant_fixture() -> SmpGrantFixture {
    let fixture = SMP_GRANT_FIXTURE.lock();
    match fixture.as_ref() {
        Some(fixture) => fixture.clone(),
        None => fail("reason=fixture_missing"),
    }
}

#[cfg(feature = "neo-test-smp-grant-cross-cpu")]
fn wait_for_smp_grant_cpu1_or_fail() {
    for _ in 0..100_000 {
        if crate::sched::scheduler::cpu_scheduler_ready(1) {
            return;
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    fail("reason=cpu1_scheduler_not_ready");
}

#[cfg(feature = "neo-test-smp-grant-cross-cpu")]
fn wait_for_smp_grant_blocked_or_fail(fixture: &SmpGrantFixture) {
    for _ in 0..100_000 {
        if fixture
            .channel
            .debug_endpoint_is_grant_blocked(crate::ipc::EndpointSide::A)
        {
            return;
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    fail("reason=grantor_did_not_block");
}

#[cfg(feature = "neo-test-smp-grant-cross-cpu")]
fn wait_for_smp_grant_completion_or_fail() {
    for _ in 0..1_000_000 {
        if SMP_GRANT_RESUMED_CPU.load(Ordering::Acquire) != u32::MAX
            && SMP_GRANT_COMPLETER_DONE.load(Ordering::Acquire) == 1
        {
            return;
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    fail("reason=grant_completion_timeout");
}

#[cfg(feature = "neo-test-smp-grant-cross-cpu")]
fn verify_smp_grant_recipient_handle(fixture: &SmpGrantFixture, handle_idx: u32) {
    crate::arch::x86_64::without_interrupts(|| {
        let recipient = crate::sched::process::get(fixture.recipient_pid)
            .unwrap_or_else(|| fail("reason=recipient_missing"));
        let handle = recipient
            .handles
            .lock()
            .get(handle_idx)
            .unwrap_or_else(|| fail("reason=recipient_handle_missing"));
        let rights = handle.rights();
        if rights != fixture.expected_rights {
            fail_with_hex(
                "reason=grant_rights_mismatch got",
                pack_cap_rights(rights) as u64,
            );
        }
        let cap_id = handle.cap_id();
        if cap_id == fixture.source_cap_id {
            fail("reason=grant_reused_source_cap_id");
        }
        let parent = recipient.derivations.parent_for_test(cap_id);
        if parent != Some(Some(fixture.source_cap_id)) {
            fail("reason=grant_derivation_parent_mismatch");
        }
    });
}

#[cfg(feature = "neo-test-smp-grant-cross-cpu")]
fn validate_smp_grant_cpus() -> (u32, u32, u32) {
    let blocked_cpu = SMP_GRANT_BLOCKED_CPU.load(Ordering::Acquire);
    let completer_cpu = SMP_GRANT_COMPLETER_CPU.load(Ordering::Acquire);
    let resumed_cpu = SMP_GRANT_RESUMED_CPU.load(Ordering::Acquire);

    if blocked_cpu == u32::MAX {
        fail("reason=blocked_cpu_missing");
    }
    if completer_cpu == u32::MAX {
        fail("reason=completer_cpu_missing");
    }
    if resumed_cpu == u32::MAX {
        fail("reason=resumed_cpu_missing");
    }
    if blocked_cpu == completer_cpu {
        fail_with_hex("reason=not_cross_cpu blocked_cpu", blocked_cpu as u64);
    }
    if completer_cpu != 1 {
        fail_with_hex(
            "reason=wrong_completer_cpu completer_cpu",
            completer_cpu as u64,
        );
    }
    if resumed_cpu != completer_cpu {
        fail_with_hex("reason=wrong_resumed_cpu resumed_cpu", resumed_cpu as u64);
    }

    (blocked_cpu, completer_cpu, resumed_cpu)
}

#[cfg(feature = "neo-test-smp-grant-cross-cpu")]
extern "C" fn smp_grant_cross_cpu_grantor() -> ! {
    let fixture = smp_grant_fixture();
    let payload = crate::ipc::GrantPayload {
        grantor_pid: fixture.grantor_pid,
        source_cap_id: fixture.source_cap_id,
        offered: SMP_GRANT_OFFERED_RIGHTS,
    };
    let ret = crate::arch::x86_64::without_interrupts(|| {
        SMP_GRANT_BLOCKED_CPU.store(
            crate::arch::x86_64::per_cpu::current_cpu_id(),
            Ordering::Release,
        );
        fixture.channel.grant(crate::ipc::EndpointSide::A, payload)
    });
    if ret != 0 {
        fail_with_hex("reason=grant_return_mismatch ret", ret as u64);
    }
    SMP_GRANT_RESUMED_CPU.store(
        crate::arch::x86_64::per_cpu::current_cpu_id(),
        Ordering::Release,
    );
    crate::sched::exit();
}

#[cfg(feature = "neo-test-smp-grant-cross-cpu")]
extern "C" fn smp_grant_cross_cpu_recipient() -> ! {
    let fixture = smp_grant_fixture();
    let ret = crate::arch::x86_64::without_interrupts(|| {
        SMP_GRANT_COMPLETER_CPU.store(
            crate::arch::x86_64::per_cpu::current_cpu_id(),
            Ordering::Release,
        );
        fixture.channel.recv_grant(
            crate::ipc::EndpointSide::B,
            fixture.recipient_pid,
            SMP_GRANT_MAX_RIGHTS,
        )
    });
    if ret < 0 {
        fail_with_hex("reason=recv_grant_return_mismatch ret", ret as u64);
    }
    let handle_idx = ret as u32;
    verify_smp_grant_recipient_handle(&fixture, handle_idx);
    SMP_GRANT_HANDLE_IDX.store(handle_idx, Ordering::Release);
    SMP_GRANT_COMPLETER_DONE.store(1, Ordering::Release);
    crate::sched::exit();
}

#[cfg(feature = "neo-test-smp-grant-cross-cpu")]
fn run_smp_grant_cross_cpu() -> ! {
    if crate::arch::x86_64::per_cpu::current_cpu_id() != 0 {
        fail("reason=test_not_on_bsp");
    }

    wait_for_smp_grant_cpu1_or_fail();
    reset_smp_grant_state();
    setup_smp_grant_fixture();

    crate::sched::spawn("smp-grant-cross-grantor", smp_grant_cross_cpu_grantor);
    let fixture = smp_grant_fixture();
    wait_for_smp_grant_blocked_or_fail(&fixture);

    let recipient = crate::sched::thread::Thread::new(
        "smp-grant-cross-recipient",
        smp_grant_cross_cpu_recipient,
    );
    if crate::sched::scheduler::place_thread_on_cpu(recipient, 1).is_err() {
        fail("reason=place_recipient_failed");
    }

    wait_for_smp_grant_completion_or_fail();
    crate::sched::reap();
    let (blocked_cpu, completer_cpu, resumed_cpu) = validate_smp_grant_cpus();
    let grant_rights = pack_cap_rights(fixture.expected_rights);
    let handle_idx = SMP_GRANT_HANDLE_IDX.load(Ordering::Acquire);
    if handle_idx == u32::MAX {
        fail("reason=handle_idx_missing");
    }

    serial_println!(
        "NEO_TEST/1 event=PASS name={} blocked_cpu={} completer_cpu={} resumed_cpu={} grant_rights={:#x} handle_idx={}",
        SCENARIO,
        blocked_cpu,
        completer_cpu,
        resumed_cpu,
        grant_rights,
        handle_idx
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(any(
    feature = "neo-test-smp-cross-cpu-migration-reap",
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation",
    feature = "neo-test-ipc-try-send"
))]
#[derive(Clone)]
struct SmpRendezvousFixture {
    channel: alloc::sync::Arc<crate::ipc::Channel>,
    sender_pmap: alloc::sync::Arc<crate::mm::pmap::Pmap>,
    receiver_pmap: alloc::sync::Arc<crate::mm::pmap::Pmap>,
    sender_phys: u64,
    receiver_phys: u64,
    send_va: u64,
    recv_va: u64,
    len: usize,
}

#[cfg(any(
    feature = "neo-test-smp-cross-cpu-migration-reap",
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation",
    feature = "neo-test-ipc-try-send"
))]
const SMP_RENDEZVOUS_PAYLOAD_LEN: usize = 8;

#[cfg(any(
    feature = "neo-test-smp-cross-cpu-migration-reap",
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation",
    feature = "neo-test-ipc-try-send"
))]
fn make_rendezvous_payload(seq: u32, pair: usize) -> [u8; SMP_RENDEZVOUS_PAYLOAD_LEN] {
    [
        b'S',
        b'C',
        b'3',
        b'B',
        pair as u8,
        (seq & 0xff) as u8,
        ((seq >> 8) & 0xff) as u8,
        ((seq >> 16) & 0xff) as u8,
    ]
}

#[cfg(any(
    feature = "neo-test-smp-cross-cpu-migration-reap",
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation",
    feature = "neo-test-ipc-try-send"
))]
fn create_rendezvous_fixture() -> SmpRendezvousFixture {
    use x86_64::structures::paging::FrameAllocator;

    const SEND_VA: u64 = 0x0000_0000_0090_0000;
    const RECV_VA: u64 = 0x0000_0000_00a0_0000;

    let sender_pmap = alloc::sync::Arc::new(
        crate::mm::pmap::Pmap::new().unwrap_or_else(|_| fail("reason=sender_pmap_new_failed")),
    );
    let receiver_pmap = alloc::sync::Arc::new(
        crate::mm::pmap::Pmap::new().unwrap_or_else(|_| fail("reason=receiver_pmap_new_failed")),
    );
    let sender_frame = crate::mm::with_frame_alloc(|fa| fa.allocate_frame())
        .unwrap_or_else(|| fail("reason=sender_frame_alloc_failed"));
    let receiver_frame = crate::mm::with_frame_alloc(|fa| fa.allocate_frame())
        .unwrap_or_else(|| fail("reason=receiver_frame_alloc_failed"));

    sender_pmap
        .map_user(
            x86_64::VirtAddr::new(SEND_VA),
            sender_frame,
            crate::mm::pmap::flags::USER_DATA_RW,
        )
        .unwrap_or_else(|_| fail("reason=sender_map_user_failed"));
    receiver_pmap
        .map_user(
            x86_64::VirtAddr::new(RECV_VA),
            receiver_frame,
            crate::mm::pmap::flags::USER_DATA_RW,
        )
        .unwrap_or_else(|_| fail("reason=receiver_map_user_failed"));

    let fixture = SmpRendezvousFixture {
        channel: crate::ipc::Channel::new(),
        sender_pmap,
        receiver_pmap,
        sender_phys: sender_frame.start_address().as_u64(),
        receiver_phys: receiver_frame.start_address().as_u64(),
        send_va: SEND_VA,
        recv_va: RECV_VA,
        len: SMP_RENDEZVOUS_PAYLOAD_LEN,
    };
    clear_rendezvous_receiver(&fixture);
    fixture
}

#[cfg(any(
    feature = "neo-test-smp-cross-cpu-migration-reap",
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation",
    feature = "neo-test-ipc-try-send"
))]
fn write_rendezvous_payload(fixture: &SmpRendezvousFixture, seq: u32, pair: usize) {
    let payload = make_rendezvous_payload(seq, pair);
    let base =
        crate::mm::phys_to_virt(x86_64::PhysAddr::new(fixture.sender_phys)).as_mut_ptr::<u8>();
    unsafe {
        for (idx, byte) in payload.iter().enumerate() {
            core::ptr::write_volatile(base.add(idx), *byte);
        }
    }
}

#[cfg(any(
    feature = "neo-test-smp-cross-cpu-migration-reap",
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation",
    feature = "neo-test-ipc-try-send"
))]
fn clear_rendezvous_receiver(fixture: &SmpRendezvousFixture) {
    let base =
        crate::mm::phys_to_virt(x86_64::PhysAddr::new(fixture.receiver_phys)).as_mut_ptr::<u8>();
    unsafe {
        core::ptr::write_bytes(base, 0, fixture.len);
    }
}

#[cfg(any(
    feature = "neo-test-smp-cross-cpu-migration-reap",
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation",
    feature = "neo-test-ipc-try-send"
))]
fn verify_rendezvous_payload(fixture: &SmpRendezvousFixture, seq: u32, pair: usize) {
    let expected = make_rendezvous_payload(seq, pair);
    let base = crate::mm::phys_to_virt(x86_64::PhysAddr::new(fixture.receiver_phys)).as_ptr::<u8>();
    unsafe {
        for (idx, byte) in expected.iter().enumerate() {
            let actual = core::ptr::read_volatile(base.add(idx));
            if actual != *byte {
                fail_with_hex("reason=payload_mismatch index", idx as u64);
            }
        }
    }
}

#[cfg(any(
    feature = "neo-test-smp-cross-cpu-migration-reap",
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-concurrent-reap-after-terminate",
    feature = "neo-test-ot31-exit-reap-race",
    feature = "neo-test-smp-c11-migration-reservation"
))]
fn detect_ready_smp_cpus(max_cpus: usize) -> usize {
    for _ in 0..100_000 {
        let count = (0..max_cpus)
            .filter(|cpu| crate::sched::scheduler::cpu_scheduler_ready(*cpu as u32))
            .count();
        if count == max_cpus {
            return count;
        }
        if count >= 2 {
            // Give later APs a short settle window, then accept the detected
            // topology. This lets the same scenario run at NEO_SMP=2 and 4.
            for _ in 0..10_000 {
                crate::sched::yield_now();
                crate::sched::reap();
            }
            return (0..max_cpus)
                .filter(|cpu| crate::sched::scheduler::cpu_scheduler_ready(*cpu as u32))
                .count();
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    fail("reason=insufficient_smp_cpus_ready");
}

#[cfg(feature = "neo-test-smp-cross-cpu-migration-reap")]
static SMP_MIGRATION_FIXTURE: crate::sync::SwitchMutex<Option<SmpRendezvousFixture>> =
    crate::sync::SwitchMutex::new(None);
#[cfg(feature = "neo-test-smp-cross-cpu-migration-reap")]
static SMP_MIGRATION_BLOCKED_CPU: core::sync::atomic::AtomicU32 =
    core::sync::atomic::AtomicU32::new(u32::MAX);
#[cfg(feature = "neo-test-smp-cross-cpu-migration-reap")]
static SMP_MIGRATION_RESUMED_CPU: core::sync::atomic::AtomicU32 =
    core::sync::atomic::AtomicU32::new(u32::MAX);
#[cfg(feature = "neo-test-smp-cross-cpu-migration-reap")]
static SMP_MIGRATION_COMPLETER_DONE: core::sync::atomic::AtomicU32 =
    core::sync::atomic::AtomicU32::new(0);
#[cfg(feature = "neo-test-smp-cross-cpu-migration-reap")]
static SMP_MIGRATION_WORKER_EXITING: core::sync::atomic::AtomicU32 =
    core::sync::atomic::AtomicU32::new(0);

#[cfg(feature = "neo-test-smp-cross-cpu-migration-reap")]
fn reset_smp_migration_state() {
    {
        let mut fixture = SMP_MIGRATION_FIXTURE.lock();
        *fixture = None;
    }
    SMP_MIGRATION_BLOCKED_CPU.store(u32::MAX, Ordering::Release);
    SMP_MIGRATION_RESUMED_CPU.store(u32::MAX, Ordering::Release);
    SMP_MIGRATION_COMPLETER_DONE.store(0, Ordering::Release);
    SMP_MIGRATION_WORKER_EXITING.store(0, Ordering::Release);
}

#[cfg(feature = "neo-test-smp-cross-cpu-migration-reap")]
fn smp_migration_fixture() -> SmpRendezvousFixture {
    let fixture = SMP_MIGRATION_FIXTURE.lock();
    match fixture.as_ref() {
        Some(fixture) => fixture.clone(),
        None => fail("reason=fixture_missing"),
    }
}

#[cfg(feature = "neo-test-smp-cross-cpu-migration-reap")]
extern "C" fn smp_migration_worker() -> ! {
    let fixture = smp_migration_fixture();
    write_rendezvous_payload(&fixture, 1, 0);
    let ret = crate::arch::x86_64::without_interrupts(|| {
        SMP_MIGRATION_BLOCKED_CPU.store(
            crate::arch::x86_64::per_cpu::current_cpu_id(),
            Ordering::Release,
        );
        fixture.channel.send(
            crate::ipc::EndpointSide::A,
            fixture.send_va,
            fixture.len,
            fixture.sender_pmap.clone(),
        )
    });
    if ret != fixture.len as i64 {
        fail_with_hex("reason=send_return_mismatch ret", ret as u64);
    }
    SMP_MIGRATION_RESUMED_CPU.store(
        crate::arch::x86_64::per_cpu::current_cpu_id(),
        Ordering::Release,
    );
    SMP_MIGRATION_WORKER_EXITING.store(1, Ordering::Release);
    crate::sched::exit();
}

#[cfg(feature = "neo-test-smp-cross-cpu-migration-reap")]
extern "C" fn smp_migration_completer() -> ! {
    let fixture = smp_migration_fixture();
    let ret = crate::arch::x86_64::without_interrupts(|| {
        fixture.channel.recv(
            crate::ipc::EndpointSide::B,
            fixture.recv_va,
            fixture.len,
            fixture.receiver_pmap.clone(),
        )
    });
    if ret != fixture.len as i64 {
        fail_with_hex("reason=recv_return_mismatch ret", ret as u64);
    }
    verify_rendezvous_payload(&fixture, 1, 0);
    SMP_MIGRATION_COMPLETER_DONE.store(1, Ordering::Release);
    crate::sched::exit();
}

#[cfg(feature = "neo-test-smp-cross-cpu-migration-reap")]
fn wait_for_migration_send_blocked(fixture: &SmpRendezvousFixture) {
    for _ in 0..100_000 {
        if fixture
            .channel
            .debug_endpoint_is_send_blocked(crate::ipc::EndpointSide::A)
        {
            return;
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    fail("reason=worker_did_not_block");
}

#[cfg(feature = "neo-test-smp-cross-cpu-migration-reap")]
fn wait_for_migration_exit_and_reap() {
    for _ in 0..1_000_000 {
        if SMP_MIGRATION_WORKER_EXITING.load(Ordering::Acquire) == 1
            && SMP_MIGRATION_COMPLETER_DONE.load(Ordering::Acquire) == 1
            && crate::sched::scheduler::debug_total_zombies() >= 2
        {
            break;
        }
        crate::sched::yield_now();
    }
    let observed_zombies = crate::sched::scheduler::debug_total_zombies();
    if observed_zombies < 2 {
        fail_with_hex(
            "reason=zombies_not_observed zombies",
            observed_zombies as u64,
        );
    }
    for _ in 0..100_000 {
        crate::sched::reap();
        if crate::sched::scheduler::debug_total_zombies() == 0 {
            return;
        }
        crate::sched::yield_now();
    }
    fail("reason=zombies_not_reaped");
}

#[cfg(feature = "neo-test-smp-cross-cpu-migration-reap")]
fn run_smp_cross_cpu_migration_reap() -> ! {
    if crate::arch::x86_64::per_cpu::current_cpu_id() != 0 {
        fail("reason=test_not_on_bsp");
    }
    let cpus = detect_ready_smp_cpus(4);
    if cpus < 2 {
        fail_with_hex("reason=insufficient_smp_cpus cpus", cpus as u64);
    }
    reset_smp_migration_state();
    {
        let mut fixture = SMP_MIGRATION_FIXTURE.lock();
        *fixture = Some(create_rendezvous_fixture());
    }
    let fixture = smp_migration_fixture();

    let worker = crate::sched::thread::Thread::new("smp-migration-worker", smp_migration_worker);
    if crate::sched::scheduler::place_thread_on_cpu(worker, 0).is_err() {
        fail("reason=place_worker_failed");
    }
    wait_for_migration_send_blocked(&fixture);

    let completer =
        crate::sched::thread::Thread::new("smp-migration-completer", smp_migration_completer);
    if crate::sched::scheduler::place_thread_on_cpu(completer, 1).is_err() {
        fail("reason=place_completer_failed");
    }

    wait_for_migration_exit_and_reap();
    let blocked_cpu = SMP_MIGRATION_BLOCKED_CPU.load(Ordering::Acquire);
    let resumed_cpu = SMP_MIGRATION_RESUMED_CPU.load(Ordering::Acquire);
    if blocked_cpu != 0 {
        fail_with_hex("reason=wrong_blocked_cpu blocked_cpu", blocked_cpu as u64);
    }
    if resumed_cpu != 1 {
        fail_with_hex("reason=wrong_resumed_cpu resumed_cpu", resumed_cpu as u64);
    }

    serial_println!(
        "NEO_TEST/1 event=PASS name={} blocked_cpu={} resumed_cpu={} exit_reaped=ok",
        SCENARIO,
        blocked_cpu,
        resumed_cpu
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(any(
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation"
))]
const STRESS_MAX_PAIRS: usize = 4;
#[cfg(any(
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation"
))]
const STRESS_ITERATIONS: u32 = 1000;

#[cfg(any(
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation"
))]
static STRESS_FIXTURES: crate::sync::SwitchMutex<[Option<SmpRendezvousFixture>; STRESS_MAX_PAIRS]> =
    crate::sync::SwitchMutex::new([const { None }; STRESS_MAX_PAIRS]);
#[cfg(any(
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation"
))]
static STRESS_PAIR_COUNT: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);
#[cfg(any(
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation"
))]
static STRESS_SENDER_GO: [core::sync::atomic::AtomicU32; STRESS_MAX_PAIRS] =
    [const { core::sync::atomic::AtomicU32::new(0) }; STRESS_MAX_PAIRS];
#[cfg(any(
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation"
))]
static STRESS_RECEIVER_GO: [core::sync::atomic::AtomicU32; STRESS_MAX_PAIRS] =
    [const { core::sync::atomic::AtomicU32::new(0) }; STRESS_MAX_PAIRS];
#[cfg(any(
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation"
))]
static STRESS_SENDER_DONE: [core::sync::atomic::AtomicU32; STRESS_MAX_PAIRS] =
    [const { core::sync::atomic::AtomicU32::new(0) }; STRESS_MAX_PAIRS];
#[cfg(any(
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation"
))]
static STRESS_RECEIVER_DONE: [core::sync::atomic::AtomicU32; STRESS_MAX_PAIRS] =
    [const { core::sync::atomic::AtomicU32::new(0) }; STRESS_MAX_PAIRS];
#[cfg(any(
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation"
))]
static STRESS_WORKERS_EXITED: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);

#[cfg(any(
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation"
))]
fn reset_stress_state() {
    {
        let mut fixtures = STRESS_FIXTURES.lock();
        for slot in fixtures.iter_mut() {
            *slot = None;
        }
    }
    STRESS_PAIR_COUNT.store(0, Ordering::Release);
    STRESS_WORKERS_EXITED.store(0, Ordering::Release);
    for idx in 0..STRESS_MAX_PAIRS {
        STRESS_SENDER_GO[idx].store(0, Ordering::Release);
        STRESS_RECEIVER_GO[idx].store(0, Ordering::Release);
        STRESS_SENDER_DONE[idx].store(0, Ordering::Release);
        STRESS_RECEIVER_DONE[idx].store(0, Ordering::Release);
    }
}

#[cfg(any(
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation"
))]
fn stress_fixture(pair: usize) -> SmpRendezvousFixture {
    let fixtures = STRESS_FIXTURES.lock();
    match fixtures.get(pair).and_then(|slot| slot.as_ref()) {
        Some(fixture) => fixture.clone(),
        None => fail_with_hex("reason=stress_fixture_missing pair", pair as u64),
    }
}

#[cfg(any(
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation"
))]
fn wait_for_stress_go(slot: &core::sync::atomic::AtomicU32, seq: u32) {
    while slot.load(Ordering::Acquire) < seq {
        crate::sched::yield_now();
    }
}

#[cfg(any(
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation"
))]
fn stress_sender(pair: usize) -> ! {
    let fixture = stress_fixture(pair);
    let pairs = STRESS_PAIR_COUNT.load(Ordering::Acquire);
    let mut seq = pair as u32 + 1;
    while seq <= STRESS_ITERATIONS {
        wait_for_stress_go(&STRESS_SENDER_GO[pair], seq);
        write_rendezvous_payload(&fixture, seq, pair);
        let ret = crate::arch::x86_64::without_interrupts(|| {
            fixture.channel.send(
                crate::ipc::EndpointSide::A,
                fixture.send_va,
                fixture.len,
                fixture.sender_pmap.clone(),
            )
        });
        if ret != fixture.len as i64 {
            fail_with_hex("reason=stress_send_return_mismatch ret", ret as u64);
        }
        STRESS_SENDER_DONE[pair].store(seq, Ordering::Release);
        seq += pairs;
    }
    STRESS_WORKERS_EXITED.fetch_add(1, Ordering::Release);
    crate::sched::exit();
}

#[cfg(any(
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation"
))]
fn stress_receiver(pair: usize) -> ! {
    let fixture = stress_fixture(pair);
    let pairs = STRESS_PAIR_COUNT.load(Ordering::Acquire);
    let mut seq = pair as u32 + 1;
    while seq <= STRESS_ITERATIONS {
        wait_for_stress_go(&STRESS_RECEIVER_GO[pair], seq);
        let ret = crate::arch::x86_64::without_interrupts(|| {
            fixture.channel.recv(
                crate::ipc::EndpointSide::B,
                fixture.recv_va,
                fixture.len,
                fixture.receiver_pmap.clone(),
            )
        });
        if ret != fixture.len as i64 {
            fail_with_hex("reason=stress_recv_return_mismatch ret", ret as u64);
        }
        verify_rendezvous_payload(&fixture, seq, pair);
        STRESS_RECEIVER_DONE[pair].store(seq, Ordering::Release);
        seq += pairs;
    }
    STRESS_WORKERS_EXITED.fetch_add(1, Ordering::Release);
    crate::sched::exit();
}

#[cfg(any(
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation"
))]
macro_rules! stress_entries {
    ($(($sender:ident, $receiver:ident, $pair:expr)),+ $(,)?) => {
        $(
            extern "C" fn $sender() -> ! {
                stress_sender($pair)
            }

            extern "C" fn $receiver() -> ! {
                stress_receiver($pair)
            }
        )+
    };
}

#[cfg(any(
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation"
))]
stress_entries!(
    (stress_sender_0, stress_receiver_0, 0),
    (stress_sender_1, stress_receiver_1, 1),
    (stress_sender_2, stress_receiver_2, 2),
    (stress_sender_3, stress_receiver_3, 3),
);

#[cfg(any(
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation"
))]
const STRESS_SENDERS: [extern "C" fn() -> !; STRESS_MAX_PAIRS] = [
    stress_sender_0,
    stress_sender_1,
    stress_sender_2,
    stress_sender_3,
];
#[cfg(any(
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation"
))]
const STRESS_RECEIVERS: [extern "C" fn() -> !; STRESS_MAX_PAIRS] = [
    stress_receiver_0,
    stress_receiver_1,
    stress_receiver_2,
    stress_receiver_3,
];

#[cfg(any(
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation"
))]
fn wait_for_stress_endpoint_blocked(pair: usize, send_first: bool) {
    let fixture = stress_fixture(pair);
    for _ in 0..100_000 {
        let blocked = if send_first {
            fixture
                .channel
                .debug_endpoint_is_send_blocked(crate::ipc::EndpointSide::A)
        } else {
            fixture
                .channel
                .debug_endpoint_is_recv_blocked(crate::ipc::EndpointSide::B)
        };
        if blocked {
            return;
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    fail_with_hex("reason=stress_endpoint_did_not_block pair", pair as u64);
}

#[cfg(any(
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation"
))]
fn wait_for_stress_iteration_done(pair: usize, seq: u32) {
    for _ in 0..100_000 {
        if STRESS_SENDER_DONE[pair].load(Ordering::Acquire) >= seq
            && STRESS_RECEIVER_DONE[pair].load(Ordering::Acquire) >= seq
        {
            return;
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    fail_with_hex("reason=stress_iteration_timeout seq", seq as u64);
}

#[cfg(any(
    feature = "neo-test-smp-cross-cpu-rendezvous-stress",
    feature = "neo-test-smp-c11-migration-reservation"
))]
fn wait_for_stress_workers_exit(expected: u32) {
    for _ in 0..1_000_000 {
        if STRESS_WORKERS_EXITED.load(Ordering::Acquire) == expected {
            crate::sched::reap();
            return;
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    fail_with_hex(
        "reason=stress_workers_exit_timeout exited",
        STRESS_WORKERS_EXITED.load(Ordering::Acquire) as u64,
    );
}

#[cfg(feature = "neo-test-smp-cross-cpu-rendezvous-stress")]
fn run_smp_cross_cpu_rendezvous_stress() -> ! {
    if crate::arch::x86_64::per_cpu::current_cpu_id() != 0 {
        fail("reason=test_not_on_bsp");
    }
    reset_stress_state();
    let pairs = detect_ready_smp_cpus(STRESS_MAX_PAIRS);
    if pairs < 2 {
        fail_with_hex("reason=insufficient_smp_cpus cpus", pairs as u64);
    }
    STRESS_PAIR_COUNT.store(pairs as u32, Ordering::Release);
    {
        let mut fixtures = STRESS_FIXTURES.lock();
        for pair in 0..pairs {
            fixtures[pair] = Some(create_rendezvous_fixture());
        }
    }

    for pair in 0..pairs {
        let sender_cpu = pair as u32;
        let receiver_cpu = ((pair + 1) % pairs) as u32;
        let sender = crate::sched::thread::Thread::new("stress-sender", STRESS_SENDERS[pair]);
        if crate::sched::scheduler::place_thread_on_cpu(sender, sender_cpu).is_err() {
            fail_with_hex("reason=place_stress_sender_failed pair", pair as u64);
        }
        let receiver = crate::sched::thread::Thread::new("stress-receiver", STRESS_RECEIVERS[pair]);
        if crate::sched::scheduler::place_thread_on_cpu(receiver, receiver_cpu).is_err() {
            fail_with_hex("reason=place_stress_receiver_failed pair", pair as u64);
        }
    }

    let mut send_first_count = 0u32;
    let mut recv_first_count = 0u32;
    for seq in 1..=STRESS_ITERATIONS {
        let pair = ((seq - 1) as usize) % pairs;
        let fixture = stress_fixture(pair);
        clear_rendezvous_receiver(&fixture);
        let send_first = (seq & 1) == 1;
        if send_first {
            send_first_count += 1;
            STRESS_SENDER_GO[pair].store(seq, Ordering::Release);
            wait_for_stress_endpoint_blocked(pair, true);
            STRESS_RECEIVER_GO[pair].store(seq, Ordering::Release);
        } else {
            recv_first_count += 1;
            STRESS_RECEIVER_GO[pair].store(seq, Ordering::Release);
            wait_for_stress_endpoint_blocked(pair, false);
            STRESS_SENDER_GO[pair].store(seq, Ordering::Release);
        }
        wait_for_stress_iteration_done(pair, seq);
    }
    wait_for_stress_workers_exit((pairs * 2) as u32);

    serial_println!(
        "NEO_TEST/1 event=PASS name={} iterations={} send_first={} recv_first={} cpus={}",
        SCENARIO,
        STRESS_ITERATIONS,
        send_first_count,
        recv_first_count,
        pairs
    );
    debug_exit(EXIT_SUCCESS);
}

// ── OT-61 C1.1 (cross-model AAG finding 1): cross-CPU migration reservation ──
// The IPC rendezvous handoff enqueues a parked peer on the COMPLETER's CPU, so
// same-process threads genuinely migrate. Before the fix that migration moved a
// thread onto CPU B without transferring its ready-ring reservation from CPU A:
// A kept a phantom reservation forever and B gained a ready thread it never
// reserved, so `ready.len() <= live_count` — the invariant blocker A's no-panic
// guarantee rests on — silently went false, and the "impossible" full-ring wake
// panic became reachable again.
//
// The pre-existing SMP batteries DROVE this migration but never asserted the
// invariant, which is exactly why a green SMP-4 gate coexisted with a real bug.
// This scenario reuses that same proven rendezvous machinery and adds the
// missing assertion, checked after every iteration so drift is caught at the
// iteration that causes it rather than at the end.
#[cfg(feature = "neo-test-smp-c11-migration-reservation")]
fn run_smp_c11_migration_reservation() -> ! {
    if crate::arch::x86_64::per_cpu::current_cpu_id() != 0 {
        fail("reason=test_not_on_bsp");
    }
    reset_stress_state();
    let pairs = detect_ready_smp_cpus(STRESS_MAX_PAIRS);
    if pairs < 2 {
        // Non-vacuity: this scenario is meaningless on one CPU (src == dst, so
        // no migration occurs). Fail loudly rather than pass trivially.
        fail_with_hex(
            "reason=insufficient_smp_cpus_migration_vacuous cpus",
            pairs as u64,
        );
    }
    STRESS_PAIR_COUNT.store(pairs as u32, Ordering::Release);
    {
        let mut fixtures = STRESS_FIXTURES.lock();
        for pair in 0..pairs {
            fixtures[pair] = Some(create_rendezvous_fixture());
        }
    }

    // Baseline: the invariant must hold before any migration.
    let (ok, cpu, ready_len, live) = crate::sched::scheduler::debug_live_count_invariant();
    if !ok {
        serial_println!(
            "NEO_TEST/1 event=FAIL name={} reason=invariant_violated_at_baseline cpu={} ready={} live={}",
            SCENARIO,
            cpu,
            ready_len,
            live
        );
        debug_exit(EXIT_FAILURE);
    }

    // Place each sender/receiver pair on DIFFERENT CPUs so every completed
    // rendezvous is a genuine cross-CPU migration through wake_thread_front.
    for pair in 0..pairs {
        let sender_cpu = pair as u32;
        let receiver_cpu = ((pair + 1) % pairs) as u32;
        let sender = crate::sched::thread::Thread::new("mig-sender", STRESS_SENDERS[pair]);
        if crate::sched::scheduler::place_thread_on_cpu(sender, sender_cpu).is_err() {
            fail_with_hex("reason=place_sender_failed pair", pair as u64);
        }
        let receiver = crate::sched::thread::Thread::new("mig-receiver", STRESS_RECEIVERS[pair]);
        if crate::sched::scheduler::place_thread_on_cpu(receiver, receiver_cpu).is_err() {
            fail_with_hex("reason=place_receiver_failed pair", pair as u64);
        }
    }

    let mut migrations = 0u32;
    for seq in 1..=STRESS_ITERATIONS {
        let pair = ((seq - 1) as usize) % pairs;
        let fixture = stress_fixture(pair);
        clear_rendezvous_receiver(&fixture);
        let send_first = (seq & 1) == 1;
        if send_first {
            STRESS_SENDER_GO[pair].store(seq, Ordering::Release);
            wait_for_stress_endpoint_blocked(pair, true);
            STRESS_RECEIVER_GO[pair].store(seq, Ordering::Release);
        } else {
            STRESS_RECEIVER_GO[pair].store(seq, Ordering::Release);
            wait_for_stress_endpoint_blocked(pair, false);
            STRESS_SENDER_GO[pair].store(seq, Ordering::Release);
        }
        wait_for_stress_iteration_done(pair, seq);
        migrations += 1;

        // The assertion the old batteries were missing. Checked EVERY iteration
        // so a drift is attributed to the migration that caused it.
        let (ok, cpu, ready_len, live) = crate::sched::scheduler::debug_live_count_invariant();
        if !ok {
            serial_println!(
                "NEO_TEST/1 event=FAIL name={} reason=reservation_invariant_violated seq={} cpu={} ready={} live={}",
                SCENARIO,
                seq,
                cpu,
                ready_len,
                live
            );
            debug_exit(EXIT_FAILURE);
        }
    }

    // Drain to quiescence and re-assert: every reservation taken must have been
    // released, so no CPU may retain a phantom count after all work is reaped.
    for _ in 0..1_000_000 {
        crate::sched::reap();
        if crate::sched::scheduler::debug_total_zombies() == 0 {
            break;
        }
        crate::sched::yield_now();
    }
    let (ok, cpu, ready_len, live) = crate::sched::scheduler::debug_live_count_invariant();
    if !ok {
        serial_println!(
            "NEO_TEST/1 event=FAIL name={} reason=invariant_violated_after_drain cpu={} ready={} live={}",
            SCENARIO,
            cpu,
            ready_len,
            live
        );
        debug_exit(EXIT_FAILURE);
    }

    serial_println!(
        "NEO_TEST/1 event=PASS name={} cross_cpu_migrations={} pairs={} reservation_invariant=held_every_iteration",
        SCENARIO,
        migrations,
        pairs
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-pci-virtio-blk-probe-smoke")]
fn run_phase3_pci_virtio_blk_probe_smoke() -> ! {
    let probe = crate::drivers::block::virtio_blk::last_probe_snapshot();
    if !probe.seen {
        fail("reason=virtio_blk_not_enumerated");
    }
    if !probe.common_config {
        fail("reason=virtio_common_config_missing");
    }
    if !probe.notify_config {
        fail("reason=virtio_notify_config_missing");
    }
    if !probe.isr_config {
        fail("reason=virtio_isr_config_missing");
    }
    if !probe.device_config {
        fail("reason=virtio_device_config_missing");
    }
    if !probe.flush_offered {
        fail("reason=virtio_blk_F_FLUSH_not_offered");
    }
    if !probe.flush_negotiated {
        fail("reason=virtio_blk_F_FLUSH_not_negotiated");
    }
    if probe.config_wce_negotiated {
        fail("reason=virtio_blk_forbidden_feature_negotiated");
    }
    if !probe.queue_ready {
        fail("reason=virtio_blk_queue_not_ready");
    }

    serial_println!(
        "NEO_TEST/1 event=PASS name={} bdf=0x{:06x} offered_features=0x{:016x} driver_features=0x{:016x} F_FLUSH_offered={} F_FLUSH_negotiated=true F_CONFIG_WCE_negotiated=false attach=rw",
        SCENARIO,
        probe.last_bdf,
        probe.offered_features,
        probe.driver_features,
        probe.flush_offered
    );
    debug_exit(EXIT_SUCCESS);
}

