#[cfg(feature = "neo-test-phase3-virtio-blk-raw-rw-smoke")]
fn run_phase3_virtio_blk_raw_rw_smoke() -> ! {
    let (probe, device) = require_phase3_virtio_blk_ready();
    let geometry = device.geometry();
    let block_size = geometry.logical_block_size as usize;
    if block_size != 512 {
        fail_with_hex(
            "reason=virtio_blk_unexpected_logical_block_size size",
            block_size as u64,
        );
    }

    let write_buf = crate::drivers::block::DmaBuffer::alloc_zeroed(block_size)
        .unwrap_or_else(|_| fail("reason=virtio_blk_write_dma_alloc_failed"));
    unsafe {
        for (idx, byte) in write_buf.as_mut_slice().iter_mut().enumerate() {
            *byte = (idx as u8).wrapping_mul(13) ^ 0x5a;
        }
    }

    if let Err(err) = device.write_block(1, core::slice::from_ref(&write_buf)) {
        fail_block_error("virtio_blk_write_failed", err);
    }

    let read_buf = crate::drivers::block::DmaBuffer::alloc_zeroed(block_size)
        .unwrap_or_else(|_| fail("reason=virtio_blk_read_dma_alloc_failed"));
    if let Err(err) = device.read_block(1, core::slice::from_ref(&read_buf)) {
        fail_block_error("virtio_blk_read_failed", err);
    }

    let (write_slice, read_slice) = unsafe { (write_buf.as_slice(), read_buf.as_slice()) };
    if write_slice != read_slice {
        fail("reason=virtio_blk_raw_rw_mismatch");
    }

    let desc_barriers = crate::drivers::block::virtio_blk::debug_descriptor_publish_barriers();
    let notify_barriers =
        crate::drivers::block::virtio_blk::debug_notification_suppression_barriers();
    if desc_barriers < 2 {
        fail_with_hex(
            "reason=virtio_blk_descriptor_barrier_missing count",
            desc_barriers,
        );
    }
    if notify_barriers < 2 {
        fail_with_hex(
            "reason=virtio_blk_notification_barrier_missing count",
            notify_barriers,
        );
    }

    serial_println!(
        "NEO_TEST/1 event=PASS name={} bdf=0x{:06x} block_size={} lba=1 completions={} descriptor_publish_barriers={} notification_suppression_barriers={} F_FLUSH_offered={} F_FLUSH_negotiated=true F_CONFIG_WCE_negotiated=false",
        SCENARIO,
        probe.last_bdf,
        block_size,
        crate::drivers::block::virtio_blk::debug_completion_count(),
        desc_barriers,
        notify_barriers,
        probe.flush_offered
    );
    debug_exit(EXIT_SUCCESS);
}

