#[cfg(any(
    feature = "neo-test-phase3-neofs-write-readback-same-boot",
    feature = "neo-test-phase3-neofs-cache-evict",
    feature = "neo-test-phase3-neofs-cache-evict-off",
    feature = "neo-test-phase3-neofs-allocator-reuse-guard"
))]
fn neofs_2c_fill_pattern(seed: u8, block_index: usize, buf: &mut [u8]) {
    for (idx, byte) in buf.iter_mut().enumerate() {
        *byte = seed
            .wrapping_add((block_index as u8).wrapping_mul(29))
            .wrapping_add((idx as u8).wrapping_mul(3))
            ^ 0x5a;
    }
}

#[cfg(any(
    feature = "neo-test-phase3-neofs-write-readback-same-boot",
    feature = "neo-test-phase3-neofs-cache-evict",
    feature = "neo-test-phase3-neofs-cache-evict-off",
    feature = "neo-test-phase3-neofs-allocator-reuse-guard"
))]
fn neofs_2c_write_pattern_file(path: &str, blocks: usize, seed: u8) {
    let file = neofs_2c_create_or_fail(path);
    let mut block = [0u8; NEOFS_2C_DIRECT_BLOCK_BYTES];
    for block_index in 0..blocks {
        neofs_2c_fill_pattern(seed, block_index, &mut block);
        neofs_2c_write_all_or_fail(&file, &block);
    }
}

#[cfg(any(
    feature = "neo-test-phase3-neofs-write-readback-same-boot",
    feature = "neo-test-phase3-neofs-cache-evict",
    feature = "neo-test-phase3-neofs-cache-evict-off",
    feature = "neo-test-phase3-neofs-allocator-reuse-guard"
))]
fn neofs_2c_verify_pattern_file(path: &str, blocks: usize, seed: u8) {
    let file = neofs_2c_open_read_or_fail(path);
    let mut got = [0u8; NEOFS_2C_DIRECT_BLOCK_BYTES];
    let mut expected = [0u8; NEOFS_2C_DIRECT_BLOCK_BYTES];
    for block_index in 0..blocks {
        let n = match file.read(&mut got) {
            Ok(n) => n,
            Err(err) => neofs_2c_fail_vfs("neofs_pattern_read_failed", err),
        };
        if n != got.len() {
            neofs_2c_fail_count("neofs_pattern_read_wrong_len", n, got.len());
        }
        neofs_2c_fill_pattern(seed, block_index, &mut expected);
        if got != expected {
            fail("reason=neofs_pattern_content_mismatch");
        }
    }
    let mut eof = [0u8; 1];
    let n = match file.read(&mut eof) {
        Ok(n) => n,
        Err(err) => neofs_2c_fail_vfs("neofs_pattern_eof_read_failed", err),
    };
    if n != 0 {
        neofs_2c_fail_count("neofs_pattern_eof_not_zero", n, 0);
    }
}

#[cfg(feature = "neo-test-phase3-neofs-create-small-file")]
fn run_phase3_neofs_create_small_file() -> ! {
    const PATH: &str = "/neofs/create-2c.txt";
    const CONTENT: &[u8] = b"NeoFS BUILD-2 2C create/write/readback.\n";

    let report = mount_neofs_rw_or_fail();
    let file = neofs_2c_create_or_fail(PATH);
    neofs_2c_write_all_or_fail(&file, CONTENT);
    drop(file);
    neofs_2c_read_literal_or_fail(PATH, CONTENT);
    serial_println!(
        "NEO_TEST/1 event=PASS name={} neofs_create=ok create_flag=OPEN_CREATE_REGULAR path={} bytes={} close_reopen_read=ok selected_superblock={} generation={} no_directory_create=true no_model_create=true",
        SCENARIO,
        PATH,
        CONTENT.len(),
        report.selected_superblock_slot,
        report.generation
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-write-readback-same-boot")]
fn run_phase3_neofs_write_readback_same_boot() -> ! {
    const PATH: &str = "/neofs/direct8.bin";
    const DIRECT_BLOCKS: usize = 8;

    let report = mount_neofs_rw_or_fail();
    neofs_2c_write_pattern_file(PATH, DIRECT_BLOCKS, 0x2c);
    neofs_2c_verify_pattern_file(PATH, DIRECT_BLOCKS, 0x2c);
    serial_println!(
        "NEO_TEST/1 event=PASS name={} neofs_write_readback=ok path={} bytes={} direct_blocks={} close_reopen_read=ok selected_superblock={} generation={} runtime_mutation=true",
        SCENARIO,
        PATH,
        DIRECT_BLOCKS * NEOFS_2C_DIRECT_BLOCK_BYTES,
        DIRECT_BLOCKS,
        report.selected_superblock_slot,
        report.generation
    );
    debug_exit(EXIT_SUCCESS);
}

/// OT-92: write and read back more blocks than the NeoFS cache holds, then
/// write with the writeback worker held so only the throttle drains, and
/// read so the held dirty blocks become the least recently used. On
/// (`neofs-cache-evict`): the cache evicts and ends within its capacity,
/// every byte reads back (misses re-read evicted blocks from the device),
/// and the held writes stay under the dirty throttle plus one file's
/// transactions. Off (`-off`, the previous layer): nothing is evicted, the
/// cache ends over the capacity, and the held writes pile up dirty: the
/// growth OT-92 names.
#[cfg(any(
    feature = "neo-test-phase3-neofs-cache-evict",
    feature = "neo-test-phase3-neofs-cache-evict-off"
))]
fn run_neofs_cache_evict() -> ! {
    use alloc::format;
    // On: 40 files of 8 blocks, more live blocks than the capacity. Off: 6
    // files already grow the cache past it; with no eviction, many more
    // would exhaust the 4 MiB heap, which is OT-92 itself.
    const FILES: usize = if cfg!(feature = "neo-test-phase3-neofs-cache-evict") {
        40
    } else {
        6
    };
    const HELD_FILES: usize = 4;
    const BLOCKS_PER_FILE: usize = 8;
    const CAPACITY: u64 = 256;
    const DIRTY_THROTTLE: u64 = 128;
    // One file's writes: 8 copy-on-write commits of up to 8 data blocks plus
    // their inode, directory, free-map and superblock blocks.
    const ONE_FILE_DIRTY: u64 = 8 * (8 + 4);

    let report = mount_neofs_rw_or_fail();
    let evict_on = cfg!(feature = "neo-test-phase3-neofs-cache-evict");
    for file in 0..FILES {
        neofs_2c_write_pattern_file(
            &format!("/neofs/evict-{file:02}.bin"),
            BLOCKS_PER_FILE,
            0x40 + file as u8,
        );
    }
    let after_write = neofs_3d_wait_clean_or_fail("reason=neofs_evict_cache_not_clean");
    // Twice: the first pass misses on blocks evicted during the writes, the
    // second on blocks the first pass evicted.
    for _ in 0..2 {
        for file in 0..FILES {
            neofs_2c_verify_pattern_file(
                &format!("/neofs/evict-{file:02}.bin"),
                BLOCKS_PER_FILE,
                0x40 + file as u8,
            );
        }
    }
    let after_read = neofs_3d_cache_stats_or_fail();

    // The held leg: the worker never drains, so dirty blocks leave only by
    // the throttle's drain at the start of a mutation.
    neofs_3d_set_writeback_hold_or_fail(true);
    let mut max_dirty = 0u64;
    let mut max_cached = 0u64;
    for file in 0..HELD_FILES {
        neofs_2c_write_pattern_file(
            &format!("/neofs/held-{file:02}.bin"),
            BLOCKS_PER_FILE,
            0x80 + file as u8,
        );
        let stats = neofs_3d_cache_stats_or_fail();
        max_dirty = max_dirty.max(stats.dirty_blocks);
        max_cached = max_cached.max(stats.cached_blocks);
    }
    // Still held: read the first leg's files, so the held files' dirty
    // blocks become the least recently used. Eviction must pass them over;
    // one that dropped a dirty block would lose that write.
    for file in 0..FILES {
        neofs_2c_verify_pattern_file(
            &format!("/neofs/evict-{file:02}.bin"),
            BLOCKS_PER_FILE,
            0x40 + file as u8,
        );
    }
    let stats = neofs_3d_cache_stats_or_fail();
    max_dirty = max_dirty.max(stats.dirty_blocks);
    max_cached = max_cached.max(stats.cached_blocks);
    neofs_3d_set_writeback_hold_or_fail(false);
    neofs_3d_wait_clean_or_fail("reason=neofs_evict_held_not_clean");
    for file in 0..HELD_FILES {
        neofs_2c_verify_pattern_file(
            &format!("/neofs/held-{file:02}.bin"),
            BLOCKS_PER_FILE,
            0x80 + file as u8,
        );
    }
    let end = neofs_3d_cache_stats_or_fail();

    // The kill-switch leg (Janus #250 item 4): drop every cached block the
    // way a large write's allocation does (all clean now). Off, that is the
    // previous layer's plain drop: no eviction counted, so a concurrent miss
    // would still be inserted. On, each one is an eviction.
    let before_forget = neofs_3d_wait_clean_or_fail("reason=neofs_evict_forget_not_clean");
    if crate::fs::debug_neofs_forget_range(0, u64::MAX).is_err() {
        fail("reason=neofs_evict_forget_range");
    }
    let after_forget = neofs_3d_cache_stats_or_fail();
    let forget_counted = after_forget.evictions - before_forget.evictions;
    serial_println!(
        "NEO_TEST/1 event=INFO name={} forget_range dropped={} counted_as_evictions={}",
        SCENARIO,
        before_forget.cached_blocks - after_forget.cached_blocks,
        forget_counted
    );
    if after_forget.cached_blocks != 0 || before_forget.cached_blocks == 0 {
        fail("reason=neofs_evict_forget_range_kept_blocks");
    }
    let want_counted = if evict_on {
        before_forget.cached_blocks
    } else {
        0
    };
    if forget_counted != want_counted {
        fail_with_hex(
            "reason=neofs_evict_forget_range_eviction_count",
            forget_counted,
        );
    }

    serial_println!(
        "NEO_TEST/1 event=INFO name={} evict={} files={} held_files={} after_write_cached={} after_read_cached={} held_max_dirty={} held_max_cached={} end_cached={} evictions={} hits={} misses={} capacity={} dirty_throttle={}",
        SCENARIO,
        evict_on as u8,
        FILES,
        HELD_FILES,
        after_write.cached_blocks,
        after_read.cached_blocks,
        max_dirty,
        max_cached,
        end.cached_blocks,
        end.evictions,
        end.hits,
        end.misses,
        CAPACITY,
        DIRTY_THROTTLE
    );
    if evict_on {
        if after_read.evictions == 0 {
            fail("reason=neofs_evict_never_evicted");
        }
        if after_read.cached_blocks > CAPACITY || end.cached_blocks > CAPACITY {
            fail_with_hex(
                "reason=neofs_evict_over_capacity cached_blocks",
                after_read.cached_blocks.max(end.cached_blocks),
            );
        }
        if max_dirty >= DIRTY_THROTTLE + ONE_FILE_DIRTY {
            fail_with_hex("reason=neofs_evict_dirty_unthrottled max_dirty", max_dirty);
        }
        // Eviction leaves max(capacity, dirty) blocks. Here no single
        // mutation dirties more than ONE_FILE_DIRTY, so dirty stays under
        // the capacity and the cache never passes it (one larger mutation
        // could: see `CACHE_CAPACITY_BLOCKS`).
        if max_cached > CAPACITY {
            fail_with_hex(
                "reason=neofs_evict_held_over_capacity max_cached",
                max_cached,
            );
        }
    } else {
        if end.evictions != 0 {
            fail("reason=neofs_evict_off_evicted");
        }
        if after_read.cached_blocks <= CAPACITY {
            fail("reason=neofs_evict_off_workload_too_small");
        }
        if max_dirty < DIRTY_THROTTLE + ONE_FILE_DIRTY {
            fail_with_hex("reason=neofs_evict_off_held_too_small max_dirty", max_dirty);
        }
    }
    serial_println!(
        "NEO_TEST/1 event=PASS name={} neofs_cache_evict=ok evict={} readback=ok held_readback=ok cached_blocks={} held_max_dirty={} evictions={} selected_superblock={} generation={}",
        SCENARIO,
        evict_on as u8,
        end.cached_blocks,
        max_dirty,
        end.evictions,
        report.selected_superblock_slot,
        report.generation
    );
    debug_exit(EXIT_SUCCESS);
}

/// L7.1: the kernel half of the boot-time numbers. The entry stamp was taken
/// before anything else ran; QEMU's firmware has no FPDT, so the firmware
/// part reports `no-fpdt` (the parse itself is host-tested on a hand-laid
/// table); the desktop stamp follows the entry stamp; the record the
/// syscall writes decodes to the snapshot; and `SYS_BOOT_TIMES` refuses a
/// wrong length or a kernel address.
#[cfg(feature = "neo-test-boot-time")]
fn run_boot_time() -> ! {
    use crate::boot_time_logic::{BOOT_TIMES_V1_LEN, FpdtError, decode, encode};
    let rsdp = crate::rsdp_phys();
    let firmware = crate::boot_time::read_firmware(rsdp);
    if firmware != Err(FpdtError::NoFpdt) {
        serial_println!(
            "NEO_TEST/1 event=FAIL name={} reason=boot_time_firmware_not_no_fpdt got={:?}",
            SCENARIO,
            firmware
        );
        debug_exit(EXIT_FAILURE);
    }
    crate::boot_time::stamp_desktop(rsdp);
    let times = crate::boot_time::snapshot();
    if times.tsc_kernel_entry == 0 {
        fail("reason=boot_time_no_entry_stamp");
    }
    if times.tsc_desktop_start <= times.tsc_kernel_entry {
        fail("reason=boot_time_desktop_not_after_entry");
    }
    if times.tsc_hz == 0 {
        fail("reason=boot_time_no_tsc_rate");
    }
    if decode(&encode(&times)) != Some(times) {
        fail("reason=boot_time_record_roundtrip");
    }
    let mut kernel_buf = [0u8; BOOT_TIMES_V1_LEN];
    let wrong_len = crate::arch::x86_64::syscall::debug_sys_boot_times_for_test(
        kernel_buf.as_mut_ptr() as u64,
        BOOT_TIMES_V1_LEN - 1,
    );
    let kernel_addr = crate::arch::x86_64::syscall::debug_sys_boot_times_for_test(
        kernel_buf.as_mut_ptr() as u64,
        BOOT_TIMES_V1_LEN,
    );
    if wrong_len != crate::errno::EINVAL || kernel_addr >= 0 || kernel_buf != [0; BOOT_TIMES_V1_LEN]
    {
        serial_println!(
            "NEO_TEST/1 event=FAIL name={} reason=boot_time_syscall_checks wrong_len={} kernel_addr={}",
            SCENARIO,
            wrong_len,
            kernel_addr
        );
        debug_exit(EXIT_FAILURE);
    }
    let copyout = boot_time_copyout_legs(&encode(&times));
    serial_println!(
        "NEO_TEST/1 event=PASS name={} boot_time=ok firmware=no-fpdt tsc_hz={} entry_tsc={} desktop_tsc={} syscall_wrong_len={} syscall_kernel_addr={} copyout={}",
        SCENARIO,
        times.tsc_hz,
        times.tsc_kernel_entry,
        times.tsc_desktop_start,
        wrong_len,
        kernel_addr,
        copyout
    );
    debug_exit(EXIT_SUCCESS);
}

/// Review #16 item 2: `SYS_BOOT_TIMES` writes through `Pmap::write_user_bytes`
/// (page-table walk under the pmap lock, HHDM write), so a bad user buffer is
/// an error with nothing written, never a ring-0 fault. A scratch address
/// space holds four pages: p0 and p1 writable, p2 unmapped, p3 read-only.
/// Legs: a record straddling p0/p1 lands intact; one straddling p1/p2 (40
/// bytes before the hole) is refused and leaves p1 untouched; p2 alone and
/// p3 alone are refused; a range ending past the user half is refused.
#[cfg(feature = "neo-test-boot-time")]
fn boot_time_copyout_legs(record: &[u8]) -> &'static str {
    use crate::mm::pmap::{Pmap, flags};
    use x86_64::VirtAddr;
    let pmap = Pmap::new().unwrap_or_else(|_| fail("reason=boot_time_pmap_new"));
    let base = pmap
        .allocate_user_region(4 * 4096, flags::USER_DATA_RW)
        .unwrap_or_else(|_| fail("reason=boot_time_region"));
    let (p1, p2, p3) = (base + 4096, base + 2 * 4096, base + 3 * 4096);
    if pmap.unmap_user_range(VirtAddr::new(p2), 4096).is_err()
        || pmap
            .protect_user(VirtAddr::new(p3), 4096, flags::USER_DATA_RO)
            .is_err()
    {
        fail("reason=boot_time_region_setup");
    }
    let read = |va: u64, out: &mut [u8]| {
        for (i, b) in out.iter_mut().enumerate() {
            let pa = pmap
                .translate(VirtAddr::new(va + i as u64))
                .unwrap_or_else(|| fail("reason=boot_time_readback_unmapped"));
            // SAFETY: a present frame of the scratch Pmap, read via the HHDM.
            *b = unsafe { *crate::mm::phys_to_virt(pa).as_ptr::<u8>() };
        }
    };
    let n = record.len() as u64;
    let straddle_ok = pmap.write_user_bytes(p1 - 40, record).is_ok();
    let mut back = [0u8; 80];
    read(p1 - 40, &mut back[..record.len()]);
    let landed = back[..record.len()] == *record;
    let hole = pmap.write_user_bytes(p2 - 40, record).is_err();
    let mut tail = [0u8; 40];
    read(p2 - 40, &mut tail);
    let untouched = tail == [0u8; 40];
    let unmapped = pmap.write_user_bytes(p2, record).is_err();
    let read_only = pmap.write_user_bytes(p3, record).is_err();
    let past_half = pmap
        .write_user_bytes(0x0000_8000_0000_0000 - n / 2, record)
        .is_err();
    if !(straddle_ok && landed && hole && untouched && unmapped && read_only && past_half) {
        serial_println!(
            "NEO_TEST/1 event=FAIL name={} reason=boot_time_copyout straddle_ok={} landed={} hole={} untouched={} unmapped={} read_only={} past_half={}",
            SCENARIO,
            straddle_ok,
            landed,
            hole,
            untouched,
            unmapped,
            read_only,
            past_half
        );
        debug_exit(EXIT_FAILURE);
    }
    "straddle+hole+unmapped+ro+past-half"
}

#[cfg(feature = "neo-test-phase3-neofs-allocator-reuse-guard")]
fn run_phase3_neofs_allocator_reuse_guard() -> ! {
    const PATH_A: &str = "/neofs/alloc-a.bin";
    const PATH_B: &str = "/neofs/alloc-b.bin";

    let report = mount_neofs_rw_or_fail();
    neofs_2c_write_pattern_file(PATH_A, 1, 0xa1);
    neofs_2c_write_pattern_file(PATH_B, 1, 0xb2);
    neofs_2c_verify_pattern_file(PATH_A, 1, 0xa1);
    neofs_2c_verify_pattern_file(PATH_B, 1, 0xb2);
    serial_println!(
        "NEO_TEST/1 event=PASS name={} neofs_allocator_reuse_guard=ok first_path={} second_path={} alias_check=distinct_content bump_allocator=true selected_superblock={} generation={}",
        SCENARIO,
        PATH_A,
        PATH_B,
        report.selected_superblock_slot,
        report.generation
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-reboot-persistence-small-file")]
fn run_phase3_neofs_reboot_persistence_small_file() -> ! {
    const PATH: &str = "/neofs/persist-2c.txt";
    const CONTENT: &[u8] = b"NeoFS BUILD-2 2C persisted across two QEMU boots.\n";

    let report = mount_neofs_rw_or_fail();
    match neofs_2c_open_read(PATH) {
        Ok(file) => {
            neofs_2c_read_literal_from_file_or_fail(&file, CONTENT);
            serial_println!(
                "NEO_TEST/1 event=PASS name={} stage=readback neofs_reboot_persistence=ok path={} bytes={} selected_superblock={} generation={} image=reused",
                SCENARIO,
                PATH,
                CONTENT.len(),
                report.selected_superblock_slot,
                report.generation
            );
        }
        Err(crate::fs::VfsError::NotFound) => {
            let file = neofs_2c_create_or_fail(PATH);
            neofs_2c_write_all_or_fail(&file, CONTENT);
            drop(file);
            neofs_2c_read_literal_or_fail(PATH, CONTENT);
            let cache = neofs_3d_wait_clean_or_fail("reason=neofs_persistence_cache_not_clean");
            serial_println!(
                "NEO_TEST/1 event=PASS name={} stage=write neofs_reboot_persistence=ok path={} bytes={} dirty_blocks_after_drain={} cache_flushes={} selected_superblock={} generation={} image=fresh",
                SCENARIO,
                PATH,
                CONTENT.len(),
                cache.dirty_blocks,
                cache.flushes,
                report.selected_superblock_slot,
                report.generation
            );
        }
        Err(err) => neofs_2c_fail_vfs("neofs_persistence_open_failed", err),
    }
    debug_exit(EXIT_SUCCESS);
}

#[cfg(any(
    feature = "neo-test-phase3-neofs-fsync-noop-write-through",
    feature = "neo-test-phase3-neofs-3e"
))]
fn neofs_2d_install_file_handle_for_fsync(file: alloc::sync::Arc<crate::fs::OpenFile>) -> u32 {
    use crate::sched::process::{self, Handle, KERNEL_PID, Process};

    let proc = process::get(KERNEL_PID)
        .unwrap_or_else(|| process::register(Process::new_kernel("neo-test-kernel")));
    let handle = Handle::File {
        file,
        cap_id: process::alloc_cap_id(),
        rights: neofs_2c_rw_rights(),
    };
    match process::install_cap_excluding(&proc, handle, None, &[1]) {
        Ok(fd) => fd,
        Err(_) => fail("reason=neofs_fsync_handle_install_failed"),
    }
}

#[cfg(any(
    feature = "neo-test-phase3-neofs-fsync-noop-write-through",
    feature = "neo-test-phase3-neofs-cow-write-after-write",
    feature = "neo-test-phase3-neofs-3c"
))]
fn neofs_2d_regular_blocks_or_fail(path: &str) -> ([u64; 8], u64) {
    match crate::fs::debug_neofs_regular_blocks(path) {
        Ok(blocks) => blocks,
        Err(err) => neofs_2c_fail_vfs("neofs_debug_regular_blocks_failed", err),
    }
}

#[cfg(any(
    feature = "neo-test-phase3-neofs-cow-write-after-write",
    feature = "neo-test-phase3-neofs-2e",
    feature = "neo-test-phase3-neofs-3c"
))]
fn neofs_2d_open_rw_or_fail(path: &str) -> alloc::sync::Arc<crate::fs::OpenFile> {
    match crate::fs::open_root_temporary(path, crate::fs::OPEN_ROOT_TEMPORARY, neofs_2c_rw_rights())
    {
        Ok(file) => file,
        Err(err) => neofs_2c_fail_vfs("neofs_open_rw_failed", err),
    }
}

#[cfg(feature = "neo-test-phase3-neofs-fsync-noop-write-through")]
fn run_phase3_neofs_fsync_noop_write_through() -> ! {
    const PATH: &str = "/neofs/fsync-2d.txt";
    const CONTENT: &[u8] = b"NeoFS BUILD-3 3E fsync now drains write-back cache.\n";

    let report = mount_neofs_rw_or_fail();
    neofs_3d_set_writeback_hold_or_fail(true);
    let file = neofs_2c_create_or_fail(PATH);
    neofs_2c_write_all_or_fail(&file, CONTENT);
    let generation_before = crate::fs::debug_neofs_generation()
        .unwrap_or_else(|err| neofs_2c_fail_vfs("neofs_generation_before_failed", err));
    let cache_before = neofs_3d_cache_stats_or_fail();
    if cache_before.dirty_blocks == 0 {
        fail("reason=neofs_fsync_no_dirty_cache_before_call");
    }
    let fd = neofs_2d_install_file_handle_for_fsync(file.clone());
    let flush_commands_before = crate::drivers::block::virtio_blk::debug_flush_command_count();
    let flush_completions_before =
        crate::drivers::block::virtio_blk::debug_flush_completion_count();
    let fsync_rc = crate::arch::x86_64::syscall::debug_sys_fsync_for_test(fd);
    if fsync_rc != 0 {
        fail_with_hex("reason=neofs_fsync_noop_rc rc", fsync_rc as u64);
    }
    let flush_commands_after = crate::drivers::block::virtio_blk::debug_flush_command_count();
    let flush_completions_after = crate::drivers::block::virtio_blk::debug_flush_completion_count();
    let generation_after = crate::fs::debug_neofs_generation()
        .unwrap_or_else(|err| neofs_2c_fail_vfs("neofs_generation_after_failed", err));
    if generation_after != generation_before {
        fail("reason=neofs_fsync_mutated_generation");
    }
    let cache_after_fsync = neofs_3d_cache_stats_or_fail();
    if cache_after_fsync.dirty_blocks != 0 || cache_after_fsync.flush_required {
        fail("reason=neofs_fsync_left_dirty_cache");
    }
    if cache_after_fsync.drained_blocks <= cache_before.drained_blocks {
        fail("reason=neofs_fsync_did_not_drain_cache");
    }
    if cache_after_fsync.flushes <= cache_before.flushes {
        fail("reason=neofs_fsync_no_cache_flush");
    }
    if flush_commands_after <= flush_commands_before {
        fail("reason=neofs_fsync_no_flush_command");
    }
    if flush_completions_after <= flush_completions_before {
        fail("reason=neofs_fsync_no_flush_completion");
    }
    drop(file);
    neofs_2c_read_literal_or_fail(PATH, CONTENT);
    neofs_3d_set_writeback_hold_or_fail(false);
    let cache_after_drain =
        neofs_3d_wait_clean_or_fail("reason=neofs_fsync_post_release_not_clean");
    serial_println!(
        "NEO_TEST/1 event=PASS name={} neofs_fsync=durable_3e_contract_changed path={} bytes={} fsync_rc=0 generation_before={} generation_after={} write_back_cache=true fsync_drained_cache=true dirty_blocks_before={} dirty_blocks_after_fsync={} dirty_blocks_after_drain={} drained_blocks_delta={} cache_flushes_delta={} flush_commands_delta={} flush_completions_delta={} no_intent_log=true selected_superblock={} generation={}",
        SCENARIO,
        PATH,
        CONTENT.len(),
        generation_before,
        generation_after,
        cache_before.dirty_blocks,
        cache_after_fsync.dirty_blocks,
        cache_after_drain.dirty_blocks,
        cache_after_fsync.drained_blocks - cache_before.drained_blocks,
        cache_after_fsync.flushes - cache_before.flushes,
        flush_commands_after - flush_commands_before,
        flush_completions_after - flush_completions_before,
        report.selected_superblock_slot,
        report.generation
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-3e")]
fn neofs_3e_fsync_or_fail(file: alloc::sync::Arc<crate::fs::OpenFile>) {
    let fd = neofs_2d_install_file_handle_for_fsync(file);
    let rc = crate::arch::x86_64::syscall::debug_sys_fsync_for_test(fd);
    if rc != 0 {
        fail_with_hex("reason=neofs_fsync_rc rc", rc as u64);
    }
}

#[cfg(feature = "neo-test-phase3-neofs-fsync-dirty-persists-after-crash")]
fn run_phase3_neofs_fsync_dirty_persists_after_crash() -> ! {
    const PATH: &str = "/neofs/fsync-3e-persist.txt";
    const CONTENT: &[u8] = b"NeoFS BUILD-3 3E fsync survives crash without teardown.\n";

    let report = mount_neofs_rw_or_fail();
    match neofs_2c_open_read(PATH) {
        Ok(file) => {
            neofs_2c_read_literal_from_file_or_fail(&file, CONTENT);
            serial_println!(
                "NEO_TEST/1 event=PASS name={} stage=readback neofs_fsync_persist=ok path={} bytes={} selected_superblock={} generation={} image=reused",
                SCENARIO,
                PATH,
                CONTENT.len(),
                report.selected_superblock_slot,
                report.generation
            );
        }
        Err(crate::fs::VfsError::NotFound) => {
            neofs_3d_set_writeback_hold_or_fail(true);
            let before = neofs_3d_cache_stats_or_fail();
            let file = neofs_2c_create_or_fail(PATH);
            neofs_2c_write_all_or_fail(&file, CONTENT);
            let dirty = neofs_3d_cache_stats_or_fail();
            if dirty.dirty_blocks == 0 || !dirty.flush_required || !dirty.writeback_hold {
                fail("reason=neofs_fsync_persist_dirty_not_held");
            }
            let flush_commands_before =
                crate::drivers::block::virtio_blk::debug_flush_command_count();
            neofs_3e_fsync_or_fail(file.clone());
            let flush_commands_after =
                crate::drivers::block::virtio_blk::debug_flush_command_count();
            let clean = neofs_3d_cache_stats_or_fail();
            if clean.dirty_blocks != 0 || clean.flush_required {
                fail("reason=neofs_fsync_persist_left_dirty");
            }
            if clean.drained_blocks <= before.drained_blocks || clean.flushes <= before.flushes {
                fail("reason=neofs_fsync_persist_no_drain");
            }
            if flush_commands_after <= flush_commands_before {
                fail("reason=neofs_fsync_persist_no_flush_command");
            }
            drop(file);
            neofs_2c_read_literal_or_fail(PATH, CONTENT);
            serial_println!(
                "NEO_TEST/1 event=PASS name={} stage=write neofs_fsync_persist=prepared path={} bytes={} dirty_blocks_before_fsync={} dirty_blocks_after_fsync={} drained_blocks_delta={} cache_flushes_delta={} flush_commands_delta={} drain_scope=mount_wide selected_superblock={} generation={} image=fresh",
                SCENARIO,
                PATH,
                CONTENT.len(),
                dirty.dirty_blocks,
                clean.dirty_blocks,
                clean.drained_blocks - before.drained_blocks,
                clean.flushes - before.flushes,
                flush_commands_after - flush_commands_before,
                report.selected_superblock_slot,
                report.generation
            );
        }
        Err(err) => neofs_2c_fail_vfs("neofs_fsync_persist_open_failed", err),
    }
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-unfsynced-dirty-may-be-lost")]
fn run_phase3_neofs_unfsynced_dirty_may_be_lost() -> ! {
    const MARKER: &str = "/neofs/fsync-3e-marker.txt";
    const TARGET: &str = "/neofs/fsync-3e-unfsynced.txt";
    const MARKER_CONTENT: &[u8] = b"NeoFS BUILD-3 3E committed marker.\n";
    const TARGET_CONTENT: &[u8] = b"NeoFS BUILD-3 3E unfsynced dirty data may be lost.\n";

    let report = mount_neofs_rw_or_fail();
    match neofs_2c_open_read(MARKER) {
        Ok(marker) => {
            neofs_2c_read_literal_from_file_or_fail(&marker, MARKER_CONTENT);
            match neofs_2c_open_read(TARGET) {
                Err(crate::fs::VfsError::NotFound) => {}
                Ok(_) => fail("reason=neofs_unfsynced_dirty_file_persisted"),
                Err(err) => neofs_2c_fail_vfs("neofs_unfsynced_dirty_probe_failed", err),
            }
            serial_println!(
                "NEO_TEST/1 event=PASS name={} stage=readback neofs_unfsynced_dirty=lost_without_corruption marker={} target={} dirty_target_absent=true selected_superblock={} generation={} image=reused",
                SCENARIO,
                MARKER,
                TARGET,
                report.selected_superblock_slot,
                report.generation
            );
        }
        Err(crate::fs::VfsError::NotFound) => {
            let marker = neofs_2c_create_or_fail(MARKER);
            neofs_2c_write_all_or_fail(&marker, MARKER_CONTENT);
            neofs_3e_fsync_or_fail(marker.clone());
            let marker_cache =
                neofs_3d_wait_clean_or_fail("reason=neofs_unfsynced_marker_not_clean");
            neofs_3d_set_writeback_hold_or_fail(true);
            let target = neofs_2c_create_or_fail(TARGET);
            neofs_2c_write_all_or_fail(&target, TARGET_CONTENT);
            drop(target);
            neofs_2c_read_literal_or_fail(TARGET, TARGET_CONTENT);
            let dirty = neofs_3d_cache_stats_or_fail();
            if dirty.dirty_blocks == 0 || !dirty.writeback_hold {
                fail("reason=neofs_unfsynced_dirty_not_held");
            }
            serial_println!(
                "NEO_TEST/1 event=PASS name={} stage=write neofs_unfsynced_dirty=prepared marker={} target={} marker_dirty_blocks_after_fsync={} dirty_blocks_before_exit={} writeback_hold=true no_target_fsync=true selected_superblock={} generation={} image=fresh",
                SCENARIO,
                MARKER,
                TARGET,
                marker_cache.dirty_blocks,
                dirty.dirty_blocks,
                report.selected_superblock_slot,
                report.generation
            );
        }
        Err(err) => neofs_2c_fail_vfs("neofs_unfsynced_marker_open_failed", err),
    }
    debug_exit(EXIT_SUCCESS);
}

/// CP-37 on `ARENA`: the forward on the inference stack takes it with
/// interrupts on, and the tensor syscalls take it at IF=0. As a plain spin
/// lock, a preempted IF-on holder could deadlock a same-CPU IF=0 taker. The
/// lock is now IRQ-safe, so no acquisition may ever find interrupts on inside
/// the section. A slot is allocated from this kernel thread (IF=1), minted from
/// the inference stack's closure (IF=1, as the forward's weight `mint`) and
/// from an IF=0 section (as a tensor syscall), counted and released; the
/// witness of acquisitions that saw IF=1 inside must read 0. The control
/// `neo-test-arena-mixed-if-control` (the plain `SwitchMutex`) must FAIL
/// `arena_held_with_interrupts_on`.
#[cfg(feature = "neo-test-arena-if-off")]
fn run_arena_if_off() -> ! {
    use alloc::sync::Arc;

    use crate::ai::arena;
    use crate::ai::tensor::{Device, Dtype, MAX_RANK, Shape, Tensor};

    let mut dims = [0u64; MAX_RANK];
    dims[0] = 16;
    let shape = Shape::new(1, dims).unwrap_or_else(|_| fail("reason=arena_if_off_shape"));
    let tensor = Tensor::allocate_writable(shape, Dtype::F32)
        .unwrap_or_else(|_| fail("reason=arena_if_off_tensor"));
    if !crate::arch::x86_64::interrupts_enabled() {
        fail("reason=arena_if_off_scenario_thread_if_off");
    }
    let before = arena::held_if_on_for_test();
    let key = arena::alloc(Arc::new(tensor), Device::Cpu);

    let (minted_on_stack, if_on_in_closure) = crate::mm::inference_stack::run_checked(|| {
        let if_on = crate::arch::x86_64::interrupts_enabled();
        (arena::mint(key).is_some(), if_on)
    })
    .0;
    if !if_on_in_closure {
        fail("reason=inference_stack_closure_not_if_on");
    }
    let (minted_if_off, count) = crate::arch::x86_64::without_interrupts(|| {
        (arena::mint(key).is_some(), arena::handle_count(key))
    });
    let freed = arena::release(key);
    let held_if_on = arena::held_if_on_for_test() - before;
    serial_println!(
        "arena_if_off minted_on_inference_stack={} minted_if_off={} handle_count={:?} freed={} held_if_on={}",
        minted_on_stack,
        minted_if_off,
        count,
        freed,
        held_if_on
    );
    if held_if_on != 0 {
        fail("reason=arena_held_with_interrupts_on");
    }
    if !minted_on_stack || !minted_if_off || count != Some(1) || !freed {
        fail("reason=arena_if_off_ops_wrong");
    }
    serial_println!(
        "NEO_TEST/1 event=PASS name={} arena=irqsafe held_if_on=0 legs=alloc_if_on,mint_inference_stack,mint_if_off,release",
        SCENARIO
    );
    debug_exit(EXIT_SUCCESS);
}

/// CP-56 / CP-82 follow-up: a file syscall whose NeoFS body takes `entries`
/// must not spin on it at IF=0. For each of model_load (its NeoFS open and
/// reads), model_query (a NeoFS-backed model's provenance check), fsync,
/// open, readdir and ftruncate, a kthread holds `entries` while yielding IF-on (a `sys_write`
/// preempted in `commit_child_update`), then this thread makes the call with
/// interrupts off, as a syscall arrives. The holder was spawned on this CPU,
/// so an IF=0 spinner never lets it run again: the control
/// `neo-test-vfs-syscall-if-off-control` (bodies at the caller's IF) hangs.
/// With the bodies IF-on, the timer preempts the spinner, the holder
/// releases, and the call completes, no earlier than the release.
#[cfg(feature = "neo-test-phase3-neofs-syscall-if-on")]
fn run_phase3_neofs_syscall_if_on() -> ! {
    use crate::fs::{ENTRIES_GATE_CALLING, ENTRIES_GATE_HELD, ENTRIES_GATE_IDLE};
    use core::sync::atomic::{AtomicBool, AtomicU8, AtomicU64, Ordering};

    const PATH: &str = "/neofs/syscall-if-on.txt";
    const MODEL_PATH: &str = "/neofs/syscall-if-on.neom";
    const NEOFS_MODEL_PATH: &str = "/neofs/model.neom";
    const CONTENT: &[u8] = b"NeoFS file syscalls run their VFS body IF-on.\n";
    const HOLD_TICKS: u64 = 20;
    // A leg whose holder released before the call could claim the gate (this
    // thread preempted between seeing HELD and the claim) is run again with a
    // new holder, without having made the call.
    const ATTEMPTS: u32 = 3;
    static GATE: AtomicU8 = AtomicU8::new(ENTRIES_GATE_IDLE);
    static RELEASED: AtomicU64 = AtomicU64::new(0);
    static CLAIMED_WHILE_HELD: AtomicBool = AtomicBool::new(false);

    let tick = || crate::arch::x86_64::timer::TICKS.load(Ordering::Acquire);
    // Each leg proves `entries` was held when its call began (Jarvis, relay
    // #58 item 5): the call runs only if this thread wins `HELD -> CALLING`
    // with interrupts off, right before it; the holder swaps the gate to
    // RELEASED before it drops the lock, so a won claim came first, and the
    // holder reports seeing CALLING. Then the completion must come no earlier
    // than the release.
    let contend = |leg: &str, call: &dyn Fn() -> i64| -> i64 {
        // Names the leg a hung control stops in.
        serial_println!("phase3_neofs_syscall_if_on leg_start={}", leg);
        for attempt in 1..=ATTEMPTS {
            GATE.store(ENTRIES_GATE_IDLE, Ordering::SeqCst);
            RELEASED.store(0, Ordering::Release);
            CLAIMED_WHILE_HELD.store(false, Ordering::Release);
            let holder = crate::sched::kthread::spawn_owned(
                "entries-holder",
                |_stop: crate::sched::kthread::KthreadStopToken| {
                    match crate::fs::debug_neofs_hold_entries_yielding(HOLD_TICKS, &GATE) {
                        Ok((released, claimed)) => {
                            CLAIMED_WHILE_HELD.store(claimed, Ordering::Release);
                            RELEASED.store(released, Ordering::Release);
                            crate::sched::kthread::KthreadExitState::Success
                        }
                        Err(_) => crate::sched::kthread::KthreadExitState::Failed(1),
                    }
                },
            );
            let deadline = tick() + 500;
            while GATE.load(Ordering::SeqCst) == ENTRIES_GATE_IDLE {
                if tick() > deadline {
                    fail("reason=entries_holder_never_held");
                }
                crate::sched::yield_now();
            }
            // Control (`neo-test-vfs-syscall-if-on-late-call-control`): the
            // race Jarvis named, forced. This thread waits until the holder
            // has released before it claims, so the call would run
            // uncontended; the leg must FAIL `entries_released_before_call`.
            #[cfg(feature = "neo-test-vfs-syscall-if-on-late-call-control")]
            while GATE.load(Ordering::SeqCst) != crate::fs::ENTRIES_GATE_RELEASED {
                crate::sched::yield_now();
            }
            let outcome = crate::arch::x86_64::without_interrupts(|| {
                let claimed = GATE
                    .compare_exchange(
                        ENTRIES_GATE_HELD,
                        ENTRIES_GATE_CALLING,
                        Ordering::SeqCst,
                        Ordering::SeqCst,
                    )
                    .is_ok();
                claimed.then(|| (tick(), call(), tick()))
            });
            let _ = holder.join();
            let released = RELEASED.load(Ordering::Acquire);
            if released == 0 {
                fail("reason=entries_holder_failed");
            }
            let Some((start, rc, done)) = outcome else {
                serial_println!(
                    "phase3_neofs_syscall_if_on leg={} attempt={} released_before_call=true retry",
                    leg,
                    attempt
                );
                continue;
            };
            let claimed_while_held = CLAIMED_WHILE_HELD.load(Ordering::Acquire);
            serial_println!(
                "phase3_neofs_syscall_if_on leg={} attempt={} rc={} held_at_call_start={} start_tick={} released_tick={} done_tick={}",
                leg,
                attempt,
                rc,
                claimed_while_held,
                start,
                released,
                done
            );
            if !claimed_while_held {
                serial_println!(
                    "NEO_TEST/1 event=FAIL name={} reason=call_not_witnessed_by_holder leg={}",
                    SCENARIO,
                    leg
                );
                debug_exit(EXIT_FAILURE);
            }
            if done < released {
                serial_println!(
                    "NEO_TEST/1 event=FAIL name={} reason=call_did_not_contend_on_entries leg={}",
                    SCENARIO,
                    leg
                );
                debug_exit(EXIT_FAILURE);
            }
            return rc;
        }
        serial_println!(
            "NEO_TEST/1 event=FAIL name={} reason=entries_released_before_call leg={} attempts={}",
            SCENARIO,
            leg,
            ATTEMPTS
        );
        debug_exit(EXIT_FAILURE);
    };

    let report = mount_neofs_rw_or_fail();
    let file = neofs_2c_create_or_fail(PATH);
    neofs_2c_write_all_or_fail(&file, CONTENT);
    let fd = neofs_2d_install_file_handle_for_fsync(file.clone());
    // The model_load leg's file, created before the directory handle is
    // opened so the directory's generation is final (readdir checks it).
    let not_a_model = neofs_2c_create_or_fail(MODEL_PATH);
    let mut junk = alloc::vec![0u8; 3 * 4096 + 123];
    for (idx, byte) in junk.iter_mut().enumerate() {
        *byte = (idx % 251) as u8;
    }
    neofs_2c_write_all_or_fail(&not_a_model, &junk);
    drop(not_a_model);
    // The model_query leg's model: the xtask fixture `valid_mlp.neom` at
    // /neofs/model.neom, loaded through the syscall body (reads only, so the
    // directory generation is unchanged).
    let model_h =
        crate::arch::x86_64::syscall::debug_sys_model_load_kernel_path_for_test(NEOFS_MODEL_PATH);
    if model_h < 0 {
        fail_with_hex("reason=if_on_fixture_model_load_rc rc", model_h as u64);
    }
    let dir = neofs_4a_open_dir_or_fail("/neofs");
    let dir_fd = neofs_4a_install_file_handle(dir, neofs_4a_dir_rights());

    // First, so the IF-off control hangs on this leg. `sys_model_load` of a
    // NeoFS file: the open and the whole-file read take `entries`
    // (`validate_current` resolves the name on every read). The file is not a
    // `.neom`, so after reading it all the build refuses it: EINVAL.
    // Skipped only to point the IF-off control at the next leg (model_query).
    #[cfg(not(feature = "neo-test-vfs-syscall-if-on-skip-model-load"))]
    {
        let model_rc = contend("model_load", &|| {
            crate::arch::x86_64::syscall::debug_sys_model_load_kernel_path_for_test(MODEL_PATH)
        });
        if model_rc != crate::errno::EINVAL {
            fail_with_hex("reason=if_on_model_load_rc rc", model_rc as u64);
        }
    }
    // `sys_model_query` of a NeoFS-backed model: its provenance check resolves
    // the file's name again (`current_child_generation` takes `entries`).
    let query_rc = contend("model_query", &|| {
        match crate::arch::x86_64::syscall::debug_sys_model_query_for_test(model_h as u32) {
            Ok(_) => 0,
            Err(e) => e,
        }
    });
    if query_rc != 0 {
        fail_with_hex("reason=if_on_model_query_rc rc", query_rc as u64);
    }

    let fsync_rc = contend("fsync", &|| {
        crate::arch::x86_64::syscall::debug_sys_fsync_for_test(fd)
    });
    if fsync_rc != 0 {
        fail_with_hex("reason=if_on_fsync_rc rc", fsync_rc as u64);
    }
    let open_rc = contend("open", &|| {
        crate::arch::x86_64::syscall::debug_sys_open_kernel_path_for_test(
            PATH,
            crate::fs::OPEN_ROOT_TEMPORARY,
            crate::fs::FileRights::READ.bits(),
        )
    });
    if open_rc < 0 {
        fail_with_hex("reason=if_on_open_rc rc", open_rc as u64);
    }
    let readdir_rc = contend("readdir", &|| {
        let mut buf = [0u8; 128];
        let mut cursor = 0u64;
        crate::arch::x86_64::syscall::debug_sys_readdir_kernel_buf_for_test(
            dir_fd,
            &mut buf,
            &mut cursor,
        )
    });
    if readdir_rc <= 0 {
        fail_with_hex("reason=if_on_readdir_rc rc", readdir_rc as u64);
    }
    let truncate_rc = contend("ftruncate", &|| {
        crate::arch::x86_64::syscall::debug_sys_ftruncate_for_test(fd, 4)
    });
    if truncate_rc != 0 {
        fail_with_hex("reason=if_on_ftruncate_rc rc", truncate_rc as u64);
    }
    drop(file);
    neofs_2c_read_literal_or_fail(PATH, &CONTENT[..4]);
    serial_println!(
        "NEO_TEST/1 event=PASS name={} vfs_syscall_body=if_on legs=model_load,model_query,fsync,open,readdir,ftruncate hold_ticks={} selected_superblock={} generation={}",
        SCENARIO,
        HOLD_TICKS,
        report.selected_superblock_slot,
        report.generation
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-fsync-issues-flush")]
fn run_phase3_neofs_fsync_issues_flush() -> ! {
    const PATH: &str = "/neofs/fsync-3e-flush.txt";
    const CONTENT: &[u8] = b"NeoFS BUILD-3 3E fsync issues virtio FLUSH.\n";

    let report = mount_neofs_rw_or_fail();
    let Some(device) = crate::drivers::block::get_device(0) else {
        fail("reason=neofs_fsync_flush_no_registered_block_device");
    };
    if !device.supports_flush() {
        fail("reason=neofs_fsync_flush_device_does_not_support_flush");
    }
    neofs_3d_set_writeback_hold_or_fail(true);
    let before = neofs_3d_cache_stats_or_fail();
    let flush_commands_before = crate::drivers::block::virtio_blk::debug_flush_command_count();
    let flush_completions_before =
        crate::drivers::block::virtio_blk::debug_flush_completion_count();
    let file = neofs_2c_create_or_fail(PATH);
    neofs_2c_write_all_or_fail(&file, CONTENT);
    let dirty = neofs_3d_cache_stats_or_fail();
    if dirty.dirty_blocks == 0 || !dirty.flush_required {
        fail("reason=neofs_fsync_flush_no_dirty_flush_required");
    }
    neofs_3e_fsync_or_fail(file.clone());
    let clean = neofs_3d_cache_stats_or_fail();
    let flush_commands_after = crate::drivers::block::virtio_blk::debug_flush_command_count();
    let flush_completions_after = crate::drivers::block::virtio_blk::debug_flush_completion_count();
    if clean.dirty_blocks != 0 || clean.flush_required {
        fail("reason=neofs_fsync_flush_left_dirty");
    }
    if clean.drained_blocks <= before.drained_blocks || clean.flushes <= before.flushes {
        fail("reason=neofs_fsync_flush_no_cache_drain");
    }
    if flush_commands_after <= flush_commands_before {
        fail("reason=neofs_fsync_flush_command_not_issued");
    }
    if flush_completions_after <= flush_completions_before {
        fail("reason=neofs_fsync_flush_completion_not_observed");
    }
    serial_println!(
        "NEO_TEST/1 event=PASS name={} neofs_fsync=issues_flush path={} device_supports_flush=true dirty_blocks_before={} dirty_blocks_after={} drained_blocks_delta={} cache_flushes_delta={} flush_commands_delta={} flush_completions_delta={} drain_scope=mount_wide selected_superblock={} generation={}",
        SCENARIO,
        PATH,
        dirty.dirty_blocks,
        clean.dirty_blocks,
        clean.drained_blocks - before.drained_blocks,
        clean.flushes - before.flushes,
        flush_commands_after - flush_commands_before,
        flush_completions_after - flush_completions_before,
        report.selected_superblock_slot,
        report.generation
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-fsync-clean-no-extra-flush")]
fn run_phase3_neofs_fsync_clean_no_extra_flush() -> ! {
    const PATH: &str = "/neofs/hello.txt";
    const EXPECTED: &[u8] = b"Hello from NeoFS v1 BUILD-2 2A mkfs.\n";

    let report = mount_neofs_rw_or_fail();
    let file = neofs_2c_open_read_or_fail(PATH);
    neofs_2c_read_literal_from_file_or_fail(&file, EXPECTED);
    let before = neofs_3d_cache_stats_or_fail();
    if before.dirty_blocks != 0 || before.flush_required {
        fail("reason=neofs_clean_fsync_not_clean_before");
    }
    let flush_commands_before = crate::drivers::block::virtio_blk::debug_flush_command_count();
    let flush_completions_before =
        crate::drivers::block::virtio_blk::debug_flush_completion_count();
    neofs_3e_fsync_or_fail(file.clone());
    let after = neofs_3d_cache_stats_or_fail();
    let flush_commands_after = crate::drivers::block::virtio_blk::debug_flush_command_count();
    let flush_completions_after = crate::drivers::block::virtio_blk::debug_flush_completion_count();
    if after.dirty_blocks != 0 || after.flush_required {
        fail("reason=neofs_clean_fsync_left_dirty");
    }
    if after.drained_blocks != before.drained_blocks || after.flushes != before.flushes {
        fail("reason=neofs_clean_fsync_did_work");
    }
    if flush_commands_after != flush_commands_before
        || flush_completions_after != flush_completions_before
    {
        fail("reason=neofs_clean_fsync_spurious_flush");
    }
    serial_println!(
        "NEO_TEST/1 event=PASS name={} neofs_fsync=clean_no_extra_flush path={} dirty_blocks_before={} dirty_blocks_after={} drained_blocks_delta=0 cache_flushes_delta=0 flush_commands_delta=0 flush_completions_delta=0 selected_superblock={} generation={}",
        SCENARIO,
        PATH,
        before.dirty_blocks,
        after.dirty_blocks,
        report.selected_superblock_slot,
        report.generation
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-fsync-coordinates-with-writeback-gc")]
fn run_phase3_neofs_fsync_coordinates_with_writeback_gc() -> ! {
    const PATH: &str = "/neofs/fsync-3e-gc.txt";
    const FIRST: &[u8] = b"NeoFS BUILD-3 3E fsync+GC version A.\n";
    const SECOND: &[u8] = b"NeoFS BUILD-3 3E fsync+GC version B.\n";

    let report = mount_neofs_rw_or_fail();
    neofs_3d_set_writeback_hold_or_fail(true);
    let before = neofs_3d_cache_stats_or_fail();
    let file = neofs_2c_create_or_fail(PATH);
    neofs_2c_write_all_or_fail(&file, FIRST);
    drop(file);
    let file = neofs_2d_open_rw_or_fail(PATH);
    neofs_2c_write_all_or_fail(&file, SECOND);
    let dirty = neofs_3d_cache_stats_or_fail();
    if dirty.dirty_blocks == 0 || !dirty.writeback_hold {
        fail("reason=neofs_fsync_gc_dirty_not_held");
    }
    neofs_3e_fsync_or_fail(file.clone());
    let after_fsync = neofs_3d_cache_stats_or_fail();
    if after_fsync.dirty_blocks != 0 || after_fsync.flush_required {
        fail("reason=neofs_fsync_gc_fsync_left_dirty");
    }
    let gc = neofs_3c_run_gc_or_fail();
    let after_gc = neofs_3d_cache_stats_or_fail();
    if after_gc.dirty_blocks == 0 || !after_gc.flush_required {
        fail("reason=neofs_fsync_gc_did_not_publish_metadata");
    }
    neofs_3e_fsync_or_fail(file.clone());
    let after_gc_fsync = neofs_3d_cache_stats_or_fail();
    if after_gc_fsync.dirty_blocks != 0 || after_gc_fsync.flush_required {
        fail("reason=neofs_fsync_gc_second_fsync_left_dirty");
    }
    neofs_3d_set_writeback_hold_or_fail(false);
    let clean = neofs_3d_wait_clean_or_fail("reason=neofs_fsync_gc_release_not_clean");
    drop(file);
    neofs_2c_read_literal_or_fail(PATH, SECOND);
    serial_println!(
        "NEO_TEST/1 event=PASS name={} neofs_fsync_gc=coordinated path={} dirty_blocks_before_fsync={} dirty_blocks_after_fsync={} dirty_blocks_after_gc={} dirty_blocks_after_gc_fsync={} dirty_blocks_after_release={} drained_blocks_delta={} gc_fsync_drained_blocks_delta={} reclaimed_blocks={} cache_flushes={} writeback_hold_during_fsync=true drain_scope=mount_wide selected_superblock={} generation={}",
        SCENARIO,
        PATH,
        dirty.dirty_blocks,
        after_fsync.dirty_blocks,
        after_gc.dirty_blocks,
        after_gc_fsync.dirty_blocks,
        clean.dirty_blocks,
        after_fsync.drained_blocks - before.drained_blocks,
        after_gc_fsync.drained_blocks - after_gc.drained_blocks,
        gc.reclaimed_blocks,
        clean.flushes,
        report.selected_superblock_slot,
        report.generation
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-fsync-filecap-stale-regression")]
fn run_phase3_neofs_fsync_filecap_stale_regression() -> ! {
    const PATH: &str = "/neofs/fsync-3e-stale.txt";
    const SEED: &[u8] = b"NeoFS BUILD-3 3E stale fsync seed.\n";
    const MUTATION: &[u8] = b"NeoFS BUILD-3 3E stale fsync mutation.\n";

    let report = mount_neofs_rw_or_fail();
    let seed = neofs_2c_create_or_fail(PATH);
    neofs_2c_write_all_or_fail(&seed, SEED);
    neofs_3e_fsync_or_fail(seed.clone());
    drop(seed);

    neofs_3d_set_writeback_hold_or_fail(true);
    let handle_a = neofs_2d_open_rw_or_fail(PATH);
    let handle_b = neofs_2d_open_rw_or_fail(PATH);
    let old_cap_generation =
        neofs_2e_generation_or_fail(&handle_b, "reason=missing_old_cap_generation");
    neofs_2c_write_all_or_fail(&handle_a, MUTATION);
    let dirty = neofs_3d_cache_stats_or_fail();
    let flush_commands_before = crate::drivers::block::virtio_blk::debug_flush_command_count();
    let stale_fd = neofs_2d_install_file_handle_for_fsync(handle_b.clone());
    let stale_rc = crate::arch::x86_64::syscall::debug_sys_fsync_for_test(stale_fd);
    if stale_rc != crate::errno::ESTALE || stale_rc != -116 {
        fail_with_hex(
            "reason=neofs_stale_fsync_errno_mismatch errno",
            stale_rc as u64,
        );
    }
    let after_stale = neofs_3d_cache_stats_or_fail();
    let flush_commands_after_stale = crate::drivers::block::virtio_blk::debug_flush_command_count();
    if after_stale.dirty_blocks != dirty.dirty_blocks
        || after_stale.drained_blocks != dirty.drained_blocks
        || flush_commands_after_stale != flush_commands_before
    {
        fail("reason=neofs_stale_fsync_mutated_durability_state");
    }
    let current_generation = match handle_b.debug_current_generation() {
        Ok(Some(generation)) => generation,
        Ok(None) => fail("reason=missing_current_generation"),
        Err(err) => neofs_2c_fail_vfs("neofs_current_generation_failed", err),
    };
    let refreshed_generation =
        neofs_2e_generation_or_fail(&handle_a, "reason=missing_refreshed_generation");
    if refreshed_generation == old_cap_generation || current_generation == old_cap_generation {
        fail("reason=neofs_stale_generation_not_advanced");
    }
    neofs_3e_fsync_or_fail(handle_a.clone());
    let clean = neofs_3d_cache_stats_or_fail();
    if clean.dirty_blocks != 0 || clean.flush_required {
        fail("reason=neofs_refreshed_fsync_left_dirty");
    }
    serial_println!(
        "NEO_TEST/1 event=PASS name={} path={} stale_fsync=ESTALE stale_errno={} stale_before_durability=true old_cap_generation={} refreshed_generation={} current_inode_generation={} dirty_blocks_before_stale={} dirty_blocks_after_stale={} dirty_blocks_after_refreshed_fsync={} flush_commands_after_stale_delta={} cache_flushes={} selected_superblock={} generation={}",
        SCENARIO,
        PATH,
        stale_rc,
        old_cap_generation,
        refreshed_generation,
        current_generation,
        dirty.dirty_blocks,
        after_stale.dirty_blocks,
        clean.dirty_blocks,
        flush_commands_after_stale - flush_commands_before,
        clean.flushes,
        report.selected_superblock_slot,
        report.generation
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-cow-write-after-write")]
fn run_phase3_neofs_cow_write_after_write() -> ! {
    const PATH: &str = "/neofs/cow-2d.txt";
    const FIRST: &[u8] = b"NeoFS BUILD-2 2D CoW version 00000000000000000001.\n";
    const SECOND: &[u8] = b"NeoFS BUILD-2 2D CoW version 00000000000000000002.\n";

    let report = mount_neofs_rw_or_fail();
    let file = neofs_2c_create_or_fail(PATH);
    neofs_2c_write_all_or_fail(&file, FIRST);
    drop(file);
    let (blocks_before, count_before) = neofs_2d_regular_blocks_or_fail(PATH);
    if count_before != 1 || blocks_before[0] == 0 {
        fail("reason=neofs_cow_initial_block_missing");
    }

    let file = neofs_2d_open_rw_or_fail(PATH);
    neofs_2c_write_all_or_fail(&file, SECOND);
    drop(file);
    let (blocks_after, count_after) = neofs_2d_regular_blocks_or_fail(PATH);
    if count_after != 1 || blocks_after[0] == 0 {
        fail("reason=neofs_cow_rewrite_block_missing");
    }
    if blocks_after[0] == blocks_before[0] {
        fail("reason=neofs_cow_data_block_reused");
    }
    neofs_2c_read_literal_or_fail(PATH, SECOND);
    serial_println!(
        "NEO_TEST/1 event=PASS name={} neofs_cow=ok path={} first_bytes={} second_bytes={} old_data_block={} new_data_block={} distinct_blocks=true selected_superblock={} generation={}",
        SCENARIO,
        PATH,
        FIRST.len(),
        SECOND.len(),
        blocks_before[0],
        blocks_after[0],
        report.selected_superblock_slot,
        report.generation
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-crash-mid-overwrite-recovery")]
fn run_phase3_neofs_crash_mid_overwrite_recovery() -> ! {
    const PATH: &str = "/neofs/crash-ow.txt";
    const FIRST: &[u8] = b"NeoFS BUILD-2 2D overwrite recovery keeps version A.\n";
    const SECOND: &[u8] = b"NeoFS BUILD-2 2D attempted version B is unpublished.\n";

    let report = mount_neofs_rw_or_fail();
    match neofs_2c_open_read(PATH) {
        Ok(file) => {
            neofs_2c_read_literal_from_file_or_fail(&file, FIRST);
            serial_println!(
                "NEO_TEST/1 event=PASS name={} stage=readback neofs_recovery=ok path={} recovered=version_a unpublished_version_b_absent=true selected_superblock={} generation={} rejected_superblock_mask=0x{:02x}",
                SCENARIO,
                PATH,
                report.selected_superblock_slot,
                report.generation,
                report.rejected_superblock_mask
            );
        }
        Err(crate::fs::VfsError::NotFound) => {
            let file = neofs_2c_create_or_fail(PATH);
            neofs_2c_write_all_or_fail(&file, FIRST);
            drop(file);
            let committed_cache =
                neofs_3d_wait_clean_or_fail("reason=neofs_overwrite_seed_cache_not_clean");
            match crate::fs::debug_neofs_inject_overwrite_before_superblock(PATH, SECOND) {
                Ok(()) => {}
                Err(err) => neofs_2c_fail_vfs("neofs_overwrite_inject_failed", err),
            }
            // The cut after the commit barrier: version B's blocks on the
            // media and flushed, no superblock naming them. The next boot
            // must still mount version A.
            let barrier_flushes = match crate::fs::debug_neofs_drain_to_barrier() {
                Ok(n) => n,
                Err(err) => neofs_2c_fail_vfs("neofs_overwrite_barrier_drain_failed", err),
            };
            if barrier_flushes == 0 {
                fail("reason=neofs_overwrite_barrier_not_flushed");
            }
            neofs_2c_read_literal_or_fail(PATH, FIRST);
            serial_println!(
                "NEO_TEST/1 event=PASS name={} stage=write neofs_recovery=prepared path={} committed=version_a attempted=version_b injection=before_superblock_publish cut=after_barrier_flush barrier_flushes={} seed_dirty_blocks_after_drain={} cache_flushes={} selected_superblock={} generation={}",
                SCENARIO,
                PATH,
                barrier_flushes,
                committed_cache.dirty_blocks,
                committed_cache.flushes,
                report.selected_superblock_slot,
                report.generation
            );
        }
        Err(err) => neofs_2c_fail_vfs("neofs_overwrite_recovery_open_failed", err),
    }
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-superblock-rotation-recovery")]
fn run_phase3_neofs_superblock_rotation_recovery() -> ! {
    const PATH: &str = "/neofs/sb-rot.txt";
    const CONTENT: &[u8] = b"NeoFS BUILD-2 2D superblock candidate recovery.\n";
    const INVALID_SLOT: usize = 2;

    let report = mount_neofs_rw_or_fail();
    match neofs_2c_open_read(PATH) {
        Ok(file) => {
            neofs_2c_read_literal_from_file_or_fail(&file, CONTENT);
            let invalid_rejected = (report.rejected_superblock_mask & (1 << INVALID_SLOT)) != 0;
            if !invalid_rejected || report.selected_superblock_slot == INVALID_SLOT {
                fail("reason=neofs_invalid_superblock_candidate_not_rejected");
            }
            serial_println!(
                "NEO_TEST/1 event=PASS name={} stage=readback neofs_superblock_recovery=ok path={} selected_superblock={} generation={} invalid_slot={} invalid_candidate_rejected=true rejected_superblock_mask=0x{:02x}",
                SCENARIO,
                PATH,
                report.selected_superblock_slot,
                report.generation,
                INVALID_SLOT,
                report.rejected_superblock_mask
            );
        }
        Err(crate::fs::VfsError::NotFound) => {
            let file = neofs_2c_create_or_fail(PATH);
            neofs_2c_write_all_or_fail(&file, CONTENT);
            drop(file);
            let content_cache =
                neofs_3d_wait_clean_or_fail("reason=neofs_superblock_seed_cache_not_clean");
            match crate::fs::debug_neofs_write_invalid_superblock_copy(INVALID_SLOT) {
                Ok(()) => {}
                Err(err) => neofs_2c_fail_vfs("neofs_superblock_inject_failed", err),
            }
            let invalid_cache =
                neofs_3d_wait_clean_or_fail("reason=neofs_invalid_superblock_cache_not_clean");
            neofs_2c_read_literal_or_fail(PATH, CONTENT);
            serial_println!(
                "NEO_TEST/1 event=PASS name={} stage=write neofs_superblock_recovery=prepared path={} invalid_slot={} injection=root_invalid_superblock seed_cache_flushes={} invalid_cache_flushes={} selected_superblock={} generation={}",
                SCENARIO,
                PATH,
                INVALID_SLOT,
                content_cache.flushes,
                invalid_cache.flushes,
                report.selected_superblock_slot,
                report.generation
            );
        }
        Err(err) => neofs_2c_fail_vfs("neofs_superblock_recovery_open_failed", err),
    }
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-crash-mid-create-recovery")]
fn run_phase3_neofs_crash_mid_create_recovery() -> ! {
    const TARGET: &str = "/neofs/crash-create.txt";
    const MARKER: &str = "/neofs/create-marker-2d.txt";
    const MARKER_CONTENT: &[u8] = b"NeoFS BUILD-2 2D committed marker before create crash.\n";

    let report = mount_neofs_rw_or_fail();
    match neofs_2c_open_read(MARKER) {
        Ok(marker) => {
            neofs_2c_read_literal_from_file_or_fail(&marker, MARKER_CONTENT);
            match neofs_2c_open_read(TARGET) {
                Err(crate::fs::VfsError::NotFound) => {}
                Ok(_) => fail("reason=neofs_crash_create_unpublished_file_visible"),
                Err(err) => neofs_2c_fail_vfs("neofs_crash_create_target_open_failed", err),
            }
            serial_println!(
                "NEO_TEST/1 event=PASS name={} stage=readback neofs_create_recovery=ok target={} marker={} target_absent=true selected_superblock={} generation={} rejected_superblock_mask=0x{:02x}",
                SCENARIO,
                TARGET,
                MARKER,
                report.selected_superblock_slot,
                report.generation,
                report.rejected_superblock_mask
            );
        }
        Err(crate::fs::VfsError::NotFound) => {
            let marker = neofs_2c_create_or_fail(MARKER);
            neofs_2c_write_all_or_fail(&marker, MARKER_CONTENT);
            drop(marker);
            let marker_cache =
                neofs_3d_wait_clean_or_fail("reason=neofs_create_marker_cache_not_clean");
            match crate::fs::debug_neofs_inject_create_before_superblock(TARGET) {
                Ok(()) => {}
                Err(err) => neofs_2c_fail_vfs("neofs_create_inject_failed", err),
            }
            match neofs_2c_open_read(TARGET) {
                Err(crate::fs::VfsError::NotFound) => {}
                Ok(_) => fail("reason=neofs_crash_create_in_memory_file_visible"),
                Err(err) => neofs_2c_fail_vfs("neofs_crash_create_probe_failed", err),
            }
            serial_println!(
                "NEO_TEST/1 event=PASS name={} stage=write neofs_create_recovery=prepared target={} marker={} injection=before_superblock_publish expected_recovery=target_absent marker_dirty_blocks_after_drain={} cache_flushes={} selected_superblock={} generation={}",
                SCENARIO,
                TARGET,
                MARKER,
                marker_cache.dirty_blocks,
                marker_cache.flushes,
                report.selected_superblock_slot,
                report.generation
            );
        }
        Err(err) => neofs_2c_fail_vfs("neofs_create_recovery_marker_open_failed", err),
    }
    debug_exit(EXIT_SUCCESS);
}

