#[cfg(feature = "neo-test-phase3-neofs-gc-mark-live-set")]
fn run_phase3_neofs_gc_mark_live_set() -> ! {
    let report = mount_neofs_rw_or_fail();
    let before = neofs_3c_free_map_stats_or_fail();
    let gc = neofs_3c_run_gc_or_fail();
    let after = neofs_3c_free_map_stats_or_fail();
    if gc.live_blocks < 10 {
        fail_with_hex(
            "reason=neofs_gc_live_set_too_small live_blocks",
            gc.live_blocks,
        );
    }
    if before.map_blocks == 0 || after.map_blocks == 0 {
        fail("reason=neofs_gc_free_map_missing");
    }
    serial_println!(
        "NEO_TEST/1 event=PASS name={} neofs_gc_mark=ok live_blocks={} reclaimed_blocks={} free_blocks_before={} free_blocks_after={} free_map_blocks={} map_start_block={} selected_superblock={} generation={}",
        SCENARIO,
        gc.live_blocks,
        gc.reclaimed_blocks,
        before.free_blocks,
        after.free_blocks,
        after.map_blocks,
        gc.map_start_block,
        report.selected_superblock_slot,
        report.generation
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-gc-reclaims-orphan-after-overwrite")]
fn run_phase3_neofs_gc_reclaims_orphan_after_overwrite() -> ! {
    const PATH: &str = "/neofs/gc-reclaim.txt";
    const FIRST: &[u8] = b"NeoFS BUILD-3 3C GC reclaim version A.\n";
    const SECOND: &[u8] = b"NeoFS BUILD-3 3C GC reclaim version B.\n";

    let report = mount_neofs_rw_or_fail();
    let file = neofs_2c_create_or_fail(PATH);
    neofs_2c_write_all_or_fail(&file, FIRST);
    drop(file);
    let old_data_block = neofs_3c_single_data_block_or_fail(PATH);
    let file = neofs_2d_open_rw_or_fail(PATH);
    neofs_2c_write_all_or_fail(&file, SECOND);
    drop(file);
    let new_data_block = neofs_3c_single_data_block_or_fail(PATH);
    if old_data_block == new_data_block {
        fail("reason=neofs_gc_cow_data_not_distinct");
    }
    let before = neofs_3c_free_map_stats_or_fail();
    let gc = neofs_3c_run_gc_or_fail();
    let cache = neofs_3d_wait_clean_or_fail("reason=neofs_gc_reclaim_cache_not_clean");
    let after = neofs_3c_free_map_stats_or_fail();
    if gc.reclaimed_blocks == 0 || after.free_blocks <= before.free_blocks {
        fail("reason=neofs_gc_reclaimed_no_blocks");
    }
    neofs_2c_read_literal_or_fail(PATH, SECOND);
    serial_println!(
        "NEO_TEST/1 event=PASS name={} neofs_gc_reclaim=ok path={} old_data_block={} new_data_block={} reclaimed_blocks={} free_blocks_before={} free_blocks_after={} dirty_blocks_after_drain={} cache_flushes={} selected_superblock={} generation={}",
        SCENARIO,
        PATH,
        old_data_block,
        new_data_block,
        gc.reclaimed_blocks,
        before.free_blocks,
        after.free_blocks,
        cache.dirty_blocks,
        cache.flushes,
        report.selected_superblock_slot,
        report.generation
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-gc-reuses-reclaimed-block")]
fn run_phase3_neofs_gc_reuses_reclaimed_block() -> ! {
    const PATH_A: &str = "/neofs/gc-reuse-a.txt";
    const PATH_B: &str = "/neofs/gc-reuse-b.txt";
    const FIRST: &[u8] = b"NeoFS BUILD-3 3C reusable version A.\n";
    const SECOND: &[u8] = b"NeoFS BUILD-3 3C reusable version B.\n";
    const REUSE: &[u8] = b"NeoFS BUILD-3 3C allocation consumes a reclaimed block.\n";

    let report = mount_neofs_rw_or_fail();
    let file = neofs_2c_create_or_fail(PATH_A);
    neofs_2c_write_all_or_fail(&file, FIRST);
    drop(file);
    let file = neofs_2d_open_rw_or_fail(PATH_A);
    neofs_2c_write_all_or_fail(&file, SECOND);
    drop(file);
    let gc = neofs_3c_run_gc_or_fail();
    let gc_cache = neofs_3d_wait_clean_or_fail("reason=neofs_gc_reuse_gc_cache_not_clean");
    let after_gc = neofs_3c_free_map_stats_or_fail();
    if gc.reclaimed_blocks == 0 || after_gc.free_blocks == 0 {
        fail("reason=neofs_gc_reuse_no_free_blocks");
    }

    let file = neofs_2c_create_or_fail(PATH_B);
    neofs_2c_write_all_or_fail(&file, REUSE);
    drop(file);
    let reuse_cache = neofs_3d_wait_clean_or_fail("reason=neofs_gc_reuse_write_cache_not_clean");
    let reused_data_block = neofs_3c_single_data_block_or_fail(PATH_B);
    if reused_data_block >= after_gc.next_free_block {
        fail_with_hex(
            "reason=neofs_gc_reuse_data_not_from_freemap block",
            reused_data_block,
        );
    }
    neofs_2c_read_literal_or_fail(PATH_A, SECOND);
    neofs_2c_read_literal_or_fail(PATH_B, REUSE);
    serial_println!(
        "NEO_TEST/1 event=PASS name={} neofs_gc_reuse=ok reclaimed_blocks={} free_blocks_after_gc={} reused_data_block={} high_water_before_reuse={} dirty_blocks_after_gc_drain={} dirty_blocks_after_reuse_drain={} cache_flushes_after_reuse={} selected_superblock={} generation={}",
        SCENARIO,
        gc.reclaimed_blocks,
        after_gc.free_blocks,
        reused_data_block,
        after_gc.next_free_block,
        gc_cache.dirty_blocks,
        reuse_cache.dirty_blocks,
        reuse_cache.flushes,
        report.selected_superblock_slot,
        report.generation
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-gc-reboot-persistence")]
fn run_phase3_neofs_gc_reboot_persistence() -> ! {
    const PATH: &str = "/neofs/gc-persist.txt";
    const REUSE_PATH: &str = "/neofs/gc-persist-reuse.txt";
    const FIRST: &[u8] = b"NeoFS BUILD-3 3C persisted GC version A.\n";
    const SECOND: &[u8] = b"NeoFS BUILD-3 3C persisted GC version B.\n";
    const REUSE: &[u8] = b"NeoFS BUILD-3 3C free map survived reboot.\n";

    let report = mount_neofs_rw_or_fail();
    match neofs_2c_open_read(PATH) {
        Ok(file) => {
            neofs_2c_read_literal_from_file_or_fail(&file, SECOND);
            let before = neofs_3c_free_map_stats_or_fail();
            if before.free_blocks == 0 {
                fail("reason=neofs_gc_reboot_free_map_not_persisted");
            }
            let reuse = neofs_2c_create_or_fail(REUSE_PATH);
            neofs_2c_write_all_or_fail(&reuse, REUSE);
            drop(reuse);
            let after = neofs_3c_free_map_stats_or_fail();
            if after.free_blocks >= before.free_blocks {
                fail("reason=neofs_gc_reboot_free_map_not_consumed");
            }
            neofs_2c_read_literal_or_fail(REUSE_PATH, REUSE);
            let cache = neofs_3d_wait_clean_or_fail("reason=neofs_gc_reuse_cache_not_clean");
            serial_println!(
                "NEO_TEST/1 event=PASS name={} stage=readback neofs_gc_reboot=ok path={} reuse_path={} free_blocks_before={} free_blocks_after={} dirty_blocks_after_drain={} cache_flushes={} selected_superblock={} generation={} image=reused",
                SCENARIO,
                PATH,
                REUSE_PATH,
                before.free_blocks,
                after.free_blocks,
                cache.dirty_blocks,
                cache.flushes,
                report.selected_superblock_slot,
                report.generation
            );
        }
        Err(crate::fs::VfsError::NotFound) => {
            let file = neofs_2c_create_or_fail(PATH);
            neofs_2c_write_all_or_fail(&file, FIRST);
            drop(file);
            let file = neofs_2d_open_rw_or_fail(PATH);
            neofs_2c_write_all_or_fail(&file, SECOND);
            drop(file);
            let gc = neofs_3c_run_gc_or_fail();
            if gc.reclaimed_blocks == 0 {
                fail("reason=neofs_gc_reboot_no_reclaim");
            }
            neofs_2c_read_literal_or_fail(PATH, SECOND);
            let cache = neofs_3d_wait_clean_or_fail("reason=neofs_gc_reboot_cache_not_clean");
            serial_println!(
                "NEO_TEST/1 event=PASS name={} stage=write neofs_gc_reboot=prepared path={} reclaimed_blocks={} dirty_blocks_after_drain={} cache_flushes={} selected_superblock={} generation={} image=fresh",
                SCENARIO,
                PATH,
                gc.reclaimed_blocks,
                cache.dirty_blocks,
                cache.flushes,
                report.selected_superblock_slot,
                report.generation
            );
        }
        Err(err) => neofs_2c_fail_vfs("neofs_gc_reboot_open_failed", err),
    }
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-gc-crash-before-publish")]
fn run_phase3_neofs_gc_crash_before_publish() -> ! {
    const PATH: &str = "/neofs/gc-crash.txt";
    const FIRST: &[u8] = b"NeoFS BUILD-3 3C unpublished GC version A.\n";
    const SECOND: &[u8] = b"NeoFS BUILD-3 3C unpublished GC version B.\n";

    let report = mount_neofs_rw_or_fail();
    match neofs_2c_open_read(PATH) {
        Ok(file) => {
            neofs_2c_read_literal_from_file_or_fail(&file, SECOND);
            let stats = neofs_3c_free_map_stats_or_fail();
            if stats.free_blocks != 0 {
                fail("reason=neofs_gc_crash_unpublished_map_selected");
            }
            serial_println!(
                "NEO_TEST/1 event=PASS name={} stage=readback neofs_gc_crash=ok path={} unpublished_gc_ignored=true free_blocks={} selected_superblock={} generation={} rejected_superblock_mask=0x{:02x}",
                SCENARIO,
                PATH,
                stats.free_blocks,
                report.selected_superblock_slot,
                report.generation,
                report.rejected_superblock_mask
            );
        }
        Err(crate::fs::VfsError::NotFound) => {
            let file = neofs_2c_create_or_fail(PATH);
            neofs_2c_write_all_or_fail(&file, FIRST);
            drop(file);
            let file = neofs_2d_open_rw_or_fail(PATH);
            neofs_2c_write_all_or_fail(&file, SECOND);
            drop(file);
            let committed_cache =
                neofs_3d_wait_clean_or_fail("reason=neofs_gc_crash_seed_cache_not_clean");
            match crate::fs::debug_neofs_inject_gc_before_superblock() {
                Ok(()) => {}
                Err(err) => neofs_2c_fail_vfs("neofs_gc_inject_failed", err),
            }
            neofs_2c_read_literal_or_fail(PATH, SECOND);
            serial_println!(
                "NEO_TEST/1 event=PASS name={} stage=write neofs_gc_crash=prepared path={} injection=free_map_before_superblock expected_recovery=published_root_old_map seed_dirty_blocks_after_drain={} cache_flushes={} selected_superblock={} generation={}",
                SCENARIO,
                PATH,
                committed_cache.dirty_blocks,
                committed_cache.flushes,
                report.selected_superblock_slot,
                report.generation
            );
        }
        Err(err) => neofs_2c_fail_vfs("neofs_gc_crash_open_failed", err),
    }
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-gc-corrupt-free-map-rejected")]
fn run_phase3_neofs_gc_corrupt_free_map_rejected() -> ! {
    let report = mount_neofs_or_fail();
    let corrupt_slot_rejected = (report.rejected_superblock_mask & 0b100) != 0;
    if !corrupt_slot_rejected || report.selected_superblock_slot == 2 {
        serial_println!(
            "NEO_TEST/1 event=FAIL name={} reason=neofs_corrupt_free_map_not_rejected selected_superblock={} generation={} rejected_mask=0x{:02x}",
            SCENARIO,
            report.selected_superblock_slot,
            report.generation,
            report.rejected_superblock_mask
        );
        debug_exit(EXIT_FAILURE);
    }
    verify_neofs_hello_read_or_fail();
    serial_println!(
        "NEO_TEST/1 event=PASS name={} neofs_gc_corrupt_free_map=ok corrupt_slot=2 corrupt_candidate_rejected=true selected_superblock={} generation={} rejected_superblock_mask=0x{:02x} valid_superblocks={} rejected_superblocks={}",
        SCENARIO,
        report.selected_superblock_slot,
        report.generation,
        report.rejected_superblock_mask,
        report.valid_superblocks,
        report.rejected_superblocks
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-cache-hit-miss-smoke")]
fn run_phase3_neofs_cache_hit_miss_smoke() -> ! {
    const PATH: &str = "/neofs/hello.txt";
    const EXPECTED: &[u8] = b"Hello from NeoFS v1 BUILD-2 2A mkfs.\n";

    let report = mount_neofs_rw_or_fail();
    let before = neofs_3d_cache_stats_or_fail();
    neofs_2c_read_literal_or_fail(PATH, EXPECTED);
    let after_first = neofs_3d_cache_stats_or_fail();
    if after_first.misses <= before.misses {
        fail("reason=neofs_cache_miss_not_observed");
    }
    neofs_2c_read_literal_or_fail(PATH, EXPECTED);
    let after_second = neofs_3d_cache_stats_or_fail();
    if after_second.hits <= after_first.hits {
        fail("reason=neofs_cache_hit_not_observed");
    }
    serial_println!(
        "NEO_TEST/1 event=PASS name={} neofs_cache=hit_miss path={} misses_delta_first={} hits_delta_second={} cached_blocks={} dirty_blocks={} selected_superblock={} generation={}",
        SCENARIO,
        PATH,
        after_first.misses - before.misses,
        after_second.hits - after_first.hits,
        after_second.cached_blocks,
        after_second.dirty_blocks,
        report.selected_superblock_slot,
        report.generation
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-writeback-dirty-drain")]
fn run_phase3_neofs_writeback_dirty_drain() -> ! {
    const PATH: &str = "/neofs/wb-drain.txt";
    const CONTENT: &[u8] = b"NeoFS BUILD-3 3D dirty write-back drain.\n";

    let report = mount_neofs_rw_or_fail();
    neofs_3d_set_writeback_hold_or_fail(true);
    let before = neofs_3d_cache_stats_or_fail();
    let file = neofs_2c_create_or_fail(PATH);
    neofs_2c_write_all_or_fail(&file, CONTENT);
    drop(file);
    let dirty = neofs_3d_cache_stats_or_fail();
    if dirty.dirty_blocks == 0 || !dirty.writeback_hold || !dirty.flush_required {
        fail("reason=neofs_writeback_dirty_not_held");
    }
    neofs_3d_set_writeback_hold_or_fail(false);
    let clean = neofs_3d_wait_clean_or_fail("reason=neofs_writeback_dirty_drain_not_clean");
    if clean.dirty_blocks != 0 || clean.flush_required {
        fail("reason=neofs_writeback_dirty_drain_left_dirty");
    }
    if clean.drained_blocks <= before.drained_blocks || clean.flushes <= before.flushes {
        fail("reason=neofs_writeback_dirty_drain_no_writeback");
    }
    neofs_2c_read_literal_or_fail(PATH, CONTENT);
    serial_println!(
        "NEO_TEST/1 event=PASS name={} neofs_writeback=dirty_drain path={} dirty_blocks_before={} dirty_blocks_after={} drained_blocks_delta={} cache_flushes_delta={} data_dirty_marks={} inode_dirty_marks={} root_dirty_marks={} superblock_dirty_marks={} selected_superblock={} generation={}",
        SCENARIO,
        PATH,
        dirty.dirty_blocks,
        clean.dirty_blocks,
        clean.drained_blocks - before.drained_blocks,
        clean.flushes - before.flushes,
        clean.data_dirty_marks - before.data_dirty_marks,
        clean.inode_dirty_marks - before.inode_dirty_marks,
        clean.root_dirty_marks - before.root_dirty_marks,
        clean.superblock_dirty_marks - before.superblock_dirty_marks,
        report.selected_superblock_slot,
        report.generation
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-writeback-worker-stop-join")]
fn run_phase3_neofs_writeback_worker_stop_join() -> ! {
    const PATH: &str = "/neofs/wb-stop.txt";
    const CONTENT: &[u8] = b"NeoFS BUILD-3 3D worker stop drains and joins.\n";

    let report = mount_neofs_rw_or_fail();
    neofs_3d_set_writeback_hold_or_fail(true);
    let file = neofs_2c_create_or_fail(PATH);
    neofs_2c_write_all_or_fail(&file, CONTENT);
    drop(file);
    let dirty = neofs_3d_cache_stats_or_fail();
    if dirty.dirty_blocks == 0 {
        fail("reason=neofs_writeback_stop_no_dirty_work");
    }
    let stop = match crate::fs::debug_neofs_stop_writeback_worker() {
        Ok(stop) => stop,
        Err(err) => neofs_2c_fail_vfs("neofs_writeback_stop_failed", err),
    };
    if !stop.had_worker || !stop.exited_success {
        fail_with_hex(
            "reason=neofs_writeback_worker_join_failed exit_code",
            stop.exit_code as u64,
        );
    }
    let clean = neofs_3d_cache_stats_or_fail();
    if clean.dirty_blocks != 0 || clean.flush_required {
        fail("reason=neofs_writeback_worker_stop_left_dirty");
    }
    neofs_2c_read_literal_or_fail(PATH, CONTENT);
    serial_println!(
        "NEO_TEST/1 event=PASS name={} neofs_writeback=worker_stop_join path={} dirty_blocks_before_stop={} dirty_blocks_after_stop={} stopped=true joined=true exit_success=true cache_flushes={} selected_superblock={} generation={}",
        SCENARIO,
        PATH,
        dirty.dirty_blocks,
        clean.dirty_blocks,
        clean.flushes,
        report.selected_superblock_slot,
        report.generation
    );
    debug_exit(EXIT_SUCCESS);
}

