#[cfg(feature = "neo-test-phase3-neofs-writeback-crash-before-drain")]
fn run_phase3_neofs_writeback_crash_before_drain() -> ! {
    const MARKER: &str = "/neofs/wb-crash-marker.txt";
    const TARGET: &str = "/neofs/wb-crash-dirty.txt";
    const MARKER_CONTENT: &[u8] = b"NeoFS BUILD-3 3D crash-before-drain marker.\n";
    const TARGET_CONTENT: &[u8] = b"NeoFS BUILD-3 3D dirty cache should not survive reboot.\n";

    let report = mount_neofs_rw_or_fail();
    match neofs_2c_open_read(MARKER) {
        Ok(marker) => {
            neofs_2c_read_literal_from_file_or_fail(&marker, MARKER_CONTENT);
            match neofs_2c_open_read(TARGET) {
                Err(crate::fs::VfsError::NotFound) => {}
                Ok(_) => fail("reason=neofs_writeback_crash_dirty_file_persisted"),
                Err(err) => neofs_2c_fail_vfs("neofs_writeback_crash_target_open_failed", err),
            }
            serial_println!(
                "NEO_TEST/1 event=PASS name={} stage=readback neofs_writeback_crash=ok marker={} target={} dirty_target_absent=true selected_superblock={} generation={} image=reused",
                SCENARIO,
                MARKER,
                TARGET,
                report.selected_superblock_slot,
                report.generation
            );
        }
        Err(crate::fs::VfsError::NotFound) => {
            let marker = neofs_2c_create_or_fail(MARKER);
            neofs_2c_write_all_or_fail(&marker, MARKER_CONTENT);
            drop(marker);
            let marker_cache =
                neofs_3d_wait_clean_or_fail("reason=neofs_writeback_crash_marker_not_clean");
            neofs_3d_set_writeback_hold_or_fail(true);
            let target = neofs_2c_create_or_fail(TARGET);
            neofs_2c_write_all_or_fail(&target, TARGET_CONTENT);
            drop(target);
            neofs_2c_read_literal_or_fail(TARGET, TARGET_CONTENT);
            let dirty = neofs_3d_cache_stats_or_fail();
            if dirty.dirty_blocks == 0 || !dirty.writeback_hold {
                fail("reason=neofs_writeback_crash_dirty_not_held");
            }
            serial_println!(
                "NEO_TEST/1 event=PASS name={} stage=write neofs_writeback_crash=prepared marker={} target={} marker_dirty_blocks_after_drain={} dirty_blocks_before_exit={} writeback_hold=true selected_superblock={} generation={} image=fresh",
                SCENARIO,
                MARKER,
                TARGET,
                marker_cache.dirty_blocks,
                dirty.dirty_blocks,
                report.selected_superblock_slot,
                report.generation
            );
        }
        Err(err) => neofs_2c_fail_vfs("neofs_writeback_crash_marker_open_failed", err),
    }
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-gc-waits-for-clean-cache")]
fn run_phase3_neofs_gc_waits_for_clean_cache() -> ! {
    const PATH: &str = "/neofs/wb-gc.txt";
    const FIRST: &[u8] = b"NeoFS BUILD-3 3D GC waits for version A.\n";
    const SECOND: &[u8] = b"NeoFS BUILD-3 3D GC waits for version B.\n";

    let report = mount_neofs_rw_or_fail();
    neofs_3d_set_writeback_hold_or_fail(true);
    let before = neofs_3d_cache_stats_or_fail();
    let file = neofs_2c_create_or_fail(PATH);
    neofs_2c_write_all_or_fail(&file, FIRST);
    drop(file);
    let file = neofs_2d_open_rw_or_fail(PATH);
    neofs_2c_write_all_or_fail(&file, SECOND);
    drop(file);
    let dirty = neofs_3d_cache_stats_or_fail();
    if dirty.dirty_blocks == 0 || !dirty.writeback_hold {
        fail("reason=neofs_gc_clean_gate_no_dirty_cache");
    }
    let gc = neofs_3c_run_gc_or_fail();
    let after_gc = neofs_3d_cache_stats_or_fail();
    if after_gc.drained_blocks <= before.drained_blocks {
        fail("reason=neofs_gc_clean_gate_did_not_force_drain");
    }
    neofs_3d_set_writeback_hold_or_fail(false);
    let clean = neofs_3d_wait_clean_or_fail("reason=neofs_gc_clean_gate_post_gc_not_clean");
    neofs_2c_read_literal_or_fail(PATH, SECOND);
    serial_println!(
        "NEO_TEST/1 event=PASS name={} neofs_gc_clean_cache=ok path={} dirty_blocks_before_gc={} forced_drain_blocks_delta={} reclaimed_blocks={} dirty_blocks_after_gc={} dirty_blocks_after_release={} cache_flushes={} selected_superblock={} generation={}",
        SCENARIO,
        PATH,
        dirty.dirty_blocks,
        after_gc.drained_blocks - before.drained_blocks,
        gc.reclaimed_blocks,
        after_gc.dirty_blocks,
        clean.dirty_blocks,
        clean.flushes,
        report.selected_superblock_slot,
        report.generation
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-2e")]
fn neofs_2e_exec_rights() -> crate::fs::FileRights {
    crate::fs::FileRights::from_bits(crate::fs::FileRights::EXECUTE.bits())
}

#[cfg(feature = "neo-test-phase3-neofs-2e")]
fn neofs_2e_read_exec_rights() -> crate::fs::FileRights {
    crate::fs::FileRights::from_bits(
        crate::fs::FileRights::READ.bits() | crate::fs::FileRights::EXECUTE.bits(),
    )
}

#[cfg(feature = "neo-test-phase3-neofs-2e")]
fn neofs_2e_forced_policy_open(
    path: &str,
    rights: crate::fs::FileRights,
) -> alloc::sync::Arc<crate::fs::OpenFile> {
    match crate::fs::debug_open_root_temporary_for_policy(path, rights) {
        Ok(file) => file,
        Err(err) => neofs_2c_fail_vfs("neofs_policy_forced_open_failed", err),
    }
}

#[cfg(feature = "neo-test-phase3-neofs-2e")]
fn neofs_2e_open_exec_or_fail(path: &str) -> alloc::sync::Arc<crate::fs::OpenFile> {
    match crate::fs::open_root_temporary(
        path,
        crate::fs::OPEN_ROOT_TEMPORARY,
        neofs_2e_exec_rights(),
    ) {
        Ok(file) => file,
        Err(err) => neofs_2c_fail_vfs("neofs_open_exec_failed", err),
    }
}

#[cfg(feature = "neo-test-phase3-neofs-2e")]
fn neofs_2e_expect_policy_err(
    file: &crate::fs::OpenFile,
    expected: crate::fs::VfsError,
    reason: &str,
) {
    match file.check_executable_policy() {
        Err(err) if err == expected => {}
        Err(err) => neofs_2c_fail_vfs(reason, err),
        Ok(()) => {
            serial_println!(
                "NEO_TEST/1 event=FAIL name={} reason={} expected_err={:?}",
                SCENARIO,
                reason,
                expected
            );
            debug_exit(EXIT_FAILURE);
        }
    }
}

#[cfg(feature = "neo-test-phase3-neofs-2e")]
fn neofs_2e_generation_or_fail(file: &crate::fs::OpenFile, reason: &str) -> u32 {
    match file.debug_captured_generation() {
        Some(generation) => generation,
        None => fail(reason),
    }
}

#[cfg(feature = "neo-test-phase3-neofs-typed-inode-exec-refusal")]
fn run_phase3_neofs_typed_inode_exec_refusal() -> ! {
    let report = mount_neofs_or_fail();
    let model = neofs_2c_open_read_or_fail("/neofs/model.neom");
    let mut buf = [0u8; 64];
    let n = match model.read(&mut buf) {
        Ok(n) => n,
        Err(err) => neofs_2c_fail_vfs("neofs_model_read_failed", err),
    };
    if n == 0 {
        fail("reason=neofs_model_read_empty");
    }

    let forced = neofs_2e_forced_policy_open("/neofs/model.neom", neofs_2e_read_exec_rights());
    neofs_2e_expect_policy_err(
        &forced,
        crate::fs::VfsError::TypeForbidden,
        "neofs_model_exec_policy_wrong_result",
    );
    serial_println!(
        "NEO_TEST/1 event=PASS name={} model_read=ok read_bytes={} forced_execute_cap=true exec_policy=TypeForbidden type_first=true selected_superblock={} generation={} no_real_mmap_exec=true",
        SCENARIO,
        n,
        report.selected_superblock_slot,
        report.generation
    );
    debug_exit(EXIT_SUCCESS);
}

