#[cfg(feature = "neo-test-phase3-neofs-type-vs-rights-policy-errors")]
fn run_phase3_neofs_type_vs_rights_policy_errors() -> ! {
    let report = mount_neofs_or_fail();
    let model_exec = neofs_2e_forced_policy_open("/neofs/model.neom", neofs_2e_read_exec_rights());
    neofs_2e_expect_policy_err(
        &model_exec,
        crate::fs::VfsError::TypeForbidden,
        "neofs_model_exec_matrix_wrong_error",
    );

    let model_no_exec =
        neofs_2e_forced_policy_open("/neofs/model.neom", crate::fs::FileRights::READ);
    neofs_2e_expect_policy_err(
        &model_no_exec,
        crate::fs::VfsError::TypeForbidden,
        "neofs_model_no_exec_matrix_wrong_error",
    );

    let regular_read = neofs_2c_open_read_or_fail("/neofs/hello.txt");
    neofs_2e_expect_policy_err(
        &regular_read,
        crate::fs::VfsError::InsufficientRights,
        "neofs_regular_no_exec_matrix_wrong_error",
    );

    let regular_exec = neofs_2e_open_exec_or_fail("/neofs/hello.txt");
    match regular_exec.check_executable_policy() {
        Ok(()) => {}
        Err(err) => neofs_2c_fail_vfs("neofs_regular_exec_matrix_failed", err),
    }

    serial_println!(
        "NEO_TEST/1 event=PASS name={} matrix_model_exec=TypeForbidden matrix_model_no_exec=TypeForbidden matrix_regular_no_exec=InsufficientRights matrix_regular_exec=ok type_first=true rights_second=true selected_superblock={} generation={} no_real_mmap_exec=true",
        SCENARIO,
        report.selected_superblock_slot,
        report.generation
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-filecap-generation-stale")]
fn run_phase3_neofs_filecap_generation_stale() -> ! {
    const PATH: &str = "/neofs/stale-2e.txt";
    const SEED: &[u8] = b"NeoFS BUILD-2 2E stale generation seed.\n";
    const MUTATION: &[u8] = b"NeoFS BUILD-2 2E stale generation mutation via handle A.\n";
    const CONTINUE: &[u8] = b"A continues after generation refresh.\n";

    let report = mount_neofs_rw_or_fail();
    let seed = neofs_2c_create_or_fail(PATH);
    neofs_2c_write_all_or_fail(&seed, SEED);
    drop(seed);

    let handle_a = neofs_2d_open_rw_or_fail(PATH);
    let handle_b = neofs_2d_open_rw_or_fail(PATH);
    let old_cap_generation =
        neofs_2e_generation_or_fail(&handle_b, "reason=missing_old_cap_generation");
    neofs_2c_write_all_or_fail(&handle_a, MUTATION);
    let refreshed_generation =
        neofs_2e_generation_or_fail(&handle_a, "reason=missing_refreshed_generation");
    if refreshed_generation == old_cap_generation {
        fail("reason=handle_a_generation_not_refreshed");
    }
    neofs_2c_write_all_or_fail(&handle_a, CONTINUE);
    let current_generation = match handle_b.debug_current_generation() {
        Ok(Some(generation)) => generation,
        Ok(None) => fail("reason=missing_current_generation"),
        Err(err) => neofs_2c_fail_vfs("neofs_current_generation_failed", err),
    };
    if current_generation == old_cap_generation {
        fail("reason=current_generation_not_advanced");
    }

    let mut buf = [0u8; 64];
    match handle_b.read(&mut buf) {
        Err(crate::fs::VfsError::Stale) => {}
        Err(err) => neofs_2c_fail_vfs("neofs_stale_handle_wrong_error", err),
        Ok(_) => fail("reason=neofs_stale_handle_read_succeeded"),
    }
    let stale_errno =
        crate::arch::x86_64::syscall::debug_vfs_errno_for_test(crate::fs::VfsError::Stale);
    if stale_errno != crate::errno::ESTALE || stale_errno != -116 {
        fail_with_hex(
            "reason=neofs_stale_errno_mismatch errno",
            stale_errno as u64,
        );
    }

    serial_println!(
        "NEO_TEST/1 event=PASS name={} path={} stale_cap=ESTALE stale_errno={} old_cap_generation={} refreshed_generation={} current_inode_generation={} handle_a_continued=true reachable_generation_checked=true selected_superblock={} generation={}",
        SCENARIO,
        PATH,
        stale_errno,
        old_cap_generation,
        refreshed_generation,
        current_generation,
        report.selected_superblock_slot,
        report.generation
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-2e")]
fn neofs_4a_dir_rights() -> crate::fs::FileRights {
    crate::fs::FileRights::from_bits(
        crate::fs::FileRights::LOOKUP.bits() | crate::fs::FileRights::READDIR.bits(),
    )
}

#[cfg(feature = "neo-test-phase3-neofs-2e")]
fn neofs_4a_install_file_handle(
    file: alloc::sync::Arc<crate::fs::OpenFile>,
    rights: crate::fs::FileRights,
) -> u32 {
    use crate::sched::process::{self, Handle, KERNEL_PID, Process};

    let proc = process::get(KERNEL_PID)
        .unwrap_or_else(|| process::register(Process::new_kernel("neo-test-kernel")));
    let handle = Handle::File {
        file,
        cap_id: process::alloc_cap_id(),
        rights,
    };
    match process::install_cap_excluding(&proc, handle, None, &[1]) {
        Ok(fd) => fd,
        Err(_) => fail("reason=neofs_readdir_handle_install_failed"),
    }
}

#[cfg(feature = "neo-test-phase3-neofs-2e")]
fn neofs_4a_open_dir_or_fail(path: &str) -> alloc::sync::Arc<crate::fs::OpenFile> {
    match crate::fs::open_root_temporary(
        path,
        crate::fs::OPEN_ROOT_TEMPORARY,
        neofs_4a_dir_rights(),
    ) {
        Ok(file) => file,
        Err(err) => neofs_2c_fail_vfs("neofs_open_dir_failed", err),
    }
}

#[cfg(feature = "neo-test-phase3-neofs-2e")]
fn neofs_4a_read_u32_le(bytes: &[u8]) -> u32 {
    u32::from_le_bytes([bytes[0], bytes[1], bytes[2], bytes[3]])
}

#[cfg(feature = "neo-test-phase3-neofs-2e")]
fn neofs_4a_read_u16_le(bytes: &[u8]) -> u16 {
    u16::from_le_bytes([bytes[0], bytes[1]])
}

#[cfg(feature = "neo-test-phase3-neofs-2e")]
fn neofs_4a_expect_dirent(fd: u32, cursor: &mut u64, expected_name: &str, expected_kind: u8) {
    let mut buf = [0u8; 64];
    let n =
        crate::arch::x86_64::syscall::debug_sys_readdir_kernel_buf_for_test(fd, &mut buf, cursor);
    if n <= 0 {
        fail_with_hex("reason=neofs_readdir_entry_failed rc", n as u64);
    }
    let n = n as usize;
    if n < 16 {
        fail("reason=neofs_readdir_short_record");
    }
    let record_len = neofs_4a_read_u32_le(&buf[0..4]) as usize;
    let name_len = neofs_4a_read_u16_le(&buf[4..6]) as usize;
    if record_len != n || record_len != 16 + name_len {
        fail("reason=neofs_readdir_bad_record_len");
    }
    if buf[6] != expected_kind || buf[7] != 0 {
        fail("reason=neofs_readdir_bad_kind_or_flags");
    }
    let next_cursor = u64::from_le_bytes([
        buf[8], buf[9], buf[10], buf[11], buf[12], buf[13], buf[14], buf[15],
    ]);
    if next_cursor != *cursor {
        fail("reason=neofs_readdir_next_cursor_mismatch");
    }
    if &buf[16..record_len] != expected_name.as_bytes() {
        fail("reason=neofs_readdir_name_mismatch");
    }
}

#[cfg(feature = "neo-test-phase3-neofs-readdir-root")]
fn run_phase3_neofs_readdir_root() -> ! {
    let report = mount_neofs_or_fail();
    let root = neofs_4a_open_dir_or_fail("/neofs");
    let fd = neofs_4a_install_file_handle(root, neofs_4a_dir_rights());
    let mut cursor = 0u64;
    neofs_4a_expect_dirent(fd, &mut cursor, "hello.txt", 2);
    neofs_4a_expect_dirent(fd, &mut cursor, "model.neom", 4);
    neofs_4a_expect_dirent(fd, &mut cursor, "subdir", 1);
    neofs_4a_expect_dirent(fd, &mut cursor, ".arthur", 1);
    let mut buf = [0u8; 64];
    let eof = crate::arch::x86_64::syscall::debug_sys_readdir_kernel_buf_for_test(
        fd,
        &mut buf,
        &mut cursor,
    );
    if eof != 0 {
        fail_with_hex("reason=neofs_readdir_eof_not_zero rc", eof as u64);
    }
    let subdir = neofs_4a_open_dir_or_fail("/neofs/subdir");
    let subdir_fd = neofs_4a_install_file_handle(subdir, neofs_4a_dir_rights());
    let mut subdir_cursor = 0u64;
    let subdir_eof = crate::arch::x86_64::syscall::debug_sys_readdir_kernel_buf_for_test(
        subdir_fd,
        &mut buf,
        &mut subdir_cursor,
    );
    if subdir_eof != 0 || subdir_cursor != 0 {
        fail("reason=neofs_subdir_readdir_not_empty_or_cursor_changed");
    }
    let arthur = neofs_4a_open_dir_or_fail("/neofs/.arthur");
    let arthur_fd = neofs_4a_install_file_handle(arthur, neofs_4a_dir_rights());
    let mut arthur_cursor = 0u64;
    neofs_4a_expect_dirent(arthur_fd, &mut arthur_cursor, "memory", 1);
    let arthur_eof = crate::arch::x86_64::syscall::debug_sys_readdir_kernel_buf_for_test(
        arthur_fd,
        &mut buf,
        &mut arthur_cursor,
    );
    if arthur_eof != 0 {
        fail_with_hex(
            "reason=neofs_arthur_readdir_eof_not_zero rc",
            arthur_eof as u64,
        );
    }
    serial_println!(
        "NEO_TEST/1 event=PASS name={} neofs_readdir=root entries=4 order=mkfs cursor={} eof=0 subdir_entries=0 subdir_eof=0 arthur_memory_entries=1 selected_superblock={} generation={} stale_generation_anchor=current_reachable_inode",
        SCENARIO,
        cursor,
        report.selected_superblock_slot,
        report.generation
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-readdir-stale-generation")]
fn run_phase3_neofs_readdir_stale_generation() -> ! {
    const PATH: &str = "/neofs/readdir-stale-4a.txt";

    let report = mount_neofs_rw_or_fail();
    let root = neofs_4a_open_dir_or_fail("/neofs");
    let captured_generation = root
        .debug_captured_generation()
        .unwrap_or_else(|| fail("reason=neofs_readdir_missing_captured_generation"));
    let fd = neofs_4a_install_file_handle(root.clone(), neofs_4a_dir_rights());
    let created = neofs_2c_create_or_fail(PATH);
    drop(created);
    let current_generation = root
        .debug_current_generation()
        .unwrap_or_else(|err| neofs_2c_fail_vfs("neofs_readdir_current_generation_failed", err))
        .unwrap_or_else(|| fail("reason=neofs_readdir_missing_current_generation"));
    if current_generation == captured_generation {
        fail("reason=neofs_readdir_root_generation_not_advanced");
    }
    let mut cursor = 0u64;
    let mut buf = [0u8; 64];
    let rc = crate::arch::x86_64::syscall::debug_sys_readdir_kernel_buf_for_test(
        fd,
        &mut buf,
        &mut cursor,
    );
    if rc != crate::errno::ESTALE {
        fail_with_hex("reason=neofs_readdir_stale_wrong_errno rc", rc as u64);
    }
    serial_println!(
        "NEO_TEST/1 event=PASS name={} neofs_readdir_stale=ok path={} errno={} captured_generation={} current_generation={} selected_superblock={} mount_generation={} anchor=current_reachable_inode_generation",
        SCENARIO,
        PATH,
        rc,
        captured_generation,
        current_generation,
        report.selected_superblock_slot,
        report.generation
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-neofs-reserved-type-refusal")]
fn run_phase3_neofs_reserved_type_refusal() -> ! {
    let (_probe, _device) = require_phase3_virtio_blk_ready();
    match crate::fs::mount_neofs_from_device0_readonly() {
        Err(crate::fs::neofs::NeoFsError::NoValidSuperblock) => {
            match crate::fs::debug_open_root_temporary_for_policy(
                "/neofs/subdir",
                neofs_2e_exec_rights(),
            ) {
                Err(crate::fs::VfsError::NotFound) => {}
                Err(err) => neofs_2c_fail_vfs("neofs_reserved_post_reject_wrong_error", err),
                Ok(_) => fail("reason=neofs_reserved_open_succeeded_after_rejected_mount"),
            }
            serial_println!(
                "NEO_TEST/1 event=PASS name={} reserved_type_mount_rejected=NoValidSuperblock executable_access=NotFound inert_before_rights=true no_real_mmap_exec=true",
                SCENARIO
            );
            debug_exit(EXIT_SUCCESS);
        }
        Err(err) => {
            serial_println!(
                "NEO_TEST/1 event=FAIL name={} reason=neofs_reserved_mount_unexpected_error err={:?}",
                SCENARIO,
                err
            );
            debug_exit(EXIT_FAILURE);
        }
        Ok(report) => {
            let forced = neofs_2e_forced_policy_open("/neofs/subdir", neofs_2e_exec_rights());
            neofs_2e_expect_policy_err(
                &forced,
                crate::fs::VfsError::TypeForbidden,
                "neofs_reserved_inert_policy_wrong_error",
            );
            serial_println!(
                "NEO_TEST/1 event=PASS name={} reserved_type_mount_rejected=false executable_access=TypeForbidden inert_before_rights=true selected_superblock={} generation={} no_real_mmap_exec=true",
                SCENARIO,
                report.selected_superblock_slot,
                report.generation
            );
            debug_exit(EXIT_SUCCESS);
        }
    }
}

#[cfg(feature = "neo-test-phase3-neofs-filerights-u32-forward-bits")]
fn run_phase3_neofs_filerights_u32_forward_bits() -> ! {
    let report = mount_neofs_or_fail();
    if core::mem::size_of::<crate::fs::FileRights>() != 4 {
        fail("reason=filerights_kernel_width_not_u32");
    }

    let high_bits = crate::fs::FileRights::RETYPE_RESERVED.bits()
        | crate::fs::FileRights::MOUNT_RESERVED.bits()
        | crate::fs::FileRights::EXECUTE.bits();
    let requested = crate::fs::FileRights::from_bits(high_bits);
    if requested.bits() != high_bits {
        fail("reason=filerights_high_bits_truncated");
    }

    match crate::fs::open_root_temporary(
        "/neofs/hello.txt",
        crate::fs::OPEN_ROOT_TEMPORARY,
        crate::fs::FileRights::RETYPE_RESERVED,
    ) {
        Err(crate::fs::VfsError::InsufficientRights) => {}
        Err(err) => neofs_2c_fail_vfs("neofs_high_bit_open_wrong_error", err),
        Ok(_) => fail("reason=neofs_high_bit_open_succeeded"),
    }

    let forced = neofs_2e_forced_policy_open("/neofs/hello.txt", requested);
    if forced.rights().bits() != high_bits {
        fail("reason=policy_forced_rights_truncated");
    }
    match forced.check_executable_policy() {
        Ok(()) => {}
        Err(err) => neofs_2c_fail_vfs("neofs_high_bit_policy_failed", err),
    }

    serial_println!(
        "NEO_TEST/1 event=PASS name={} kernel_filerights_size=4 libneo_filerights_size=4 requested_bits=0x{:08x} observed_bits=0x{:08x} retype_bit=0x{:08x} open_error=InsufficientRights policy_preserved_high_bits=true selected_superblock={} generation={}",
        SCENARIO,
        high_bits,
        forced.rights().bits(),
        crate::fs::FileRights::RETYPE_RESERVED.bits(),
        report.selected_superblock_slot,
        report.generation
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(any(
    feature = "neo-test-phase3-kthread-spawn-join-smoke",
    feature = "neo-test-phase3-kthread-stop-join-smoke",
    feature = "neo-test-phase3-kthread-stop-wakes-parked-worker",
    feature = "neo-test-phase3-kthread-detached-worker-smoke",
    feature = "neo-test-phase3-kthread-no-thread-arc-lifetime"
))]
#[derive(Copy, Clone)]
#[allow(dead_code)]
struct KthreadTestState {
    started: bool,
    stop_observed: bool,
    detached_done: bool,
    runs: u32,
}

#[cfg(any(
    feature = "neo-test-phase3-kthread-spawn-join-smoke",
    feature = "neo-test-phase3-kthread-stop-join-smoke",
    feature = "neo-test-phase3-kthread-stop-wakes-parked-worker",
    feature = "neo-test-phase3-kthread-detached-worker-smoke",
    feature = "neo-test-phase3-kthread-no-thread-arc-lifetime"
))]
impl KthreadTestState {
    const fn new() -> Self {
        Self {
            started: false,
            stop_observed: false,
            detached_done: false,
            runs: 0,
        }
    }
}

#[cfg(any(
    feature = "neo-test-phase3-kthread-spawn-join-smoke",
    feature = "neo-test-phase3-kthread-stop-join-smoke",
    feature = "neo-test-phase3-kthread-stop-wakes-parked-worker",
    feature = "neo-test-phase3-kthread-detached-worker-smoke",
    feature = "neo-test-phase3-kthread-no-thread-arc-lifetime"
))]
static KTHREAD_TEST_STATE: crate::sync::SwitchMutex<KthreadTestState> =
    crate::sync::SwitchMutex::new(KthreadTestState::new());

#[cfg(any(
    feature = "neo-test-phase3-kthread-spawn-join-smoke",
    feature = "neo-test-phase3-kthread-stop-join-smoke",
    feature = "neo-test-phase3-kthread-stop-wakes-parked-worker",
    feature = "neo-test-phase3-kthread-detached-worker-smoke",
    feature = "neo-test-phase3-kthread-no-thread-arc-lifetime"
))]
fn reset_kthread_test_state() {
    *KTHREAD_TEST_STATE.lock() = KthreadTestState::new();
}

#[cfg(any(
    feature = "neo-test-phase3-kthread-spawn-join-smoke",
    feature = "neo-test-phase3-kthread-stop-join-smoke",
    feature = "neo-test-phase3-kthread-stop-wakes-parked-worker",
    feature = "neo-test-phase3-kthread-detached-worker-smoke",
    feature = "neo-test-phase3-kthread-no-thread-arc-lifetime"
))]
fn mark_kthread_started() {
    let mut state = KTHREAD_TEST_STATE.lock();
    state.started = true;
    state.runs += 1;
}

#[cfg(any(
    feature = "neo-test-phase3-kthread-stop-join-smoke",
    feature = "neo-test-phase3-kthread-stop-wakes-parked-worker"
))]
fn mark_kthread_stop_observed() {
    KTHREAD_TEST_STATE.lock().stop_observed = true;
}

#[cfg(feature = "neo-test-phase3-kthread-detached-worker-smoke")]
fn mark_kthread_detached_done() {
    KTHREAD_TEST_STATE.lock().detached_done = true;
}

#[cfg(any(
    feature = "neo-test-phase3-kthread-spawn-join-smoke",
    feature = "neo-test-phase3-kthread-stop-join-smoke",
    feature = "neo-test-phase3-kthread-stop-wakes-parked-worker",
    feature = "neo-test-phase3-kthread-no-thread-arc-lifetime"
))]
fn expect_kthread_join_success(result: crate::sched::kthread::KthreadJoinResult) {
    if result
        != crate::sched::kthread::KthreadJoinResult::Exited(
            crate::sched::kthread::KthreadExitState::Success,
        )
    {
        fail("reason=kthread_join_not_success");
    }
}

#[cfg(any(
    feature = "neo-test-phase3-kthread-spawn-join-smoke",
    feature = "neo-test-phase3-kthread-stop-join-smoke",
    feature = "neo-test-phase3-kthread-stop-wakes-parked-worker",
    feature = "neo-test-phase3-kthread-no-thread-arc-lifetime"
))]
#[allow(dead_code)]
fn wait_for_kthread_started() {
    for _ in 0..100_000 {
        if KTHREAD_TEST_STATE.lock().started {
            return;
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    fail("reason=kthread_worker_not_started");
}

#[cfg(feature = "neo-test-phase3-kthread-detached-worker-smoke")]
fn wait_for_kthread_detached_done() {
    for _ in 0..100_000 {
        if KTHREAD_TEST_STATE.lock().detached_done {
            return;
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    fail("reason=kthread_detached_worker_not_done");
}

#[cfg(feature = "neo-test-phase3-kthread-stop-wakes-parked-worker")]
fn wait_for_kthread_stop_waiter(handle: &crate::sched::kthread::KthreadHandle) {
    for _ in 0..100_000 {
        if crate::sched::kthread::debug_stop_waiter_present(handle) {
            return;
        }
        crate::sched::yield_now();
        crate::sched::reap();
    }
    fail("reason=kthread_stop_waiter_not_parked");
}

#[cfg(any(
    feature = "neo-test-phase3-kthread-spawn-join-smoke",
    feature = "neo-test-phase3-kthread-stop-join-smoke",
    feature = "neo-test-phase3-kthread-stop-wakes-parked-worker",
    feature = "neo-test-phase3-kthread-detached-worker-smoke",
    feature = "neo-test-phase3-kthread-no-thread-arc-lifetime",
    feature = "neo-test-virtio-blk-io-gate-contention"
))]
fn reap_kthread_zombies() {
    for _ in 0..100_000 {
        crate::sched::reap();
        if crate::sched::scheduler::debug_total_zombies() == 0 {
            return;
        }
        crate::sched::yield_now();
    }
    fail("reason=kthread_zombie_not_reaped");
}

#[cfg(feature = "neo-test-phase3-kthread-spawn-join-smoke")]
fn kthread_spawn_join_worker(
    stop: crate::sched::kthread::KthreadStopToken,
) -> crate::sched::kthread::KthreadExitState {
    if stop.is_stop_requested() {
        return crate::sched::kthread::KthreadExitState::Failed(1);
    }
    mark_kthread_started();
    crate::sched::kthread::KthreadExitState::Success
}

#[cfg(feature = "neo-test-phase3-kthread-spawn-join-smoke")]
fn run_phase3_kthread_spawn_join_smoke() -> ! {
    reset_kthread_test_state();
    let handle =
        crate::sched::kthread::spawn_owned("kthread-spawn-join", kthread_spawn_join_worker);
    let id = handle.id();
    expect_kthread_join_success(handle.join());
    reap_kthread_zombies();
    let state = KTHREAD_TEST_STATE.lock();
    if !state.started || state.runs != 1 {
        fail("reason=kthread_spawn_join_run_count_bad");
    }
    if crate::sched::kthread::debug_registered(id) {
        fail("reason=kthread_join_left_registry_entry");
    }
    serial_println!(
        "NEO_TEST/1 event=PASS name={} kthread_slot={} generation={} runs={} joined=true reaped=true",
        SCENARIO,
        id.slot(),
        id.generation(),
        state.runs
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-virtio-blk-flush-command-smoke")]
fn run_phase3_virtio_blk_flush_command_smoke() -> ! {
    let (probe, device) = require_phase3_virtio_blk_ready();
    let block_size = require_phase3_block_size(&device);
    let write_buf =
        phase3_alloc_block_buffer(block_size, "reason=virtio_blk_flush_write_dma_alloc_failed");
    phase3_fill_block_pattern(&write_buf, 0x7e);
    if let Err(err) = device.write_block(6, core::slice::from_ref(&write_buf)) {
        fail_block_error("virtio_blk_flush_write_failed", err);
    }

    let completions_before = crate::drivers::block::virtio_blk::debug_completion_count();
    let flush_commands_before = crate::drivers::block::virtio_blk::debug_flush_command_count();
    let flush_completions_before =
        crate::drivers::block::virtio_blk::debug_flush_completion_count();
    let desc_barriers_before =
        crate::drivers::block::virtio_blk::debug_descriptor_publish_barriers();
    let notify_barriers_before =
        crate::drivers::block::virtio_blk::debug_notification_suppression_barriers();
    let live_before = crate::drivers::block::dma::debug_live_buffers();

    if let Err(err) = device.flush() {
        fail_block_error("virtio_blk_flush_failed", err);
    }

    let completions_after = crate::drivers::block::virtio_blk::debug_completion_count();
    let flush_commands_after = crate::drivers::block::virtio_blk::debug_flush_command_count();
    let flush_completions_after = crate::drivers::block::virtio_blk::debug_flush_completion_count();
    let desc_barriers_after =
        crate::drivers::block::virtio_blk::debug_descriptor_publish_barriers();
    let notify_barriers_after =
        crate::drivers::block::virtio_blk::debug_notification_suppression_barriers();
    let live_after = crate::drivers::block::dma::debug_live_buffers();

    if completions_after <= completions_before {
        fail("reason=virtio_blk_flush_completion_not_observed");
    }
    if flush_commands_after <= flush_commands_before {
        fail("reason=virtio_blk_flush_command_not_issued");
    }
    if flush_completions_after <= flush_completions_before {
        fail("reason=virtio_blk_flush_completion_counter_not_observed");
    }
    if crate::drivers::block::virtio_blk::debug_in_flight_dma_buffers() != 0 {
        fail("reason=virtio_blk_flush_dma_not_released");
    }
    if crate::drivers::block::virtio_blk::debug_last_completed_request_type() != 4 {
        fail_with_hex(
            "reason=virtio_blk_flush_wrong_request_type type",
            crate::drivers::block::virtio_blk::debug_last_completed_request_type() as u64,
        );
    }
    if crate::drivers::block::virtio_blk::debug_last_completed_dma_buffers() != 2 {
        fail_with_hex(
            "reason=virtio_blk_flush_wrong_dma_retention count",
            crate::drivers::block::virtio_blk::debug_last_completed_dma_buffers() as u64,
        );
    }
    if crate::drivers::block::virtio_blk::debug_last_completed_had_data_buffer() {
        fail("reason=virtio_blk_flush_fabricated_data_buffer");
    }
    let wake = crate::drivers::block::virtio_blk::debug_last_wake_result();
    if !crate::drivers::block::virtio_blk::debug_wake_result_woken_or_inline(wake) {
        fail_with_hex(
            "reason=virtio_blk_flush_completion_not_woken_or_inline result",
            wake as u64,
        );
    }
    if desc_barriers_after <= desc_barriers_before {
        fail("reason=virtio_blk_flush_descriptor_barrier_missing");
    }
    if notify_barriers_after <= notify_barriers_before {
        fail("reason=virtio_blk_flush_notification_barrier_missing");
    }
    if live_after != live_before {
        serial_println!(
            "NEO_TEST/1 event=FAIL name={} reason=virtio_blk_flush_dma_live_leak before={} after={}",
            SCENARIO,
            live_before,
            live_after
        );
        debug_exit(EXIT_FAILURE);
    }

    let read_buf =
        phase3_alloc_block_buffer(block_size, "reason=virtio_blk_flush_read_dma_alloc_failed");
    if let Err(err) = device.read_block(6, core::slice::from_ref(&read_buf)) {
        fail_block_error("virtio_blk_flush_readback_failed", err);
    }
    if !phase3_blocks_equal(&write_buf, &read_buf) {
        fail("reason=virtio_blk_flush_readback_mismatch");
    }

    serial_println!(
        "NEO_TEST/1 event=PASS name={} bdf=0x{:06x} request_type=4 VIRTIO_BLK_T_FLUSH=true completions_delta={} flush_commands_delta={} flush_completions_delta={} wake_result={} retained_dma_buffers=2 has_data_buffer=false readback=ok descriptor_publish_barriers_delta={} notification_suppression_barriers_delta={} live_before={} live_after={} F_FLUSH_offered={} F_FLUSH_negotiated=true F_CONFIG_WCE_negotiated=false",
        SCENARIO,
        probe.last_bdf,
        completions_after - completions_before,
        flush_commands_after - flush_commands_before,
        flush_completions_after - flush_completions_before,
        wake,
        desc_barriers_after - desc_barriers_before,
        notify_barriers_after - notify_barriers_before,
        live_before,
        live_after,
        probe.flush_offered
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-kthread-stop-join-smoke")]
fn kthread_stop_join_worker(
    stop: crate::sched::kthread::KthreadStopToken,
) -> crate::sched::kthread::KthreadExitState {
    mark_kthread_started();
    for _ in 0..100_000 {
        if stop.is_stop_requested() {
            mark_kthread_stop_observed();
            return crate::sched::kthread::KthreadExitState::Success;
        }
        crate::sched::yield_now();
    }
    crate::sched::kthread::KthreadExitState::Failed(2)
}

#[cfg(feature = "neo-test-phase3-kthread-stop-join-smoke")]
fn run_phase3_kthread_stop_join_smoke() -> ! {
    reset_kthread_test_state();
    let handle = crate::sched::kthread::spawn_owned("kthread-stop-join", kthread_stop_join_worker);
    let id = handle.id();
    wait_for_kthread_started();
    handle.request_stop();
    expect_kthread_join_success(handle.join());
    reap_kthread_zombies();
    if !KTHREAD_TEST_STATE.lock().stop_observed {
        fail("reason=kthread_stop_not_observed");
    }
    serial_println!(
        "NEO_TEST/1 event=PASS name={} kthread_slot={} generation={} stop_observed=true joined=true",
        SCENARIO,
        id.slot(),
        id.generation()
    );
    debug_exit(EXIT_SUCCESS);
}

