#[cfg(feature = "neo-test-phase3-ext4-extent-chain-read")]
fn run_phase3_ext4_extent_chain_read() -> ! {
    ext4_mount_or_fail(0);
    let bytes = ext4_expect_large_pattern("/ext4/large.bin");
    let Some(device) = crate::drivers::block::get_device(2) else {
        fail("reason=ext4_device2_missing_for_extent_debug");
    };
    let extent_count = match crate::fs::ext4::debug_extent_count_for_device(device, "large.bin") {
        Ok(count) => count,
        Err(err) => neofs_2c_fail_vfs("ext4_extent_count_failed", err),
    };
    if extent_count <= 1 {
        fail_with_hex(
            "reason=ext4_large_not_fragmented extents",
            extent_count as u64,
        );
    }
    serial_println!(
        "NEO_TEST/1 event=PASS name={} path=/ext4/large.bin bytes={} extents={} pattern_match=true",
        SCENARIO,
        bytes,
        extent_count
    );
    debug_exit(EXIT_SUCCESS);
}

#[cfg(feature = "neo-test-phase3-ext4-write-is-rejected")]
fn run_phase3_ext4_write_is_rejected() -> ! {
    ext4_mount_or_fail(0);
    match crate::fs::open_root_temporary(
        "/ext4/hello.txt",
        crate::fs::OPEN_ROOT_TEMPORARY,
        crate::fs::FileRights::WRITE,
    ) {
        Err(crate::fs::VfsError::InsufficientRights) => {
            serial_println!(
                "NEO_TEST/1 event=PASS name={} write_rejected=open errno=EACCES readonly=true",
                SCENARIO
            );
            debug_exit(EXIT_SUCCESS);
        }
        Err(err) => neofs_2c_fail_vfs("ext4_write_open_wrong_error", err),
        Ok(file) => match file.write(b"x") {
            Err(crate::fs::VfsError::InsufficientRights) => {
                serial_println!(
                    "NEO_TEST/1 event=PASS name={} write_rejected=write errno=EACCES readonly=true",
                    SCENARIO
                );
                debug_exit(EXIT_SUCCESS);
            }
            Err(err) => neofs_2c_fail_vfs("ext4_write_wrong_error", err),
            Ok(_) => fail("reason=ext4_write_succeeded"),
        },
    }
}

