#[cfg(feature = "neo-test-phase3-ext4-type-import-is-regular")]
fn run_phase3_ext4_type_import_is_regular() -> ! {
    ext4_mount_or_fail(0);
    let entries = ext4_collect_dirents("/ext4");
    let mut saw_neom_regular = false;
    for (name, kind) in &entries {
        match *kind {
            1 | 2 => {}
            3 => fail("reason=ext4_imported_symlink"),
            4 => fail("reason=ext4_imported_model"),
            _ => fail("reason=ext4_imported_unknown_kind"),
        }
        if name.as_str() == "notes.neom" {
            if *kind != 2 {
                fail("reason=ext4_neom_not_regular");
            }
            saw_neom_regular = true;
        }
    }
    if !saw_neom_regular {
        fail("reason=ext4_neom_fixture_missing");
    }
    serial_println!(
        "NEO_TEST/1 event=PASS name={} neom_kind=Regular xattr_type_ignored=true model_imports=0 symlink_imports=0 entries={}",
        SCENARIO,
        entries.len()
    );
    debug_exit(EXIT_SUCCESS);
}

// === BUILD-5a-AHCI block backend scenarios ==============================

#[cfg(feature = "neo-test-phase3-ahci")]
const AHCI_PATTERN_LBA: u64 = 8;
#[cfg(feature = "neo-test-phase3-ahci")]
const AHCI_WRITE_LBA: u64 = 32;

#[cfg(feature = "neo-test-phase3-ahci")]
#[allow(dead_code)]
fn ahci_probe_or_fail() -> crate::drivers::block::ahci::ProbeSnapshot {
    let probe = crate::drivers::block::ahci::last_probe_snapshot();
    if !probe.seen {
        fail("reason=ahci_controller_not_seen");
    }
    if !probe.abar_mapped {
        fail("reason=ahci_abar_not_mapped");
    }
    if !probe.probe_ok {
        fail("reason=ahci_probe_not_ok");
    }
    probe
}

#[cfg(feature = "neo-test-phase3-ahci")]
#[allow(dead_code)]
fn ahci_device_with_index_or_fail() -> (
    usize,
    alloc::sync::Arc<dyn crate::drivers::block::BlockDevice>,
) {
    let Some((device_index, device)) = crate::drivers::block::find_device_by_driver("ahci") else {
        fail("reason=ahci_device_missing");
    };
    if device.identity().driver != "ahci" {
        fail("reason=ahci_device_wrong_driver");
    }
    (device_index, device)
}

#[cfg(feature = "neo-test-phase3-ahci")]
#[allow(dead_code)]
fn ahci_device_or_fail() -> alloc::sync::Arc<dyn crate::drivers::block::BlockDevice> {
    ahci_device_with_index_or_fail().1
}

#[cfg(feature = "neo-test-phase3-ahci")]
#[allow(dead_code)]
fn ahci_alloc_buffer(len: usize) -> alloc::sync::Arc<crate::drivers::block::DmaBuffer> {
    crate::drivers::block::DmaBuffer::alloc_zeroed(len)
        .unwrap_or_else(|_| fail("reason=ahci_dma_alloc_failed"))
}

#[cfg(feature = "neo-test-phase3-ahci")]
#[allow(dead_code)]
fn ahci_raw_pattern_byte(offset: usize) -> u8 {
    ((offset as u8).wrapping_mul(29)).wrapping_add(0x5a) ^ 0xa5
}

#[cfg(feature = "neo-test-phase3-ahci")]
#[allow(dead_code)]
fn ahci_verify_raw_pattern(buffer: &crate::drivers::block::DmaBuffer, absolute_start: usize) {
    let slice = unsafe { buffer.as_slice() };
    for (idx, byte) in slice.iter().copied().enumerate() {
        if byte != ahci_raw_pattern_byte(absolute_start + idx) {
            fail("reason=ahci_raw_pattern_mismatch");
        }
    }
}

#[cfg(feature = "neo-test-phase3-ahci")]
#[allow(dead_code)]
fn ahci_fill_write_pattern(buffer: &alloc::sync::Arc<crate::drivers::block::DmaBuffer>, salt: u8) {
    unsafe {
        for (idx, byte) in buffer.as_mut_slice().iter_mut().enumerate() {
            *byte = (idx as u8).wrapping_mul(31).wrapping_add(salt) ^ 0x6d;
        }
    }
}

#[cfg(feature = "neo-test-phase3-ahci")]
#[allow(dead_code)]
fn ahci_buffers_equal(
    left: &alloc::sync::Arc<crate::drivers::block::DmaBuffer>,
    right: &alloc::sync::Arc<crate::drivers::block::DmaBuffer>,
) -> bool {
    unsafe { left.as_slice() == right.as_slice() }
}

#[cfg(feature = "neo-test-phase3-ahci")]
#[allow(dead_code)]
fn ahci_root_mount_rights() -> crate::fs::FileRights {
    crate::fs::FileRights::from_bits(
        crate::fs::FileRights::LOOKUP.bits()
            | crate::fs::FileRights::READDIR.bits()
            | crate::fs::FileRights::MOUNT.bits(),
    )
}

#[cfg(feature = "neo-test-phase3-ahci")]
#[allow(dead_code)]
fn ahci_dir_rights() -> crate::fs::FileRights {
    crate::fs::FileRights::from_bits(
        crate::fs::FileRights::LOOKUP.bits() | crate::fs::FileRights::READDIR.bits(),
    )
}

#[cfg(feature = "neo-test-phase3-ahci")]
#[allow(dead_code)]
fn ahci_mount_or_fail(fs_type: u32, target: &str) -> usize {
    let _probe = ahci_probe_or_fail();
    let (device_index, _device) = ahci_device_with_index_or_fail();
    let root = mount4b_open_dir_or_fail("/", ahci_root_mount_rights());
    let dir_fd = mount4b_install_fd(root, crate::fs::FileRights::MOUNT);
    let source = alloc::format!("device{}", device_index);
    let req = mount4b_build_request_v1(fs_type, &source, target);
    let rc = crate::arch::x86_64::syscall::debug_sys_mount_for_test(dir_fd, &req, 0);
    if rc != 0 {
        fail_with_hex("reason=ahci_mount_rc", rc as u64);
    }
    device_index
}

