#[cfg(feature = "neo-test-phase3-ahci")]
#[allow(dead_code)]
fn ahci_expect_file_bytes(path: &str, expected: &[u8]) {
    let file = ahci_open_or_fail(path, crate::fs::FileRights::READ);
    let mut buf = [0u8; 128];
    let n = match file.read(&mut buf) {
        Ok(n) => n,
        Err(err) => neofs_2c_fail_vfs("ahci_read_failed", err),
    };
    if n != expected.len() {
        serial_println!(
            "NEO_TEST/1 event=FAIL name={} reason=ahci_read_len got={} expected={}",
            SCENARIO,
            n,
            expected.len()
        );
        debug_exit(EXIT_FAILURE);
    }
    if &buf[..n] != expected {
        fail("reason=ahci_read_bytes_mismatch");
    }
}

#[cfg(feature = "neo-test-phase3-ahci")]
#[allow(dead_code)]
fn ahci_collect_dirents(path: &str) -> alloc::vec::Vec<(alloc::string::String, u8)> {
    let dir = ahci_open_or_fail(path, ahci_dir_rights());
    let fd = mount4b_install_fd(dir, crate::fs::FileRights::READDIR);
    let mut entries = alloc::vec::Vec::new();
    let mut cursor = 0u64;

    for _ in 0..64 {
        let mut buf = [0u8; 128];
        let n = crate::arch::x86_64::syscall::debug_sys_readdir_kernel_buf_for_test(
            fd,
            &mut buf,
            &mut cursor,
        );
        if n == 0 {
            return entries;
        }
        if n < 0 {
            fail_with_hex("reason=ahci_readdir_rc rc", n as u64);
        }
        let n = n as usize;
        if n < 16 {
            fail("reason=ahci_readdir_short_record");
        }
        let record_len = u32::from_le_bytes([buf[0], buf[1], buf[2], buf[3]]) as usize;
        let name_len = u16::from_le_bytes([buf[4], buf[5]]) as usize;
        if record_len != n || record_len != 16 + name_len {
            fail("reason=ahci_readdir_bad_record_len");
        }
        let name = match core::str::from_utf8(&buf[16..record_len]) {
            Ok(name) => alloc::string::String::from(name),
            Err(_) => fail("reason=ahci_readdir_name_not_utf8"),
        };
        entries.push((name, buf[6]));
    }
    fail("reason=ahci_readdir_too_many_entries");
}

#[cfg(feature = "neo-test-phase3-ahci")]
#[allow(dead_code)]
fn ahci_has_dirent(entries: &[(alloc::string::String, u8)], expected_name: &str) -> bool {
    entries
        .iter()
        .any(|(name, _kind)| name.as_str() == expected_name)
}

