#[cfg(feature = "neo-test-phase3-ahci-write-sector-pattern")]
fn run_phase3_ahci_write_sector_pattern() -> ! {
    let _probe = ahci_probe_or_fail();
    let device = ahci_device_or_fail();
    let block_size = device.geometry().logical_block_size as usize;
    let write_buf = ahci_alloc_buffer(block_size);
    ahci_fill_write_pattern(&write_buf, 0x41);
    if let Err(err) = device.write_block(AHCI_WRITE_LBA, core::slice::from_ref(&write_buf)) {
        fail_block_error("ahci_write_sector_failed", err);
    }
    if let Err(err) = device.flush() {
        fail_block_error("ahci_flush_after_write_failed", err);
    }
    let read_buf = ahci_alloc_buffer(block_size);
    if let Err(err) = device.read_block(AHCI_WRITE_LBA, core::slice::from_ref(&read_buf)) {
        fail_block_error("ahci_write_readback_failed", err);
    }
    if !ahci_buffers_equal(&write_buf, &read_buf) {
        fail("reason=ahci_write_readback_mismatch");
    }
    serial_println!(
        "NEO_TEST/1 event=PASS name={} lba={} bytes={} write=ok flush=ok readback=ok",
        SCENARIO,
        AHCI_WRITE_LBA,
        block_size
    );
    debug_exit(EXIT_SUCCESS);
}

