    serial_println!(
        "NEO_TEST/1 event=PASS name={} fs=fat32 source=device{} readdir=ok path=/nvme-fat32/hello.txt bytes=18 content_match=true",
        SCENARIO,
        source_index
    );
    debug_exit(EXIT_SUCCESS);
